INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地狱", "is_correct": true, "explanation": "地狱：极痛苦的境地，与“没有朋友的学校”给孩子带来的痛苦相符。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场令人快乐，与“没有朋友的学校”的痛苦处境相反，句意矛盾。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是令人舒适的地方，与句中痛苦的语境相矛盾。"}, {"text": "天国", "is_correct": false, "explanation": "语域：“天国”是宗教书面用语，与“对孩子来说”的口语语境不协调，且句意相反。"}], "explanations": {"地狱": "地狱：极痛苦的境地，与“没有朋友的学校”给孩子带来的痛苦相符。", "游乐场": "语义：游乐场令人快乐，与“没有朋友的学校”的痛苦处境相反，句意矛盾。", "花园": "语义：花园是令人舒适的地方，与句中痛苦的语境相矛盾。", "天国": "语域：“天国”是宗教书面用语，与“对孩子来说”的口语语境不协调，且句意相反。"}, "sentence_index": 6, "correct_answer": "地狱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷每年清明都去地狱祭扫。", "explanation": "这里应该用〈墓地〉。地狱是传说中的地方，不是可以去祭扫的地点。"}, {"text": "我每天早上都要擦一遍地狱。", "explanation": "这里应该用〈地板〉。地狱指受苦的地方或极痛苦的境地，不是可以擦的东西。"}, {"text": "周末我们去地狱买菜了。", "explanation": "这里应该用〈菜市场〉。地狱指受苦的地方或极痛苦的境地，不是买菜的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他那段时间过得像一只地狱。", "corrected_sentence": "他那段时间过得像一个地狱。", "error_description": "“地狱”应用量词“个”，不能用“只”（“只”多用于动物或成对物品中的一件）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那里的日子像一条真正的地狱。", "corrected_sentence": "那里的日子像一个真正的地狱。", "error_description": "量词错误：指“地狱”应用“个”，不能用“条”（“条”多用于细长的东西）。正确说法是“一个真正的地狱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
