INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90129, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "查是去看,去找,弄清楚。", "primary_collocate": null, "pronunciation": "chá", "ipa": "ʈʂʰa˧˥", "syllable_count": 1, "sentences": [{"text": "我不会写这个字，想查词典。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以上网查一下地图。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在图书馆查资料。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想查查明天的天气。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前我查了火车几点开。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词是什么意思？你查过吗？", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请帮我查一下他的电话号码。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用手机查了菜谱。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我查了半天，也没找到那家店。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不懂的地方要自己查清楚。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "查查", "label": "重叠"}, {"form": "查了", "label": "体标"}, {"form": "查过", "label": "体标"}], "register": "中性", "sense_fingerprint": "翻看、寻找资料以弄清楚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '133a0cf0-cdf6-4e93-b59b-2c72829dec62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90129, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "查", "is_correct": true, "explanation": "正确答案：查（chá，第二声），意思是查找、查阅。"}, {"text": "插", "is_correct": false, "explanation": "插（chā，第一声）与查（chá，第二声）声调不同，意思是插入。"}, {"text": "常", "is_correct": false, "explanation": "常（cháng）与查（chá）韵母不同，多了 ng，意思是经常。"}, {"text": "扎", "is_correct": false, "explanation": "扎（zhá）与查（chá）声母不同，zh 对 ch，意思是扎进、扎针。"}, {"text": "闸", "is_correct": false, "explanation": "闸（zhá）与查（chá）声母不同，zh 对 ch，意思是闸门。"}], "explanations": {"查": "正确答案：查（chá，第二声），意思是查找、查阅。", "插": "插（chā，第一声）与查（chá，第二声）声调不同，意思是插入。", "常": "常（cháng）与查（chá）韵母不同，多了 ng，意思是经常。", "扎": "扎（zhá）与查（chá）声母不同，zh 对 ch，意思是扎进、扎针。", "闸": "闸（zhá）与查（chá）声母不同，zh 对 ch，意思是闸门。"}, "sentence_index": null, "correct_answer": "查"}, "level_3": {"options": [{"text": "查", "is_correct": true, "explanation": "正确：「想查词典」中的“查”表示查阅，与“不会写这个字”的语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只能搭配食物，不能说“吃词典”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能搭配“词典”。"}, {"text": "忘", "is_correct": false, "explanation": "语义：“忘”是忘记，与“不会写这个字，想找答案”的语境不合。"}], "explanations": {"查": "正确：「想查词典」中的“查”表示查阅，与“不会写这个字”的语境相合。", "吃": "搭配：“吃”只能搭配食物，不能说“吃词典”。", "唱": "搭配：“唱”不能搭配“词典”。", "忘": "语义：“忘”是忘记，与“不会写这个字，想找答案”的语境不合。"}, "sentence_index": 0, "correct_answer": "查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想查查她的心意。", "explanation": "这里应该用〈猜〉。查用于查明事实，心意要用猜。"}, {"text": "他每天都查一个小时的电视。", "explanation": "这里应该用〈看〉。查是查阅资料、核实，看电视要用看。"}, {"text": "妈妈在厨房查了一会儿饭。", "explanation": "这里应该用〈做〉。查不能用于做饭，做饭要用做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90129, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "查", "is_correct": true, "explanation": "正确答案：查（chá，第二声），意思是查找、查阅。"}, {"text": "叉", "is_correct": false, "explanation": "叉（chā，第一声）与查（chá，第二声）声调不同，意思是叉子。"}, {"text": "长", "is_correct": false, "explanation": "长（cháng）与查（chá）韵母不同，多了 ng，意思是长短。"}, {"text": "馋", "is_correct": false, "explanation": "馋（chán）与查（chá）韵母不同，多了 n，意思是贪吃。"}, {"text": "柴", "is_correct": false, "explanation": "柴（chái）与查（chá）韵母不同，ai 对 a，意思是柴火。"}], "explanations": {"查": "正确答案：查（chá，第二声），意思是查找、查阅。", "叉": "叉（chā，第一声）与查（chá，第二声）声调不同，意思是叉子。", "长": "长（cháng）与查（chá）韵母不同，多了 ng，意思是长短。", "馋": "馋（chán）与查（chá）韵母不同，多了 n，意思是贪吃。", "柴": "柴（chái）与查（chá）韵母不同，ai 对 a，意思是柴火。"}, "sentence_index": null, "correct_answer": "查"}, "level_3": {"options": [{"text": "查", "is_correct": true, "explanation": "正确：「请帮我查一下他的电话号码」中的“查”表示查找、查询，与语境相合。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”只能用于食物或液体，不能说“煮电话号码”。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”是丢弃，不能用于查询电话号码。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗，与查询电话号码无关。"}], "explanations": {"查": "正确：「请帮我查一下他的电话号码」中的“查”表示查找、查询，与语境相合。", "煮": "搭配：“煮”只能用于食物或液体，不能说“煮电话号码”。", "扔": "搭配：“扔”是丢弃，不能用于查询电话号码。", "洗": "语义：“洗”是清洗，与查询电话号码无关。"}, "sentence_index": 6, "correct_answer": "查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "不懂的地方要自己查老师。", "explanation": "这里应该用〈问〉。查是查阅资料、核实，向老师请教要用问。"}, {"text": "他每天都查笑话，大家都很喜欢他。", "explanation": "这里应该用〈讲〉。查不能用于讲笑话，讲笑话要用讲。"}, {"text": "妈妈查完碗，就去睡觉了。", "explanation": "这里应该用〈洗〉。查是查阅、核实，洗碗要用洗，不能说查碗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90129, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想把这个字的意思查。", "corrected_sentence": "我想把这个字的意思查清楚。", "error_description": "“把”字句中，动词“查”后须有补语或“了”；只说“我想把这个字的意思查”不完整，应说“我想把这个字的意思查清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90129, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告的数据你要认真查一场。", "corrected_sentence": "这份报告的数据你要认真查一遍。", "error_description": "量词用错：“场”用于比赛、雨、病等事件，不能用于“查”这类动作；动作“查”的量词应用“遍”。应说“这份报告的数据你要认真查一遍。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
