INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90130, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "检查;调查;翻阅以了解情况。", "primary_collocate": null, "pronunciation": "chá", "ipa": "ʈʂʰa˧˥", "syllable_count": 1, "sentences": [{"text": "警察正在查这件事。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师每天都要查作业。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上车后，工作人员来查票。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给我查了一下血。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关的人要查我的行李。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司派人去查这个月的账。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理叫小王把问题查清楚。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车上有人查过我的身份证。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们得查一查水管为什么漏水。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们查了三天，才发现问题。", "target_word": "查", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "查查", "label": "重叠"}, {"form": "查了", "label": "体标"}, {"form": "查过", "label": "体标"}], "register": "中性", "sense_fingerprint": "检查、调查某事以弄清情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '133a0cf0-cdf6-4e93-b59b-2c72829dec62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90130, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "查", "is_correct": true, "explanation": "正确答案：查（chá，第二声），意思是检查、调查。"}, {"text": "插", "is_correct": false, "explanation": "插（chā，第一声）与查（chá，第二声）声调不同，意思是插入。"}, {"text": "常", "is_correct": false, "explanation": "常（cháng）与查（chá）韵母不同，多了 ng，意思是经常。"}, {"text": "扎", "is_correct": false, "explanation": "扎（zhá）与查（chá）声母不同，zh 对 ch，意思是扎进、扎针。"}, {"text": "闸", "is_correct": false, "explanation": "闸（zhá）与查（chá）声母不同，zh 对 ch，意思是闸门。"}], "explanations": {"查": "正确答案：查（chá，第二声），意思是检查、调查。", "插": "插（chā，第一声）与查（chá，第二声）声调不同，意思是插入。", "常": "常（cháng）与查（chá）韵母不同，多了 ng，意思是经常。", "扎": "扎（zhá）与查（chá）声母不同，zh 对 ch，意思是扎进、扎针。", "闸": "闸（zhá）与查（chá）声母不同，zh 对 ch，意思是闸门。"}, "sentence_index": null, "correct_answer": "查"}, "level_3": {"options": [{"text": "查", "is_correct": true, "explanation": "正确：「警察正在查这件事」中的“查”表示调查，与“警察”和“这件事”相合。"}, {"text": "忘", "is_correct": false, "explanation": "语义：“忘”是忘记，与警察处理案件的语境相反。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”只能买东西，不能说“买这件事”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只能搭配食物，不能说“吃这件事”。"}], "explanations": {"查": "正确：「警察正在查这件事」中的“查”表示调查，与“警察”和“这件事”相合。", "忘": "语义：“忘”是忘记，与警察处理案件的语境相反。", "买": "搭配：“买”只能买东西，不能说“买这件事”。", "吃": "搭配：“吃”只能搭配食物，不能说“吃这件事”。"}, "sentence_index": 0, "correct_answer": "查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈一看我的脸，就查出了我的心情。", "explanation": "这里应该用〈看出〉。查出用于查明事实或问题，心情要用看出。"}, {"text": "我把电视的声音查小了一点。", "explanation": "这里应该用〈调〉。查是检查、调查，调节音量要用调。"}, {"text": "妈妈把葱查得很碎，放进了汤里。", "explanation": "这里应该用〈切〉。查是检查、调查，切葱要用切，不能说查得很碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90130, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "查", "is_correct": true, "explanation": "正确答案：查（chá，第二声），意思是检查、调查。"}, {"text": "叉", "is_correct": false, "explanation": "叉（chā，第一声）与查（chá，第二声）声调不同，意思是叉子。"}, {"text": "长", "is_correct": false, "explanation": "长（cháng）与查（chá）韵母不同，多了 ng，意思是长短。"}, {"text": "馋", "is_correct": false, "explanation": "馋（chán）与查（chá）韵母不同，多了 n，意思是贪吃。"}, {"text": "柴", "is_correct": false, "explanation": "柴（chái）与查（chá）韵母不同，ai 对 a，意思是柴火。"}], "explanations": {"查": "正确答案：查（chá，第二声），意思是检查、调查。", "叉": "叉（chā，第一声）与查（chá，第二声）声调不同，意思是叉子。", "长": "长（cháng）与查（chá）韵母不同，多了 ng，意思是长短。", "馋": "馋（chán）与查（chá）韵母不同，多了 n，意思是贪吃。", "柴": "柴（chái）与查（chá）韵母不同，ai 对 a，意思是柴火。"}, "sentence_index": null, "correct_answer": "查"}, "level_3": {"options": [{"text": "查", "is_correct": true, "explanation": "正确：「经理叫小王把问题查清楚」中的“查”表示调查、核实，与“清楚”相合。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”不能用于“问题”，不能说“煮清楚”。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”是丢弃，不能用于“把问题……清楚”的结构。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”是丢失，与“弄清楚问题”的目的相反。"}], "explanations": {"查": "正确：「经理叫小王把问题查清楚」中的“查”表示调查、核实，与“清楚”相合。", "煮": "搭配：“煮”不能用于“问题”，不能说“煮清楚”。", "扔": "搭配：“扔”是丢弃，不能用于“把问题……清楚”的结构。", "丢": "语义：“丢”是丢失，与“弄清楚问题”的目的相反。"}, "sentence_index": 6, "correct_answer": "查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他查了我一眼，就转身走了。", "explanation": "这里应该用〈看〉。查是检查、核实，不用于一瞥。"}, {"text": "他很快就把饭查完了。", "explanation": "这里应该用〈吃〉。查指检查、核实，不能用于吃饭。"}, {"text": "这首歌他查得很好听。", "explanation": "这里应该用〈唱〉。查不能用于唱歌，唱歌要用唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会计把这笔账查。", "corrected_sentence": "会计把这笔账查清楚了。", "error_description": "“把”字句中，动词“查”后要有补语或“了”，只说“把这笔账查”不完整，应说“把这笔账查清楚了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经过查他的身份证了。", "corrected_sentence": "我们已经查过他的身份证了。", "error_description": "“过”是动词后的体标，应说“查过”，“过查”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
