INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90131, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纪念碑是立起来记住一个人或一件大事的石头。", "primary_collocate": null, "pronunciation": "jì niàn bēi", "ipa": "tɕi˥˩ njɛn˥˩ peɪ˥", "syllable_count": 3, "sentences": [{"text": "村口立着一座纪念碑。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座纪念碑是给谁立的？", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把纪念碑擦得很干净。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纪念碑是石头做的，很高。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们在纪念碑下面等。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有一座纪念碑，纪念一位老人。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在纪念碑前站了很久。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带着我们去看纪念碑。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纪念碑上有一行红色的字。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园东边新立了一座纪念碑。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "紀念碑", "label": "繁体"}], "register": "中性", "sense_fingerprint": "立起来记住一个人或一件大事的石头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcba9692-cced-4943-a1b3-313ddd5c52a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90131, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纪念碑", "is_correct": true, "explanation": "“纪念碑”是立起来的碑，可以立在村口，用“座”计量，符合语境。"}, {"text": "树", "is_correct": false, "explanation": "搭配：树用“棵”计量，不能说“村口立着一座树”。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：村口立不起一座海洋。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能立在村口，句子说的是一个立起来的东西。"}], "explanations": {"纪念碑": "“纪念碑”是立起来的碑，可以立在村口，用“座”计量，符合语境。", "树": "搭配：树用“棵”计量，不能说“村口立着一座树”。", "海洋": "语义：村口立不起一座海洋。", "天空": "语义：天空不能立在村口，句子说的是一个立起来的东西。"}, "sentence_index": 0, "correct_answer": "纪念碑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座纪念碑里陈列着很多古董。", "explanation": "这里应该用〈博物馆〉。纪念碑是立在外面的碑，不能陈列古董，陈列古董要用博物馆。"}, {"text": "这座纪念碑的墙上贴满了老照片。", "explanation": "这里应该用〈纪念堂〉。纪念碑是立起来的石碑，墙上贴照片的是纪念堂。"}, {"text": "这座纪念碑里挂着一幅油画。", "explanation": "这里应该用〈美术馆〉。纪念碑不能挂画，挂油画要在美术馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90131, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纪念碑", "is_correct": true, "explanation": "“纪念碑”是可以站在它前面的碑，符合“站在……前”的语境。"}, {"text": "微风", "is_correct": false, "explanation": "配价：“站在……前”要接能作参照的处所，微风不是可以站在前面的地方。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：人可以站在纪念碑前，却不能站在歌声前。"}, {"text": "早晨", "is_correct": false, "explanation": "配价：“站在……前”需要空间处所，“早晨”是时间，不能作站立的参照。"}], "explanations": {"纪念碑": "“纪念碑”是可以站在它前面的碑，符合“站在……前”的语境。", "微风": "配价：“站在……前”要接能作参照的处所，微风不是可以站在前面的地方。", "歌声": "语义：人可以站在纪念碑前，却不能站在歌声前。", "早晨": "配价：“站在……前”需要空间处所，“早晨”是时间，不能作站立的参照。"}, "sentence_index": 6, "correct_answer": "纪念碑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里的纪念碑很深，大家每天从里面打水。", "explanation": "这里应该用〈水井〉。水井很深，可以从里面打水；纪念碑是为纪念人或事而立的，不能打水。"}, {"text": "办公室里的纪念碑坏了，大家喝不上热水。", "explanation": "这里应该用〈饮水机〉。饮水机用来供应饮用水，纪念碑不能给人提供热水。"}, {"text": "公园东边新建了一座纪念碑，里面种满了花。", "explanation": "这里应该用〈花坛〉。花坛用来种花，纪念碑是为纪念人或事而立的，不能种花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90131, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里人在路口立了一只纪念碑。", "corrected_sentence": "村里人在路口立了一座纪念碑。", "error_description": "错误：“一只纪念碑”。正确：“一座纪念碑”。纪念碑是碑形建筑，量词用“座”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90131, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去过那只纪念碑。", "corrected_sentence": "我们去过那座纪念碑。", "error_description": "错误：“那只纪念碑”。正确：“那座纪念碑”。纪念碑是碑形建筑，量词用“座”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
