INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90132, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为纪念重要人物或事件而建立的碑形建筑。", "primary_collocate": null, "pronunciation": "jì niàn bēi", "ipa": "tɕi˥˩ njɛn˥˩ peɪ˥", "syllable_count": 3, "sentences": [{"text": "广场中间有一座纪念碑。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们在纪念碑前放了很多花。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座纪念碑是为了纪念英雄建的。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们去纪念碑那里参观。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纪念碑上刻着很多名字。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座纪念碑已经有五十年的历史了。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边建了一座纪念碑。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们站在纪念碑旁边照了相。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纪念碑的后面是一个大公园。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每年都会去看那座纪念碑。", "target_word": "纪念碑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "紀念碑", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为纪念重要人物或事件而建的碑形建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcba9692-cced-4943-a1b3-313ddd5c52a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纪念碑", "is_correct": true, "explanation": "“纪念碑”是立起来的碑形建筑，可以立在广场中间，用“座”计量，符合语境。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：广场中间立不起一座海洋。"}, {"text": "水井", "is_correct": false, "explanation": "搭配：水井用“口”计量，不能说“广场中间有一座水井”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空无法作为建筑物立在广场中间。"}], "explanations": {"纪念碑": "“纪念碑”是立起来的碑形建筑，可以立在广场中间，用“座”计量，符合语境。", "海洋": "语义：广场中间立不起一座海洋。", "水井": "搭配：水井用“口”计量，不能说“广场中间有一座水井”。", "天空": "语义：天空无法作为建筑物立在广场中间。"}, "sentence_index": 0, "correct_answer": "纪念碑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座纪念碑里陈列着很多文物。", "explanation": "这里应该用〈纪念馆〉。纪念碑是立在露天的碑形建筑，不能陈列文物，陈列文物要用纪念馆。"}, {"text": "这座纪念碑的大厅里挂满了老照片。", "explanation": "这里应该用〈纪念堂〉。纪念碑没有可以挂照片的大厅，有大厅、能挂照片的是纪念堂。"}, {"text": "这座纪念碑的展厅里摆着一排玻璃柜。", "explanation": "这里应该用〈展览馆〉。纪念碑不是展厅，玻璃展柜要放在展览馆里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纪念碑", "is_correct": true, "explanation": "“纪念碑”是可以建在海边的碑形建筑，用“座”计量，符合语境。"}, {"text": "树", "is_correct": false, "explanation": "搭配：树用“棵”计量，不能说“建了一座树”。"}, {"text": "海风", "is_correct": false, "explanation": "语义：海风是流动的空气，不能被建造。"}, {"text": "沙滩", "is_correct": false, "explanation": "语义：沙滩本身就在海边，不是人能建起来的东西。"}], "explanations": {"纪念碑": "“纪念碑”是可以建在海边的碑形建筑，用“座”计量，符合语境。", "树": "搭配：树用“棵”计量，不能说“建了一座树”。", "海风": "语义：海风是流动的空气，不能被建造。", "沙滩": "语义：沙滩本身就在海边，不是人能建起来的东西。"}, "sentence_index": 6, "correct_answer": "纪念碑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路口的纪念碑上画着箭头，告诉司机往哪儿开。", "explanation": "这里应该用〈路标〉。路标用来指示方向，纪念碑是为纪念人或事而立的，不用来指路。"}, {"text": "街边的纪念碑上写着：新商场开业，全场打八折。", "explanation": "这里应该用〈广告牌〉。广告牌用来做宣传，纪念碑是为纪念人或事而立的，不用来登开业广告。"}, {"text": "这座纪念碑里装满了水，可以用来浇花。", "explanation": "这里应该用〈水塔〉。水塔用来储水，纪念碑不储水，不能装满水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小时候去过那只纪念碑。", "corrected_sentence": "他小时候去过那座纪念碑。", "error_description": "错误：“那只纪念碑”。正确：“那座纪念碑”。纪念碑是碑形建筑，量词用“座”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们已经把这只纪念碑修好了。", "corrected_sentence": "工人们已经把这座纪念碑修好了。", "error_description": "量词错误：“纪念碑”的量词应为“座”，“只”用于动物等，不能用来计量纪念碑。正确说法是“这座纪念碑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
