INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90133, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西用力放进很小的地方。", "primary_collocate": null, "pronunciation": "sāi", "ipa": "sai˥", "syllable_count": 1, "sentences": [{"text": "他把书塞进了书包里。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈往我的包里塞了两个苹果。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子太小了，我塞不进去这件大衣。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手机塞到口袋里就跑了。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别往抽屉里塞这么多东西。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把信塞进门缝，转身走了。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用力把毛巾塞进小包里。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把糖塞进嘴里，不说话。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他偷偷往我手里塞了一张纸条。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把脏衣服塞到床底下。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "塞了", "label": "体标"}, {"form": "塞着", "label": "体标"}, {"form": "塞过", "label": "体标"}, {"form": "塞进", "label": "复合"}], "register": "口语", "sense_fingerprint": "塞(sāi)：用力把东西放进狭小的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00c0937f-79df-4cbd-baf9-10d33b79d40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90133, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "塞", "is_correct": true, "explanation": "正确：塞（sāi），意思是把东西用力放进狭小的地方。"}, {"text": "猜", "is_correct": false, "explanation": "cāi 与 sāi 声母不同（c 与 s），意思是猜测。"}, {"text": "筛", "is_correct": false, "explanation": "shāi 与 sāi 声母不同（sh 与 s），意思是筛子。"}, {"text": "胎", "is_correct": false, "explanation": "tāi 与 sāi 声母不同（t 与 s），意思是胎儿或轮胎。"}, {"text": "三", "is_correct": false, "explanation": "sān 与 sāi 韵母不同（n 与 i），意思是数字三。"}], "explanations": {"塞": "正确：塞（sāi），意思是把东西用力放进狭小的地方。", "猜": "cāi 与 sāi 声母不同（c 与 s），意思是猜测。", "筛": "shāi 与 sāi 声母不同（sh 与 s），意思是筛子。", "胎": "tāi 与 sāi 声母不同（t 与 s），意思是胎儿或轮胎。", "三": "sān 与 sāi 韵母不同（n 与 i），意思是数字三。"}, "sentence_index": null, "correct_answer": "塞"}, "level_3": {"options": [{"text": "塞", "is_correct": true, "explanation": "正确：“塞”表示用力把东西放进狭小处，与“塞进书包里”相符。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指用火毁坏或加热，与“放进书包里”不符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象须是食物，不能说“吃进书包里”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于用水清洁物品，不能说“洗进书包里”。"}], "explanations": {"塞": "正确：“塞”表示用力把东西放进狭小处，与“塞进书包里”相符。", "烧": "语义：“烧”指用火毁坏或加热，与“放进书包里”不符。", "吃": "搭配：“吃”的对象须是食物，不能说“吃进书包里”。", "洗": "搭配：“洗”用于用水清洁物品，不能说“洗进书包里”。"}, "sentence_index": 0, "correct_answer": "塞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把咖啡塞在了桌子上。", "explanation": "这里应该用〈放〉。“塞”要把东西用力挤进狭小的地方，平放在桌面上不需要这样。"}, {"text": "工人把灯塞在了天花板上。", "explanation": "这里应该用〈挂〉。“塞”要把东西挤进狭小的空间，灯挂在天花板上不是挤入，应该用“挂”。"}, {"text": "老师把花瓶塞在了讲台上。", "explanation": "这里应该用〈摆〉。“塞”指挤进狭小处，花瓶放在讲台上应该用“摆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90133, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "塞", "is_correct": true, "explanation": "正确：塞（sāi），意思是把东西用力放进狭小的地方。"}, {"text": "赛", "is_correct": false, "explanation": "sài 与 sāi 声调不同（第四声与第一声），意思是比赛。"}, {"text": "灾", "is_correct": false, "explanation": "zāi 与 sāi 声母不同（z 与 s），意思是灾害。"}, {"text": "栽", "is_correct": false, "explanation": "zāi 与 sāi 声母不同（z 与 s），意思是栽种。"}], "explanations": {"塞": "正确：塞（sāi），意思是把东西用力放进狭小的地方。", "赛": "sài 与 sāi 声调不同（第四声与第一声），意思是比赛。", "灾": "zāi 与 sāi 声母不同（z 与 s），意思是灾害。", "栽": "zāi 与 sāi 声母不同（z 与 s），意思是栽种。"}, "sentence_index": null, "correct_answer": "塞"}, "level_3": {"options": [{"text": "塞", "is_correct": true, "explanation": "正确：“塞”表示用力把东西放进狭小处，与“用力把毛巾塞进小包里”相符。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指用气流推动，与“把毛巾放进小包”不符。"}, {"text": "晒", "is_correct": false, "explanation": "搭配：“晒”指日光照射，不能说“晒进小包里”。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”指用热使物体变形或受热，与此句情境不符。"}], "explanations": {"塞": "正确：“塞”表示用力把东西放进狭小处，与“用力把毛巾塞进小包里”相符。", "吹": "语义：“吹”指用气流推动，与“把毛巾放进小包”不符。", "晒": "搭配：“晒”指日光照射，不能说“晒进小包里”。", "烫": "语义：“烫”指用热使物体变形或受热，与此句情境不符。"}, "sentence_index": 6, "correct_answer": "塞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把桌子塞进了操场。", "explanation": "这里应该用〈搬〉。“塞”指把东西用力挤进很小的地方，操场很大，搬运桌子应该用“搬”。"}, {"text": "他把水塞进了杯子里。", "explanation": "这里应该用〈倒〉。“塞”要把固体用力挤进小地方，水是液体，应该用“倒”。"}, {"text": "孩子把风筝塞到了天上。", "explanation": "这里应该用〈放〉。“塞”指把东西用力挤进很小的地方，天空很大，放风筝应该用“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90133, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把钥匙塞出了裤兜里。", "corrected_sentence": "他把钥匙塞进了裤兜里。", "error_description": "补语“出”表示由里向外，与表示在内部的“裤兜里”矛盾；应改用表示向内的“进”，说“塞进了裤兜里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90133, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把毛巾塞着进了小包里。", "corrected_sentence": "我把毛巾塞进了小包里。", "error_description": "“着”表示持续的状态，与“塞进了”这种已完成的动作矛盾，应去掉“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
