INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90134, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放进空隙，填满。", "primary_collocate": null, "pronunciation": "sāi", "ipa": "sai˥", "syllable_count": 1, "sentences": [{"text": "他用纸把窗户的缝塞住了。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拿布塞着瓶口，不让水流出来。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用纸巾塞住了流血的鼻子。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上有个小洞，爸爸用纸团塞上了。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天他们用旧报纸塞门缝，风就进不来。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用耳机塞住耳朵，不想听吵闹声。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用泥把墙缝塞满了。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用毛巾塞一下水管的口，水就不漏了。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把瓶子的口塞好，放回了冰箱。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不让鞋变形，她往鞋里塞满了纸。", "target_word": "塞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "塞了", "label": "体标"}, {"form": "塞着", "label": "体标"}, {"form": "塞住", "label": "复合"}, {"form": "塞满", "label": "复合"}], "register": "口语", "sense_fingerprint": "塞(sāi)：把东西放进空隙或洞口，堵住或填满", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00c0937f-79df-4cbd-baf9-10d33b79d40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "塞", "is_correct": true, "explanation": "正确：塞（sāi），意思是把东西放进空隙使其堵住或填满。"}, {"text": "猜", "is_correct": false, "explanation": "cāi 与 sāi 声母不同（c 与 s），意思是猜测。"}, {"text": "筛", "is_correct": false, "explanation": "shāi 与 sāi 声母不同（sh 与 s），意思是筛子。"}, {"text": "胎", "is_correct": false, "explanation": "tāi 与 sāi 声母不同（t 与 s），意思是胎儿或轮胎。"}, {"text": "三", "is_correct": false, "explanation": "sān 与 sāi 韵母不同（n 与 i），意思是数字三。"}], "explanations": {"塞": "正确：塞（sāi），意思是把东西放进空隙使其堵住或填满。", "猜": "cāi 与 sāi 声母不同（c 与 s），意思是猜测。", "筛": "shāi 与 sāi 声母不同（sh 与 s），意思是筛子。", "胎": "tāi 与 sāi 声母不同（t 与 s），意思是胎儿或轮胎。", "三": "sān 与 sāi 韵母不同（n 与 i），意思是数字三。"}, "sentence_index": null, "correct_answer": "塞"}, "level_3": {"options": [{"text": "塞", "is_correct": true, "explanation": "正确：“塞”表示把东西填入缝隙使其堵住，与“用纸把窗户的缝塞住了”相符。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”指分割，与“把窗缝堵住”不符。"}, {"text": "刷", "is_correct": false, "explanation": "搭配：“刷”指涂抹或清洁，不能说“刷住窗缝”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热食物，与此句情境无关。"}], "explanations": {"塞": "正确：“塞”表示把东西填入缝隙使其堵住，与“用纸把窗户的缝塞住了”相符。", "切": "语义：“切”指分割，与“把窗缝堵住”不符。", "刷": "搭配：“刷”指涂抹或清洁，不能说“刷住窗缝”。", "煮": "语义：“煮”指加热食物，与此句情境无关。"}, "sentence_index": 0, "correct_answer": "塞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把水塞进了瓶子里。", "explanation": "这里应该用〈倒〉。“塞”指把东西挤进空隙或狭小处，液体要倒入瓶中，不能用“塞”。"}, {"text": "她把碗塞在了桌子上。", "explanation": "这里应该用〈放〉。“塞”要把东西填进或挤进空隙，碗平放在桌面上不是填空隙，应该用“放”。"}, {"text": "工人把沙发塞进了广场。", "explanation": "这里应该用〈搬〉。“塞”要把东西填进空隙，沙发放进广场不是填空隙，应该用“搬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90134, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "塞", "is_correct": true, "explanation": "正确：塞（sāi），意思是把东西放进空隙使其堵住或填满。"}, {"text": "赛", "is_correct": false, "explanation": "sài 与 sāi 声调不同（第四声与第一声），意思是比赛。"}, {"text": "灾", "is_correct": false, "explanation": "zāi 与 sāi 声母不同（z 与 s），意思是灾害。"}, {"text": "栽", "is_correct": false, "explanation": "zāi 与 sāi 声母不同（z 与 s），意思是栽种。"}], "explanations": {"塞": "正确：塞（sāi），意思是把东西放进空隙使其堵住或填满。", "赛": "sài 与 sāi 声调不同（第四声与第一声），意思是比赛。", "灾": "zāi 与 sāi 声母不同（z 与 s），意思是灾害。", "栽": "zāi 与 sāi 声母不同（z 与 s），意思是栽种。"}, "sentence_index": null, "correct_answer": "塞"}, "level_3": {"options": [{"text": "塞", "is_correct": true, "explanation": "正确：“塞”表示把东西填满空隙，与“工人用泥把墙缝塞满了”相符。"}, {"text": "拔", "is_correct": false, "explanation": "语义：“拔”指把东西拉出，与“把墙缝填满”相反。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：“扫”指清除，不能说“扫满墙缝”。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”指掘出，与“填满”相反。"}], "explanations": {"塞": "正确：“塞”表示把东西填满空隙，与“工人用泥把墙缝塞满了”相符。", "拔": "语义：“拔”指把东西拉出，与“把墙缝填满”相反。", "扫": "搭配：“扫”指清除，不能说“扫满墙缝”。", "挖": "语义：“挖”指掘出，与“填满”相反。"}, "sentence_index": 6, "correct_answer": "塞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用窗帘塞住了阳光。", "explanation": "这里应该用〈挡〉。“塞住”指把东西填入空隙使其不通，不用于遮挡阳光。"}, {"text": "他用伞塞住了太阳。", "explanation": "这里应该用〈遮〉。“塞住”指把东西填入空隙使其堵死，不用于遮挡太阳。"}, {"text": "工作人员用栏杆塞住了人群。", "explanation": "这里应该用〈拦〉。“塞住”指填入空隙使其堵死，不用于拦住人群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用布把门缝塞开了。", "corrected_sentence": "她用布把门缝塞住了。", "error_description": "补语“开”表示打开，与“塞”的堵住义相反。正确的补语是“住”，应说“塞住了门缝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用布塞了着窗缝，怕风吹进来。", "corrected_sentence": "他用布塞着窗缝，怕风吹进来。", "error_description": "“了”与“着”不能同时出现在同一个动词后，“塞了着”自相矛盾。应去掉“了”，说“塞着窗缝”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ed71ce-13b7-4378-b8fc-afd2c89213ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
