INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物的起因或来历。", "primary_collocate": null, "pronunciation": "yóu lái", "ipa": "joʊ˧˥ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "你知道春节的由来吗？", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个名字有一个有趣的由来。", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了端午节的由来。", "target_word": "由来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街的名字有什么由来？", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶知道这道菜的由来。", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词语的由来很有意思。", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想了解这个习惯的由来。", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里写了这座桥的由来。", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说不清这个故事的由来。", "target_word": "由来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个节日的由来，大家都不太清楚。", "target_word": "由来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "事物的起因或来历", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e31bf265-f6b7-4c52-b5e9-a7a9c46a99af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "由来", "is_correct": true, "explanation": "正确答案。读作 yóu lái（第二声），意思是事物的起因或来历。"}, {"text": "又来", "is_correct": false, "explanation": "yòu lái（第四声）与 yóu lái（第二声）只有第一个音节声调不同，意思是“再来、又来”，与题目词义无关。"}, {"text": "有赖", "is_correct": false, "explanation": "yǒu lài 与 yóu lái 两个音节的声调都不同，意思是“依靠”，不是起因或来历。"}, {"text": "有来", "is_correct": false, "explanation": "yǒu lái（第三声）与 yóu lái（第二声）只有第一个音节声调不同，见于“有来有往”，意思与起因、来历无关。"}], "explanations": {"由来": "正确答案。读作 yóu lái（第二声），意思是事物的起因或来历。", "又来": "yòu lái（第四声）与 yóu lái（第二声）只有第一个音节声调不同，意思是“再来、又来”，与题目词义无关。", "有赖": "yǒu lài 与 yóu lái 两个音节的声调都不同，意思是“依靠”，不是起因或来历。", "有来": "yǒu lái（第三声）与 yóu lái（第二声）只有第一个音节声调不同，见于“有来有往”，意思与起因、来历无关。"}, "sentence_index": null, "correct_answer": "由来"}, "level_3": {"options": [{"text": "由来", "is_correct": true, "explanation": "正确：由来指事物的起因或来历，可以说“春节的由来”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”只用于商品或服务，不能说“春节的价格”。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指人或有形事物的外形，春节不能说外貌。"}, {"text": "芳名", "is_correct": false, "explanation": "语域：“芳名”是敬辞，只用于问别人的名字，用在这里语域不对，也不指来历。"}], "explanations": {"由来": "正确：由来指事物的起因或来历，可以说“春节的由来”。", "价格": "语义：“价格”只用于商品或服务，不能说“春节的价格”。", "外貌": "体貌：“外貌”指人或有形事物的外形，春节不能说外貌。", "芳名": "语域：“芳名”是敬辞，只用于问别人的名字，用在这里语域不对，也不指来历。"}, "sentence_index": 0, "correct_answer": "由来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天的由来很好。", "explanation": "这里应该用〈心情〉。由来指事物的起因或来历，不能用来描述人的心情好坏；说心情要用“心情”。"}, {"text": "他今天没来上课的由来是生病了。", "explanation": "这里应该用〈原因〉。由来指事物（节日、名字等）的起因或来历，说某人某次行为为什么发生要用“原因”。"}, {"text": "这次旅行是我最难忘的由来。", "explanation": "这里应该用〈经历〉。由来指事物的起因或来历，不指个人亲身遭遇过的事；说“最难忘的经历”要用“经历”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "由来", "is_correct": true, "explanation": "正确：由来指习惯的起因或来历，可以说“这个习惯的由来”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或物的重量，习惯没有体重，这里说不通。"}, {"text": "尊姓", "is_correct": false, "explanation": "语域：“尊姓”是敬辞，只用于问人的姓氏，不能用来问习惯的来历。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体态特征，习惯没有身高，这里不成立。"}], "explanations": {"由来": "正确：由来指习惯的起因或来历，可以说“这个习惯的由来”。", "体重": "语义：“体重”指人或物的重量，习惯没有体重，这里说不通。", "尊姓": "语域：“尊姓”是敬辞，只用于问人的姓氏，不能用来问习惯的来历。", "身高": "体貌：“身高”是人的体态特征，习惯没有身高，这里不成立。"}, "sentence_index": 6, "correct_answer": "由来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说话的由来很大声。", "explanation": "这里应该用〈音量〉。由来指事物的起因或来历，不指说话的音量；说音量大小要用“音量”。"}, {"text": "这件衣服的由来很亮。", "explanation": "这里应该用〈外观〉。由来指事物的起因或来历，不能用来描述衣服亮不亮这类外观。"}, {"text": "这次比赛的由来是我们赢了。", "explanation": "这里应该用〈结果〉。由来指事物的起因或来历，不指事情最后的结果；说比赛的结果要用“结果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条街的名字有一个奇怪由来。", "corrected_sentence": "这条街的名字有一个奇怪的由来。", "error_description": "“奇怪”和“由来”之间漏了结构助词“的”。形容词修饰名词时要用“的”，应说“奇怪的由来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人们都很清楚这个节日的了由来。", "corrected_sentence": "老人们都很清楚这个节日的由来。", "error_description": "“了”不能插在定语“的”和“由来”之间，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
