INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90137, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "经纪是帮别人买卖东西，从中赚点钱的人或工作。", "primary_collocate": null, "pronunciation": "jīng jì", "ipa": "tɕiŋ˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "他以前做经纪，常帮朋友买卖房子。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当了十年经纪，认识很多客人。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做经纪要诚实，客人才会相信你。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我舅舅做经纪，专门帮人买卖旧车。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个经纪帮我找到了一套便宜的房子。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠做经纪赚钱，生活过得不错。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经纪这份工作，要多和人说话。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位经纪告诉我，这块地很快就能卖出去。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一个经纪，帮我卖掉旧房子。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李年轻时做过经纪，什么人都认识。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经纪人", "label": "复合"}, {"form": "经纪公司", "label": "复合"}], "register": "中性", "sense_fingerprint": "帮人买卖东西、赚佣金的人或工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9b14e92-3a0f-44e7-b1c6-121a5b382a86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90137, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "经纪", "is_correct": true, "explanation": "经纪：帮人买卖东西、从中赚佣金的人或工作，即本词。"}, {"text": "竞技", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是竞技比赛。"}, {"text": "京剧", "is_correct": false, "explanation": "jù 与 jì 韵母不同，意思是京剧。"}, {"text": "星际", "is_correct": false, "explanation": "xīng 与 jīng 声母不同，意思是星际（太空中各星球之间）。"}, {"text": "精致", "is_correct": false, "explanation": "zhì 与 jì 声母不同，意思是精致、细致。"}], "explanations": {"经纪": "经纪：帮人买卖东西、从中赚佣金的人或工作，即本词。", "竞技": "jìng（第四声）与 jīng（第一声）声调不同，意思是竞技比赛。", "京剧": "jù 与 jì 韵母不同，意思是京剧。", "星际": "xīng 与 jīng 声母不同，意思是星际（太空中各星球之间）。", "精致": "zhì 与 jì 声母不同，意思是精致、细致。"}, "sentence_index": null, "correct_answer": "经纪"}, "level_3": {"options": [{"text": "经纪", "is_correct": true, "explanation": "经纪：帮人买卖房子、从中赚佣金的人，与句中“常帮朋友买卖房子”相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师做饭，与“帮朋友买卖房子”的工作不相干。"}, {"text": "大使", "is_correct": false, "explanation": "语域：大使是正式的外交职务，与“常帮朋友买卖房子”这种私人口语语境不搭。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机负责开车，并不做买卖房子的中间工作。"}], "explanations": {"经纪": "经纪：帮人买卖房子、从中赚佣金的人，与句中“常帮朋友买卖房子”相符。", "厨师": "语义：厨师做饭，与“帮朋友买卖房子”的工作不相干。", "大使": "语域：大使是正式的外交职务，与“常帮朋友买卖房子”这种私人口语语境不搭。", "司机": "语义：司机负责开车，并不做买卖房子的中间工作。"}, "sentence_index": 0, "correct_answer": "经纪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老王做经纪，专门管理旧车店。", "explanation": "这里应该用〈经理〉。经纪是帮人买卖、赚佣金的人，管理店铺的是经理，经纪不指管理工作。"}, {"text": "他是这所学校的经纪，负责给学生上课。", "explanation": "这里应该用〈老师〉。经纪是帮人买卖、赚佣金的人，给学生上课的是老师，经纪不指这种工作。"}, {"text": "小张有十年经纪，客人都很信任他。", "explanation": "这里应该用〈经验〉。“经纪”指职业，不能用来表示积累下来的年限，应说“有十年经验”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90137, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "经纪", "is_correct": true, "explanation": "经纪：帮人买卖东西、从中赚佣金的人或工作，即本词。"}, {"text": "精力", "is_correct": false, "explanation": "lì 与 jì 声母不同，意思是精力（体力和精神）。"}, {"text": "精密", "is_correct": false, "explanation": "mì 与 jì 声母不同，意思是精密、细致。"}, {"text": "精辟", "is_correct": false, "explanation": "pì 与 jì 声母不同，意思是精辟、透彻。"}, {"text": "精细", "is_correct": false, "explanation": "xì 与 jì 声母不同，意思是精细、仔细。"}], "explanations": {"经纪": "经纪：帮人买卖东西、从中赚佣金的人或工作，即本词。", "精力": "lì 与 jì 声母不同，意思是精力（体力和精神）。", "精密": "mì 与 jì 声母不同，意思是精密、细致。", "精辟": "pì 与 jì 声母不同，意思是精辟、透彻。", "精细": "xì 与 jì 声母不同，意思是精细、仔细。"}, "sentence_index": null, "correct_answer": "经纪"}, "level_3": {"options": [{"text": "经纪", "is_correct": true, "explanation": "经纪：帮人买卖、居中牵线的工作，与句中“要多和人说话”相符。"}, {"text": "潜水员", "is_correct": false, "explanation": "语义：潜水员大多在水下独自工作，与“要多和人说话”的要求矛盾。"}, {"text": "矿工", "is_correct": false, "explanation": "语义：矿工在井下作业，很少与人交谈，与句中的建议不符。"}, {"text": "院士", "is_correct": false, "explanation": "语域：院士是正式的学术称号，与“要多和人说话”这种口语化的建议不搭。"}], "explanations": {"经纪": "经纪：帮人买卖、居中牵线的工作，与句中“要多和人说话”相符。", "潜水员": "语义：潜水员大多在水下独自工作，与“要多和人说话”的要求矛盾。", "矿工": "语义：矿工在井下作业，很少与人交谈，与句中的建议不符。", "院士": "语域：院士是正式的学术称号，与“要多和人说话”这种口语化的建议不搭。"}, "sentence_index": 6, "correct_answer": "经纪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老李年轻时做过一只经纪，什么人都认识。", "explanation": "量词错误：“只”多用于动物或小件物品，指人的经纪应用“个”或“位”。"}, {"text": "老李年轻时做过一把经纪，什么人都认识。", "explanation": "量词错误：“把”用于有柄的器具，不能用来数经纪这个人，应用“个”或“位”。"}, {"text": "老李年轻时做过一块经纪，什么人都认识。", "explanation": "量词错误：“块”用于块状的物体，不能用来数人，应用“个”或“位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我请了一只经纪，帮我卖掉了房子。", "corrected_sentence": "我请了一位经纪，帮我卖掉了房子。", "error_description": "错误形式是“一只经纪”，“只”用于动物或小件物品，指人的经纪要用“位”或“个”；正确形式是“一位经纪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从没做了经纪，对这行不太了解。", "corrected_sentence": "他从没做过经纪，对这行不太了解。", "error_description": "错误形式是“没做了经纪”，“没”的否定句里不能用“了”；正确形式是“没做过经纪”，表示从未有过这种经历要用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
