INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90138, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为买卖双方牵线、居间成交并收取佣金的活动；也指从事此业的人。", "primary_collocate": null, "pronunciation": "jīng jì", "ipa": "tɕiŋ˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "做经纪不用本钱，只靠中间的佣金。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从事经纪多年，对市场很熟。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司只做经纪，不做装修。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经纪就是在买家和卖家之间牵线。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做经纪，每成交一单就拿一笔佣金。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想学经纪，将来帮人买卖房子。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把经纪当成一份长期的工作。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人做了一辈子经纪，从不骗人。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买家和卖家都信他，所以他做经纪很成功。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多人在网上做经纪，帮人卖东西。", "target_word": "经纪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经纪人", "label": "复合"}, {"form": "经纪公司", "label": "复合"}], "register": "中性", "sense_fingerprint": "居间牵线成交并收佣金的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9b14e92-3a0f-44e7-b1c6-121a5b382a86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90138, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "经纪", "is_correct": true, "explanation": "经纪：为买卖双方牵线、居间成交并收佣金的活动，即本词。"}, {"text": "精力", "is_correct": false, "explanation": "lì 与 jì 声母不同，意思是精力。"}, {"text": "精密", "is_correct": false, "explanation": "mì 与 jì 声母不同，意思是精密。"}, {"text": "精辟", "is_correct": false, "explanation": "pì 与 jì 声母不同，意思是精辟。"}, {"text": "精细", "is_correct": false, "explanation": "xì 与 jì 声母不同，意思是精细。"}], "explanations": {"经纪": "经纪：为买卖双方牵线、居间成交并收佣金的活动，即本词。", "精力": "lì 与 jì 声母不同，意思是精力。", "精密": "mì 与 jì 声母不同，意思是精密。", "精辟": "pì 与 jì 声母不同，意思是精辟。", "精细": "xì 与 jì 声母不同，意思是精细。"}, "sentence_index": null, "correct_answer": "经纪"}, "level_3": {"options": [{"text": "经纪", "is_correct": true, "explanation": "经纪：居中牵线、靠佣金赚钱的活动，与“不用本钱，只靠中间的佣金”相符。"}, {"text": "农业", "is_correct": false, "explanation": "语义：农业需要土地和投入，与“不用本钱”矛盾。"}, {"text": "餐饮", "is_correct": false, "explanation": "语义：餐饮要有店面和食材，与“不用本钱”矛盾。"}, {"text": "墙壁", "is_correct": false, "explanation": "搭配：“做”不能带“墙壁”这类实物名词，说“做墙壁”不通。"}], "explanations": {"经纪": "经纪：居中牵线、靠佣金赚钱的活动，与“不用本钱，只靠中间的佣金”相符。", "农业": "语义：农业需要土地和投入，与“不用本钱”矛盾。", "餐饮": "语义：餐饮要有店面和食材，与“不用本钱”矛盾。", "墙壁": "搭配：“做”不能带“墙壁”这类实物名词，说“做墙壁”不通。"}, "sentence_index": 0, "correct_answer": "经纪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经纪就是长期管理一家企业。", "explanation": "这里应该用〈经营〉。经营指长期管理一家企业，经纪是居中牵线、收佣金的活动。"}, {"text": "经纪就是从实践中学到的东西。", "explanation": "这里应该用〈经验〉。经验是从实践中学到的东西，经纪指居间成交的活动。"}, {"text": "经纪就是亲身遇到的事情。", "explanation": "这里应该用〈经历〉。经历是亲身遇到的事情，经纪并不指这种意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90138, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "经纪", "is_correct": true, "explanation": "经纪：为买卖双方牵线、居间成交并收佣金的活动，即本词。"}, {"text": "竞技", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是竞技。"}, {"text": "京剧", "is_correct": false, "explanation": "jù 与 jì 韵母不同，意思是京剧。"}, {"text": "星际", "is_correct": false, "explanation": "xīng 与 jīng 声母不同，意思是星际。"}, {"text": "精致", "is_correct": false, "explanation": "zhì 与 jì 声母不同，意思是精致。"}], "explanations": {"经纪": "经纪：为买卖双方牵线、居间成交并收佣金的活动，即本词。", "竞技": "jìng（第四声）与 jīng（第一声）声调不同，意思是竞技。", "京剧": "jù 与 jì 韵母不同，意思是京剧。", "星际": "xīng 与 jīng 声母不同，意思是星际。", "精致": "zhì 与 jì 声母不同，意思是精致。"}, "sentence_index": null, "correct_answer": "经纪"}, "level_3": {"options": [{"text": "经纪", "is_correct": true, "explanation": "经纪：居中牵线、赚佣金的活动，可以当成一份长期的工作，与句意相符。"}, {"text": "玩笑", "is_correct": false, "explanation": "语义：玩笑不是职业，不能当成长期的工作。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能当成工作。"}, {"text": "皇位", "is_correct": false, "explanation": "语域：“皇位”是古代的政治名号，与现代口语说的“一份工作”不搭。"}], "explanations": {"经纪": "经纪：居中牵线、赚佣金的活动，可以当成一份长期的工作，与句意相符。", "玩笑": "语义：玩笑不是职业，不能当成长期的工作。", "天气": "语义：天气是自然现象，不能当成工作。", "皇位": "语域：“皇位”是古代的政治名号，与现代口语说的“一份工作”不搭。"}, "sentence_index": 6, "correct_answer": "经纪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他请了一只经纪，很快就把房子卖了。", "explanation": "量词错误：这里经纪指人，“只”多用于动物，应用“位”或“个”。"}, {"text": "他认识一把经纪，常帮人卖旧车。", "explanation": "量词错误：“把”用于有柄的器具，不能用来数人，应用“位”或“个”。"}, {"text": "那块经纪在网上帮人卖东西。", "explanation": "量词错误：“块”用于块状物，不能用来数人，应用“位”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一只经纪，客人都很信任她。", "corrected_sentence": "她是一位经纪，客人都很信任她。", "error_description": "错误形式是“一只经纪”，“只”用于动物或小件物品，指人的经纪要用“位”或“个”；正确形式是“一位经纪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我大学毕业后做过一年经纪过，很有收获。", "corrected_sentence": "我大学毕业后做过一年经纪，很有收获。", "error_description": "错误形式是句中“经纪过”后多出一个“过”，“过”不能跟在名词后面表示经历；正确形式是“做过一年经纪”，去掉多余的“过”，“过”只紧跟动词“做”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
