INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90139, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "故事里住在天上的神仙。", "primary_collocate": null, "pronunciation": "tiān rén", "ipa": "tʰjɛn˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "故事里的天人住在天上。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶给我讲过一个天人的故事。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天人穿着漂亮的白衣服，从云里走出来。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说天人有一双会飞的翅膀。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩说，她看见天人在云上跳舞。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个天人从天上来到人间。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古画里的天人在天上飘着。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里，天人不用吃饭，也不会老。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问妈妈，天人为什么住在天上。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天人看见人间的河，就下来玩了。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "故事和传说中住在天上的神仙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5461ebd-d36b-4535-a617-61dd6497bd0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90139, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天人", "is_correct": true, "explanation": "目标词，指住在天上的神仙，听到的读音即为此词。"}, {"text": "天然", "is_correct": false, "explanation": "韵母不同：rán（第二声）与 rén（第二声）的韵母分别是 an 与 en，意思是自然。"}, {"text": "千人", "is_correct": false, "explanation": "声母不同：qiān（第一声）与 tiān 的声母分别是 q 与 t，意思是一千个人。"}, {"text": "天文", "is_correct": false, "explanation": "声母不同：wén（第二声）与 rén 的声母分别是 w 与 r，意思是天文学。"}], "explanations": {"天人": "目标词，指住在天上的神仙，听到的读音即为此词。", "天然": "韵母不同：rán（第二声）与 rén（第二声）的韵母分别是 an 与 en，意思是自然。", "千人": "声母不同：qiān（第一声）与 tiān 的声母分别是 q 与 t，意思是一千个人。", "天文": "声母不同：wén（第二声）与 rén 的声母分别是 w 与 r，意思是天文学。"}, "sentence_index": null, "correct_answer": "天人"}, "level_3": {"options": [{"text": "天人", "is_correct": true, "explanation": "“故事里”的天人住在天上，指神仙，与语境相符。"}, {"text": "鼹鼠", "is_correct": false, "explanation": "语义：鼹鼠生活在地下，与“住在天上”正好相反。"}, {"text": "鲤鱼", "is_correct": false, "explanation": "语义：鲤鱼生活在水里，不能住在天上。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“住”需要有生命的主体，石头没有生命，不能住在天上。"}], "explanations": {"天人": "“故事里”的天人住在天上，指神仙，与语境相符。", "鼹鼠": "语义：鼹鼠生活在地下，与“住在天上”正好相反。", "鲤鱼": "语义：鲤鱼生活在水里，不能住在天上。", "石头": "语义：“住”需要有生命的主体，石头没有生命，不能住在天上。"}, "sentence_index": 0, "correct_answer": "天人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人们相信，好人死后会去天人。", "explanation": "这里应该用〈天堂〉。天堂指死后灵魂去的地方，天人指神仙，不能用来表示地点。"}, {"text": "人们常把护士称为白衣天人。", "explanation": "这里应该用〈天使〉。“白衣天使”是固定说法，指护士；天人指神仙，不能这样称呼护士。"}, {"text": "他们一直在天人快乐地生活。", "explanation": "这里应该用〈人间〉。人间指人类生活的世界，天人指神仙，不能指人所生活的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90139, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天人", "is_correct": true, "explanation": "“古画里”的天人在天上飘着，指神仙，与语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“飘着”多用于云、雾、衣裙等轻的东西，石头不能飘在天上。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有飘浮的能力，与“在天上飘着”的描述矛盾。"}, {"text": "锅", "is_correct": false, "explanation": "语义：锅是厨房用具，不会在天上飘着。"}], "explanations": {"天人": "“古画里”的天人在天上飘着，指神仙，与语境相符。", "石头": "搭配：“飘着”多用于云、雾、衣裙等轻的东西，石头不能飘在天上。", "桌子": "语义：桌子没有飘浮的能力，与“在天上飘着”的描述矛盾。", "锅": "语义：锅是厨房用具，不会在天上飘着。"}, "sentence_index": 6, "correct_answer": "天人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的天人很好，适合去公园散步。", "explanation": "这里应该用〈天气〉。天气指大气的冷暖、晴雨等状况，天人指神仙，不能用来描述天气。"}, {"text": "桌上摆着一把天人。", "explanation": "量词用错。“天人”指神仙或人，不能用“把”，“把”多用于有柄或有把手的东西。"}, {"text": "学校希望培养很多天人。", "explanation": "这里应该用〈人才〉。天人指神仙，不能泛指一批人才，学校不会“培养”神仙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
