INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指神仙；也指才能出众的人。", "primary_collocate": null, "pronunciation": "tiān rén", "ipa": "tʰjɛn˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "传说里的天人住在云上。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年纪轻轻就能作曲编曲，同行都把她看作天人。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画美得像天人画的。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古书里说，天人可以飞上天。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都觉得他是个天人，什么都会。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老先生才高八斗，人称天人。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里，天人从天上下来看世界。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跳舞的样子，像天人一样。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们说天人不会老，也不会生病。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的才华让人觉得他是天人。", "target_word": "天人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "神仙，或才能出众、像神仙一样的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5461ebd-d36b-4535-a617-61dd6497bd0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90140, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天人", "is_correct": true, "explanation": "目标词，指神仙或才能出众的人，听到的读音即为此词。"}, {"text": "天然", "is_correct": false, "explanation": "韵母不同：rán（第二声）与 rén（第二声）的韵母分别是 an 与 en，意思是自然。"}, {"text": "千人", "is_correct": false, "explanation": "声母不同：qiān（第一声）与 tiān 的声母分别是 q 与 t，意思是一千个人。"}, {"text": "天文", "is_correct": false, "explanation": "声母不同：wén（第二声）与 rén 的声母分别是 w 与 r，意思是天文学。"}], "explanations": {"天人": "目标词，指神仙或才能出众的人，听到的读音即为此词。", "天然": "韵母不同：rán（第二声）与 rén（第二声）的韵母分别是 an 与 en，意思是自然。", "千人": "声母不同：qiān（第一声）与 tiān 的声母分别是 q 与 t，意思是一千个人。", "天文": "声母不同：wén（第二声）与 rén 的声母分别是 w 与 r，意思是天文学。"}, "sentence_index": null, "correct_answer": "天人"}, "level_3": {"options": [{"text": "天人", "is_correct": true, "explanation": "“传说里”的神仙住在云上，“天人”指神仙，与语境相符。"}, {"text": "渔民", "is_correct": false, "explanation": "语义：渔民是在水上劳作的普通人，传说中不会住在云上。"}, {"text": "商人", "is_correct": false, "explanation": "语义：商人是做买卖的人，与“传说里住在云上”的神话色彩不合。"}, {"text": "老百姓", "is_correct": false, "explanation": "语域：“老百姓”是通俗口语词，与这句书面化的传说叙述不协调，而且普通百姓也不住在云上。"}], "explanations": {"天人": "“传说里”的神仙住在云上，“天人”指神仙，与语境相符。", "渔民": "语义：渔民是在水上劳作的普通人，传说中不会住在云上。", "商人": "语义：商人是做买卖的人，与“传说里住在云上”的神话色彩不合。", "老百姓": "语域：“老百姓”是通俗口语词，与这句书面化的传说叙述不协调，而且普通百姓也不住在云上。"}, "sentence_index": 0, "correct_answer": "天人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口站着一只天人。", "explanation": "量词用错。“天人”指神仙或才能出众的人，应用“位”或“个”，不能用“只”，“只”多用于动物。"}, {"text": "天人需要保护环境，珍惜资源。", "explanation": "这里应该用〈人类〉。人类指所有人，天人指神仙或个别才能出众的人，不能泛指全体人类。"}, {"text": "这家公司正在招聘很多天人。", "explanation": "这里应该用〈人才〉。天人指神仙或个别才能出众的人，不能泛指一批人才。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天人", "is_correct": true, "explanation": "“故事里”的天人从天上下来看世界，指神仙，与语境相符。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼生活在水里，不能从天上下来看世界。"}, {"text": "地鼠", "is_correct": false, "explanation": "语义：地鼠住在地下，与“从天上下来”的描述正好相反。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有眼睛，不能从天上下来看世界。"}], "explanations": {"天人": "“故事里”的天人从天上下来看世界，指神仙，与语境相符。", "鱼": "语义：鱼生活在水里，不能从天上下来看世界。", "地鼠": "语义：地鼠住在地下，与“从天上下来”的描述正好相反。", "石头": "语义：石头没有眼睛，不能从天上下来看世界。"}, "sentence_index": 6, "correct_answer": "天人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他相信，人死后灵魂会去天人。", "explanation": "这里应该用〈天堂〉。天堂指死后灵魂去的地方，天人指神仙或才能出众的人，不能用来表示地点。"}, {"text": "我们生活在天人，要善待彼此。", "explanation": "这里应该用〈人间〉。人间指人类生活的世界，天人指神仙或才能出众的人，不能指生活的地方。"}, {"text": "厨房里放着一把天人。", "explanation": "量词用错。“天人”指神仙或人，不能用“把”，“把”多用于有柄或有把手的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
