INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90141, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "符合是跟要求一样,合得上。", "primary_collocate": null, "pronunciation": "fú hé", "ipa": "fu˧˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这个房子符合我们的要求。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成绩符合学校的条件。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服的大小符合我的要求。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说的话不符合事实。", "target_word": "符合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个办法符合大家的想法。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的年龄符合比赛的要求。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店的菜符合我的口味。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说我的作业符合要求了。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样做不符合学校的规定。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我找了很久，才找到符合条件的房子。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "符合了", "label": "体标"}, {"form": "符合过", "label": "体标"}], "register": "中性", "sense_fingerprint": "与要求相合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84adf9-f7e5-4676-ae12-1e74b754fae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90141, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "符合", "is_correct": true, "explanation": "正确：符合 fú hé，即题目所给词。"}, {"text": "复合", "is_correct": false, "explanation": "fù 与 fú 声调不同（第四声与第二声），意思是由几部分组成，不是“相合”。"}, {"text": "附和", "is_correct": false, "explanation": "fù hè 与 fú hé 两个音节声调都不同，意思是跟着别人表态。"}, {"text": "负荷", "is_correct": false, "explanation": "fù hè 与 fú hé 两个音节声调都不同（第四声与第二声），意思是承担的重量或压力，与“相合”无关。"}], "explanations": {"符合": "正确：符合 fú hé，即题目所给词。", "复合": "fù 与 fú 声调不同（第四声与第二声），意思是由几部分组成，不是“相合”。", "附和": "fù hè 与 fú hé 两个音节声调都不同，意思是跟着别人表态。", "负荷": "fù hè 与 fú hé 两个音节声调都不同（第四声与第二声），意思是承担的重量或压力，与“相合”无关。"}, "sentence_index": null, "correct_answer": "符合"}, "level_3": {"options": [{"text": "符合", "is_correct": true, "explanation": "正确：“这个房子符合我们的要求”，表示与要求相合。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：房子没有感情，不能喜欢“要求”，“这个房子喜欢我们的要求”说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“要求”搭配。"}, {"text": "满意", "is_correct": false, "explanation": "配价：“满意”不能带“我们的要求”作宾语。"}], "explanations": {"符合": "正确：“这个房子符合我们的要求”，表示与要求相合。", "喜欢": "语义：房子没有感情，不能喜欢“要求”，“这个房子喜欢我们的要求”说不通。", "吃": "搭配：“吃”不能与“要求”搭配。", "满意": "配价：“满意”不能带“我们的要求”作宾语。"}, "sentence_index": 0, "correct_answer": "符合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父母符合了我的计划。", "explanation": "这里应该用〈同意〉。符合表示与标准、要求相合，对人的赞同要用“同意”。"}, {"text": "我在路上符合了老朋友。", "explanation": "这里应该用〈遇见〉。符合只能接标准、要求，不能接人。"}, {"text": "我很符合这本书。", "explanation": "这里应该用〈喜欢〉。符合不表示对事物的喜爱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90141, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "符合", "is_correct": true, "explanation": "正确：“这家饭店的菜符合我的口味”，表示与口味一致。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人或行为，不能与“口味”搭配。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：菜没有感情，不能讨厌人的口味。"}, {"text": "猜", "is_correct": false, "explanation": "语义：菜不会猜测，“猜”的主体必须是人。"}], "explanations": {"符合": "正确：“这家饭店的菜符合我的口味”，表示与口味一致。", "批评": "搭配：“批评”的对象是人或行为，不能与“口味”搭配。", "讨厌": "语义：菜没有感情，不能讨厌人的口味。", "猜": "语义：菜不会猜测，“猜”的主体必须是人。"}, "sentence_index": 6, "correct_answer": "符合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快符合了新环境。", "explanation": "这里应该用〈适应〉。符合表示与标准一致，人对环境的适应要用“适应”。"}, {"text": "我们符合了比赛。", "explanation": "这里应该用〈参加〉。符合不能接活动，参与比赛要用“参加”。"}, {"text": "我们明天在车站符合。", "explanation": "这里应该用〈见面〉。符合不能表示人与人相见，应说“见面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90141, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告符合着公司的格式。", "corrected_sentence": "这份报告符合公司的格式。", "error_description": "错误：“符合”后加了“着”。“着”表示动作或状态的持续，而“符合”是表示与要求相合的动词，一般不与“着”连用。正确应为“符合公司的格式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90141, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套系统符合得安全标准。", "corrected_sentence": "这套系统符合安全标准。", "error_description": "错误：“符合”是及物动词，后面直接带宾语，中间不能加“得”。正确应为“符合安全标准”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
