INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90143, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "网络语言是大家上网聊天时，常常用的特别说法。", "primary_collocate": null, "pronunciation": "wǎng luò yǔ yán", "ipa": "wɑŋ˨˩˦ lwo˥˩ y˨˩˦ jɛn˧˥", "syllable_count": 4, "sentences": [{"text": "朋友发来一句网络语言，我看了半天才懂。", "target_word": "网络语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络语言听起来很有意思，但是有时候不太清楚。", "target_word": "网络语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和同学聊天时，喜欢说网络语言。", "target_word": "网络语言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网络语言是什么意思？你能给我讲讲吗？", "target_word": "网络语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上网聊天，大家常常用特别的网络语言。", "target_word": "网络语言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟一边玩游戏，一边说网络语言。", "target_word": "网络语言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶学会了几句网络语言，大家都笑了。", "target_word": "网络语言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络语言有时很短，三个字就能表示一个意思。", "target_word": "网络语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把网络语言用在了自己的信里。", "target_word": "网络语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们在群里聊天，说的全是网络语言。", "target_word": "网络语言", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "網絡語言", "label": "繁体"}], "register": "中性", "sense_fingerprint": "上网聊天时常用的特别说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a138068c-42b9-49dc-b301-f8a5ab1de2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90143, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网络语言", "is_correct": true, "explanation": "正确：指上网聊天时的特别说法，所以朋友发来的话要“看了半天才懂”。"}, {"text": "图片", "is_correct": false, "explanation": "搭配：“一句”只用于话语或文字，不说“发来一句图片”。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字不是需要“看了半天才懂”的话语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是一句需要“看了半天才懂”的表达。"}], "explanations": {"网络语言": "正确：指上网聊天时的特别说法，所以朋友发来的话要“看了半天才懂”。", "图片": "搭配：“一句”只用于话语或文字，不说“发来一句图片”。", "数字": "语义：数字不是需要“看了半天才懂”的话语。", "天气": "语义：天气不是一句需要“看了半天才懂”的表达。"}, "sentence_index": 0, "correct_answer": "网络语言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在网上买了一台网络语言。", "explanation": "量词：〈台〉用于机器等，网络语言应该用〈句〉或〈种〉。"}, {"text": "工程师正在调试服务器的网络语言。", "explanation": "词义：这里指〈网络协议〉。网络语言指上网聊天时的用语，不是服务器的通信规则。"}, {"text": "他能流利地说英语和法语两门网络语言。", "explanation": "近义混淆：这里应该说〈外语〉，即英语、法语等外国语言。网络语言是网上交流的用语，不能用来指外国语言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90143, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网络语言", "is_correct": true, "explanation": "正确：奶奶学会的是上网聊天时的说法，所以大家都笑了。"}, {"text": "菜名", "is_correct": false, "explanation": "搭配：“几句”计量话语，菜名不说“学会几句”。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：电影是作品，不说“学会几句”。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不是可以“学会几句”的话语。"}], "explanations": {"网络语言": "正确：奶奶学会的是上网聊天时的说法，所以大家都笑了。", "菜名": "搭配：“几句”计量话语，菜名不说“学会几句”。", "电影": "搭配：电影是作品，不说“学会几句”。", "数学": "语义：数学是学科，不是可以“学会几句”的话语。"}, "sentence_index": 6, "correct_answer": "网络语言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个软件是他用网络语言编写的，运行得很快。", "explanation": "词义：这里应该用〈编程语言〉，即写程序用的语言。网络语言是上网聊天时的特别说法，不能用来编写软件。"}, {"text": "这个村子里的人说的全是网络语言，外人听不懂。", "explanation": "近义混淆：这里应该用〈方言〉。方言是地区口语，网络语言指网上交流的用语。"}, {"text": "他把一块网络语言写进了日记。", "explanation": "量词：〈块〉用于块状物，网络语言应该用〈种〉或〈句〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90143, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我学了过一些网络语言。", "corrected_sentence": "我学过一些网络语言。", "error_description": "体标错误：“学过”已表示经历，不能再加“了”，应说“我学过一些网络语言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90143, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们聊网络语言得很开心。", "corrected_sentence": "孩子们聊网络语言聊得很开心。", "error_description": "补语错误：“聊得很开心”的“得”前要重复动词，应说“聊网络语言聊得很开心”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
