INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在网络交流中形成并流行的语言，包括缩略语、符号等。", "primary_collocate": null, "pronunciation": "wǎng luò yǔ yán", "ipa": "wɑŋ˨˩˦ lwo˥˩ y˨˩˦ jɛn˧˥", "syllable_count": 4, "sentences": [{"text": "网络语言变化很快，每年都有新词。", "target_word": "网络语言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，写作文时不要用网络语言。", "target_word": "网络语言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷看不懂孩子们发的网络语言。", "target_word": "网络语言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“给力”是十几年前流行的网络语言。", "target_word": "网络语言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我妈妈不懂网络语言，所以总是问我。", "target_word": "网络语言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人聊天时常常用网络语言。", "target_word": "网络语言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇新闻里用了很多网络语言，让人觉得很新鲜。", "target_word": "网络语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些缩略语和符号也是网络语言的一部分。", "target_word": "网络语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语的同学也想学一点网络语言。", "target_word": "网络语言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家把网络语言写进了小说里。", "target_word": "网络语言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "網絡語言", "label": "繁体"}], "register": "中性", "sense_fingerprint": "网上交流中形成并流行的语言，含缩略语和符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a138068c-42b9-49dc-b301-f8a5ab1de2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网络语言", "is_correct": true, "explanation": "正确：指网上交流中形成的用语，变化快，每年都有新词。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不会“每年都有新词”，与“新词”的说法不搭。"}, {"text": "汉字", "is_correct": false, "explanation": "搭配：“汉字”是书写符号，不说“变化很快”，也不说“每年都有新词”。"}, {"text": "成语", "is_correct": false, "explanation": "语义：成语是固定的古语词组，不会每年出现新词。"}], "explanations": {"网络语言": "正确：指网上交流中形成的用语，变化快，每年都有新词。", "天气": "语义：天气不会“每年都有新词”，与“新词”的说法不搭。", "汉字": "搭配：“汉字”是书写符号，不说“变化很快”，也不说“每年都有新词”。", "成语": "语义：成语是固定的古语词组，不会每年出现新词。"}, "sentence_index": 0, "correct_answer": "网络语言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "木匠之间用网络语言交流，外人听不懂。", "explanation": "近义混淆：这里指木匠的〈行话〉，即行业内部的专门用语。网络语言只指网上交流的用语，不能用来称呼木匠之间的行话。"}, {"text": "他用网络语言编写了这个网站的程序。", "explanation": "词义：这里指编写程序的〈编程语言〉。网络语言指网上交流中形成的用语，不能用来编写程序。"}, {"text": "他教了我一把网络语言。", "explanation": "量词：〈把〉用于有柄的器具或椅子，网络语言应该用〈句〉或〈种〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网络语言", "is_correct": true, "explanation": "正确：这里指网上用语，用在新闻里让人觉得新鲜。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“用了很多”后接的是语言或表达，天气不能这样用。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“用了很多”后接的是语言或表达，石头不能这样用。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“用了很多”后接的是语言或表达，月亮不能这样用。"}], "explanations": {"网络语言": "正确：这里指网上用语，用在新闻里让人觉得新鲜。", "天气": "搭配：“用了很多”后接的是语言或表达，天气不能这样用。", "石头": "搭配：“用了很多”后接的是语言或表达，石头不能这样用。", "月亮": "搭配：“用了很多”后接的是语言或表达，月亮不能这样用。"}, "sentence_index": 6, "correct_answer": "网络语言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥是用网络语言修建的。", "explanation": "词义：网络语言不是建筑材料，这里应该用〈钢筋〉或〈水泥〉。"}, {"text": "我奶奶只会说老家的网络语言，我们都听不懂。", "explanation": "近义混淆：这里应该用〈方言〉。方言是地区口语，网络语言指网上交流的用语。"}, {"text": "这座网络语言很有名。", "explanation": "量词：〈座〉用于山、楼等大型固定物，网络语言应该用〈种〉或〈套〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经学会了很多只网络语言。", "corrected_sentence": "我已经学会了很多网络语言。", "error_description": "量词错误：“只”用来量动物，不能用来修饰“网络语言”。“很多”可以直接修饰“网络语言”，应去掉“只”，说“学会了很多网络语言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本杂志里用了很网络语言。", "corrected_sentence": "这本杂志里用了很多网络语言。", "error_description": "数量错误：“很”不能直接修饰名词，表示数量要说“很多”，应说“用了很多网络语言”，不说“用了很网络语言”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
