INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90145, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人活到很老，一生应该活的岁数。", "primary_collocate": null, "pronunciation": "tiān nián", "ipa": "tʰjɛn˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "人人都希望能安享天年。", "target_word": "天年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷享尽天年，安详地走了。", "target_word": "天年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他活到九十岁，可以说是终其天年。", "target_word": "天年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人尽享天年，儿孙都在身边。", "target_word": "天年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不少人没能活到天年就去世了。", "target_word": "天年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，好好保养，你能活到天年。", "target_word": "天年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人享尽天年，一生很平安。", "target_word": "天年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古人说，人活一百岁才算尽了天年。", "target_word": "天年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他身体一直很好，一定能享尽天年。", "target_word": "天年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她没有病痛，安安静静地度尽了天年。", "target_word": "天年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "人应当活到的高寿，常与享尽、终其搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8c8e5f0-0406-4b36-85f5-8cace11e88a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90145, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天年", "is_correct": true, "explanation": "天年 tiān nián，指人活到很老的岁数。"}, {"text": "千年", "is_correct": false, "explanation": "千年 qiānnián 与 tiānnián 声母不同（q 与 t），意思是一千年。"}, {"text": "先年", "is_correct": false, "explanation": "先年 xiānnián 与 tiānnián 声母不同（x 与 t），意思是从前的年份。"}, {"text": "天南", "is_correct": false, "explanation": "天南 tiānnán 第二个音节少了介音 i，意思是天的南方。"}], "explanations": {"天年": "天年 tiān nián，指人活到很老的岁数。", "千年": "千年 qiānnián 与 tiānnián 声母不同（q 与 t），意思是一千年。", "先年": "先年 xiānnián 与 tiānnián 声母不同（x 与 t），意思是从前的年份。", "天南": "天南 tiānnán 第二个音节少了介音 i，意思是天的南方。"}, "sentence_index": null, "correct_answer": "天年"}, "level_3": {"options": [{"text": "天年", "is_correct": true, "explanation": "天年：人活到很老的岁数，与“安享”搭配，句子通顺。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“安享”接的是寿数、生活之类，不能接天气。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是可以被“安享”的东西。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不是可以被安享的内容，句子不成立。"}], "explanations": {"天年": "天年：人活到很老的岁数，与“安享”搭配，句子通顺。", "天气": "搭配：“安享”接的是寿数、生活之类，不能接天气。", "汽车": "语义：汽车不是可以被“安享”的东西。", "教室": "语义：教室不是可以被安享的内容，句子不成立。"}, "sentence_index": 0, "correct_answer": "天年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵老树的天年很长。", "explanation": "这里应该用〈寿命〉。天年指人活到很老的岁数，只说人，不说树木；树的寿命要用“寿命”。"}, {"text": "他天年大了，记性不好。", "explanation": "这里应该用〈年纪〉。天年指人应当活到的岁数，不能用来说现在年纪大不大。"}, {"text": "全家为他庆祝天年。", "explanation": "这里应该用〈寿辰〉。庆祝的是寿辰，天年是人应当活到的岁数，不能用来庆祝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90145, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天年", "is_correct": true, "explanation": "天年：人一生应活到的高寿，与“享尽”搭配，句子通顺。"}, {"text": "家具", "is_correct": false, "explanation": "搭配：“享尽”接的是寿数、福分之类，不能接家具。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“享尽”不能和“书包”搭配，句子不通。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不是可以被“享尽”的东西。"}], "explanations": {"天年": "天年：人一生应活到的高寿，与“享尽”搭配，句子通顺。", "家具": "搭配：“享尽”接的是寿数、福分之类，不能接家具。", "书包": "搭配：“享尽”不能和“书包”搭配，句子不通。", "电视": "语义：电视不是可以被“享尽”的东西。"}, "sentence_index": 6, "correct_answer": "天年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的天年很长。", "explanation": "这里应该用〈使用年限〉。天年指人的自然寿命，不能用来说衣物的耐用期限。"}, {"text": "今天是他的天年。", "explanation": "这里应该用〈生日〉。天年是人应活到的寿数，不能用来指生日。"}, {"text": "他天年勤俭持家。", "explanation": "这里应该用〈一生〉。天年是人自然的寿数，是名词，不能用来形容一生的品行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90145, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他身体硬朗，一定能活了天年。", "corrected_sentence": "他身体硬朗，一定能活到天年。", "error_description": "表示“活到某个岁数”要用补语“到”，应说“活到天年”，不能说“活了天年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90145, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人一生平安，享尽了一个天年。", "corrected_sentence": "老人一生平安，享尽了天年。", "error_description": "“天年”是抽象名词，不能用“一个”来计量，应说“享尽了天年”，加上“一个”就不对了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
