INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90147, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "节是大家一起快乐过的特别日子。", "primary_collocate": null, "pronunciation": "jié", "ipa": "tɕjɛ˧˥", "syllable_count": 1, "sentences": [{"text": "这个节我们一起吃饺子吧。", "target_word": "节", "complexity_tier": "T3", "furigana": "zhè ge jié wǒ men yì qǐ chī jiǎo zi ba", "sentence_source": "generated"}, {"text": "这个节大家都很开心。", "target_word": "节", "complexity_tier": "T3", "furigana": "zhè ge jié dà jiā dōu hěn kāi xīn", "sentence_source": "generated"}, {"text": "哪个节最热闹？", "target_word": "节", "complexity_tier": "T3", "furigana": "nǎ ge jié zuì rè nao", "sentence_source": "generated"}, {"text": "今天是什么节？我忘了。", "target_word": "节", "complexity_tier": "T3", "furigana": "jīn tiān shì shén me jié wǒ wàng le", "sentence_source": "generated"}, {"text": "我们一起过这个节吧。", "target_word": "节", "complexity_tier": "T3", "furigana": "wǒ men yì qǐ guò zhè ge jié ba", "sentence_source": "generated"}, {"text": "过节的时候，朋友们来我家玩。", "target_word": "节", "complexity_tier": "T3", "furigana": "guò jié de shí hou péng you men lái wǒ jiā wán", "sentence_source": "generated"}, {"text": "每个节，家里都很热闹。", "target_word": "节", "complexity_tier": "T3", "furigana": "měi ge jié jiā lǐ dōu hěn rè nao", "sentence_source": "generated"}, {"text": "这个节很特别，大家都穿红色。", "target_word": "节", "complexity_tier": "T3", "furigana": "zhè ge jié hěn tè bié dà jiā dōu chuān hóng sè", "sentence_source": "generated"}, {"text": "你最喜欢哪个节？", "target_word": "节", "complexity_tier": "T3", "furigana": "nǐ zuì xǐ huan nǎ ge jié", "sentence_source": "generated"}, {"text": "中国的节，我最喜欢中秋。", "target_word": "节", "complexity_tier": "T3", "furigana": "zhōng guó de jié wǒ zuì xǐ huan zhōng qiū", "sentence_source": "generated"}], "morphological_forms": [{"form": "節", "label": "繁体"}, {"form": "节日", "label": "复合"}, {"form": "春节", "label": "复合"}], "register": "中性", "sense_fingerprint": "大家欢庆的特别日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84adf9-f7e5-4676-ae12-1e74b754fae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90147, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "节", "is_correct": true, "explanation": "节 jié（第二声）指大家一起过的特别日子，正是听到的词。"}, {"text": "解", "is_correct": false, "explanation": "jiě（第三声）与 jié 声调不同，意思是解开、理解。"}, {"text": "介", "is_correct": false, "explanation": "jiè（第四声）与 jié 声调不同，意思是介绍、介于。"}, {"text": "鞋", "is_correct": false, "explanation": "xié 与 jié 声母不同（x 与 j），意思是鞋子。"}], "explanations": {"节": "节 jié（第二声）指大家一起过的特别日子，正是听到的词。", "解": "jiě（第三声）与 jié 声调不同，意思是解开、理解。", "介": "jiè（第四声）与 jié 声调不同，意思是介绍、介于。", "鞋": "xié 与 jié 声母不同（x 与 j），意思是鞋子。"}, "sentence_index": null, "correct_answer": "节"}, "level_3": {"options": [{"text": "节", "is_correct": true, "explanation": "节指大家一起快乐过的特别日子，「这个节我们一起吃饺子吧」句意通顺。"}, {"text": "车", "is_correct": false, "explanation": "语义：车是交通工具，不能与「一起吃饺子」相搭，句意不通。"}, {"text": "镜子", "is_correct": false, "explanation": "搭配：「一起吃饺子」要求指向时间或活动，〈镜子〉不能与之搭配。"}, {"text": "钟", "is_correct": false, "explanation": "语义：钟是计时器具，不是可以「一起吃饺子」的日子。"}], "explanations": {"节": "节指大家一起快乐过的特别日子，「这个节我们一起吃饺子吧」句意通顺。", "车": "语义：车是交通工具，不能与「一起吃饺子」相搭，句意不通。", "镜子": "搭配：「一起吃饺子」要求指向时间或活动，〈镜子〉不能与之搭配。", "钟": "语义：钟是计时器具，不是可以「一起吃饺子」的日子。"}, "sentence_index": 0, "correct_answer": "节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的节是十二月三号，朋友们都会来看我。", "explanation": "这里应该用〈生日〉。生日指个人出生的那一天，不是大家一起快乐过的日子，「节」不能用来指个人生日。"}, {"text": "下周的节很难，我要好好准备。", "explanation": "这里应该用〈考试〉。考试指测验，不是大家一起快乐过的日子，「节」不能用来指考试。"}, {"text": "今晚的节很激烈，我们一起去看吧。", "explanation": "这里应该用〈比赛〉。比赛指竞赛，不是大家一起快乐过的日子，「节」不能用来指比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90147, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "节", "is_correct": true, "explanation": "节 jié（第二声）指大家一起快乐过的特别日子，正是听到的词。"}, {"text": "接", "is_correct": false, "explanation": "jiē（第一声）与 jié（第二声）声调不同，意思是接收、接触，与节日不同。"}, {"text": "姐", "is_correct": false, "explanation": "jiě（第三声）与 jié 声调不同，意思是姐姐。"}, {"text": "借", "is_correct": false, "explanation": "jiè（第四声）与 jié 声调不同，意思是借出或借入。"}], "explanations": {"节": "节 jié（第二声）指大家一起快乐过的特别日子，正是听到的词。", "接": "jiē（第一声）与 jié（第二声）声调不同，意思是接收、接触，与节日不同。", "姐": "jiě（第三声）与 jié 声调不同，意思是姐姐。", "借": "jiè（第四声）与 jié 声调不同，意思是借出或借入。"}, "sentence_index": null, "correct_answer": "节"}, "level_3": {"options": [{"text": "节", "is_correct": true, "explanation": "节指大家一起快乐过的特别日子，「每个节，家里都很热闹」句意通顺。"}, {"text": "老师", "is_correct": false, "explanation": "语义：「每个老师，家里都很热闹」中，老师是人，不是可以按期到来的日子。"}, {"text": "马", "is_correct": false, "explanation": "语义：马是动物，不是按期到来的日子，句意不通。"}, {"text": "字", "is_correct": false, "explanation": "搭配：〈热闹〉描述人群或场合，〈字〉与之不搭配，句意不通。"}], "explanations": {"节": "节指大家一起快乐过的特别日子，「每个节，家里都很热闹」句意通顺。", "老师": "语义：「每个老师，家里都很热闹」中，老师是人，不是可以按期到来的日子。", "马": "语义：马是动物，不是按期到来的日子，句意不通。", "字": "搭配：〈热闹〉描述人群或场合，〈字〉与之不搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的节定在五月，请了很多亲戚朋友。", "explanation": "这里应该用〈婚礼〉。婚礼是两人结婚的仪式，不是大家一起快乐过的日子，「节」不能用来指婚礼。"}, {"text": "我们相识的节是三月十号，我们每年都庆祝。", "explanation": "这里应该用〈纪念日〉。纪念日指纪念某件事的日子，如相识纪念日，不是大家一起快乐过的节日。"}, {"text": "这首歌的节很慢，我们一起听吧。", "explanation": "这里应该用〈节奏〉。节奏指音乐的快慢规律，不是大家一起快乐过的日子，「节」不能单独表示节奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90147, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中秋是只节，大家都很开心。", "corrected_sentence": "中秋是个节，大家都很开心。", "error_description": "〈节〉指大家一起过的日子，量词应用〈个〉。〈只〉多用于动物或成对物品中的单件，不能用来数节日，应说「中秋是个节」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90147, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每年都节过。", "corrected_sentence": "我们每年都过节。", "error_description": "〈过节〉是动宾式离合词，〈节〉是宾语，应说「过节」，「节过」语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90149, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与“羞辱”不是反义关系。"}, {"text": "尊重", "is_correct": true, "explanation": "“尊重”指重视、敬重别人，与“羞辱”意思相反。"}, {"text": "邀请", "is_correct": false, "explanation": "“邀请”指请人来，与“羞辱”没有反义关系。"}, {"text": "拥有", "is_correct": false, "explanation": "“拥有”指占有，与“羞辱”没有反义关系。"}], "correct_answer": "尊重", "explanations": {"观察": "“观察”指仔细看，与“羞辱”不是反义关系。", "尊重": "“尊重”指重视、敬重别人，与“羞辱”意思相反。", "邀请": "“邀请”指请人来，与“羞辱”没有反义关系。", "拥有": "“拥有”指占有，与“羞辱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90149, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "迎接", "is_correct": false, "explanation": "“迎接”指等候并接待来人，与“羞辱”没有反义关系。"}, {"text": "尊重", "is_correct": true, "explanation": "“尊重”指重视、敬重别人，与“羞辱”意思相反。"}, {"text": "喂养", "is_correct": false, "explanation": "“喂养”指给人或动物提供食物，与“羞辱”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指用脑子考虑问题，与“羞辱”没有反义关系。"}], "correct_answer": "尊重", "explanations": {"迎接": "“迎接”指等候并接待来人，与“羞辱”没有反义关系。", "尊重": "“尊重”指重视、敬重别人，与“羞辱”意思相反。", "喂养": "“喂养”指给人或动物提供食物，与“羞辱”没有反义关系。", "思考": "“思考”指用脑子考虑问题，与“羞辱”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90149, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "羞辱是说难听的话，让别人觉得丢脸。", "primary_collocate": null, "pronunciation": "xiū rǔ", "ipa": "ɕjoʊ˥ ʐu˨˩˦", "syllable_count": 2, "sentences": [{"text": "老板当着大家的面羞辱他。", "target_word": "羞辱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说难听的话羞辱我。", "target_word": "羞辱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不应该羞辱别人。", "target_word": "羞辱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在网上羞辱了那位老师。", "target_word": "羞辱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们常常拿他的口音羞辱他。", "target_word": "羞辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从没羞辱过自己的孩子。", "target_word": "羞辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想听你羞辱我的朋友。", "target_word": "羞辱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人骂我，想羞辱我。", "target_word": "羞辱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人羞辱你，你不要生气。", "target_word": "羞辱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用难听的话羞辱了她。", "target_word": "羞辱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "羞辱了", "label": "完成体"}, {"form": "羞辱过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用难听的话让人丢脸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb690da-b4fb-44a8-8915-e03b8c08ddd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90149, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哺育", "is_correct": false, "explanation": "语域：“哺育”偏书面，指养育幼小，与这句口语的语境不符。"}, {"text": "羞辱", "is_correct": true, "explanation": "“羞辱”指用言行让人丢脸，与“当着大家的面”的语境相符。"}, {"text": "抚养", "is_correct": false, "explanation": "搭配：“抚养”的对象多是孩子或亲人，不能用于老板对员工当众的行为。"}, {"text": "梦见", "is_correct": false, "explanation": "语义：“梦见”指睡梦中见到，不能用于当众的行为。"}], "explanations": {"哺育": "语域：“哺育”偏书面，指养育幼小，与这句口语的语境不符。", "羞辱": "“羞辱”指用言行让人丢脸，与“当着大家的面”的语境相符。", "抚养": "搭配：“抚养”的对象多是孩子或亲人，不能用于老板对员工当众的行为。", "梦见": "语义：“梦见”指睡梦中见到，不能用于当众的行为。"}, "sentence_index": 0, "correct_answer": "羞辱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "裁判羞辱了他的成绩。", "explanation": "这里应该用〈肯定〉。“羞辱”针对的是人，不能用于“成绩”这类事物，表示认可别人的成绩要用“肯定”。"}, {"text": "同学们常常羞辱他的口音。", "explanation": "这里应该用〈嘲笑〉。“羞辱”针对的是人，不能说“羞辱口音”，取笑口音要用“嘲笑”。"}, {"text": "我感谢你的帮助，但我羞辱你的帮助。", "explanation": "这里应该用〈感激〉。“羞辱”针对的是人，不能用于“帮助”这类事物，表达对别人帮助的谢意要用“感激”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90149, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拜访", "is_correct": false, "explanation": "搭配：“听”的对象多是话语，不能说“听拜访”。"}, {"text": "羞辱", "is_correct": true, "explanation": "“羞辱”指用难听的话让人丢脸，与“我不想听你”的语境相符。"}, {"text": "招待", "is_correct": false, "explanation": "搭配：“招待”指接待客人，不能与“听”搭配。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”指保存物品，与这句话的意思不相关。"}], "explanations": {"拜访": "搭配：“听”的对象多是话语，不能说“听拜访”。", "羞辱": "“羞辱”指用难听的话让人丢脸，与“我不想听你”的语境相符。", "招待": "搭配：“招待”指接待客人，不能与“听”搭配。", "收藏": "语义：“收藏”指保存物品，与这句话的意思不相关。"}, "sentence_index": 6, "correct_answer": "羞辱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我羞辱他的勇气。", "explanation": "这里应该用〈欣赏〉。“羞辱”针对的是人，不能用于“勇气”这类品质，表示赞赏别人的勇敢要用“欣赏”。"}, {"text": "老师羞辱了他的字。", "explanation": "这里应该用〈称赞〉。“羞辱”的对象必须是人，不能用于“字”这类事物。"}, {"text": "老师认真羞辱了他的作业。", "explanation": "这里应该用〈批改〉。“羞辱”不能用于“作业”，批改作业要用“批改”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90149, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在羞辱过那个孩子。", "corrected_sentence": "他正在羞辱那个孩子。", "error_description": "“正在”表示动作正在进行，不能和表示经历的“过”一起用，应去掉“过”，改为“正在羞辱那个孩子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90149, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我父亲从没羞辱了过我。", "corrected_sentence": "我父亲从没羞辱过我。", "error_description": "表示经历的“过”前面不能再加“了”，“羞辱”后只用“过”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
