INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90150, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用言语或行为使人难堪、蒙受耻辱。", "primary_collocate": null, "pronunciation": "xiū rǔ", "ipa": "ɕjoʊ˥ ʐu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他当众扔掉我的作业，羞辱了我。", "target_word": "羞辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不该用这种方式羞辱学生。", "target_word": "羞辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛后，对手做手势羞辱我们。", "target_word": "羞辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们让她站着道歉，想羞辱她。", "target_word": "羞辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王羞辱了战败的将军。", "target_word": "羞辱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我受不了他那样羞辱我的家人。", "target_word": "羞辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得老板的话是在羞辱她。", "target_word": "羞辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个队员羞辱过对手。", "target_word": "羞辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不停地羞辱着那个孩子。", "target_word": "羞辱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把别人的名字写在墙上，是羞辱人的做法。", "target_word": "羞辱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "羞辱了", "label": "完成体"}, {"form": "羞辱过", "label": "经历体"}, {"form": "羞辱着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "用言行让人难堪受辱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb690da-b4fb-44a8-8915-e03b8c08ddd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90150, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "帮助", "is_correct": false, "explanation": "语义：“帮助”是善意的行为，与“扔掉我的作业”的情境矛盾。"}, {"text": "羞辱", "is_correct": true, "explanation": "“羞辱”指当众让人丢脸，与“扔掉我的作业”的行为相符。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”表示赞扬，与“扔掉我的作业”的行为相反。"}, {"text": "祝福", "is_correct": false, "explanation": "搭配：“祝福”多用于美好的愿望，不与“扔掉作业”的行为搭配。"}], "explanations": {"帮助": "语义：“帮助”是善意的行为，与“扔掉我的作业”的情境矛盾。", "羞辱": "“羞辱”指当众让人丢脸，与“扔掉我的作业”的行为相符。", "夸奖": "语义：“夸奖”表示赞扬，与“扔掉我的作业”的行为相反。", "祝福": "搭配：“祝福”多用于美好的愿望，不与“扔掉作业”的行为搭配。"}, "sentence_index": 0, "correct_answer": "羞辱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们嘲笑他的穿着，我们羞辱他的穿着。", "explanation": "这里应该用〈赞美〉。“羞辱”针对的是人，不能用于“穿着”这类事物，夸奖别人的穿着要用“赞美”。"}, {"text": "我感谢你的耐心，也羞辱你的耐心。", "explanation": "这里应该用〈赞赏〉。“羞辱”针对的是人，不能用于“耐心”这类品质，表示欣赏别人的品质要用“赞赏”。"}, {"text": "我尊重你的意见，也羞辱你的意见。", "explanation": "这里应该用〈重视〉。“羞辱”针对的是人，不能用于“意见”这类事物，认真对待别人的看法要用“重视”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥抱", "is_correct": false, "explanation": "搭配：“拥抱”的动作要由人完成，不能以“老板的话”作为动作的发出者。"}, {"text": "羞辱", "is_correct": true, "explanation": "“羞辱”指让人丢脸，与“她觉得”的感受相符。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”的对象多是食物，不能用于人。"}, {"text": "颁发", "is_correct": false, "explanation": "语义：“颁发”指授予证书或奖励，与“老板的话”的语境不相符。"}], "explanations": {"拥抱": "搭配：“拥抱”的动作要由人完成，不能以“老板的话”作为动作的发出者。", "羞辱": "“羞辱”指让人丢脸，与“她觉得”的感受相符。", "品尝": "搭配：“品尝”的对象多是食物，不能用于人。", "颁发": "语义：“颁发”指授予证书或奖励，与“老板的话”的语境不相符。"}, "sentence_index": 6, "correct_answer": "羞辱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我羞辱他的毅力。", "explanation": "这里应该用〈佩服〉。“羞辱”针对的是人，不能用于“毅力”这类品质，表示敬佩别人的坚持要用“佩服”。"}, {"text": "我同情他的遭遇，也羞辱他的遭遇。", "explanation": "这里应该用〈关心〉。“羞辱”针对的是人，不能用于“遭遇”这类事情，表示挂念别人的处境要用“关心”。"}, {"text": "我原谅了他的过错，也羞辱了他的过错。", "explanation": "这里应该用〈宽恕〉。“羞辱”不能用于“过错”，表示不再计较别人的错误要用“宽恕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他当众被羞辱了我的朋友。", "corrected_sentence": "他当众羞辱了我的朋友。", "error_description": "“羞辱”是及物动词，句中已有施事“他”和宾语“我的朋友”，不能再加“被”表示被动。应去掉“被”，改为“当众羞辱了我的朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候被老师羞辱了过。", "corrected_sentence": "他小时候被老师羞辱过。", "error_description": "表示经历的“过”前面不能再加“了”，“羞辱”后只用“过”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
