INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90152, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女性君主。", "primary_collocate": null, "pronunciation": "nǚ wáng", "ipa": "ny˨˩ wɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "英国女王住在伦敦的王宫里。", "target_word": "女王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位女王很受人民喜欢。", "target_word": "女王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女王今天要去学校看孩子们。", "target_word": "女王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女王管理国家四十年了。", "target_word": "女王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女王的王冠上有很多宝石。", "target_word": "女王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说女王明天会发表重要的讲话。", "target_word": "女王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电视上看到了女王。", "target_word": "女王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的第一位女王很聪明。", "target_word": "女王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女王去世后，国家下了半旗。", "target_word": "女王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家站起来欢迎女王。", "target_word": "女王", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：女性君主，一国之主的女性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f596c5e-c3d7-46bf-a6c0-de9768bc6679') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女王", "is_correct": true, "explanation": "正确：女王指女性君主，住在王宫里符合句意。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生不住在王宫里，与“英国……住在伦敦的王宫里”不合。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民通常不住在王宫里，句子的语境排除了这个词。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“住”的主语须是人，不能说“工厂住在王宫里”。"}], "explanations": {"女王": "正确：女王指女性君主，住在王宫里符合句意。", "学生": "语义：学生不住在王宫里，与“英国……住在伦敦的王宫里”不合。", "农民": "语义：农民通常不住在王宫里，句子的语境排除了这个词。", "工厂": "搭配：“住”的主语须是人，不能说“工厂住在王宫里”。"}, "sentence_index": 0, "correct_answer": "女王"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "康熙的女王住在紫禁城里。", "explanation": "这里应该用〈皇后〉。皇后是皇帝的妻子，不是统治者；女王是自己统治国家的女性君主。"}, {"text": "他是英国的女王，每天都要处理国家大事。", "explanation": "这里应该用〈国王〉。女王指女性君主，男性君主要说国王；“他”是男性，不能称为女王。"}, {"text": "慈宁宫里住着一位女王，她是皇帝的母亲，从来不管国家大事。", "explanation": "这里应该用〈太后〉。太后是皇帝的母亲，并不是自己即位统治国家的君主；女王是统治国家的女性君主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女王", "is_correct": true, "explanation": "正确：女王，“看到了”的对象是人，符合语境。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，不能在电视上“看到”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是用耳朵听的，不能说在电视上看到。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看到”不搭配“味道”，味道要用“闻到”或“尝到”。"}], "explanations": {"女王": "正确：女王，“看到了”的对象是人，符合语境。", "空气": "语义：空气看不见，不能在电视上“看到”。", "声音": "语义：声音是用耳朵听的，不能说在电视上看到。", "味道": "搭配：“看到”不搭配“味道”，味道要用“闻到”或“尝到”。"}, "sentence_index": 6, "correct_answer": "女王"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位女王是国王的妻子。", "explanation": "这里应该用〈王后〉。王后是国王的妻子；女王是自己即位统治国家的君主。"}, {"text": "她是国王的女儿，还没有即位，却已经是女王了。", "explanation": "这里应该用〈公主〉。公主是国王的女儿，未即位时不能称女王；女王是即位统治国家的君主。"}, {"text": "皇帝的妃子住在后宫，她是女王。", "explanation": "这里应该用〈皇妃〉。皇妃是帝王的妃子，不即位统治国家；女王是即位统治国家的君主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只女王昨天接见了外国客人。", "corrected_sentence": "这位女王昨天接见了外国客人。", "error_description": "量词错误：指人的“女王”应说“位”，不能说“只”（“只”多用于动物）。正确说法是“这位女王”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在宫殿里见到了一条女王。", "corrected_sentence": "我们在宫殿里见到了一位女王。", "error_description": "量词错误：指人的“女王”应用“位”，不能用“条”（“条”用于细长的东西）。正确说法是“一位女王”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
