INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90153, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "要地是很要紧的地方。", "primary_collocate": null, "pronunciation": "yào dì", "ipa": "jɑʊ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这座山是军事要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，这里是兵家必争的要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人想占领这个要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "港口是国家的交通要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们守着这个要地好几天。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是守卫全城的要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在要地修了一道墙。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小岛是海上的要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军派人把要地守住了。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市是南北交通的要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "军事要地", "label": "复合"}, {"form": "交通要地", "label": "复合"}, {"form": "处", "label": "量词"}], "register": "书面", "sense_fingerprint": "军事、交通上很要紧的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bac65704-61f2-44c4-864d-746c99e18fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90153, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要地", "is_correct": true, "explanation": "要地指很要紧的地方。这句说这座山是军事上很要紧的地方，只有“要地”符合。"}, {"text": "农田", "is_correct": false, "explanation": "搭配：“军事”后面不能接“农田”，“军事农田”不成立。"}, {"text": "乐园", "is_correct": false, "explanation": "语义：乐园指供人游玩的地方，与“军事”的意思相冲突。"}, {"text": "湖泊", "is_correct": false, "explanation": "语义：湖泊是水域，不能说这座山是湖泊，与题干中的“山”不符。"}], "explanations": {"要地": "要地指很要紧的地方。这句说这座山是军事上很要紧的地方，只有“要地”符合。", "农田": "搭配：“军事”后面不能接“农田”，“军事农田”不成立。", "乐园": "语义：乐园指供人游玩的地方，与“军事”的意思相冲突。", "湖泊": "语义：湖泊是水域，不能说这座山是湖泊，与题干中的“山”不符。"}, "sentence_index": 0, "correct_answer": "要地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅是我们周末常去的要地。", "explanation": "这里应该用〈地方〉。要地指军事、交通等方面很要紧的地方，一般的餐厅只能说地方，不能说要地。"}, {"text": "我家的要地在城南。", "explanation": "这里应该用〈住址〉。要地不指居住的地址，表示地址要用“住址”。"}, {"text": "图书馆是我们学习的要地。", "explanation": "这里应该用〈地方〉。要地指军事、交通等方面很要紧的地方，图书馆只是普通的学习场所，不能说要地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90153, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要地", "is_correct": true, "explanation": "要地指很要紧的地方。这句说他们在某个很要紧的地方修墙，只有“要地”符合。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是喝的东西，不能在上面修墙。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“修”的对象应是具体的场所或物体，“歌曲”不能修墙。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不是可以修墙的地方，与“修了一道墙”不相符。"}], "explanations": {"要地": "要地指很要紧的地方。这句说他们在某个很要紧的地方修墙，只有“要地”符合。", "饮料": "语义：饮料是喝的东西，不能在上面修墙。", "歌曲": "搭配：“修”的对象应是具体的场所或物体，“歌曲”不能修墙。", "课本": "语义：课本是书，不是可以修墙的地方，与“修了一道墙”不相符。"}, "sentence_index": 6, "correct_answer": "要地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每天都在要地上锻炼身体。", "explanation": "这里应该用〈操场〉。要地指很要紧的地方，不用于体育活动的场地。"}, {"text": "我的要地在南方。", "explanation": "这里应该用〈家乡〉。要地指很要紧的地方，不用于指出生或长大的地方。"}, {"text": "这座古镇是游客最爱去的要地。", "explanation": "这里应该用〈景点〉。要地指军事、交通等方面很要紧的地方，不用于游览的景点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90153, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城里有三条军事要地。", "corrected_sentence": "这座城里有三处军事要地。", "error_description": "“要地”的量词应为“处”，应说“三处军事要地”，不能说“三条”（“条”用于河流、道路等细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90153, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵们要地上站岗。", "corrected_sentence": "士兵们在要地上站岗。", "error_description": "表示地点的“要地”前要加介词“在”，应说“在要地上站岗”。去掉“在”后，“要”会被理解为动词“要”，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
