INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90154, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "重要的地方。", "primary_collocate": null, "pronunciation": "yào dì", "ipa": "jɑʊ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "长江边的这个城市是商业要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个渡口是古代的交通要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队在山口这个要地上修了工事。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌军夺走了我们的要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座关口是进入西北的要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子过去是商人必经的要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察守住了城里的几个要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "守住要地，我们才能保护家人。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥头是双方都想争夺的要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城以前是边境上的要地。", "target_word": "要地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "军事要地", "label": "复合"}, {"form": "商业要地", "label": "复合"}, {"form": "处", "label": "量词"}], "register": "书面", "sense_fingerprint": "位置重要、必须把守的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bac65704-61f2-44c4-864d-746c99e18fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90154, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要地", "is_correct": true, "explanation": "要地指重要的地方。这句说这个城市在商业上很重要，只有“要地”符合。"}, {"text": "农田", "is_correct": false, "explanation": "搭配：“商业”不能修饰“农田”，“这个城市是商业农田”不成立。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地是埋葬死者的地方，与“商业”的意思不符，城市也不是墓地。"}, {"text": "山谷", "is_correct": false, "explanation": "语义：山谷是地形，题干说的是城市，不能说城市是商业山谷。"}], "explanations": {"要地": "要地指重要的地方。这句说这个城市在商业上很重要，只有“要地”符合。", "农田": "搭配：“商业”不能修饰“农田”，“这个城市是商业农田”不成立。", "墓地": "语义：墓地是埋葬死者的地方，与“商业”的意思不符，城市也不是墓地。", "山谷": "语义：山谷是地形，题干说的是城市，不能说城市是商业山谷。"}, "sentence_index": 0, "correct_answer": "要地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一拳打中了对手的要地。", "explanation": "这里应该用〈要害〉。要害指身体上致命的部位，要地指很要紧的地方，不用于人的身体部位。"}, {"text": "我们每天在要地上吃午饭。", "explanation": "这里应该用〈食堂〉。要地指很要紧的地方，不用于吃饭的场所；“我们每天在食堂吃午饭”才自然。"}, {"text": "这家咖啡馆是我和朋友聊天的要地。", "explanation": "这里应该用〈地方〉。要地指位置重要、必须把守的地方，普通的咖啡馆不能说要地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要地", "is_correct": true, "explanation": "要地指必须把守的重要地方，与“守住”搭配，题干说警察守住的是城里的几个要地。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是喝的东西，不能被“守住”。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“守住”的对象应是地方或要害，不能说“守住歌曲”。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“守住”和“冰箱”不搭配，冰箱不需要警察把守。"}], "explanations": {"要地": "要地指必须把守的重要地方，与“守住”搭配，题干说警察守住的是城里的几个要地。", "饮料": "语义：饮料是喝的东西，不能被“守住”。", "歌曲": "搭配：“守住”的对象应是地方或要害，不能说“守住歌曲”。", "冰箱": "搭配：“守住”和“冰箱”不搭配，冰箱不需要警察把守。"}, "sentence_index": 6, "correct_answer": "要地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋老房子是他们一家的要地。", "explanation": "这里应该用〈住宅〉。要地指位置很要紧的地方，不用于指居住的房子。"}, {"text": "这家要地的菜是附近最好吃的。", "explanation": "这里应该用〈餐馆〉。要地指军事、交通等方面很要紧的地方，不用于指餐厅。"}, {"text": "我们每周末都在这个要地踢球。", "explanation": "这里应该用〈球场〉。要地指很要紧的地方，不用于体育活动的场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市里有三条商业要地。", "corrected_sentence": "这座城市里有三处商业要地。", "error_description": "“要地”的量词应为“处”，应说“三处商业要地”，不能说“三条”（“条”用于河流、道路等细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "守卫们要地上巡逻。", "corrected_sentence": "守卫们在要地上巡逻。", "error_description": "表示地点的“要地”前要加介词“在”，应说“在要地上巡逻”。去掉“在”后，“要”会被理解为动词，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
