INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90155, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "老鼠是身体小小的、尾巴长长的，会偷吃东西的动物。", "primary_collocate": null, "pronunciation": "lǎo shǔ", "ipa": "lɑʊ˨˩˦ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "厨房里有一只老鼠。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠半夜偷吃了我们的饭。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫看见老鼠就跑过去。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只老鼠的尾巴又细又长。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里有老鼠，晚上总有声音。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠怕猫，看到猫就躲起来。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他害怕老鼠，不敢进仓库。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只老鼠躲在洞里不出来。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠把我的面包吃了一半。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有老鼠跑过，吓了我一跳。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}], "register": "口语", "sense_fingerprint": "身体小、尾巴长、爱偷吃东西的常见小动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '507d993d-83f4-4b0f-871f-33290f029136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90155, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老鼠", "is_correct": true, "explanation": "老鼠：身体小、尾巴长、会偷吃东西的小动物，正确答案。"}, {"text": "老虎", "is_correct": false, "explanation": "hǔ（第三声）与 shǔ（第三声）声母不同（h 与 sh），意思是老虎，不是老鼠。"}, {"text": "老手", "is_correct": false, "explanation": "shǒu（第三声）与 shǔ（第三声）韵母不同（ou 与 u），意思是熟练的人，即老手。"}, {"text": "老树", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同，意思是年老的树，即老树。"}, {"text": "老叔", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，意思是对年长男性的称呼，即老叔。"}], "explanations": {"老鼠": "老鼠：身体小、尾巴长、会偷吃东西的小动物，正确答案。", "老虎": "hǔ（第三声）与 shǔ（第三声）声母不同（h 与 sh），意思是老虎，不是老鼠。", "老手": "shǒu（第三声）与 shǔ（第三声）韵母不同（ou 与 u），意思是熟练的人，即老手。", "老树": "shù（第四声）与 shǔ（第三声）声调不同，意思是年老的树，即老树。", "老叔": "shū（第一声）与 shǔ（第三声）声调不同，意思是对年长男性的称呼，即老叔。"}, "sentence_index": null, "correct_answer": "老鼠"}, "level_3": {"options": [{"text": "老鼠", "is_correct": true, "explanation": "老鼠是厨房里常见的小动物，符合句子的语境。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是大型野生动物，不会出现在厨房里，句子意思说不通。"}, {"text": "狮子", "is_correct": false, "explanation": "语义：狮子是草原上的动物，不会出现在厨房里。"}, {"text": "熊", "is_correct": false, "explanation": "语义：熊是大型野生动物，不会在厨房里出现。"}], "explanations": {"老鼠": "老鼠是厨房里常见的小动物，符合句子的语境。", "老虎": "语义：老虎是大型野生动物，不会出现在厨房里，句子意思说不通。", "狮子": "语义：狮子是草原上的动物，不会出现在厨房里。", "熊": "语义：熊是大型野生动物，不会在厨房里出现。"}, "sentence_index": 0, "correct_answer": "老鼠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用老鼠点击电脑上的图标。", "explanation": "这里应该用〈鼠标〉。老鼠是动物，点击电脑图标要用鼠标。"}, {"text": "一条老鼠从墙角跑过。", "explanation": "这里量词用错了。「条」用于细长的东西，老鼠应该用「只」。"}, {"text": "墙角有一朵老鼠。", "explanation": "这里量词用错了。「朵」用于花、云等，老鼠应该用「只」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90155, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老鼠", "is_correct": true, "explanation": "老鼠是他害怕的对象，符合句子的语境。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不是可以让人“害怕”的对象，句子意思说不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是可以让人害怕的对象，句子意思说不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：这里“害怕”的对象应是具体的动物或东西，“时间”不合句意。"}], "explanations": {"老鼠": "老鼠是他害怕的对象，符合句子的语境。", "面包": "语义：面包不是可以让人“害怕”的对象，句子意思说不通。", "钥匙": "语义：钥匙不是可以让人害怕的对象，句子意思说不通。", "时间": "语义：这里“害怕”的对象应是具体的动物或东西，“时间”不合句意。"}, "sentence_index": 6, "correct_answer": "老鼠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地上有一颗老鼠跑过，吓了我一跳。", "explanation": "这里量词用错了。「颗」用于圆粒状的东西，老鼠应该用「只」。"}, {"text": "地上有一座老鼠跑过，吓了我一跳。", "explanation": "这里量词用错了。「座」用于山、房屋等大型固定的东西，老鼠应该用「只」。"}, {"text": "地上有一张老鼠跑过，吓了我一跳。", "explanation": "这里量词用错了。「张」用于纸、桌子等扁平的东西，老鼠应该用「只」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90155, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里有一颗老鼠。", "corrected_sentence": "院子里有一只老鼠。", "error_description": "量词错误：“老鼠”应说“一只老鼠”，不能说“一颗老鼠”。“颗”用于圆粒状的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90155, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地上有一块老鼠。", "corrected_sentence": "地上有一只老鼠。", "error_description": "量词错误：“老鼠”应说“一只老鼠”，不能说“一块老鼠”。“块”用于块状的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
