INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90156, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "啮齿目动物，体小尾长，门齿发达，常偷吃粮食。", "primary_collocate": null, "pronunciation": "lǎo shǔ", "ipa": "lɑʊ˨˩˦ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "仓库里的老鼠偷吃了不少粮食。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠的牙齿很长，什么都能咬。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在田里放了药，不让老鼠来。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠是一种小动物，尾巴很长。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里养着几只老鼠。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠一晚上能吃很多粮食。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的老鼠多了，大家都很担心。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只老鼠从墙边快速跑过。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠咬坏了我家的书。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠的牙一直在长，所以爱咬东西。", "target_word": "老鼠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}], "register": "中性", "sense_fingerprint": "啮齿目小型动物，门齿发达，常盗食粮食、咬坏物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '507d993d-83f4-4b0f-871f-33290f029136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90156, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老鼠", "is_correct": true, "explanation": "老鼠：啮齿目小动物，门齿发达，常偷吃粮食，正确答案。"}, {"text": "老虎", "is_correct": false, "explanation": "hǔ（第三声）与 shǔ（第三声）声母不同（h 与 sh），意思是老虎，不是老鼠。"}, {"text": "老手", "is_correct": false, "explanation": "shǒu（第三声）与 shǔ（第三声）韵母不同（ou 与 u），意思是熟练的人，即老手。"}, {"text": "老树", "is_correct": false, "explanation": "shù（第四声）与 shǔ（第三声）声调不同，意思是年老的树，即老树。"}, {"text": "老叔", "is_correct": false, "explanation": "shū（第一声）与 shǔ（第三声）声调不同，意思是对年长男性的称呼，即老叔。"}], "explanations": {"老鼠": "老鼠：啮齿目小动物，门齿发达，常偷吃粮食，正确答案。", "老虎": "hǔ（第三声）与 shǔ（第三声）声母不同（h 与 sh），意思是老虎，不是老鼠。", "老手": "shǒu（第三声）与 shǔ（第三声）韵母不同（ou 与 u），意思是熟练的人，即老手。", "老树": "shù（第四声）与 shǔ（第三声）声调不同，意思是年老的树，即老树。", "老叔": "shū（第一声）与 shǔ（第三声）声调不同，意思是对年长男性的称呼，即老叔。"}, "sentence_index": null, "correct_answer": "老鼠"}, "level_3": {"options": [{"text": "老鼠", "is_correct": true, "explanation": "老鼠偷吃粮食，符合句子的语境。"}, {"text": "粮食", "is_correct": false, "explanation": "语义：粮食是被吃的东西，不会自己去“偷吃”，句子意思说不通。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不会在仓库里偷吃粮食，这里指的是啮齿类的小动物。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不会偷吃东西。"}], "explanations": {"老鼠": "老鼠偷吃粮食，符合句子的语境。", "粮食": "语义：粮食是被吃的东西，不会自己去“偷吃”，句子意思说不通。", "老虎": "语义：老虎不会在仓库里偷吃粮食，这里指的是啮齿类的小动物。", "石头": "语义：石头没有生命，不会偷吃东西。"}, "sentence_index": 0, "correct_answer": "老鼠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用老鼠点击电脑上的文件。", "explanation": "这里应该用〈鼠标〉。老鼠是动物，点击电脑上的文件要用鼠标。"}, {"text": "一条老鼠从墙边跑过。", "explanation": "这里量词用错了。「条」用于细长的东西，老鼠应该用「只」。"}, {"text": "仓库里有一把老鼠。", "explanation": "这里量词用错了。「把」用于有把手或能握住的东西，老鼠应该用「只」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老鼠", "is_correct": true, "explanation": "老鼠多了会让人担心，符合句子的语境。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不会因为多了而让人担心，句子意思说不通。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星挂在天上，不会在村里多起来让人担心。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不会在村里“多了”而让大家担心，句子意思说不通。"}], "explanations": {"老鼠": "老鼠多了会让人担心，符合句子的语境。", "钢琴": "语义：钢琴不会因为多了而让人担心，句子意思说不通。", "星星": "语义：星星挂在天上，不会在村里多起来让人担心。", "月亮": "语义：月亮是天体，不会在村里“多了”而让大家担心，句子意思说不通。"}, "sentence_index": 6, "correct_answer": "老鼠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一张老鼠在厨房里找吃的。", "explanation": "这里量词用错了。「张」用于纸、桌子等扁平的东西，老鼠应该用「只」。"}, {"text": "一座老鼠在墙角乱跑。", "explanation": "这里量词用错了。「座」用于山、房屋等大型固定的东西，老鼠应该用「只」。"}, {"text": "一块老鼠在地上跑过。", "explanation": "这里量词用错了。「块」用于块状的东西，老鼠应该用「只」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "田里有一朵老鼠在跑。", "corrected_sentence": "田里有一只老鼠在跑。", "error_description": "量词错误：“老鼠”应说“一只老鼠”，不能说“一朵老鼠”。“朵”用于花、云等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仓库角落里有一颗老鼠。", "corrected_sentence": "仓库角落里有一只老鼠。", "error_description": "量词错误：“老鼠”应说“一只老鼠”，不能说“一颗老鼠”。“颗”用于圆粒状的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
