INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90157, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大学读完后，学校发给学生的一种证明。", "primary_collocate": null, "pronunciation": "xué wèi", "ipa": "ɕɥɛ˧˥ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他大学毕业后拿到了学位。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没写完论文，学校不会授予你学位。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在英国读了三年书，拿到了学位。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校授予毕业生学位。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为考试不过，没有拿到学位。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有学位，他很难找到好工作。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边工作，一边努力读书拿学位。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业的时候，每个学生都会拿到学位。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要读完四年，你就能拿到学位。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他两年前就拿到了这所大学的学位。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "学位证书", "label": "复合"}, {"form": "學位", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大学毕业后学校发给学生的证明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e56a80-f319-4a83-b29d-b93d5094fd86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90157, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学费", "is_correct": false, "explanation": "wèi 与 fèi 声母不同（w / f），意思是学费（上学要交的钱）。"}, {"text": "学位", "is_correct": true, "explanation": "正确答案，学位（xué wèi）指大学毕业后学校发给学生的证明。"}, {"text": "学问", "is_correct": false, "explanation": "wèi 与 wèn 韵母不同（-ei / -en），意思是学问（知识和学识）。"}, {"text": "学妹", "is_correct": false, "explanation": "wèi 与 mèi 声母不同（w / m），意思是学妹（比自己低一届的女同学）。"}], "explanations": {"学费": "wèi 与 fèi 声母不同（w / f），意思是学费（上学要交的钱）。", "学位": "正确答案，学位（xué wèi）指大学毕业后学校发给学生的证明。", "学问": "wèi 与 wèn 韵母不同（-ei / -en），意思是学问（知识和学识）。", "学妹": "wèi 与 mèi 声母不同（w / m），意思是学妹（比自己低一届的女同学）。"}, "sentence_index": null, "correct_answer": "学位"}, "level_3": {"options": [{"text": "退休金", "is_correct": false, "explanation": "语义：退休金是退休后才领取的，与“大学毕业后”的时间不符。"}, {"text": "学位", "is_correct": true, "explanation": "正确答案，学位指大学毕业后学校授予的学业证明，可以说“拿到学位”。"}, {"text": "出生证", "is_correct": false, "explanation": "语义：出生证是出生时办理的，与“大学毕业后”的时间不符。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“拿到”不搭配疾病，应说“得”或“患”。"}], "explanations": {"退休金": "语义：退休金是退休后才领取的，与“大学毕业后”的时间不符。", "学位": "正确答案，学位指大学毕业后学校授予的学业证明，可以说“拿到学位”。", "出生证": "语义：出生证是出生时办理的，与“大学毕业后”的时间不符。", "感冒": "搭配：“拿到”不搭配疾病，应说“得”或“患”。"}, "sentence_index": 0, "correct_answer": "学位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的学位进步得很快。", "explanation": "这里应该用〈学业〉。学业指学习的进度和成绩，可以说“进步”；学位是授予的称号，不能说“进步”。"}, {"text": "他每天早上八点去学位上课。", "explanation": "这里应该用〈学校〉。学校是上课的地方，学位是学校发的证明，不能去学位上课。"}, {"text": "他的学位很深。", "explanation": "这里应该用〈学问〉。学问指知识和学识，可以说“很深”；学位是学校授予的称号，不能说“很深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90157, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毛衣", "is_correct": false, "explanation": "语义：毛衣是衣物，“读书拿毛衣”不能表示取得学业资格。"}, {"text": "车站", "is_correct": false, "explanation": "配价：“拿”在此义下要求物或事作宾语，车站是场所，不能被“拿”。"}, {"text": "学位", "is_correct": true, "explanation": "正确答案，学位指大学授予的学业证明，可以说“拿学位”。"}, {"text": "老师", "is_correct": false, "explanation": "配价：“拿”在此义下不能以人作宾语，“拿老师”不成立。"}], "explanations": {"毛衣": "语义：毛衣是衣物，“读书拿毛衣”不能表示取得学业资格。", "车站": "配价：“拿”在此义下要求物或事作宾语，车站是场所，不能被“拿”。", "学位": "正确答案，学位指大学授予的学业证明，可以说“拿学位”。", "老师": "配价：“拿”在此义下不能以人作宾语，“拿老师”不成立。"}, "sentence_index": 6, "correct_answer": "学位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电影院还有很多学位空着。", "explanation": "这里应该用〈座位〉。学位指学业称号或入学名额，不能指电影院里的座位。"}, {"text": "他的学位是初中。", "explanation": "这里应该用〈学历〉。学历指受教育的程度，“初中”是学历；学位是大学授予的证明，不能说“是初中”。"}, {"text": "他交完了所有学位。", "explanation": "这里应该用〈学费〉。交完的是学费，学位是授予的称号，不能说“交完学位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90157, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年终于拿了到学位。", "corrected_sentence": "她去年终于拿到了学位。", "error_description": "错误：“了”插在“拿”和“到”之间，写成“拿了到”。正确是“拿到了”：“到”是“拿”的结果补语，“了”应放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90157, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在英国拿了过学位，所以对那里很熟悉。", "corrected_sentence": "她在英国拿过学位，所以对那里很熟悉。", "error_description": "错误：“过”已表示经历，不能与“了”同用，此处多了“了”。正确是“拿过学位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
