INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "授予学业达到一定水平者的称号，如学士、硕士、博士。", "primary_collocate": null, "pronunciation": "xué wèi", "ipa": "ɕɥɛ˧˥ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "她的学位是硕士，不是博士。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学士是大学毕业后得到的第一个学位。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有两个学位，一个是学士，一个是硕士。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想读什么学位，硕士还是博士？", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博士是最高的学位。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学位叫文学学士。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥正在国外读博士学位。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请这个学位，你需要先读完大学。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的学位比我们都高。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边工作一边读硕士学位。", "target_word": "学位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "学位论文", "label": "复合"}, {"form": "學位", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学士、硕士、博士等表示学业水平的称号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e56a80-f319-4a83-b29d-b93d5094fd86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90158, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学费", "is_correct": false, "explanation": "wèi 与 fèi 声母不同（w / f），意思是学费（上学要交的钱）。"}, {"text": "学问", "is_correct": false, "explanation": "wèi 与 wèn 韵母不同（-ei / -en），意思是学问（知识和学识）。"}, {"text": "学位", "is_correct": true, "explanation": "正确答案，学位（xué wèi）指学士、硕士、博士等表示学业水平的称号。"}, {"text": "学妹", "is_correct": false, "explanation": "wèi 与 mèi 声母不同（w / m），意思是学妹（比自己低一届的女同学）。"}], "explanations": {"学费": "wèi 与 fèi 声母不同（w / f），意思是学费（上学要交的钱）。", "学问": "wèi 与 wèn 韵母不同（-ei / -en），意思是学问（知识和学识）。", "学位": "正确答案，学位（xué wèi）指学士、硕士、博士等表示学业水平的称号。", "学妹": "wèi 与 mèi 声母不同（w / m），意思是学妹（比自己低一届的女同学）。"}, "sentence_index": null, "correct_answer": "学位"}, "level_3": {"options": [{"text": "职务", "is_correct": false, "explanation": "语义：职务是工作岗位的名称，不能是学历称号，不能说“是硕士”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是身体的高度，与学历称号毫不相干，“是硕士”不成立。"}, {"text": "学位", "is_correct": true, "explanation": "正确答案，学位指硕士、博士等学业称号，可以说“学位是硕士”。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“成绩”说好坏高低，不能用“是硕士”来说明。"}], "explanations": {"职务": "语义：职务是工作岗位的名称，不能是学历称号，不能说“是硕士”。", "身高": "语义：身高是身体的高度，与学历称号毫不相干，“是硕士”不成立。", "学位": "正确答案，学位指硕士、博士等学业称号，可以说“学位是硕士”。", "成绩": "搭配：“成绩”说好坏高低，不能用“是硕士”来说明。"}, "sentence_index": 0, "correct_answer": "学位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大学本科的学位是四年。", "explanation": "这里应该用〈学制〉。学制指学习的年限，可以说“是四年”；学位是称号，不能这样说。"}, {"text": "公交车上还有两个学位空着。", "explanation": "这里应该用〈座位〉。学位指学业称号或入学名额，不能指公交车上的座位。"}, {"text": "他每学期都教很多学位。", "explanation": "这里应该用〈课程〉。教的是课程，学位是授予的称号，不能说“教很多学位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "语义：“身材”指外形和体型，与读书的学业称号无关。"}, {"text": "学堂", "is_correct": false, "explanation": "语义：学堂是上学的地方，不是学业称号，“读博士学堂”不成立。"}, {"text": "学位", "is_correct": true, "explanation": "正确答案，此处指博士学位，与“读博士”搭配。"}, {"text": "朋友", "is_correct": false, "explanation": "配价：“读”在此义下不带人作宾语，“读博士朋友”不成立。"}], "explanations": {"身材": "语义：“身材”指外形和体型，与读书的学业称号无关。", "学堂": "语义：学堂是上学的地方，不是学业称号，“读博士学堂”不成立。", "学位": "正确答案，此处指博士学位，与“读博士”搭配。", "朋友": "配价：“读”在此义下不带人作宾语，“读博士朋友”不成立。"}, "sentence_index": 6, "correct_answer": "学位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的学位是高中。", "explanation": "这里应该用〈学历〉。学历指受教育的程度，“高中”是学历；学位是学校授予的称号，不能说“是高中”。"}, {"text": "他的学位很优秀。", "explanation": "这里应该用〈学业〉。学业指学习的成绩和进度，可以说“优秀”；学位是称号，不能用“优秀”来形容。"}, {"text": "他一年交两万元学位。", "explanation": "这里应该用〈学费〉。交付的是学费，学位是授予的称号，不能用来交付金额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她已经拿到着硕士学位。", "corrected_sentence": "她已经拿到了硕士学位。", "error_description": "错误：“拿到”表示动作已完成，应用“了”；此处用“着”，表示状态持续，与完成义不合。正确是“拿到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经拿了过硕士学位，后来又去国外进修。", "corrected_sentence": "他曾经拿过硕士学位，后来又去国外进修。", "error_description": "错误：“过”已表示经历，不能与“了”同用，此处多了“了”。正确是“拿过硕士学位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
