INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90161, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "联合组织是由很多团体合起来形成的大团体。", "primary_collocate": null, "pronunciation": "lián hé zǔ zhī", "ipa": "ljɛn˧˥ xɤ˧˥ tsu˨˩˦ ʈʂʅ˥", "syllable_count": 4, "sentences": [{"text": "这个联合组织由十个小团体组成。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们成立了一个新的联合组织。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个联合组织帮助很多孩子。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合组织每年开一次大会。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校加入了这个联合组织。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个小公司合起来，成了一个联合组织。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合组织的会员来自不同城市。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合组织为大家提供了很多帮助。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个联合组织的负责人。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的联合组织有三百个会员。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "聯合組織", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由很多团体合起来形成的大团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcba9692-cced-4943-a1b3-313ddd5c52a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90161, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "篮球", "is_correct": false, "explanation": "语义：篮球是球类用品，不能由十个小团体组成。"}, {"text": "联合组织", "is_correct": true, "explanation": "正确。联合组织指由多个团体合起来形成的大团体，与“由十个小团体组成”相符。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不是由团体合成的组织。"}, {"text": "社稷", "is_correct": false, "explanation": "语域：社稷是文言用语，用在这样的现代句子里不协调，且它指国家政权，不是由小团体组成的。"}], "explanations": {"篮球": "语义：篮球是球类用品，不能由十个小团体组成。", "联合组织": "正确。联合组织指由多个团体合起来形成的大团体，与“由十个小团体组成”相符。", "西瓜": "语义：西瓜是水果，不是由团体合成的组织。", "社稷": "语域：社稷是文言用语，用在这样的现代句子里不协调，且它指国家政权，不是由小团体组成的。"}, "sentence_index": 0, "correct_answer": "联合组织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的联合组织坏了，经常死机。", "explanation": "这里应该用〈电脑〉。联合组织指由团体合并而成的组织，不会“死机”，“死机”只用于电脑等机器。"}, {"text": "我们班是一个联合组织，大家一起学习。", "explanation": "这里应该用〈团体〉。联合组织指由多个团体合起来形成的大团体，一个班级不是由几个团体合并而成。"}, {"text": "这个联合组织一岁了，刚学会走路。", "explanation": "这里应该用〈孩子〉。联合组织是由团体组成的组织，不会“学会走路”，这种说法只用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90161, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "联合组织", "is_correct": true, "explanation": "正确。联合组织由多个团体合并而成，其会员来自不同城市，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有会员，也谈不上会员来自哪里。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，不可能有会员。"}, {"text": "江湖", "is_correct": false, "explanation": "语域：江湖是文学性的说法，与“会员”这样的现代组织用语不搭，且江湖本身不能有会员。"}], "explanations": {"联合组织": "正确。联合组织由多个团体合并而成，其会员来自不同城市，与句意相符。", "石头": "语义：石头没有会员，也谈不上会员来自哪里。", "书桌": "语义：书桌是家具，不可能有会员。", "江湖": "语域：江湖是文学性的说法，与“会员”这样的现代组织用语不搭，且江湖本身不能有会员。"}, "sentence_index": 6, "correct_answer": "联合组织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个联合组织结婚十年了，感情很好。", "explanation": "这里应该用〈夫妇〉。联合组织指由团体联合而成的组织，不能结婚，也谈不上感情好。"}, {"text": "他去年考上了联合组织，现在学习很努力。", "explanation": "这里应该用〈大学〉。“考上”用于学校，联合组织不是学校，不能通过考试录取。"}, {"text": "他是一个联合组织，自己经营一家小店。", "explanation": "这里应该用〈个体户〉。联合组织指由团体联合而成的组织，不能用来指一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90161, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "几家协会合起来，成立了一只联合组织。", "corrected_sentence": "几家协会合起来，成立了一个联合组织。", "error_description": "量词错误：“联合组织”的量词应为“个”，“只”用于动物等，不能用来计量组织。正确说法是“成立了一个联合组织”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90161, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三所大学的老师一起组成了一个联合组织着。", "corrected_sentence": "三所大学的老师一起组成了一个联合组织。", "error_description": "体标错误：“着”表示动作的持续或状态，不能加在名词“联合组织”之后。正确说法是“组成了一个联合组织”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
