INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90162, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由若干单位或国家联合而成的组织。", "primary_collocate": null, "pronunciation": "lián hé zǔ zhī", "ipa": "ljɛn˧˥ xɤ˧˥ tsu˨˩˦ ʈʂʅ˥", "syllable_count": 4, "sentences": [{"text": "联合国是一个很大的联合组织。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些国家建立了一个联合组织。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个国家的联合组织开会讨论问题。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合组织决定帮助受灾的国家。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家想加入那个联合组织。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个城市的学校组成了联合组织。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合组织的会议在北京举行。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个联合组织由五个国家组成。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在联合组织工作了十年。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合组织里的每个国家都有一票。", "target_word": "联合组织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "聯合組織", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由若干单位或国家联合而成的组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcba9692-cced-4943-a1b3-313ddd5c52a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90162, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湖泊", "is_correct": false, "explanation": "语义：联合国是国际组织，不是湖泊。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：联合国不是家用器具，句意不通。"}, {"text": "庙堂", "is_correct": false, "explanation": "语域：庙堂是文言用语，与“联合国”这样的现代机构不协调，且庙堂不是组织。"}, {"text": "联合组织", "is_correct": true, "explanation": "正确。联合组织指由若干单位或国家联合而成的组织，与“联合国是一个很大的组织”相符。"}], "explanations": {"湖泊": "语义：联合国是国际组织，不是湖泊。", "洗衣机": "语义：联合国不是家用器具，句意不通。", "庙堂": "语域：庙堂是文言用语，与“联合国”这样的现代机构不协调，且庙堂不是组织。", "联合组织": "正确。联合组织指由若干单位或国家联合而成的组织，与“联合国是一个很大的组织”相符。"}, "sentence_index": 0, "correct_answer": "联合组织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个联合组织今天摔坏了，很可惜。", "explanation": "这里应该用〈手机〉。联合组织指由单位或国家联合而成的组织，不能说“摔坏”，这种说法只用于物品。"}, {"text": "这个联合组织爱吃红烧肉，每天都要吃一碗。", "explanation": "这里应该用〈妈妈〉。联合组织指由单位或国家联合而成的组织，不会吃饭，不能说“爱吃”“每天吃一碗”。"}, {"text": "这个联合组织今天去理发了，头发剪得很短。", "explanation": "这里应该用〈同学〉。联合组织是由单位或国家联合而成的组织，不会去理发，这种说法只用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会召开会议，也谈不上会议在北京举行。"}, {"text": "豆腐", "is_correct": false, "explanation": "语义：豆腐是食品，没有会议。"}, {"text": "江湖", "is_correct": false, "explanation": "语域：江湖是文学性的说法，与正式会议的语域不搭，且江湖不会在北京开会。"}, {"text": "联合组织", "is_correct": true, "explanation": "正确。联合组织指由多个单位或国家联合而成的组织，它的会议在北京举行，合乎句意。"}], "explanations": {"小猫": "语义：小猫不会召开会议，也谈不上会议在北京举行。", "豆腐": "语义：豆腐是食品，没有会议。", "江湖": "语域：江湖是文学性的说法，与正式会议的语域不搭，且江湖不会在北京开会。", "联合组织": "正确。联合组织指由多个单位或国家联合而成的组织，它的会议在北京举行，合乎句意。"}, "sentence_index": 6, "correct_answer": "联合组织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个联合组织很重，搬起来很费力。", "explanation": "这里应该用〈石头〉。联合组织是单位或国家联合而成的组织，没有重量，不能说“搬起来很费力”。"}, {"text": "这个联合组织去年毕业，现在找到了工作。", "explanation": "这里应该用〈学生〉。毕业、找工作只用于人，联合组织是单位或国家联合而成的组织，不能这样说。"}, {"text": "她是一个联合组织，自己开了一家理发店。", "explanation": "这里应该用〈个体户〉。联合组织指由单位或国家联合而成的组织，不能用来指一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个国家的代表商量后，成立了一只联合组织。", "corrected_sentence": "两个国家的代表商量后，成立了一个联合组织。", "error_description": "量词错误：“联合组织”的量词应为“个”，“只”用于动物等，不能用来计量组织。正确说法是“成立了一个联合组织”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些城市的代表开会后，建立了一个联合组织着。", "corrected_sentence": "这些城市的代表开会后，建立了一个联合组织。", "error_description": "体标错误：“着”表示动作的持续或状态，不能加在名词“联合组织”之后。正确说法是“建立了一个联合组织”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
