INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90163, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一件大事现在是什么样子，往哪里变。", "primary_collocate": null, "pronunciation": "jú shì", "ipa": "tɕy˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "比赛到了最后十分钟，局势还不清楚。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谈判桌上，局势一下子对我们有利了。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洪水越来越大，现场的局势变得很危险。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队连丢两球，局势马上变了。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家公司竞争得很厉害，市场的局势越来越复杂。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火灾现场很乱，消防员先看清局势再行动。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下棋时局势变化很快，要多想一步。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到困难要沉着，先冷静地分析局势。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场辩论一开始，我方的局势就很不利。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁也说不准，明天的局势会往哪个方向走。", "target_word": "局势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "局勢", "label": "繁体"}], "register": "书面", "sense_fingerprint": "一件大事当前的样子和变化方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5461ebd-d36b-4535-a617-61dd6497bd0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90163, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "局势", "is_correct": true, "explanation": "“比赛到了最后十分钟”说的是比赛的走向，“还不清楚”针对局势，与语境相符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用的书，与比赛的走向无关，“还不清楚”说不通。"}, {"text": "服装", "is_correct": false, "explanation": "搭配：“还不清楚”说的是情况或结果，不能用于服装。"}, {"text": "奶茶", "is_correct": false, "explanation": "语义：奶茶是饮品，比赛到最后十分钟不会说奶茶还不清楚。"}], "explanations": {"局势": "“比赛到了最后十分钟”说的是比赛的走向，“还不清楚”针对局势，与语境相符。", "课本": "语义：课本是学习用的书，与比赛的走向无关，“还不清楚”说不通。", "服装": "搭配：“还不清楚”说的是情况或结果，不能用于服装。", "奶茶": "语义：奶茶是饮品，比赛到最后十分钟不会说奶茶还不清楚。"}, "sentence_index": 0, "correct_answer": "局势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "操场上的局势很热闹，孩子们在跑来跑去。", "explanation": "这里应该用〈场面〉。局势指事情的发展形势，描述热闹的场景要用场面。"}, {"text": "他现在的局势很困难，身边没有人帮他。", "explanation": "这里应该用〈处境〉。局势指一件大事的形势，说个人的境遇要用处境。"}, {"text": "这台机器的局势很好，能正常运行。", "explanation": "这里应该用〈状况〉。局势指大事的形势，机器的工作情况要用状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "局势", "is_correct": true, "explanation": "“下棋时”的局势随着棋子移动而变化，变化很快，与语境相符。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯是铺在地上的东西，下棋时不会说它变化很快。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：“变化很快”多用于局势、天气等，账单不能这样搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，下棋时不会谈到它的变化。"}], "explanations": {"局势": "“下棋时”的局势随着棋子移动而变化，变化很快，与语境相符。", "地毯": "语义：地毯是铺在地上的东西，下棋时不会说它变化很快。", "账单": "搭配：“变化很快”多用于局势、天气等，账单不能这样搭配。", "冰箱": "语义：冰箱是家用电器，下棋时不会谈到它的变化。"}, "sentence_index": 6, "correct_answer": "局势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生说，病人的局势已经稳定了。", "explanation": "这里应该用〈病情〉。局势指大事的形势，说病人的状况要用病情。"}, {"text": "会场的局势很热烈，大家一起鼓掌。", "explanation": "这里应该用〈气氛〉。局势指事情的走向，描述热烈的感觉要用气氛。"}, {"text": "他在公司的局势很高，大家都很尊敬他。", "explanation": "这里应该用〈地位〉。局势指事情的形势，人在组织中的位置要用地位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只局势很少见。", "corrected_sentence": "这种局势很少见。", "error_description": "量词错误：“局势”是抽象名词，应用“种”，“只”多用于动物或成对物品中的一个，不能说“这只局势”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们很快局势控制住了。", "corrected_sentence": "我们很快把局势控制住了。", "error_description": "把字句错误：“局势”是“控制”的宾语，放在动词前时必须用“把”引出，应说“把局势控制住了”，不能直接说“局势控制住了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
