INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90164, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政治、军事等方面一定时期内的形势。", "primary_collocate": null, "pronunciation": "jú shì", "ipa": "tɕy˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "中东的局势这几年一直不太平静。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国的军队都在边境，局势很紧张。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总统开会讨论国家的政治局势。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争结束后，当地的局势慢慢稳定了。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家分析说，国际局势正在发生变化。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者向大家报告了前线的局势。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军队很快控制了城市，局势平静下来。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保护市民，政府密切关注边境局势。", "target_word": "局势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "局势一天比一天紧张，很多人离开了家乡。", "target_word": "局势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那个地区的局势已经慢慢好起来了。", "target_word": "局势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "局勢", "label": "繁体"}], "register": "书面", "sense_fingerprint": "政治军事方面一段时期的形势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5461ebd-d36b-4535-a617-61dd6497bd0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "局势", "is_correct": true, "explanation": "“中东的局势”指政治、军事方面的形势，“不太平静”符合这一含义。"}, {"text": "课表", "is_correct": false, "explanation": "语义：课表是学校的日程表，不能用来说“不太平静”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不能说“不太平静”，与中东的政治形势无关。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不会“不太平静”，与“中东”的政治形势不符。"}], "explanations": {"局势": "“中东的局势”指政治、军事方面的形势，“不太平静”符合这一含义。", "课表": "语义：课表是学校的日程表，不能用来说“不太平静”。", "体重": "语义：体重是身体的重量，不能说“不太平静”，与中东的政治形势无关。", "味道": "语义：味道不会“不太平静”，与“中东”的政治形势不符。"}, "sentence_index": 0, "correct_answer": "局势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "节日庙会上的局势很热闹，大家来来往往。", "explanation": "这里应该用〈场面〉。局势指事情的发展形势，描述热闹的场景要用场面。"}, {"text": "护士说，病人的局势已经稳定了。", "explanation": "这里应该用〈病情〉。局势指大事的形势，病人的状况要用病情。"}, {"text": "这辆汽车的局势很好，车况不错。", "explanation": "这里应该用〈状况〉。局势指大事的形势，汽车的工作情况要用状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "局势", "is_correct": true, "explanation": "“军队很快控制了城市”之后，局势随之平静下来，与语境相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会因为军队控制城市而平静下来。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是纸上或屏幕上的图，不会“平静下来”。"}, {"text": "发型", "is_correct": false, "explanation": "搭配：“平静下来”多用于局势、情绪，不能用于发型。"}], "explanations": {"局势": "“军队很快控制了城市”之后，局势随之平静下来，与语境相符。", "冰箱": "语义：冰箱不会因为军队控制城市而平静下来。", "地图": "语义：地图是纸上或屏幕上的图，不会“平静下来”。", "发型": "搭配：“平静下来”多用于局势、情绪，不能用于发型。"}, "sentence_index": 6, "correct_answer": "局势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚会上的局势很热烈，大家一起唱歌。", "explanation": "这里应该用〈气氛〉。局势指事情的走向，描述热烈的感觉要用气氛。"}, {"text": "他在班里的局势很高，大家都很佩服他。", "explanation": "这里应该用〈地位〉。局势指事情的形势，人在集体中的位置要用地位。"}, {"text": "她现在的局势很艰难，身边没有朋友。", "explanation": "这里应该用〈处境〉。局势指大事的形势，说个人的境遇要用处境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把局势让人担心。", "corrected_sentence": "这种局势让人担心。", "error_description": "量词错误：“局势”是抽象名词，应用“种”，不能用“把”，“把”多用于有柄的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府必须局势稳住，恢复秩序。", "corrected_sentence": "政府必须把局势稳住，恢复秩序。", "error_description": "把字句错误：“局势”是“稳住”的宾语，放在动词前时必须用“把”引出，应说“把局势稳住”，不能直接说“局势稳住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfcdee2-e4c2-47e9-9808-71d19bc475db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
