INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90166, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把片状的东西粘在另一物体上。", "primary_collocate": null, "pronunciation": "tiē", "ipa": "tʰjɛ˥˥", "syllable_count": 1, "sentences": [{"text": "她在脸上贴了一片面膜。", "target_word": "贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上贴着很多海报。", "target_word": "贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在箱子上贴一张标签。", "target_word": "贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，我们在窗上贴窗花。", "target_word": "贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把膏药贴在腰上。", "target_word": "贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在书包上贴了一张小图片。", "target_word": "贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一张纸条贴在冰箱上。", "target_word": "贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把这张票贴在这里。", "target_word": "贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电脑旁贴了一张便条。", "target_word": "贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们把名字贴在黑板上。", "target_word": "贴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "貼", "label": "繁体"}, {"form": "贴了", "label": "体标"}, {"form": "贴着", "label": "体标"}, {"form": "贴过", "label": "体标"}, {"form": "贴纸", "label": "复合"}, {"form": "张贴", "label": "复合"}], "register": "中性", "sense_fingerprint": "把片状的东西粘在别的物体上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bac65704-61f2-44c4-864d-746c99e18fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90166, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "贴", "is_correct": true, "explanation": "贴 tiē，表示把片状的东西粘在别的物体上。"}, {"text": "铁", "is_correct": false, "explanation": "铁 tiě（第三声）与 tiē（第一声）声调不同，意思是金属铁。"}, {"text": "捏", "is_correct": false, "explanation": "捏 niē 与 tiē 声母不同（n 与 t），意思是用手指夹住或揉。"}, {"text": "憋", "is_correct": false, "explanation": "憋 biē 与 tiē 声母不同（b 与 t），意思是忍住或闷住。"}, {"text": "些", "is_correct": false, "explanation": "些 xiē 与 tiē 声母不同（x 与 t），意思是一点或几个。"}], "explanations": {"贴": "贴 tiē，表示把片状的东西粘在别的物体上。", "铁": "铁 tiě（第三声）与 tiē（第一声）声调不同，意思是金属铁。", "捏": "捏 niē 与 tiē 声母不同（n 与 t），意思是用手指夹住或揉。", "憋": "憋 biē 与 tiē 声母不同（b 与 t），意思是忍住或闷住。", "些": "些 xiē 与 tiē 声母不同（x 与 t），意思是一点或几个。"}, "sentence_index": null, "correct_answer": "贴"}, "level_3": {"options": [{"text": "画", "is_correct": false, "explanation": "语义：画是用笔作画，面膜不能画在脸上。"}, {"text": "贴", "is_correct": true, "explanation": "贴：把面膜敷在脸上，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢掉，与把面膜敷在脸上的意思不符。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说写面膜。"}], "explanations": {"画": "语义：画是用笔作画，面膜不能画在脸上。", "贴": "贴：把面膜敷在脸上，符合句意。", "扔": "语义：扔是丢掉，与把面膜敷在脸上的意思不符。", "写": "搭配：“写”的对象是文字，不能说写面膜。"}, "sentence_index": 0, "correct_answer": "贴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "过年时，我们在树上贴灯笼。", "explanation": "这里应该用〈挂〉。挂是把东西悬吊起来，灯笼要挂，不能说贴灯笼。"}, {"text": "过年时，我们把饺子贴在桌上。", "explanation": "这里应该用〈摆〉。摆是把东西陈列放置，饺子要摆在桌上；贴是把片状东西粘在另一物体上，饺子不是片状，不能说贴饺子。"}, {"text": "过年时，我们在院子里贴鞭炮。", "explanation": "这里应该用〈放〉。鞭炮是点燃了放的，贴是把片状东西粘在物体上，不能说贴鞭炮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90166, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "贴", "is_correct": true, "explanation": "贴 tiē，表示把片状的东西粘在别的物体上。"}, {"text": "跌", "is_correct": false, "explanation": "跌 diē 与 tiē 声母不同（d 与 t），意思是摔倒。"}, {"text": "瞥", "is_correct": false, "explanation": "瞥 piē 与 tiē 声母不同（p 与 t），意思是很快地看一眼。"}, {"text": "歇", "is_correct": false, "explanation": "歇 xiē 与 tiē 声母不同（x 与 t），意思是休息。"}], "explanations": {"贴": "贴 tiē，表示把片状的东西粘在别的物体上。", "跌": "跌 diē 与 tiē 声母不同（d 与 t），意思是摔倒。", "瞥": "瞥 piē 与 tiē 声母不同（p 与 t），意思是很快地看一眼。", "歇": "歇 xiē 与 tiē 声母不同（x 与 t），意思是休息。"}, "sentence_index": null, "correct_answer": "贴"}, "level_3": {"options": [{"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住，纸条不能咬在冰箱上。"}, {"text": "绣", "is_correct": false, "explanation": "语义：绣是用针线做图案，纸条不能绣在冰箱上。"}, {"text": "倒", "is_correct": false, "explanation": "配价：“倒”要带液体作宾语，不能说倒纸条。"}, {"text": "贴", "is_correct": true, "explanation": "贴：把纸条粘在冰箱上，符合句意。"}], "explanations": {"咬": "语义：咬是用牙齿夹住，纸条不能咬在冰箱上。", "绣": "语义：绣是用针线做图案，纸条不能绣在冰箱上。", "倒": "配价：“倒”要带液体作宾语，不能说倒纸条。", "贴": "贴：把纸条粘在冰箱上，符合句意。"}, "sentence_index": 6, "correct_answer": "贴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用粉笔在黑板上贴名字。", "explanation": "这里应该用〈写〉。写是用笔留下字迹，名字要写在黑板上；贴是把片状东西粘上去，用粉笔不能说贴名字。"}, {"text": "妈妈用湿布贴黑板。", "explanation": "这里应该用〈擦〉。擦是用布抹去脏东西，贴是把东西粘上去，不能用湿布来贴黑板。"}, {"text": "她把花贴在花瓶里。", "explanation": "这里应该用〈插〉。插是把花枝放进容器里，贴是粘在表面上，不能说贴在花瓶里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把标签贴了在箱子上。", "corrected_sentence": "我把标签贴在箱子上。", "error_description": "错误形式：“贴了在”；正确形式：“贴在”。“了”不能放在动词与“在”短语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在冰箱上贴了过一张便条。", "corrected_sentence": "她在冰箱上贴过一张便条。", "error_description": "错误形式：“贴了过”；正确形式：“贴过”。“了”和“过”不能同时用在动词后面，表示曾经有过的经历只用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90168, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "精神", "is_correct": true, "explanation": "“肉体”与“精神”相对，是这一义项的反义词。"}, {"text": "树木", "is_correct": false, "explanation": "与“肉体”没有反义关系，指植物，与人的身体无关。"}, {"text": "房屋", "is_correct": false, "explanation": "与“肉体”没有反义关系，指供人居住的建筑。"}, {"text": "河流", "is_correct": false, "explanation": "与“肉体”没有反义关系，指地面上流动的水。"}], "correct_answer": "精神", "explanations": {"精神": "“肉体”与“精神”相对，是这一义项的反义词。", "树木": "与“肉体”没有反义关系，指植物，与人的身体无关。", "房屋": "与“肉体”没有反义关系，指供人居住的建筑。", "河流": "与“肉体”没有反义关系，指地面上流动的水。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90168, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "精神", "is_correct": true, "explanation": "“肉体”与“精神”相对，是这一义项的反义词。"}, {"text": "草地", "is_correct": false, "explanation": "与“肉体”没有反义关系，指地面上长草的平地。"}, {"text": "桌子", "is_correct": false, "explanation": "与“肉体”没有反义关系，是一种家具。"}, {"text": "海水", "is_correct": false, "explanation": "与“肉体”没有反义关系，指海里的水。"}], "correct_answer": "精神", "explanations": {"精神": "“肉体”与“精神”相对，是这一义项的反义词。", "草地": "与“肉体”没有反义关系，指地面上长草的平地。", "桌子": "与“肉体”没有反义关系，是一种家具。", "海水": "与“肉体”没有反义关系，指海里的水。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90168, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人的身体，与精神、灵魂相对。", "primary_collocate": null, "pronunciation": "ròu tǐ", "ipa": "ʐoʊ˥˩ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的肉体死了，精神还活着。", "target_word": "肉体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说肉体会老，灵魂不会。", "target_word": "肉体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的生活要照顾肉体，也要照顾精神。", "target_word": "肉体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肉体上的苦他不怕，心里的苦他最怕。", "target_word": "肉体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是肉体和灵魂的关系。", "target_word": "肉体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的肉体在这里，心却在家乡。", "target_word": "肉体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的肉体很累，精神却很好。", "target_word": "肉体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灵魂离开了肉体，人就死了。", "target_word": "肉体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人只关心肉体，不关心精神。", "target_word": "肉体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肉体会生病，精神也会生病。", "target_word": "肉体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一具肉体", "label": "量词"}], "register": "中性", "sense_fingerprint": "与精神、灵魂相对而言的人的身体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01aef012-b953-4027-8c37-cd1db6afc7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90168, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肉体", "is_correct": true, "explanation": "肉体指与精神相对的身体，“死了”与“精神还活着”形成对比，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不与“精神”相对，“房子死了”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是生命体，“石头死了，精神还活着”与句意不符。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“死”一般只用于生物，“衣服死了”不能这样说。"}], "explanations": {"肉体": "肉体指与精神相对的身体，“死了”与“精神还活着”形成对比，符合句意。", "房子": "语义：房子不与“精神”相对，“房子死了”说不通。", "石头": "语义：石头不是生命体，“石头死了，精神还活着”与句意不符。", "衣服": "搭配：“死”一般只用于生物，“衣服死了”不能这样说。"}, "sentence_index": 0, "correct_answer": "肉体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的肉体很高尚，从不说谎。", "explanation": "这里应该用〈精神〉。“高尚”说的是品格，属于精神方面，肉体不能用来形容。"}, {"text": "他的心里充满了肉体。", "explanation": "这里应该用〈感情〉。肉体是身体本身，不能“充满”在心里。"}, {"text": "他的肉体很坚定，从不动摇。", "explanation": "这里应该用〈信仰〉。坚定说的是信念和意志，肉体不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肉体", "is_correct": true, "explanation": "肉体指身体，与“精神却很好”形成对比，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不会“很累”，与“精神却很好”的对比也说不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是物品，不能“很累”，句意不通。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“很累”一般用于人或动物，说“电脑很累”不搭配。"}], "explanations": {"肉体": "肉体指身体，与“精神却很好”形成对比，符合句意。", "天空": "语义：天空不会“很累”，与“精神却很好”的对比也说不通。", "课本": "语义：课本是物品，不能“很累”，句意不通。", "电脑": "搭配：“很累”一般用于人或动物，说“电脑很累”不搭配。"}, "sentence_index": 6, "correct_answer": "肉体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很有肉体，懂得怎么赚钱。", "explanation": "这里应该用〈头脑〉。“有头脑”形容思考和判断能力，肉体不能用来形容聪明。"}, {"text": "那个肉体很感人，让人流泪。", "explanation": "这里应该用〈故事〉。肉体指身体，不能用来指令人感动的故事。"}, {"text": "他很讲肉体，从不欺骗别人。", "explanation": "这里应该用〈道德〉。“讲”的对象是品德或道理，肉体不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人都有一只肉体，它会慢慢变老。", "corrected_sentence": "每个人都有一具肉体，它会慢慢变老。", "error_description": "错误：量词“只”用于动物，指人的身体应用“具”。正确说法是“一具肉体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人这只肉体慢慢变弱，精神却很清醒。", "corrected_sentence": "老人这具肉体慢慢变弱，精神却很清醒。", "error_description": "错误：量词“只”多用于动物，指人的身体应当用“具”。正确说法是“这具肉体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
