INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90171, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "斗争是为了赢，跟对方用力对着干。", "primary_collocate": null, "pronunciation": "dòu zhēng", "ipa": "tou˥˩ ʈʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "工人们跟老板斗争了很久，最后赢了。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王不怕困难，一直在跟命运斗争。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了自己的权利，不停地斗争。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个人在公司里斗争了好几年。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民们敢跟地主斗争。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有放弃，继续跟病痛斗争着。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要和不公平的事斗争到底。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和对手斗争得很厉害。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弱小的动物也会为了生存而斗争。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人跟坏人斗争过，所以不怕他们。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "斗争了", "label": "体标"}, {"form": "斗争着", "label": "体标"}, {"form": "斗争过", "label": "体标"}, {"form": "斗争性", "label": "复合"}], "register": "书面", "sense_fingerprint": "为了赢而与对方用力对抗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bac65704-61f2-44c4-864d-746c99e18fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90171, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搬", "is_correct": false, "explanation": "语义：“搬”是移动物体，搬东西谈不上输赢，与“最后赢了”不符。"}, {"text": "斗争", "is_correct": true, "explanation": "斗争：为了赢而跟老板对抗，符合句意。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修理，与跟老板较量的意思不符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物品或身体，不能与“跟老板”搭配表示对抗。"}], "explanations": {"搬": "语义：“搬”是移动物体，搬东西谈不上输赢，与“最后赢了”不符。", "斗争": "斗争：为了赢而跟老板对抗，符合句意。", "修": "语义：“修”是修理，与跟老板较量的意思不符。", "洗": "搭配：“洗”的对象是物品或身体，不能与“跟老板”搭配表示对抗。"}, "sentence_index": 0, "correct_answer": "斗争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天斗争早饭。", "explanation": "这里应该用〈吃〉。吃是把食物咽下，早饭要吃；斗争的对象必须是对立的一方，早饭不是对手，不能说斗争早饭。"}, {"text": "他斗争学习英语，每天都很认真。", "explanation": "这里应该用〈努力〉。努力是尽力去做，学习不是对抗；斗争只能用于对立的双方，不能说斗争学习。"}, {"text": "他一个月斗争了五千块钱。", "explanation": "这里应该用〈挣〉。挣是靠劳动得到钱财，斗争不能与钱搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90171, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原谅", "is_correct": false, "explanation": "语义：原谅是宽恕，与“斗争到底”的对抗语境相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能与“不公平的事”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是唱歌，与“不公平的事”和“到底”的语境不合。"}, {"text": "斗争", "is_correct": true, "explanation": "斗争：与不公平的事对抗到底，符合句意。"}], "explanations": {"原谅": "语义：原谅是宽恕，与“斗争到底”的对抗语境相反。", "吃": "搭配：“吃”的对象是食物，不能与“不公平的事”搭配。", "唱": "语义：唱是唱歌，与“不公平的事”和“到底”的语境不合。", "斗争": "斗争：与不公平的事对抗到底，符合句意。"}, "sentence_index": 6, "correct_answer": "斗争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想斗争世界纪录。", "explanation": "这里应该用〈挑战〉。挑战是向困难或纪录发起较量，斗争的对象是对立的一方，不能说斗争纪录。"}, {"text": "他经常斗争班上的花。", "explanation": "这里应该用〈浇〉。浇是把水倒在植物上，花要浇水；斗争的对象必须是对立的一方，花不是对手，不能说斗争花。"}, {"text": "他斗争了自己的作业。", "explanation": "这里应该用〈完成〉。完成是做完任务，斗争的对象必须是对立的一方，不能用于作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跟坏人斗争了了很久，终于赢了。", "corrected_sentence": "他跟坏人斗争了很久，终于赢了。", "error_description": "错误形式：“斗争了了很久”；正确形式：“斗争了很久”。动词后只能用一个“了”，多出的“了”要删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时跟命运斗争了过。", "corrected_sentence": "他年轻时跟命运斗争过。", "error_description": "错误形式：“斗争了过”；正确形式：“斗争过”。“了”和“过”不能同时用在动词后面，表示曾经有过的经历只用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90172, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无私", "is_correct": true, "explanation": "正确：不计个人利益，是“自私”的反义词。"}, {"text": "懒惰", "is_correct": false, "explanation": "无关：懒惰指不愿劳动，与“自私”没有反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "无关：勇敢指有胆量，与“自私”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：聪明指头脑好，与“自私”没有反义关系。"}], "correct_answer": "无私", "explanations": {"无私": "正确：不计个人利益，是“自私”的反义词。", "懒惰": "无关：懒惰指不愿劳动，与“自私”没有反义关系。", "勇敢": "无关：勇敢指有胆量，与“自私”没有反义关系。", "聪明": "无关：聪明指头脑好，与“自私”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90172, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无私", "is_correct": true, "explanation": "正确：不计个人利益，是“自私”的反义词。"}, {"text": "热情", "is_correct": false, "explanation": "无关：热情指待人亲切，与“自私”没有反义关系。"}, {"text": "诚实", "is_correct": false, "explanation": "无关：诚实指不说假话，与“自私”没有反义关系。"}, {"text": "勤劳", "is_correct": false, "explanation": "无关：勤劳指努力干活，与“自私”没有反义关系。"}], "correct_answer": "无私", "explanations": {"无私": "正确：不计个人利益，是“自私”的反义词。", "热情": "无关：热情指待人亲切，与“自私”没有反义关系。", "诚实": "无关：诚实指不说假话，与“自私”没有反义关系。", "勤劳": "无关：勤劳指努力干活，与“自私”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90172, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "自私是只想着自己，不想别人。", "primary_collocate": null, "pronunciation": "zì sī", "ipa": "tsz̩˥˩ sz̩˥", "syllable_count": 2, "sentences": [{"text": "他很自私，只想自己。", "target_word": "自私", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你别这么自私，也想想别人。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她觉得哥哥太自私，不愿意帮忙。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自私的人常常不想别人。", "target_word": "自私", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都不喜欢自私的同学。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他自私得连一块饼干也不分给弟弟。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，做朋友不能太自私。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们吵架了，因为每个人都很自私。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个自私的老板从来不关心工人。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想做一个自私的人。", "target_word": "自私", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "自私自利", "label": "复合"}, {"form": "自私鬼", "label": "复合"}], "register": "中性", "sense_fingerprint": "只想自己、不为别人着想的性格或态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a138068c-42b9-49dc-b301-f8a5ab1de2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自私", "is_correct": true, "explanation": "正确：只想自己，不为别人着想。"}, {"text": "善良", "is_correct": false, "explanation": "语义：善良是为别人着想，与“只想自己”矛盾。"}, {"text": "大方", "is_correct": false, "explanation": "语义：大方是不计较、愿意给别人，与“只想自己”矛盾。"}, {"text": "客气", "is_correct": false, "explanation": "搭配：“客气”说礼貌态度，与“只想自己”的意思不搭配。"}], "explanations": {"自私": "正确：只想自己，不为别人着想。", "善良": "语义：善良是为别人着想，与“只想自己”矛盾。", "大方": "语义：大方是不计较、愿意给别人，与“只想自己”矛盾。", "客气": "搭配：“客气”说礼貌态度，与“只想自己”的意思不搭配。"}, "sentence_index": 0, "correct_answer": "自私"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很自私，把一半的钱捐给了灾区。", "explanation": "语义：这里应该用〈慷慨〉。自私指只想自己，与捐钱给灾区的行为矛盾。"}, {"text": "这个孩子很自私，自己穿衣服、整理房间。", "explanation": "语义：这里应该用〈独立〉。自私形容不为别人着想，不能用来形容自己做事。"}, {"text": "这家医院的医生很自私，每天主动为病人延长门诊时间。", "explanation": "语义：这里应该用〈敬业〉。为病人延长门诊是为别人着想，自私不能形容这种人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自私", "is_correct": true, "explanation": "正确：只顾自己，不替别人着想。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：勇敢指有胆量，与“做朋友不能太……”的意思不合。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：聪明指头脑灵活，不能用来说“做朋友不能太……”。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌，不用于说朋友相处的态度。"}], "explanations": {"自私": "正确：只顾自己，不替别人着想。", "勇敢": "语义：勇敢指有胆量，与“做朋友不能太……”的意思不合。", "聪明": "语义：聪明指头脑灵活，不能用来说“做朋友不能太……”。", "漂亮": "搭配：“漂亮”形容外貌，不用于说朋友相处的态度。"}, "sentence_index": 6, "correct_answer": "自私"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妈妈很自私，每天早起给全家做早饭。", "explanation": "语义：早起做饭是为家人着想，应该用〈体贴〉，不能用〈自私〉。"}, {"text": "这个小伙子很自私，每次看到老人过马路都主动扶一把。", "explanation": "近义混淆：这里应该用〈热心〉，指主动帮助别人。自私指只顾自己，与主动扶老人的行为矛盾。"}, {"text": "这个班长很自私，把自己的作业借给大家抄。", "explanation": "语义：这里应该用〈大方〉。自私指只想自己，与借作业给大家的行为矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很很自私，从来不借东西给别人。", "corrected_sentence": "她很自私，从来不借东西给别人。", "error_description": "程度副词重复：“很”只用一次，应说“她很自私”，不能说“她很很自私”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个自私人，从不肯借东西给别人。", "corrected_sentence": "他是一个自私的人，从不肯借东西给别人。", "error_description": "结构错误：“自私”修饰名词“人”时要加“的”，应说“自私的人”，不能说“自私人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90173, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无私", "is_correct": true, "explanation": "正确：不计个人利益，是“自私”的反义词。"}, {"text": "懒惰", "is_correct": false, "explanation": "无关：懒惰指不愿劳动，与“自私”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：聪明指头脑好，与“自私”没有反义关系。"}, {"text": "幽默", "is_correct": false, "explanation": "无关：幽默指风趣，与“自私”没有反义关系。"}], "correct_answer": "无私", "explanations": {"无私": "正确：不计个人利益，是“自私”的反义词。", "懒惰": "无关：懒惰指不愿劳动，与“自私”没有反义关系。", "聪明": "无关：聪明指头脑好，与“自私”没有反义关系。", "幽默": "无关：幽默指风趣，与“自私”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90173, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无私", "is_correct": true, "explanation": "正确：不计个人利益，是“自私”的反义词。"}, {"text": "活泼", "is_correct": false, "explanation": "无关：活泼指性格开朗好动，与“自私”没有反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "无关：认真指做事专心，与“自私”没有反义关系。"}, {"text": "勤快", "is_correct": false, "explanation": "无关：勤快指愿意干活，与“自私”没有反义关系。"}], "correct_answer": "无私", "explanations": {"无私": "正确：不计个人利益，是“自私”的反义词。", "活泼": "无关：活泼指性格开朗好动，与“自私”没有反义关系。", "认真": "无关：认真指做事专心，与“自私”没有反义关系。", "勤快": "无关：勤快指愿意干活，与“自私”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90173, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "只顾自己的利益，不顾他人。", "primary_collocate": null, "pronunciation": "zì sī", "ipa": "tsz̩˥˩ sz̩˥", "syllable_count": 2, "sentences": [{"text": "他只顾自己的利益，真自私。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自私的人不顾他人的感受。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板自私，一个人拿走了所有的钱。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样做太自私了，别人会生气。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他自私地占了最好的座位。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了自己的好处，他变得越来越自私。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司只想赚钱，不管工人，真自私。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你这样做太自私，没有想过邻居。", "target_word": "自私", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的自私让朋友们都离开了他。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子不分玩具给别人，不一定是自私。", "target_word": "自私", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "自私自利", "label": "复合"}, {"form": "自私鬼", "label": "复合"}], "register": "中性", "sense_fingerprint": "只顾自己的利益而不顾他人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a138068c-42b9-49dc-b301-f8a5ab1de2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90173, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自私", "is_correct": true, "explanation": "正确：只顾自己的利益，不顾他人。"}, {"text": "大方", "is_correct": false, "explanation": "语义：大方是不计较，与“只顾自己的利益”矛盾。"}, {"text": "热心", "is_correct": false, "explanation": "语义：热心是乐于帮助人，与“只顾自己的利益”矛盾。"}, {"text": "客气", "is_correct": false, "explanation": "搭配：“客气”说礼貌态度，不能用来描述只顾自己利益的人。"}], "explanations": {"自私": "正确：只顾自己的利益，不顾他人。", "大方": "语义：大方是不计较，与“只顾自己的利益”矛盾。", "热心": "语义：热心是乐于帮助人，与“只顾自己的利益”矛盾。", "客气": "搭配：“客气”说礼貌态度，不能用来描述只顾自己利益的人。"}, "sentence_index": 0, "correct_answer": "自私"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了大家的利益，他自私地放弃了休假。", "explanation": "语义：放弃休假是为大家，不是只顾自己，这里应该用〈无私〉。"}, {"text": "这位邻居很自私，经常主动帮我们搬东西。", "explanation": "语义：这里应该用〈热心〉。自私表示只顾自己，与主动帮忙矛盾。"}, {"text": "老奶奶很自私，总是把自己的口粮分给邻居。", "explanation": "近义混淆：这里应该用〈善良〉。自私指只顾自己，与把口粮分给邻居的行为矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90173, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自私", "is_correct": true, "explanation": "正确：只顾赚钱，不顾工人。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：慷慨是乐于给予，与“只想赚钱，不管工人”矛盾。"}, {"text": "仁慈", "is_correct": false, "explanation": "语义：仁慈是待人宽厚，与“不管工人”矛盾。"}, {"text": "慈祥", "is_correct": false, "explanation": "语义：慈祥指和蔼宽厚，多用于长辈，与“不管工人”矛盾。"}], "explanations": {"自私": "正确：只顾赚钱，不顾工人。", "慷慨": "语义：慷慨是乐于给予，与“只想赚钱，不管工人”矛盾。", "仁慈": "语义：仁慈是待人宽厚，与“不管工人”矛盾。", "慈祥": "语义：慈祥指和蔼宽厚，多用于长辈，与“不管工人”矛盾。"}, "sentence_index": 6, "correct_answer": "自私"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位医生每天免费给穷人看病，真自私。", "explanation": "语义：免费看病是为别人着想，这里应该用〈无私〉。"}, {"text": "我爸爸很自私，每个周末都陪我们去公园。", "explanation": "语义：陪家人去公园是为别人着想，这里应该用〈顾家〉。"}, {"text": "老板很自私，每天给员工放假，还发奖金。", "explanation": "语义：这里应该用〈慷慨〉。自私指只顾自己，与放假发奖金矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他只顾自己玩，真很自私。", "corrected_sentence": "他只顾自己玩，真自私。", "error_description": "程度副词重复：“真”已表示程度，后面不能再加“很”，应说“真自私”，不说“真很自私”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他因为太自私得，朋友们都离开了他。", "corrected_sentence": "他因为太自私，朋友们都离开了他。", "error_description": "结构错误：“得”后面缺少补语，“太自私得”后直接断句，应去掉“得”，说“他因为太自私，朋友们都离开了他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
