INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90174, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了达到目的与对立的一方进行对抗。", "primary_collocate": null, "pronunciation": "dòu zhēng", "ipa": "tou˥˩ ʈʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "人民为了自由，与敌人进行斗争。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了保护森林，跟砍树的人斗争。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工会为工人的利益而斗争。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了得到公平，她勇敢地斗争了。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们团结起来，与坏人斗争。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个政党为了权力一直在斗争。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须为和平而斗争。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生都在为理想斗争。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们为自己的权利斗争过。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们和不公平的制度斗争着。", "target_word": "斗争", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "斗争了", "label": "体标"}, {"form": "斗争着", "label": "体标"}, {"form": "斗争过", "label": "体标"}, {"form": "斗争性", "label": "复合"}], "register": "书面", "sense_fingerprint": "为达到目的而与对立方对抗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bac65704-61f2-44c4-864d-746c99e18fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90174, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游戏", "is_correct": false, "explanation": "语义：游戏是娱乐活动，与敌人对立的语境不符。"}, {"text": "斗争", "is_correct": true, "explanation": "斗争：与敌人对抗，符合句意。"}, {"text": "体操", "is_correct": false, "explanation": "语义：体操是体育运动，不能用于与敌人对立的情境。"}, {"text": "聚会", "is_correct": false, "explanation": "搭配：聚会指人们相聚，不能与“敌人”搭配。"}], "explanations": {"游戏": "语义：游戏是娱乐活动，与敌人对立的语境不符。", "斗争": "斗争：与敌人对抗，符合句意。", "体操": "语义：体操是体育运动，不能用于与敌人对立的情境。", "聚会": "搭配：聚会指人们相聚，不能与“敌人”搭配。"}, "sentence_index": 0, "correct_answer": "斗争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们勇敢地斗争了加薪的机会。", "explanation": "这里应该用〈争取〉。争取是力求得到，可以说争取机会；斗争是对抗，不能说斗争机会。"}, {"text": "他认真地斗争了一份工作。", "explanation": "这里应该用〈申请〉。申请是提出要求以获得，斗争不能用来指求职。"}, {"text": "他斗争了一个笑话，大家都笑了。", "explanation": "这里应该用〈讲〉。讲是把话说出来，斗争不能表示讲笑话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是休息，不能作为为和平而采取的行动。"}, {"text": "斗争", "is_correct": true, "explanation": "斗争：为和平而对抗，符合句意。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡是个人卫生，与为和平的目标不符。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“为……而”后接的动词要表示主动追求，“吃饭”不能这样搭配。"}], "explanations": {"睡觉": "语义：睡觉是休息，不能作为为和平而采取的行动。", "斗争": "斗争：为和平而对抗，符合句意。", "洗澡": "语义：洗澡是个人卫生，与为和平的目标不符。", "吃饭": "搭配：“为……而”后接的动词要表示主动追求，“吃饭”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "斗争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他斗争了坏掉的收音机。", "explanation": "这里应该用〈修理〉。修理是把坏的东西弄好，斗争的对象必须是对立的一方，不能用于收音机。"}, {"text": "我们要斗争美丽的家园。", "explanation": "这里应该用〈建设〉。建设是建立、营造，斗争是对抗，不能用来说斗争家园。"}, {"text": "他斗争了老师的建议。", "explanation": "这里应该用〈接受〉。接受是收下或同意，斗争不能用于建议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们为了权益，把老板斗争。", "corrected_sentence": "工人们为了权益，与老板斗争。", "error_description": "错误形式：“把老板斗争”；正确形式：“与老板斗争”。“斗争”引出对象须用介词“与”，不能用“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一直为自由斗争了着。", "corrected_sentence": "她一直为自由斗争着。", "error_description": "错误形式：“斗争了着”；正确形式：“斗争着”。“了”和“着”不能同时用在动词后面，表示状态持续只用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
