INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90175, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90175, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有足够的钱或力气，能做某件事。", "primary_collocate": null, "pronunciation": "de qǐ", "ipa": "tɤ tɕʰi˨˩", "syllable_count": 2, "sentences": [{"text": "这么贵的车，我可买得起。", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个月挣得多，住得起大房子。", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子很贵，我们一家人住得起吗？", "target_word": "得起", "complexity_tier": "T3", "furigana": "zhè tào fángzi hěn guì, wǒmen yì jiā rén zhù de qǐ ma?", "sentence_source": "generated"}, {"text": "他们家有钱，天天吃得起海鲜。", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我现在存了钱，出国玩得起了。", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百块的鞋子，学生也穿得起。", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工资不高，但是请得起一个保姆。", "target_word": "得起", "complexity_tier": "T3", "furigana": "tā gōngzī bù gāo, dànshì qǐng de qǐ yí gè bǎomǔ.", "sentence_source": "generated"}, {"text": "工资涨了，我们终于租得起新房子。", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一张票三千块，你们坐得起头等舱吗？", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么贵的包，只有她用得起。", "target_word": "得起", "complexity_tier": "T3", "furigana": "zhème guì de bāo, zhǐyǒu tā yòng de qǐ.", "sentence_source": "generated"}], "morphological_forms": [{"form": "不起", "label": "否定式"}], "register": "口语", "sense_fingerprint": "接在动词后，表示钱或力气足够，能买、能住、能搬等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3028915b-04fc-4478-8fb7-63277b2eed09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90175, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得起", "is_correct": true, "explanation": "得起：有足够的钱，能买这辆车，符合句意。"}, {"text": "得动", "is_correct": false, "explanation": "语义：“得动”指有力气搬动或移动，与钱够不够无关。"}, {"text": "得住", "is_correct": false, "explanation": "搭配：“得住”表示撑住或承受，不能与“买”搭配。"}, {"text": "得出", "is_correct": false, "explanation": "语义：“得出”表示得到结论或推出，与买车无关。"}], "explanations": {"得起": "得起：有足够的钱，能买这辆车，符合句意。", "得动": "语义：“得动”指有力气搬动或移动，与钱够不够无关。", "得住": "搭配：“得住”表示撑住或承受，不能与“买”搭配。", "得出": "语义：“得出”表示得到结论或推出，与买车无关。"}, "sentence_index": 0, "correct_answer": "得起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题很难，我们解决得起。", "explanation": "这里应该用〈解决得了〉。“得起”表示有足够的钱或力气去承担某事，说问题能否解决要用“解决得了”。"}, {"text": "他们家很穷，所以天天吃得起海鲜。", "explanation": "这里应该用〈吃不起〉。“得起”表示有足够的钱能负担，“很穷”不可能推出能负担，句意应是“很穷，所以吃不起海鲜”。"}, {"text": "这张床很大，三个人睡得起。", "explanation": "这里应该用〈睡得下〉。“得起”表示有钱或力气能负担某事，说床能容纳几个人要用“睡得下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90175, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得起", "is_correct": true, "explanation": "得起：有足够的钱，能请得起保姆，符合句意。"}, {"text": "得上", "is_correct": false, "explanation": "搭配：“得上”不能与“请”搭配，不表示有钱负担。"}, {"text": "得去", "is_correct": false, "explanation": "配价：“得去”需要处所或方向，不能接“请一个保姆”作宾语。"}, {"text": "得开", "is_correct": false, "explanation": "语义：“得开”表示能打开，与请保姆无关。"}], "explanations": {"得起": "得起：有足够的钱，能请得起保姆，符合句意。", "得上": "搭配：“得上”不能与“请”搭配，不表示有钱负担。", "得去": "配价：“得去”需要处所或方向，不能接“请一个保姆”作宾语。", "得开": "语义：“得开”表示能打开，与请保姆无关。"}, "sentence_index": 6, "correct_answer": "得起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路很远，我们走得起。", "explanation": "这里应该用〈走得完〉。“得起”表示有钱或力气能负担某事，说路程能否走完要用“走得完”。"}, {"text": "他工资很低，所以买得起三套房子。", "explanation": "这里应该用〈买不起〉。“买得起”表示有足够的钱能负担，“工资很低”推不出这个结果，应说“买不起三套房子”。"}, {"text": "这个箱子很小，放得起十本书。", "explanation": "这里应该用〈放得下〉。“得起”表示有钱或力气能负担，说空间能否容纳要用“放得下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90175, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆新车很贵，我买不得起。", "corrected_sentence": "这辆新车很贵，我买不起。", "error_description": "错误：“得”和“不”同时出现（买不得起）。正确：可能补语的否定式是“买不起”，即把“得”换成“不”，句意为买不了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90175, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套公寓很贵，他们付得得起。", "corrected_sentence": "这套公寓很贵，他们付得起。", "error_description": "错误：“得”重复出现（付得得起）。正确：应说“付得起”，表示有钱能负担，“得”只出现一次。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
