INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90176, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90176, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "用在动词后，表示有能力承担或承受。", "primary_collocate": null, "pronunciation": "de qǐ", "ipa": "tɤ tɕʰi˨˩", "syllable_count": 2, "sentences": [{"text": "他很勇敢，输得起，也赢得起。", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子打坏了玻璃，我们赔得起。", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错是你犯的，你要负得起责任。", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方案有风险，但我们亏得起。", "target_word": "得起", "complexity_tier": "T3", "furigana": "zhège fāng''àn yǒu fēngxiǎn, dàn wǒmen kuī de qǐ.", "sentence_source": "generated"}, {"text": "他脾气好，开得起玩笑。", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要冒险，也要亏得起。", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么高的荣誉，我受得起吗？", "target_word": "得起", "complexity_tier": "T3", "furigana": "zhème gāo de róngyù, wǒ shòu de qǐ ma?", "sentence_source": "generated"}, {"text": "他身体很好，熬得起夜。", "target_word": "得起", "complexity_tier": "T3", "furigana": "tā shēntǐ hěn hǎo, áo de qǐ yè.", "sentence_source": "generated"}, {"text": "他丢了工作，但是他承受得起。", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事出了问题，我担得起。", "target_word": "得起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不起", "label": "否定式"}], "register": "口语", "sense_fingerprint": "用在动词后的可能补语，表示能承担责任、损失、压力或考验", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3028915b-04fc-4478-8fb7-63277b2eed09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得起", "is_correct": true, "explanation": "得起：能承受，输得起，符合句意。"}, {"text": "得动", "is_correct": false, "explanation": "语义：“得动”指有力气移动，与承受输赢无关。"}, {"text": "得上", "is_correct": false, "explanation": "搭配：“得上”不能与“输”搭配，不表示承受。"}, {"text": "得去", "is_correct": false, "explanation": "配价：“得去”需要处所或方向，不能接“输”作宾语。"}], "explanations": {"得起": "得起：能承受，输得起，符合句意。", "得动": "语义：“得动”指有力气移动，与承受输赢无关。", "得上": "搭配：“得上”不能与“输”搭配，不表示承受。", "得去": "配价：“得去”需要处所或方向，不能接“输”作宾语。"}, "sentence_index": 0, "correct_answer": "得起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身体很弱，熬得起夜。", "explanation": "这里应该用〈熬不起〉。“得起”表示身体能承受，与“身体很弱”矛盾，句意应是身体弱，熬不起夜。"}, {"text": "这么冷的天，我冻得起。", "explanation": "这里应该用〈受得了〉。“得起”多用于经济、责任或损失等，冷的感受要用〈受得了〉。"}, {"text": "这项任务很难，他完成得起。", "explanation": "这里应该用〈完成得了〉。“得起”表示能承担或承受，说任务能否完成要用“完成得了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得起", "is_correct": true, "explanation": "得起：能承受，这么高的荣誉我能承受吗，符合句意。"}, {"text": "得开", "is_correct": false, "explanation": "语义：“得开”表示能打开，与承受荣誉无关。"}, {"text": "得出", "is_correct": false, "explanation": "语义：“得出”指得出结论，不能说“受得出荣誉”。"}, {"text": "得成", "is_correct": false, "explanation": "搭配：“得成”后要接动词才通，不能与“受”搭配。"}], "explanations": {"得起": "得起：能承受，这么高的荣誉我能承受吗，符合句意。", "得开": "语义：“得开”表示能打开，与承受荣誉无关。", "得出": "语义：“得出”指得出结论，不能说“受得出荣誉”。", "得成": "搭配：“得成”后要接动词才通，不能与“受”搭配。"}, "sentence_index": 6, "correct_answer": "得起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么苦的药，他咽得起。", "explanation": "这里应该用〈咽得下〉。“得起”表示能承担或承受，药物的吞咽要用“咽得下”。"}, {"text": "他一点玩笑都受不了，所以开得起玩笑。", "explanation": "这里应该用〈开不起〉。“开得起玩笑”表示能承受玩笑，与“一点玩笑都受不了”矛盾，应说“开不起玩笑”。"}, {"text": "这个错误很严重，他改正得起。", "explanation": "这里应该用〈改正得了〉。“得起”表示能承担或承受，改正错误要用“改正得了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这点批评，他受得不起。", "corrected_sentence": "这点批评，他受不起。", "error_description": "错误：“得”和“不”同时出现（受得不起）。正确：可能补语的否定式是“受不起”，即把“得”换成“不”，句意为承受不了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个错误是他犯的，他负得得起责任。", "corrected_sentence": "这个错误是他犯的，他负得起责任。", "error_description": "错误：“得”重复出现（负得得起责任）。正确：应说“负得起责任”，“得”只出现一次，宾语“责任”放在“得起”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90177, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90177, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90177, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "上面是高的那一边。", "primary_collocate": null, "pronunciation": "shàng miàn", "ipa": "ʂaŋ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这张纸上面是红的，下面是白的。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶子上面细，下面粗。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两张照片，上面那张是我的，下面那张是你的。", "target_word": "上面", "complexity_tier": "T3", "furigana": "liǎng zhāng zhàopiàn，shàngmian nà zhāng shì wǒ de，xiàmian nà zhāng shì nǐ de。", "sentence_source": "generated"}, {"text": "大的放下面，小的放上面。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看上面，那里有一只鸟。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上面太高了，我拿不到。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下很热，上面很凉快。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子上面不要放杯子。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图，上面的颜色比较深，下面的比较浅。", "target_word": "上面", "complexity_tier": "T3", "furigana": "zhè zhāng tú，shàngmian de yánsè bǐjiào shēn，xiàmian de bǐjiào qiǎn。", "sentence_source": "generated"}, {"text": "这个杯子上面宽，下面窄。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "高的那一边，与下面相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '133a0cf0-cdf6-4e93-b59b-2c72829dec62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90177, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上面", "is_correct": true, "explanation": "上面 shàng miàn，指高的那一边，与下面相对，是本词的正确读音和意思。"}, {"text": "场面", "is_correct": false, "explanation": "chǎng 与 shàng 声母、声调都不同（ch 与 sh），场面指场景、局面，与高低方位无关。"}, {"text": "账面", "is_correct": false, "explanation": "zhàng 与 shàng 声母不同（zh 与 sh），账面指账目上的记载，与高低的方位无关。"}, {"text": "扇面", "is_correct": false, "explanation": "shàn 与 shàng 韵母不同（an 与 ang），扇面指扇子上可以书画的部分，意思不同。"}], "explanations": {"上面": "上面 shàng miàn，指高的那一边，与下面相对，是本词的正确读音和意思。", "场面": "chǎng 与 shàng 声母、声调都不同（ch 与 sh），场面指场景、局面，与高低方位无关。", "账面": "zhàng 与 shàng 声母不同（zh 与 sh），账面指账目上的记载，与高低的方位无关。", "扇面": "shàn 与 shàng 韵母不同（an 与 ang），扇面指扇子上可以书画的部分，意思不同。"}, "sentence_index": null, "correct_answer": "上面"}, "level_3": {"options": [{"text": "上次", "is_correct": false, "explanation": "语义：上次指时间，不指纸张的一边，“这张纸上次是红的”说不通。"}, {"text": "大小", "is_correct": false, "explanation": "搭配：“大小”说的是尺寸，不能作颜色的主体，“这张纸大小是红的”不成立。"}, {"text": "上面", "is_correct": true, "explanation": "上面指高的那一边，与下面相对，这张纸的上面是红的，下面是白的，句子通顺。"}, {"text": "下午", "is_correct": false, "explanation": "语义：下午是时段，不指纸张的方位，与“下面是白的”也不构成上下对比。"}], "explanations": {"上次": "语义：上次指时间，不指纸张的一边，“这张纸上次是红的”说不通。", "大小": "搭配：“大小”说的是尺寸，不能作颜色的主体，“这张纸大小是红的”不成立。", "上面": "上面指高的那一边，与下面相对，这张纸的上面是红的，下面是白的，句子通顺。", "下午": "语义：下午是时段，不指纸张的方位，与“下面是白的”也不构成上下对比。"}, "sentence_index": 0, "correct_answer": "上面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我站在他的上面，给他递了一杯水。", "explanation": "这里应该用〈前面〉。站在别人前方要说前面；“站在他的上面”指站到他身体的上方，不表示在他面前。"}, {"text": "我在房间上面写作业，很安静。", "explanation": "这里应该用〈里面〉。在房间内部写作业要说里面；“房间上面”指房间的高处，不能表示在屋内。"}, {"text": "他一直站在窗户上面看雨。", "explanation": "这里应该用〈外面〉。站在窗外看雨要说外面；“窗户上面”指窗户的高处，不表示窗外。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能作地点主语被“很凉快”描述，“颜色很凉快”搭配不当。"}, {"text": "上面", "is_correct": true, "explanation": "上面指高的那一边，山上面很凉快，与“山下很热”形成对比，句子通顺。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指时间的长短，不指山的位置，“年龄很凉快”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能说凉快，“味道很凉快”搭配不当。"}], "explanations": {"颜色": "搭配：“颜色”不能作地点主语被“很凉快”描述，“颜色很凉快”搭配不当。", "上面": "上面指高的那一边，山上面很凉快，与“山下很热”形成对比，句子通顺。", "年龄": "语义：年龄指时间的长短，不指山的位置，“年龄很凉快”说不通。", "味道": "搭配：“味道”不能说凉快，“味道很凉快”搭配不当。"}, "sentence_index": 6, "correct_answer": "上面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的座位在他的上面，所以看不到黑板。", "explanation": "这里应该用〈后面〉。坐在别人身后要说后面；“上面”指高处，不能指身后的位置。"}, {"text": "学校在医院的上面，隔着马路就能看到。", "explanation": "这里应该用〈对面〉。马路另一侧要说对面；“上面”只表示高处，不能指道路另一边的位置。"}, {"text": "图书馆在我的上面，你从这边走。", "explanation": "这里应该用〈左边〉。位于左侧要说左边；“上面”表示高处，不能指左边的方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "盒子的一个上面贴着一张纸。", "corrected_sentence": "盒子的上面贴着一张纸。", "error_description": "“上面”是方位名词，前面不能加量词“一个”。错误形式“盒子的一个上面”，正确形式“盒子的上面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个箱子衣柜上面。", "corrected_sentence": "那个箱子在衣柜上面。", "error_description": "“衣柜上面”表示处所，前面需要介词“在”引出，应说“那个箱子在衣柜上面”，不能漏掉“在”说“那个箱子衣柜上面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
