INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90178, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "位置较高的部分或方向。", "primary_collocate": null, "pronunciation": "shàng miàn", "ipa": "ʂaŋ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "桌子上面有一杯水。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把名字写在纸的上面。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上面挂着一张地图。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上面的风很大。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在云的上面飞。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "椅子上面有一只小猫。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架最上面放着一本字典。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，鸟在树上面唱歌。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥上面有很多人在拍照。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱上面放着一个红色的杯子。", "target_word": "上面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "位置较高的部分或方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '133a0cf0-cdf6-4e93-b59b-2c72829dec62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90178, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上面", "is_correct": true, "explanation": "上面 shàng miàn，指位置较高的部分或方向，是本词的正确读音和意思。"}, {"text": "赏面", "is_correct": false, "explanation": "shǎng（第三声）与 shàng（第四声）声调不同，赏面是“赏光、给面子”的意思，不指位置。"}, {"text": "账面", "is_correct": false, "explanation": "zhàng 与 shàng 声母不同（zh 与 sh），账面指账目上的记载，与方位无关。"}, {"text": "扇面", "is_correct": false, "explanation": "shàn 与 shàng 韵母不同（an 与 ang），扇面指扇子上可以书画的部分，意思不同。"}], "explanations": {"上面": "上面 shàng miàn，指位置较高的部分或方向，是本词的正确读音和意思。", "赏面": "shǎng（第三声）与 shàng（第四声）声调不同，赏面是“赏光、给面子”的意思，不指位置。", "账面": "zhàng 与 shàng 声母不同（zh 与 sh），账面指账目上的记载，与方位无关。", "扇面": "shàn 与 shàng 韵母不同（an 与 ang），扇面指扇子上可以书画的部分，意思不同。"}, "sentence_index": null, "correct_answer": "上面"}, "level_3": {"options": [{"text": "下午", "is_correct": false, "explanation": "语义：下午指一天中的时段，不能表示桌子所在的方位，“桌子下午有一杯水”说不通。"}, {"text": "上面", "is_correct": true, "explanation": "上面指位置较高的部分，桌子上面放着一杯水，句子通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能充当桌子的方位，“桌子颜色有一杯水”不成立。"}, {"text": "上级", "is_correct": false, "explanation": "语义：上级指职务或等级较高的人或机构，不指物体的位置，句子说不通。"}], "explanations": {"下午": "语义：下午指一天中的时段，不能表示桌子所在的方位，“桌子下午有一杯水”说不通。", "上面": "上面指位置较高的部分，桌子上面放着一杯水，句子通顺。", "颜色": "搭配：“颜色”不能充当桌子的方位，“桌子颜色有一杯水”不成立。", "上级": "语义：上级指职务或等级较高的人或机构，不指物体的位置，句子说不通。"}, "sentence_index": 0, "correct_answer": "上面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在我的上面，挡住了我的视线。", "explanation": "这里应该用〈前面〉。“上面”指高处，站在别人前方要说前面；“站在我的上面”指站到我身体的上方。"}, {"text": "学校就在我家上面，走路五分钟就到。", "explanation": "这里应该用〈附近〉。“走路五分钟就到”说的是平面上的距离，要说附近；“上面”只表示位置较高，不能表示离得近。"}, {"text": "他的鼻子在眼睛上面。", "explanation": "这里应该用〈下面〉。鼻子在眼睛的下方，“上面”表示位置较高，不能用来描述低于眼睛的鼻子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：时间指时段，不能表示放东西的位置，“书架最时间放着一本字典”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能充当放东西的方位，也不能与“最”组成方位词语，句子说不通。"}, {"text": "上面", "is_correct": true, "explanation": "上面指位置较高的部分，书架最上面放着一本字典，句子通顺。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人或事物存在时间的长短，不指位置，“书架最年龄放着一本字典”说不通。"}], "explanations": {"时间": "语义：时间指时段，不能表示放东西的位置，“书架最时间放着一本字典”说不通。", "味道": "搭配：“味道”不能充当放东西的方位，也不能与“最”组成方位词语，句子说不通。", "上面": "上面指位置较高的部分，书架最上面放着一本字典，句子通顺。", "年龄": "语义：年龄指人或事物存在时间的长短，不指位置，“书架最年龄放着一本字典”说不通。"}, "sentence_index": 6, "correct_answer": "上面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在老师的上面排好队了。", "explanation": "这里应该用〈后面〉。排队时站在别人身后要说后面；“老师的上面”指老师的上方，不表示身后。"}, {"text": "公园在我家上面，走路过去要十分钟。", "explanation": "这里应该用〈附近〉。走路十分钟到达说的是平面上的距离，要说附近；“上面”只表示高处，不能表示离得不远。"}, {"text": "他坐在我的上面，帮我看作业。", "explanation": "这里应该用〈旁边〉。并排坐在身边要说旁边；“坐在我的上面”指坐到我身体的上方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌子的一个上面有一只小鸟。", "corrected_sentence": "桌子的上面有一只小鸟。", "error_description": "“上面”是方位名词，前面不能加量词“一个”。错误形式“桌子的一个上面”，正确形式“桌子的上面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个时钟门上面。", "corrected_sentence": "那个时钟在门上面。", "error_description": "“门上面”表示处所，前面需要介词“在”引出，应说“那个时钟在门上面”，不能漏掉“在”说“那个时钟门上面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
