INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90180, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，用在分句开头，引出另一事物，相当于“至于”。", "primary_collocate": null, "pronunciation": "zhì ruò", "ipa": "ʈʂʅ˥˩ ʐwo˥˩", "syllable_count": 2, "sentences": [{"text": "春天花开满山，至若秋天，树叶红了。", "target_word": "至若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的字写得很好，至若画画，也很不错。", "target_word": "至若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢夏天的海，至若冬天的山，也很安静。", "target_word": "至若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的春天很短，至若秋天，天气最好。", "target_word": "至若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会说英语，至若法语，他还没学过。", "target_word": "至若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写得很清楚，至若那本，我没看过。", "target_word": "至若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了语法，至若生词，请大家回家看。", "target_word": "至若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先说工作，至若玩的事，以后再谈。", "target_word": "至若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上海的夏天很热，至若冬天，也不太冷。", "target_word": "至若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌我听过，至若他的电影，我没看过。", "target_word": "至若", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面连词，放在分句开头，引出另一件事，相当于至于", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a37e-859d-480a-acef-93c3977707a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "至若", "is_correct": true, "explanation": "至若引出另一件事秋天，与前面“春天花开满山”形成对照，语境吻合。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果结果，前后不是因果关系，这里是转到另一件事。"}, {"text": "并且", "is_correct": false, "explanation": "搭配：“并且”要连接并列的动作或分句，“并且秋天”没有谓语，不成立。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示由此得出的结论，这里只是要引出秋天这一话题。"}], "explanations": {"至若": "至若引出另一件事秋天，与前面“春天花开满山”形成对照，语境吻合。", "因此": "语义：“因此”表示因果结果，前后不是因果关系，这里是转到另一件事。", "并且": "搭配：“并且”要连接并列的动作或分句，“并且秋天”没有谓语，不成立。", "所以": "语义：“所以”表示由此得出的结论，这里只是要引出秋天这一话题。"}, "sentence_index": 0, "correct_answer": "至若"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他走出门，至若下起雨来。", "explanation": "这里应该用〈于是〉。于是表示前一件事之后紧接着出现的结果；至若只用来转到另一件事，不表示先后或结果。"}, {"text": "至若你不来，我就走了。", "explanation": "这里应该用〈如果〉。如果表示条件；至若只用来转到另一件事，不能表示假设的条件。"}, {"text": "至若他很努力，还是没成功。", "explanation": "这里应该用〈虽然〉。虽然表示让步，先承认前一件事，再转折；至若不表示让步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "至若", "is_correct": true, "explanation": "至若引出“生词”这另一件事，与前面的“语法”形成对照，符合句意。"}, {"text": "况且", "is_correct": false, "explanation": "语义：“况且”表示进一步补充理由，这句要的是转到另一件事，不是补充理由。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”前面要有“不是”，这句前面没有否定，搭配不对。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示如果不这样就会怎样，与“老师讲了语法”的内容不相关。"}], "explanations": {"至若": "至若引出“生词”这另一件事，与前面的“语法”形成对照，符合句意。", "况且": "语义：“况且”表示进一步补充理由，这句要的是转到另一件事，不是补充理由。", "而是": "搭配：“而是”前面要有“不是”，这句前面没有否定，搭配不对。", "否则": "语义：“否则”表示如果不这样就会怎样，与“老师讲了语法”的内容不相关。"}, "sentence_index": 6, "correct_answer": "至若"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没来，至若生病了。", "explanation": "这里应该用〈因为〉。因为表示原因；至若只用来转到另一件事，不表示因果关系。"}, {"text": "天气很好，至若我们没去。", "explanation": "这里应该用〈然而〉。然而表示转折，前后意思相反；至若只是转到另一件事，不表示转折。"}, {"text": "我没有时间，至若没去。", "explanation": "这里应该用〈所以〉。所以表示由前面的原因得出结果；至若只是转到另一件事，不表示结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校很大，至若至若操场，也很宽敞。", "corrected_sentence": "学校很大，至若操场，也很宽敞。", "error_description": "重复：“至若”只需用一次，引出另一事物时直接接“操场”。“至若至若操场”重复了连词，应说“至若操场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他爱吃甜食，至若的水果，他也常吃。", "corrected_sentence": "他爱吃甜食，至若水果，他也常吃。", "error_description": "错误：“至若的水果”。正确：“至若水果”。“至若”后面直接接所引出的事物，中间不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
