INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90181, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90181, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不出声，嘴角往上弯着笑。", "primary_collocate": null, "pronunciation": "wēi xiào", "ipa": "weɪ˥ ɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "她嘴角往上弯，对我微笑。", "target_word": "微笑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "照相的时候，请大家微笑。", "target_word": "微笑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他看到我，嘴角一弯，微笑了。", "target_word": "微笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "服务员见到客人，总是微笑。", "target_word": "微笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐看着照片，微笑着不说话。", "target_word": "微笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝一看到我，就开心地微笑。", "target_word": "微笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有说话，只是看着我微笑。", "target_word": "微笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里的奶奶微笑着，很好看。", "target_word": "微笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王一边走，一边对路人微笑。", "target_word": "微笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人坐在椅子上，微笑着晒太阳。", "target_word": "微笑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "微笑了", "label": "完成体"}, {"form": "微笑着", "label": "持续体"}, {"form": "微笑过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "不出声，嘴角微微上扬的笑，多见于面对他人或拍照时", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '472a9012-31ef-4449-9907-721337a9f32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90181, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怒吼", "is_correct": false, "explanation": "语义：怒吼带着愤怒，与“嘴角往上弯”的笑意矛盾。"}, {"text": "微笑", "is_correct": true, "explanation": "正确。嘴角往上弯、不出声，正是微笑的样子，与“对我”相符。"}, {"text": "叹气", "is_correct": false, "explanation": "语义：叹气表示失落，与“嘴角往上弯”的笑意相反。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭与“嘴角往上弯”的笑意相反，不能用来描述这样的表情。"}], "explanations": {"怒吼": "语义：怒吼带着愤怒，与“嘴角往上弯”的笑意矛盾。", "微笑": "正确。嘴角往上弯、不出声，正是微笑的样子，与“对我”相符。", "叹气": "语义：叹气表示失落，与“嘴角往上弯”的笑意相反。", "哭": "语义：哭与“嘴角往上弯”的笑意相反，不能用来描述这样的表情。"}, "sentence_index": 0, "correct_answer": "微笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听了笑话，咯咯微笑起来。", "explanation": "语义：“咯咯”形容有声的笑，“微笑”不出声，二者不能搭配，这里应用〈咯咯地笑〉。"}, {"text": "她在教室里放声微笑，同学们都看着她。", "explanation": "语义：“放声”与“微笑”的不出声冲突，这里应用〈大笑〉之类的有声表达。"}, {"text": "他拍着大腿狂微笑，把桌子都震动了。", "explanation": "语义：“狂”描述剧烈的笑，与“微笑”的轻柔不符，这里应用〈狂笑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90181, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大喊", "is_correct": false, "explanation": "语义：大喊要出声，与“没有说话，只是看着我”的安静语境矛盾。"}, {"text": "微笑", "is_correct": true, "explanation": "正确。“没有说话，只是看着我”的安静语境与微笑相符。"}, {"text": "咆哮", "is_correct": false, "explanation": "语义：咆哮是激烈的吼叫，与“没有说话，只是看着我”的安静语境不符。"}, {"text": "说教", "is_correct": false, "explanation": "搭配：“没有说话”之后不能接“说教”这种有言语内容的动作。"}], "explanations": {"大喊": "语义：大喊要出声，与“没有说话，只是看着我”的安静语境矛盾。", "微笑": "正确。“没有说话，只是看着我”的安静语境与微笑相符。", "咆哮": "语义：咆哮是激烈的吼叫，与“没有说话，只是看着我”的安静语境不符。", "说教": "搭配：“没有说话”之后不能接“说教”这种有言语内容的动作。"}, "sentence_index": 6, "correct_answer": "微笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人坐在椅子上，对着太阳微笑了一声。", "explanation": "语义：“微笑”不出声，不能用“一声”计量，这里说的是有声的笑，应用〈笑出声〉。"}, {"text": "老人坐在椅子上，微笑着大叫，吓坏了路过的人。", "explanation": "语义：这里把“微笑”误当成有声的喊叫，应用〈大喊〉。"}, {"text": "老人坐在椅子上，微笑着扯着嗓子大吼，把鸽子都吓飞了。", "explanation": "语义：“微笑”不出声，不能与有声的喊叫搭配，这里应用〈大声喊〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90181, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她听了我的话，微笑着一下。", "corrected_sentence": "她听了我的话，微笑了一下。", "error_description": "错误：“微笑”后用了持续态“着”，与表示一次动作的“一下”冲突。应改为完成态“了”，写作“微笑了一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90181, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他我微笑，没有说话。", "corrected_sentence": "他对我微笑，没有说话。", "error_description": "错误：“微笑”是不及物动词，不带宾语；引出对象须用介词“对”。这里“我”作对象却漏掉“对”，且句中已有主语“他”，应说“他对我微笑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
