INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90185, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "艰苦是说日子过得很难、很辛苦。", "primary_collocate": null, "pronunciation": "jiān kǔ", "ipa": "tɕjɛn˥ kʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "那时候，他们的生活很艰苦。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷小时候家里很穷，日子过得很艰苦。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的生活条件艰苦，冬天特别冷。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在艰苦的日子里没有放弃学习。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前农村的生活比现在艰苦多了。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然日子艰苦，一家人还是很开心。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小过着艰苦的生活。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争年代，人们的生活非常艰苦。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几年我们家过得艰苦，很少吃肉。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶常说，过去的日子太艰苦了。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "艱苦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日子过得很难很辛苦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcba9692-cced-4943-a1b3-313ddd5c52a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90185, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "艰苦", "is_correct": true, "explanation": "艰苦说日子过得辛苦，与“那时候，他们的生活很……”的描述相符。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的智力，不能用来说生活。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的外形，不能用来说生活的状况。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”指明白、不模糊，与生活的艰难程度无关。"}], "explanations": {"艰苦": "艰苦说日子过得辛苦，与“那时候，他们的生活很……”的描述相符。", "聪明": "搭配：“聪明”形容人的智力，不能用来说生活。", "高大": "体貌：“高大”形容人或物的外形，不能用来说生活的状况。", "清楚": "语义：“清楚”指明白、不模糊，与生活的艰难程度无关。"}, "sentence_index": 0, "correct_answer": "艰苦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道数学题很艰苦，我想了一个小时。", "explanation": "这里应该用〈困难〉。艰苦描述生活或工作条件的辛苦，题目的难度要用困难。"}, {"text": "听到这个消息，他感到非常艰苦。", "explanation": "这里应该用〈痛苦〉。艰苦说条件难熬，不用来形容人内心的感受，心里的苦要用痛苦。"}, {"text": "这个系统的结构很艰苦，我花了很长时间才弄懂。", "explanation": "这里应该用〈复杂〉。艰苦强调生活的辛苦，事物结构繁多、难以理解要用复杂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90185, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "艰苦", "is_correct": true, "explanation": "艰苦说生活条件辛苦，与“他从小过着……的生活”的语境相符。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容个子或体型，不能用来说生活。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音清亮爽脆，与生活的状况无关。"}, {"text": "聪慧", "is_correct": false, "explanation": "搭配：“聪慧”形容人的才智，不能用来修饰“生活”。"}], "explanations": {"艰苦": "艰苦说生活条件辛苦，与“他从小过着……的生活”的语境相符。", "矮小": "体貌：“矮小”形容个子或体型，不能用来说生活。", "清脆": "语义：“清脆”形容声音清亮爽脆，与生活的状况无关。", "聪慧": "搭配：“聪慧”形容人的才智，不能用来修饰“生活”。"}, "sentence_index": 6, "correct_answer": "艰苦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他忙了一整天，身体很艰苦，走路都慢了。", "explanation": "这里应该用〈劳累〉。艰苦说生活或条件的辛苦，不用来形容人身体的疲乏。"}, {"text": "这个街区停车很艰苦，常常要绕好几圈。", "explanation": "这里应该用〈不便〉。艰苦描述生活条件的艰难，停车、交通带来的麻烦要用不便。"}, {"text": "他穿着很艰苦，但看上去很有精神。", "explanation": "这里应该用〈寒酸〉。艰苦不用来形容人的穿着和外表，衣着简陋、显得穷困要用寒酸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90185, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小时候家里穷，我们过的很艰苦。", "corrected_sentence": "小时候家里穷，我们过得很艰苦。", "error_description": "“过的很艰苦”应为“过得很艰苦”。“得”引出补语“很艰苦”，说明过日子的状态；写成“的”就成了定语，后面缺少中心词，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90185, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "过去的岁月比现在艰苦地多。", "corrected_sentence": "过去的岁月比现在艰苦得多。", "error_description": "“艰苦地多”应为“艰苦得多”。“得”引出程度补语“得多”，表示比较的差距；“地”只用于修饰动词，不能放在形容词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90186, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "舒适", "is_correct": true, "explanation": "舒适与艰苦相对，指环境安逸、使人舒服。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰形容清楚分明，与环境的艰苦程度无关。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速形容速度快，与艰苦的意思没有对立关系。"}, {"text": "热烈", "is_correct": false, "explanation": "热烈形容情绪或气氛激动，不是艰苦的反义词。"}], "correct_answer": "舒适", "explanations": {"舒适": "舒适与艰苦相对，指环境安逸、使人舒服。", "清晰": "清晰形容清楚分明，与环境的艰苦程度无关。", "迅速": "迅速形容速度快，与艰苦的意思没有对立关系。", "热烈": "热烈形容情绪或气氛激动，不是艰苦的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90186, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "舒适", "is_correct": true, "explanation": "舒适与艰苦相对，指环境安逸、使人舒服。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐形容排列有序，与环境的艰苦程度无关。"}, {"text": "愉快", "is_correct": false, "explanation": "愉快形容心情高兴，不是艰苦的反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线充足，与艰苦的意思没有对立关系。"}], "correct_answer": "舒适", "explanations": {"舒适": "舒适与艰苦相对，指环境安逸、使人舒服。", "整齐": "整齐形容排列有序，与环境的艰苦程度无关。", "愉快": "愉快形容心情高兴，不是艰苦的反义词。", "明亮": "明亮形容光线充足，与艰苦的意思没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90186, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "艰难困苦。", "primary_collocate": null, "pronunciation": "jiān kǔ", "ipa": "tɕjɛn˥ kʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "山区的条件很艰苦，但老师愿意留下。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在艰苦的环境里工作了十年。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行很艰苦，我们要走很远的路。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在艰苦的条件下修好了路。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的工作又累又艰苦。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过艰苦的努力，他终于成功了。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人的训练非常艰苦。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不怕艰苦，一个人去了西部。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在最艰苦的时候，朋友帮了我。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们每天走的路很远，学习的条件也很艰苦。", "target_word": "艰苦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "艱苦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "环境、工作、训练等艰难困苦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcba9692-cced-4943-a1b3-313ddd5c52a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "艰苦", "is_correct": true, "explanation": "艰苦形容条件艰难，与“山区的条件很……，但老师愿意留下”相符。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音清亮爽脆，不能用来说条件。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”多用于声音或名声，不能说“条件很响亮”。"}, {"text": "圆润", "is_correct": false, "explanation": "体貌：“圆润”形容外形圆满或声音饱满，不能用来形容条件。"}], "explanations": {"艰苦": "艰苦形容条件艰难，与“山区的条件很……，但老师愿意留下”相符。", "清脆": "语义：“清脆”形容声音清亮爽脆，不能用来说条件。", "响亮": "搭配：“响亮”多用于声音或名声，不能说“条件很响亮”。", "圆润": "体貌：“圆润”形容外形圆满或声音饱满，不能用来形容条件。"}, "sentence_index": 0, "correct_answer": "艰苦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题很艰苦，大家讨论了一个下午。", "explanation": "这里应该用〈困难〉。艰苦说环境或工作的艰难，问题本身的难度要用困难。"}, {"text": "这座桥很艰苦，车辆最好不要通过。", "explanation": "这里应该用〈危险〉。艰苦强调条件的辛苦，桥梁存在安全风险要用危险。"}, {"text": "这份表格很艰苦，我填了一个晚上。", "explanation": "这里应该用〈繁琐〉。艰苦强调辛苦、难熬，表格项目多、手续麻烦要用繁琐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "艰苦", "is_correct": true, "explanation": "艰苦形容训练的艰难，与“军人的训练非常……”相符。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地松软，与训练的难度无关。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”形容颜色洁白，不能用来形容训练。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”多用于味道，不能说“训练非常辣”。"}], "explanations": {"艰苦": "艰苦形容训练的艰难，与“军人的训练非常……”相符。", "柔软": "语义：“柔软”形容质地松软，与训练的难度无关。", "雪白": "体貌：“雪白”形容颜色洁白，不能用来形容训练。", "辣": "搭配：“辣”多用于味道，不能说“训练非常辣”。"}, "sentence_index": 6, "correct_answer": "艰苦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他训练完，人很艰苦，一躺下就睡着了。", "explanation": "这里应该用〈疲惫〉。艰苦说环境或工作的艰难，不用来形容人身体的疲乏。"}, {"text": "这位老师的衣服很艰苦，但很整洁。", "explanation": "这里应该用〈寒酸〉。艰苦说条件的艰难，外表简陋、穷酸的样子要用寒酸。"}, {"text": "这件衣服的价格很艰苦，我买不起。", "explanation": "这里应该用〈昂贵〉。艰苦说生活或条件的艰难，商品价格高要用昂贵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在艰苦地环境中生活，从不抱怨。", "corrected_sentence": "他在艰苦的环境中生活，从不抱怨。", "error_description": "“艰苦地环境”应为“艰苦的环境”。“艰苦”在这里修饰名词“环境”，修饰名词要用“的”；“地”用来修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "训练营里的日子过的很艰苦，但大家都很努力。", "corrected_sentence": "训练营里的日子过得很艰苦，但大家都很努力。", "error_description": "“过的很艰苦”应为“过得很艰苦”。“得”引出补语“很艰苦”，说明日子的状态；写成“的”就成了定语，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
