INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90187, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人说了，你也跟着说一样的话。", "primary_collocate": null, "pronunciation": "yìng hè", "ipa": "iŋ˥˩ xɤ˥˩", "syllable_count": 2, "sentences": [{"text": "大家都说好，他也跟着应和。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想说话，只会在旁边应和别人。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理说这个办法好，大家都应和起来。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不要别人说什么就应和什么。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她只是笑着点头，偶尔应和一两句。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在抱怨天气，我也应和了几句。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有自己的想法，总是应和老板的话。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明刚说完，同学们就跟着应和，笑成一团。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的时候，他一直低着头，从不应和别人。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说天冷了，爸爸也应和说该加衣服了。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "应和着", "label": "着体标"}, {"form": "应和了", "label": "了体标"}, {"form": "应和过", "label": "过体标"}], "register": "书面", "sense_fingerprint": "应和|别人说话后跟着附和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '410036aa-66b9-4036-830e-495e3a8f36e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90187, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应和", "is_correct": true, "explanation": "正确：应和（yìng hè），指别人说话后，你也跟着说一样的话。"}, {"text": "硬核", "is_correct": false, "explanation": "hé（第二声）与 hè（第四声）声调不同，意思是硬核，指核心内容，与应和不同。"}, {"text": "印盒", "is_correct": false, "explanation": "yìn 与 yìng 韵尾不同，hé（第二声）与 hè（第四声）声调不同，意思是装印章的盒子。"}, {"text": "硬盒", "is_correct": false, "explanation": "hé（第二声）与 hè（第四声）声调不同，意思是硬质的盒子。"}], "explanations": {"应和": "正确：应和（yìng hè），指别人说话后，你也跟着说一样的话。", "硬核": "hé（第二声）与 hè（第四声）声调不同，意思是硬核，指核心内容，与应和不同。", "印盒": "yìn 与 yìng 韵尾不同，hé（第二声）与 hè（第四声）声调不同，意思是装印章的盒子。", "硬盒": "hé（第二声）与 hè（第四声）声调不同，意思是硬质的盒子。"}, "sentence_index": null, "correct_answer": "应和"}, "level_3": {"options": [{"text": "顶嘴", "is_correct": false, "explanation": "语义：“顶嘴”指反驳、回嘴，与前文“大家都说好”的赞同语境相反，放进句中不合句意。"}, {"text": "应和", "is_correct": true, "explanation": "正确：“应和”指跟着别人说一样的话，与“跟着”搭配，符合句意。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：“怀疑”与前文“大家都说好”的赞同态度相反，“跟着怀疑”语义矛盾，不合句意。"}, {"text": "反驳", "is_correct": false, "explanation": "语义：“反驳”与“跟着”的意思相反，前文是大家都表示赞同。"}], "explanations": {"顶嘴": "语义：“顶嘴”指反驳、回嘴，与前文“大家都说好”的赞同语境相反，放进句中不合句意。", "应和": "正确：“应和”指跟着别人说一样的话，与“跟着”搭配，符合句意。", "怀疑": "语义：“怀疑”与前文“大家都说好”的赞同态度相反，“跟着怀疑”语义矛盾，不合句意。", "反驳": "语义：“反驳”与“跟着”的意思相反，前文是大家都表示赞同。"}, "sentence_index": 0, "correct_answer": "应和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器和那个零件应和得很好，装上就能用。", "explanation": "这里应该用〈配合〉。应和指跟着别人说一样的话，机器零件之间相互适配要用“配合”。"}, {"text": "两根木棍互相应和，接得很牢。", "explanation": "这里应该用〈连接〉。应和指跟着别人说一样的话，不能用来说两个物体接在一起。"}, {"text": "两扇门的把手互相应和，看起来很整齐。", "explanation": "这里应该用〈对齐〉。应和指跟着别人说一样的话，两个物体的位置对齐要用“对齐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”指对人不热情、不理睬，不能用于“老板的话”。"}, {"text": "创造", "is_correct": false, "explanation": "配价：“创造”的对象是事物或成果，不能说“创造老板的话”。"}, {"text": "应和", "is_correct": true, "explanation": "正确：“应和”指跟着别人说一样的话，与“总是……老板的话”搭配，符合句意。"}, {"text": "发明", "is_correct": false, "explanation": "配价：“发明”的对象是新的事物或方法，“发明老板的话”不成立。"}], "explanations": {"冷落": "语义：“冷落”指对人不热情、不理睬，不能用于“老板的话”。", "创造": "配价：“创造”的对象是事物或成果，不能说“创造老板的话”。", "应和": "正确：“应和”指跟着别人说一样的话，与“总是……老板的话”搭配，符合句意。", "发明": "配价：“发明”的对象是新的事物或方法，“发明老板的话”不成立。"}, "sentence_index": 6, "correct_answer": "应和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师问他问题，他想了一下，然后应和了老师的问题。", "explanation": "这里应该用〈回答〉。应和指跟着别人说一样的话，回答老师的问题要用“回答”。"}, {"text": "他应和了文章的结尾三次。", "explanation": "这里应该用〈修改〉。应和指跟着别人说一样的话，修改文章的结尾要用“修改”。"}, {"text": "这本书用线应和在一起，很结实。", "explanation": "这里应该用〈装订〉。应和指跟着别人说一样的话，把书页用线连起来要用“装订”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没有应和了老师的话，只是笑了笑。", "corrected_sentence": "他没有应和老师的话，只是笑了笑。", "error_description": "错误：否定句里多用了“了”。“没有”后面不能加“了”，应说“没有应和”，不能说“没有应和了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议上，他总是把应和经理的话。", "corrected_sentence": "会议上，他总是应和经理的话。", "error_description": "错误：多用了“把”。“应和”后面直接带宾语，不需要“把”，应说“他总是应和经理的话”，不能说“把应和经理的话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
