INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90188, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90188, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "声音相互呼应，彼此回应。", "primary_collocate": null, "pronunciation": "yìng hè", "ipa": "iŋ˥˩ xɤ˥˩", "syllable_count": 2, "sentences": [{"text": "山谷里，鸟叫声和流水声互相应和。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远处传来钟声，近处的歌声与它相互应和。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只青蛙先叫，别的青蛙都来应和。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师弹钢琴，学生的歌声在旁边应和。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里一只狗叫起来，远处的狗也叫着应和。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的蛙声和树上的蝉声互相应和，很热闹。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱了一句，台下的观众立刻应和起来。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风吹过竹林，沙沙声与远处的流水声应和着。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱起歌来，树上的小鸟也在应和。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鼓声响起，笛声马上应和，音乐一下子热闹了。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应和着", "label": "着体标"}, {"form": "应和了", "label": "了体标"}, {"form": "应和过", "label": "过体标"}], "register": "书面", "sense_fingerprint": "应和|声音相互呼应，彼此回应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '410036aa-66b9-4036-830e-495e3a8f36e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90188, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应和", "is_correct": true, "explanation": "正确：应和（yìng hè），指声音相互呼应。"}, {"text": "硬核", "is_correct": false, "explanation": "hé（第二声）与 hè（第四声）声调不同，意思是硬核，指核心内容，与应和不同。"}, {"text": "印盒", "is_correct": false, "explanation": "yìn 与 yìng 韵尾不同，hé（第二声）与 hè（第四声）声调不同，意思是装印章的盒子。"}, {"text": "硬盒", "is_correct": false, "explanation": "hé（第二声）与 hè（第四声）声调不同，意思是硬质的盒子。"}], "explanations": {"应和": "正确：应和（yìng hè），指声音相互呼应。", "硬核": "hé（第二声）与 hè（第四声）声调不同，意思是硬核，指核心内容，与应和不同。", "印盒": "yìn 与 yìng 韵尾不同，hé（第二声）与 hè（第四声）声调不同，意思是装印章的盒子。", "硬盒": "hé（第二声）与 hè（第四声）声调不同，意思是硬质的盒子。"}, "sentence_index": null, "correct_answer": "应和"}, "level_3": {"options": [{"text": "争吵", "is_correct": false, "explanation": "语义：“争吵”指人之间因意见不合而大声吵，鸟叫声和流水声不会争吵。"}, {"text": "应和", "is_correct": true, "explanation": "正确：“应和”指声音相互呼应，与“互相”搭配，符合句意。"}, {"text": "对骂", "is_correct": false, "explanation": "语域：“对骂”是口语中很粗的说法，不能用于描写山谷里的声音。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：“道歉”要向人认错，鸟叫声和流水声之间不存在道歉的关系。"}], "explanations": {"争吵": "语义：“争吵”指人之间因意见不合而大声吵，鸟叫声和流水声不会争吵。", "应和": "正确：“应和”指声音相互呼应，与“互相”搭配，符合句意。", "对骂": "语域：“对骂”是口语中很粗的说法，不能用于描写山谷里的声音。", "道歉": "语义：“道歉”要向人认错，鸟叫声和流水声之间不存在道歉的关系。"}, "sentence_index": 0, "correct_answer": "应和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把海报应和在墙上，很显眼。", "explanation": "这里应该用〈贴〉。应和指声音相互呼应，把海报贴在墙上要用“贴”。"}, {"text": "这把钥匙和锁应和得很好，一插就开。", "explanation": "这里应该用〈吻合〉。应和指声音相互呼应，钥匙和锁形状相合要用“吻合”。"}, {"text": "他把两张纸应和在一起，很结实。", "explanation": "这里应该用〈粘〉。应和指声音相互呼应，把两张纸粘在一起要用“粘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撒谎", "is_correct": false, "explanation": "语义：“撒谎”指说假话，观众听到歌声后不会因此撒谎。"}, {"text": "让步", "is_correct": false, "explanation": "语义：“让步”指一方向另一方妥协，台下观众并没有与谁对立。"}, {"text": "应和", "is_correct": true, "explanation": "正确：“应和”指跟着歌声发出声音，与“立刻……起来”搭配，符合句意。"}, {"text": "夸口", "is_correct": false, "explanation": "语域：“夸口”偏口语，且与观众跟着唱的情境不合。"}], "explanations": {"撒谎": "语义：“撒谎”指说假话，观众听到歌声后不会因此撒谎。", "让步": "语义：“让步”指一方向另一方妥协，台下观众并没有与谁对立。", "应和": "正确：“应和”指跟着歌声发出声音，与“立刻……起来”搭配，符合句意。", "夸口": "语域：“夸口”偏口语，且与观众跟着唱的情境不合。"}, "sentence_index": 6, "correct_answer": "应和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把照片应和在本子上，很整齐。", "explanation": "这里应该用〈贴〉。应和指声音相互呼应，把照片贴在本子上要用“贴”。"}, {"text": "两根电线互相应和，把电路接在一起。", "explanation": "这里应该用〈连接〉。应和指声音相互呼应，两个物体接在一起要用“连接”。"}, {"text": "他把两块木板应和在一起，钉得很牢。", "explanation": "这里应该用〈钉〉。应和指声音相互呼应，把木板钉在一起要用“钉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋外的鸟叫声和屋里的歌声互相应和很好。", "corrected_sentence": "屋外的鸟叫声和屋里的歌声互相应和得很好。", "error_description": "错误：动词后的程度补语漏了“得”。动词后带表示程度的补语，要说“动词＋得＋补语”，应说“互相应和得很好”，不能说“互相应和很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到这首歌，乐迷们立刻应和下来。", "corrected_sentence": "听到这首歌，乐迷们立刻应和起来。", "error_description": "错误：趋向补语用错。“应和”后面应接“起来”，表示开始并持续，应说“应和起来”，不能说“应和下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
