INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90189, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90189, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "花用是把钱拿去买东西用掉。", "primary_collocate": null, "pronunciation": "huā yòng", "ipa": "xu̯a˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他一个月花用三千块钱。", "target_word": "花用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把这笔钱花用在孩子的书上。", "target_word": "花用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我这个月花用了不少钱买衣服。", "target_word": "花用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的钱要小心花用，不要一下子用完。", "target_word": "花用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天花用多少钱，都记在本子上。", "target_word": "花用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，我们花用了两千块买东西。", "target_word": "花用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把工资都花用在吃饭和买书上。", "target_word": "花用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱我只花用了一半。", "target_word": "花用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生花用父母给的钱，要想一想。", "target_word": "花用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花用了很多钱买新手机。", "target_word": "花用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "花用了", "label": "体标"}, {"form": "花用过", "label": "体标"}, {"form": "花用着", "label": "体标"}], "register": "中性", "sense_fingerprint": "把钱拿去买东西用掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcba9692-cced-4943-a1b3-313ddd5c52a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90189, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花用", "is_correct": true, "explanation": "花用指把钱拿去买东西用掉，与“一个月……三千块钱”的开支语境相符。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指把坏了的东西弄好，不能用来指钱的开支。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能直接带“三千块钱”作宾语。"}, {"text": "浇", "is_correct": false, "explanation": "语义：“浇”指把水洒在植物或土地上，与钱无关。"}], "explanations": {"花用": "花用指把钱拿去买东西用掉，与“一个月……三千块钱”的开支语境相符。", "修理": "语义：“修理”指把坏了的东西弄好，不能用来指钱的开支。", "睡": "配价：“睡”是不及物动词，后面不能直接带“三千块钱”作宾语。", "浇": "语义：“浇”指把水洒在植物或土地上，与钱无关。"}, "sentence_index": 0, "correct_answer": "花用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请先花用这台机器，再开始工作。", "explanation": "这里应该用〈使用〉。花用只用于钱财的开支，操作机器、工具要用使用。"}, {"text": "我们要花用好这块土地，种出更多粮食。", "explanation": "这里应该用〈利用〉。花用指把钱用掉，充分发挥土地、资源的作用要用利用。"}, {"text": "工人们花用了一座大桥。", "explanation": "这里应该用〈修建〉。花用指把钱用掉，建造桥梁、房屋要用修建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90189, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花用", "is_correct": true, "explanation": "花用指把钱用在消费上，与“她把工资都……在吃饭和买书上”的语境相符。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”指击打或拨打，不能用来说钱的去向。"}, {"text": "飞", "is_correct": false, "explanation": "配价：“飞”是不及物动词，不能带“工资”这类受事作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指用水清除污垢，用在钱上不通。"}], "explanations": {"花用": "花用指把钱用在消费上，与“她把工资都……在吃饭和买书上”的语境相符。", "打": "语义：“打”指击打或拨打，不能用来说钱的去向。", "飞": "配价：“飞”是不及物动词，不能带“工资”这类受事作宾语。", "洗": "语义：“洗”指用水清除污垢，用在钱上不通。"}, "sentence_index": 6, "correct_answer": "花用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板把工作花用给每个员工。", "explanation": "这里应该用〈分配〉。花用指钱财的开支，把工作派给各人要用分配。"}, {"text": "他把粮食花用在仓库里，等待冬天。", "explanation": "这里应该用〈储存〉。花用是把钱用掉，把物资存放起来要用储存。"}, {"text": "他从小就喜欢花用邮票，现在已经有三千多张了。", "explanation": "这里应该用〈收集〉。花用指把钱用掉，搜罗、积攒物品要用收集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把零花钱花用买零食上。", "corrected_sentence": "我把零花钱花用在买零食上。", "error_description": "“花用买零食上”缺少介词“在”。“花用”后面接表示用途或地点的成分时要用“在”，应说“花用在买零食上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月我把钱都花用在旅行了上。", "corrected_sentence": "这个月我把钱都花用在旅行上了。", "error_description": "“了”的位置错误。“了”应放在句末，表示完成，说“花用在旅行上了”；“旅行了上”中“了”插在“旅行”和“上”之间，不能这样用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开", "is_correct": true, "explanation": "开：与“合”（闭合）相对，指打开、张开，构成反义。"}, {"text": "唱", "is_correct": false, "explanation": "唱：指发声歌唱，与“合”没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "走：指移动脚步，与“合”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "看：指用眼睛观察，与“合”没有反义关系。"}], "correct_answer": "开", "explanations": {"开": "开：与“合”（闭合）相对，指打开、张开，构成反义。", "唱": "唱：指发声歌唱，与“合”没有反义关系。", "走": "走：指移动脚步，与“合”没有反义关系。", "看": "看：指用眼睛观察，与“合”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "睁", "is_correct": true, "explanation": "睁：指把闭着的眼睛张开，与“合”（闭眼）相反。"}, {"text": "吃", "is_correct": false, "explanation": "吃：指进食，与“合”的闭合义无关，不构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "跑：指快速移动，与“合”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写：指用笔书写，与“合”没有反义关系。"}], "correct_answer": "睁", "explanations": {"睁": "睁：指把闭着的眼睛张开，与“合”（闭眼）相反。", "吃": "吃：指进食，与“合”的闭合义无关，不构成反义。", "跑": "跑：指快速移动，与“合”没有反义关系。", "写": "写：指用笔书写，与“合”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "合是把张开的东西关起来,使其闭拢。", "primary_collocate": null, "pronunciation": "hé", "ipa": "xɤ˧˥", "syllable_count": 1, "sentences": [{"text": "请把书合上,我们开始上课。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了,花慢慢合起来了。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累得眼睛一合就睡着了。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把嘴合上,不要说话了。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子盖太大,合不上。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她合上雨伞,走进了商店。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里,小鸟把翅膀合起来睡觉。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书太厚了,我合不上。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把窗户合上，屋里很安静。", "target_word": "合", "complexity_tier": "T3", "furigana": "tā bǎ chuānghu hé shàng, wūlǐ hěn ānjìng.", "sentence_source": "generated"}, {"text": "他合着眼睛,听了一首歌。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "合上", "label": "复合"}, {"form": "合拢", "label": "复合"}, {"form": "合了", "label": "体标"}, {"form": "合着", "label": "体标"}], "register": "中性", "sense_fingerprint": "合:把张开的东西关上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb4c8f47-f9b5-4427-b6c0-3ded0add6b63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "合", "is_correct": true, "explanation": "合（hé）：把张开的东西关上，指闭合。"}, {"text": "贺", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，贺是祝贺的意思。"}, {"text": "格", "is_correct": false, "explanation": "gé 与 hé 声母不同（g 与 h），格是格子的意思。"}, {"text": "喝", "is_correct": false, "explanation": "hē（第一声）与 hé（第二声）声调不同，喝是饮用的意思。"}], "explanations": {"合": "合（hé）：把张开的东西关上，指闭合。", "贺": "hè（第四声）与 hé（第二声）声调不同，贺是祝贺的意思。", "格": "gé 与 hé 声母不同（g 与 h），格是格子的意思。", "喝": "hē（第一声）与 hé（第二声）声调不同，喝是饮用的意思。"}, "sentence_index": null, "correct_answer": "合"}, "level_3": {"options": [{"text": "合", "is_correct": true, "explanation": "合上：闭拢，把书合起来，与“开始上课”的语境相合。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写上”指在书上写字，与“请把书……我们开始上课”的关书之意不符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦上”要求擦拭某个表面，“把书擦上”说不通，书本不需要擦。"}, {"text": "点", "is_correct": false, "explanation": "搭配：“点”用于点火、点灯，不能与“书”搭配，“把书点上”不成立。"}], "explanations": {"合": "合上：闭拢，把书合起来，与“开始上课”的语境相合。", "写": "语义：“写上”指在书上写字，与“请把书……我们开始上课”的关书之意不符。", "擦": "搭配：“擦上”要求擦拭某个表面，“把书擦上”说不通，书本不需要擦。", "点": "搭配：“点”用于点火、点灯，不能与“书”搭配，“把书点上”不成立。"}, "sentence_index": 0, "correct_answer": "合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "睡觉前，我把灯合上了。", "explanation": "这里应该用〈关〉。灯要用关上，合用于书、盒子、嘴等能开合的东西。"}, {"text": "下雨了，他把鞋合上才出门。", "explanation": "这里应该用〈穿〉。鞋要用穿，合只用于书、盒子、嘴等能开合的东西。"}, {"text": "施工期间，这条马路被合上了，车辆不能通行。", "explanation": "这里应该用〈封〉。道路要用封，合只用于书、盒子、嘴等能开合的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "合", "is_correct": true, "explanation": "合（hé）：把张开的东西关上，指闭合。"}, {"text": "鹤", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，鹤是仙鹤的意思。"}, {"text": "咳", "is_correct": false, "explanation": "ké 与 hé 声母不同（k 与 h），咳是咳嗽的意思。"}, {"text": "隔", "is_correct": false, "explanation": "gé 与 hé 声母不同（g 与 h），隔是隔开的意思。"}], "explanations": {"合": "合（hé）：把张开的东西关上，指闭合。", "鹤": "hè（第四声）与 hé（第二声）声调不同，鹤是仙鹤的意思。", "咳": "ké 与 hé 声母不同（k 与 h），咳是咳嗽的意思。", "隔": "gé 与 hé 声母不同（g 与 h），隔是隔开的意思。"}, "sentence_index": null, "correct_answer": "合"}, "level_3": {"options": [{"text": "合", "is_correct": true, "explanation": "合起来：收拢，指小鸟把翅膀收拢贴在身上。"}, {"text": "扇", "is_correct": false, "explanation": "语义：“扇起来”是拍动翅膀，小鸟夜里睡觉时不会这样做，与句意不符。"}, {"text": "晃", "is_correct": false, "explanation": "搭配：“晃起来”指摇动，“把翅膀晃起来睡觉”说不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象要能清洗，不能与“翅膀”搭配，“洗起来睡觉”不成立。"}], "explanations": {"合": "合起来：收拢，指小鸟把翅膀收拢贴在身上。", "扇": "语义：“扇起来”是拍动翅膀，小鸟夜里睡觉时不会这样做，与句意不符。", "晃": "搭配：“晃起来”指摇动，“把翅膀晃起来睡觉”说不通。", "洗": "搭配：“洗”的对象要能清洗，不能与“翅膀”搭配，“洗起来睡觉”不成立。"}, "sentence_index": 6, "correct_answer": "合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里太吵了，他把电视合上，睡了一会儿。", "explanation": "这里应该用〈关〉。电视要用关，合只用于书、盒子、嘴等能开合的东西。"}, {"text": "夜里很冷，他把被子合上睡觉了。", "explanation": "这里应该用〈盖〉。被子要用盖上，合只用于书、盒子等能开合的东西。"}, {"text": "天冷了，他把帽子合上了。", "explanation": "这里应该用〈戴〉。帽子要用戴，合只用于书、盒子、嘴等能开合的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把箱子合下了。", "corrected_sentence": "妈妈把箱子合上了。", "error_description": "错误：“合下”，补语“下”不能表示闭拢；正确：“合上”，补语“上”表示闭合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本词典太厚，我怎么也合不住。", "corrected_sentence": "这本词典太厚，我怎么也合不上。", "error_description": "错误：“合不住”，补语“住”表示牢牢固定，不能用来表示合拢；正确：“合不上”，表示无法合拢，补语“上”表示闭合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
