INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90192, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "聚拢;结合。", "primary_collocate": null, "pronunciation": "hé", "ipa": "xɤ˧˥", "syllable_count": 1, "sentences": [{"text": "两只手合在一起,他开始祈祷。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这两块木板合在一起,就是一张桌子。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的力量合起来,一定能搬走石头。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两条河在前面合到一起,变成大河。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这两个小盒子合到一起放吧。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个人的钱合起来才买了一台电脑。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把两张图合在一起看看。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两队人合在一起,一共有五十个人。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司合在一起，力量就更大了。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个班合在一起上课,教室太小了。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "合起来", "label": "复合"}, {"form": "合在一起", "label": "复合"}, {"form": "合了", "label": "体标"}], "register": "中性", "sense_fingerprint": "合:聚拢、结合在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb4c8f47-f9b5-4427-b6c0-3ded0add6b63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90192, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "合", "is_correct": true, "explanation": "合（hé）：聚拢、结合在一起。"}, {"text": "褐", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，褐是褐色的意思。"}, {"text": "革", "is_correct": false, "explanation": "gé 与 hé 声母不同（g 与 h），革是皮革、变革的意思。"}, {"text": "咳", "is_correct": false, "explanation": "ké 与 hé 声母不同（k 与 h），咳是咳嗽的意思。"}], "explanations": {"合": "合（hé）：聚拢、结合在一起。", "褐": "hè（第四声）与 hé（第二声）声调不同，褐是褐色的意思。", "革": "gé 与 hé 声母不同（g 与 h），革是皮革、变革的意思。", "咳": "ké 与 hé 声母不同（k 与 h），咳是咳嗽的意思。"}, "sentence_index": null, "correct_answer": "合"}, "level_3": {"options": [{"text": "合", "is_correct": true, "explanation": "合在一起：聚拢、靠拢成一处，指两只手靠到一起。"}, {"text": "分", "is_correct": false, "explanation": "语义：“分”表示分开，与“在一起”的聚拢义相反，“两只手分在一起”说不通。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”指悬挂，不能与“两只手”搭配，“挂在一起”不成立。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”指抛掷，不能表示两只手聚在一起，“扔在一起”不成立。"}], "explanations": {"合": "合在一起：聚拢、靠拢成一处，指两只手靠到一起。", "分": "语义：“分”表示分开，与“在一起”的聚拢义相反，“两只手分在一起”说不通。", "挂": "搭配：“挂”指悬挂，不能与“两只手”搭配，“挂在一起”不成立。", "扔": "搭配：“扔”指抛掷，不能表示两只手聚在一起，“扔在一起”不成立。"}, "sentence_index": 0, "correct_answer": "合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每个月都把工资合到老家去。", "explanation": "这里应该用〈汇〉。寄钱要用汇，合表示把东西聚拢在一起，不能说“合到老家”。"}, {"text": "他渴极了，把水合进杯子里一口喝光。", "explanation": "这里应该用〈倒〉。水要用倒，合不能表示把液体注入容器。"}, {"text": "各地的报告都合到了总部。", "explanation": "这里应该用〈汇总〉。报告要用汇总，合只表示把东西拼在一起，不能说“合到总部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90192, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "合", "is_correct": true, "explanation": "合（hé）：聚拢、结合在一起。"}, {"text": "贺", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，贺是祝贺的意思。"}, {"text": "隔", "is_correct": false, "explanation": "gé 与 hé 声母不同（g 与 h），隔是隔开的意思。"}, {"text": "喝", "is_correct": false, "explanation": "hē（第一声）与 hé（第二声）声调不同，喝是饮用的意思。"}], "explanations": {"合": "合（hé）：聚拢、结合在一起。", "贺": "hè（第四声）与 hé（第二声）声调不同，贺是祝贺的意思。", "隔": "gé 与 hé 声母不同（g 与 h），隔是隔开的意思。", "喝": "hē（第一声）与 hé（第二声）声调不同，喝是饮用的意思。"}, "sentence_index": null, "correct_answer": "合"}, "level_3": {"options": [{"text": "合", "is_correct": true, "explanation": "合在一起：并列放置，指把两张图靠在一起看。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指撕破，与“放在一起看看”的意思相反，图不能这样处理。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”用于食物，不能与“两张图”搭配，“吃在一起”说不通。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能与“两张图”搭配，“喝在一起”不成立。"}], "explanations": {"合": "合在一起：并列放置，指把两张图靠在一起看。", "撕": "语义：“撕”指撕破，与“放在一起看看”的意思相反，图不能这样处理。", "吃": "搭配：“吃”用于食物，不能与“两张图”搭配，“吃在一起”说不通。", "喝": "搭配：“喝”的对象是液体，不能与“两张图”搭配，“喝在一起”不成立。"}, "sentence_index": 6, "correct_answer": "合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩合成了好朋友。", "explanation": "这里应该用〈结成〉。建立友谊要用结成，合表示把东西拼合在一起，不说“合成朋友”。"}, {"text": "同学们在操场合，然后一起出发。", "explanation": "这里应该用〈集合〉。“合”单用时不表示召集、聚集的意思，人群聚在一起要用集合。"}, {"text": "洗完手，他把水龙头合上了。", "explanation": "这里应该用〈关〉。水龙头要用关上，合只用于书、盒子、嘴等能开合的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家店合到在一起，生意更好了。", "corrected_sentence": "两家店合到一起，生意更好了。", "error_description": "错误：「合到在一起」中「到」和「在」两个补语重复使用。正确：说「合到一起」或「合在一起」，只用一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "把两张纸合上一起，装订成一本书。", "corrected_sentence": "把两张纸合在一起，装订成一本书。", "error_description": "错误：“合上一起”，补语“上”表示闭合，不能与“一起”搭配；正确：“合在一起”，表示聚拢到同一处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
