INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90193, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "唱", "is_correct": false, "explanation": "指发出歌声，与“插”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "指快速移动双腿前进，与“插”没有反义关系。"}, {"text": "拔", "is_correct": true, "explanation": "指把立在里面的东西抽出来，与“插”的动作相反，是反义词。"}, {"text": "吃", "is_correct": false, "explanation": "指把食物放进嘴里咽下，与“插”没有反义关系。"}], "correct_answer": "拔", "explanations": {"唱": "指发出歌声，与“插”没有反义关系。", "跑": "指快速移动双腿前进，与“插”没有反义关系。", "拔": "指把立在里面的东西抽出来，与“插”的动作相反，是反义词。", "吃": "指把食物放进嘴里咽下，与“插”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90193, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把细长的东西放进去，立在里面。", "primary_collocate": null, "pronunciation": "chā", "ipa": "ʈʂʰa˥", "syllable_count": 1, "sentences": [{"text": "她把花插在花瓶里。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的花瓶里插着几朵红花。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕上插着六根蜡烛。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在沙滩上插了一面小旗。", "target_word": "插", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要把筷子插在饭里。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在花盆里插了一根小木棍。", "target_word": "插", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山顶上插着一面红旗，很远就能看见。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在地里插了几根竹竿。", "target_word": "插", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把伞插在门口的伞筒里。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在雪地里插了一根树枝。", "target_word": "插", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "插着", "label": "着体标"}, {"form": "插了", "label": "了体标"}, {"form": "插过", "label": "过体标"}, {"form": "插入", "label": "复合词"}], "register": "中性", "sense_fingerprint": "插|把细长的东西放进去并立在里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '410036aa-66b9-4036-830e-495e3a8f36e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90193, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "插", "is_correct": true, "explanation": "正确：插（chā），指把细长的东西放进去并立在里面。"}, {"text": "查", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是检查。"}, {"text": "茶", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是茶叶。"}, {"text": "擦", "is_correct": false, "explanation": "cā（平舌音 c）与 chā（翘舌音 ch）声母不同，意思是擦拭。"}, {"text": "掺", "is_correct": false, "explanation": "chān 与 chā 韵母不同（多一个 -n），意思是掺和。"}], "explanations": {"插": "正确：插（chā），指把细长的东西放进去并立在里面。", "查": "chá（第二声）与 chā（第一声）声调不同，意思是检查。", "茶": "chá（第二声）与 chā（第一声）声调不同，意思是茶叶。", "擦": "cā（平舌音 c）与 chā（翘舌音 ch）声母不同，意思是擦拭。", "掺": "chān 与 chā 韵母不同（多一个 -n），意思是掺和。"}, "sentence_index": null, "correct_answer": "插"}, "level_3": {"options": [{"text": "插", "is_correct": true, "explanation": "正确：“插”指把花放进花瓶里并立住，与“在花瓶里”搭配，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”要加热，花不能煮在花瓶里。"}, {"text": "倒", "is_correct": false, "explanation": "语义：“倒”指把液体倒出，花不是液体，不能倒在花瓶里。"}, {"text": "别", "is_correct": false, "explanation": "搭配：“别”一般接衣服、头发等，不能说“别在花瓶里”。"}], "explanations": {"插": "正确：“插”指把花放进花瓶里并立住，与“在花瓶里”搭配，符合句意。", "煮": "语义：“煮”要加热，花不能煮在花瓶里。", "倒": "语义：“倒”指把液体倒出，花不是液体，不能倒在花瓶里。", "别": "搭配：“别”一般接衣服、头发等，不能说“别在花瓶里”。"}, "sentence_index": 0, "correct_answer": "插"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把海报插在墙上，很显眼。", "explanation": "这里应该用〈贴〉。插指把细长的东西放进去并立在里面，海报平贴在墙上要用“贴”。"}, {"text": "他把饼干插在桌子上。", "explanation": "这里应该用〈放〉。插指把细长的东西放进去并立在里面，饼干这类东西放在桌上要用“放”。"}, {"text": "他用笔插了一行字。", "explanation": "这里应该用〈写〉。插指把细长的东西放进去并立在里面，写字要用“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90193, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "插", "is_correct": true, "explanation": "正确：插（chā），指把细长的东西放进去并立在里面。"}, {"text": "察", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是观察。"}, {"text": "岔", "is_correct": false, "explanation": "chà（第四声）与 chā（第一声）声调不同，意思是岔开、分岔。"}, {"text": "搽", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是涂抹。"}, {"text": "昌", "is_correct": false, "explanation": "chāng 比 chā 多一个 -ng 韵尾，意思是昌盛。"}], "explanations": {"插": "正确：插（chā），指把细长的东西放进去并立在里面。", "察": "chá（第二声）与 chā（第一声）声调不同，意思是观察。", "岔": "chà（第四声）与 chā（第一声）声调不同，意思是岔开、分岔。", "搽": "chá（第二声）与 chā（第一声）声调不同，意思是涂抹。", "昌": "chāng 比 chā 多一个 -ng 韵尾，意思是昌盛。"}, "sentence_index": null, "correct_answer": "插"}, "level_3": {"options": [{"text": "挖", "is_correct": false, "explanation": "语义：“挖”指挖掘，不能说“挖着一面红旗”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”要用水清洗东西，与“山顶上”搭不上。"}, {"text": "插", "is_correct": true, "explanation": "正确：“插着”表示红旗立在山顶上的状态，符合句意。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣服，不能说“穿着一面红旗”。"}], "explanations": {"挖": "语义：“挖”指挖掘，不能说“挖着一面红旗”。", "洗": "语义：“洗”要用水清洗东西，与“山顶上”搭不上。", "插": "正确：“插着”表示红旗立在山顶上的状态，符合句意。", "穿": "搭配：“穿”的对象是衣服，不能说“穿着一面红旗”。"}, "sentence_index": 6, "correct_answer": "插"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士把药膏插在伤口上，很快就好了。", "explanation": "这里应该用〈涂〉。插指把细长的东西放进去并立在里面，药膏抹在伤口上要用“涂”。"}, {"text": "他把水插进瓶子里。", "explanation": "这里应该用〈装〉。插指把细长的东西放进去并立在里面，液体装进容器要用“装”。"}, {"text": "他把衣服插干净了。", "explanation": "这里应该用〈洗〉。插指把细长的东西放进去并立在里面，把衣服弄干净要用“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在花瓶里着插一束白花。", "corrected_sentence": "她在花瓶里插着一束白花。", "error_description": "错误：“着”的位置不对。表示状态持续的“着”应紧跟动词，要说“插着一束白花”，不能说“着插一束白花”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他树枝插在雪地里。", "corrected_sentence": "他把树枝插在雪地里。", "error_description": "错误：“把”字句漏了“把”。“树枝”是被插的东西，要放在“把”后面，应说“他把树枝插在雪地里”，不能说“他树枝插在雪地里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90194, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "唱", "is_correct": false, "explanation": "指发出歌声，与“插”没有反义关系。"}, {"text": "拔", "is_correct": true, "explanation": "指把插进空隙里的东西抽出来，与“插”的动作相反，是反义词。"}, {"text": "读", "is_correct": false, "explanation": "指看着文字发出声音或理解内容，与“插”没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "指迈步前进，与“插”没有反义关系。"}], "correct_answer": "拔", "explanations": {"唱": "指发出歌声，与“插”没有反义关系。", "拔": "指把插进空隙里的东西抽出来，与“插”的动作相反，是反义词。", "读": "指看着文字发出声音或理解内容，与“插”没有反义关系。", "走": "指迈步前进，与“插”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90194, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跑", "is_correct": false, "explanation": "指快速移动双腿前进，与“插”没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "指脸上露出高兴的表情或发出笑声，与“插”没有反义关系。"}, {"text": "拔", "is_correct": true, "explanation": "指把插进空隙里的东西抽出来，与“插”的动作相反，是反义词。"}, {"text": "吃", "is_correct": false, "explanation": "指把食物放进嘴里咽下，与“插”没有反义关系。"}], "correct_answer": "拔", "explanations": {"跑": "指快速移动双腿前进，与“插”没有反义关系。", "笑": "指脸上露出高兴的表情或发出笑声，与“插”没有反义关系。", "拔": "指把插进空隙里的东西抽出来，与“插”的动作相反，是反义词。", "吃": "指把食物放进嘴里咽下，与“插”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90194, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把细长或薄的东西放进空隙。", "primary_collocate": null, "pronunciation": "chā", "ipa": "ʈʂʰa˥", "syllable_count": 1, "sentences": [{"text": "他把钥匙插进锁里。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一张纸条插进门缝里。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把照片插进书页中间。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把耳机插到手机上。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把一把木尺插进书架的空隙里。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用细铁丝插进锁孔，把门打开了。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行卡插反了，机器没反应。", "target_word": "插", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把这把小刀插进刀鞘里。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上有道缝，小明把硬币插了进去。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先把卡插进去，再输入密码。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "插着", "label": "着体标"}, {"form": "插了", "label": "了体标"}, {"form": "插过", "label": "过体标"}, {"form": "插入", "label": "复合词"}], "register": "中性", "sense_fingerprint": "插|把细长或薄的东西放进空隙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '410036aa-66b9-4036-830e-495e3a8f36e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90194, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "插", "is_correct": true, "explanation": "正确：插（chā），指把细长或薄的东西放进空隙。"}, {"text": "查", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是检查。"}, {"text": "茶", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是茶叶。"}, {"text": "擦", "is_correct": false, "explanation": "cā（平舌音 c）与 chā（翘舌音 ch）声母不同，意思是擦拭。"}, {"text": "掺", "is_correct": false, "explanation": "chān 与 chā 韵母不同（多一个 -n），意思是掺和。"}], "explanations": {"插": "正确：插（chā），指把细长或薄的东西放进空隙。", "查": "chá（第二声）与 chā（第一声）声调不同，意思是检查。", "茶": "chá（第二声）与 chā（第一声）声调不同，意思是茶叶。", "擦": "cā（平舌音 c）与 chā（翘舌音 ch）声母不同，意思是擦拭。", "掺": "chān 与 chā 韵母不同（多一个 -n），意思是掺和。"}, "sentence_index": null, "correct_answer": "插"}, "level_3": {"options": [{"text": "摸", "is_correct": false, "explanation": "语义：“摸”指用手轻轻碰，不表示把东西放进空隙。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指抛出去，钥匙不能扔进锁孔里。"}, {"text": "插", "is_correct": true, "explanation": "正确：“插”指把细长的东西放进空隙，钥匙插进锁孔，符合句意。"}, {"text": "开", "is_correct": false, "explanation": "搭配：“开”要带“锁”“门”作宾语，不能说“开进锁里”。"}], "explanations": {"摸": "语义：“摸”指用手轻轻碰，不表示把东西放进空隙。", "扔": "语义：“扔”指抛出去，钥匙不能扔进锁孔里。", "插": "正确：“插”指把细长的东西放进空隙，钥匙插进锁孔，符合句意。", "开": "搭配：“开”要带“锁”“门”作宾语，不能说“开进锁里”。"}, "sentence_index": 0, "correct_answer": "插"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把糖插进罐子里。", "explanation": "这里应该用〈装〉。插指把细长或薄的东西放进空隙，把糖放进罐子用“装”。"}, {"text": "他把苹果插在桌子中间。", "explanation": "这里应该用〈放〉。插指把细长或薄的东西放进空隙，苹果这类圆物放在桌上要用“放”。"}, {"text": "他把牛奶插进杯子里。", "explanation": "这里应该用〈倒〉。插指把细长或薄的东西放进空隙，液体要用“倒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90194, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "插", "is_correct": true, "explanation": "正确：插（chā），指把细长或薄的东西放进空隙。"}, {"text": "察", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是观察。"}, {"text": "岔", "is_correct": false, "explanation": "chà（第四声）与 chā（第一声）声调不同，意思是岔开、分岔。"}, {"text": "搽", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是涂抹。"}, {"text": "昌", "is_correct": false, "explanation": "chāng 比 chā 多一个 -ng 韵尾，意思是昌盛。"}], "explanations": {"插": "正确：插（chā），指把细长或薄的东西放进空隙。", "察": "chá（第二声）与 chā（第一声）声调不同，意思是观察。", "岔": "chà（第四声）与 chā（第一声）声调不同，意思是岔开、分岔。", "搽": "chá（第二声）与 chā（第一声）声调不同，意思是涂抹。", "昌": "chāng 比 chā 多一个 -ng 韵尾，意思是昌盛。"}, "sentence_index": null, "correct_answer": "插"}, "level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "语义：“写”用于写字，银行卡不能写反。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与“银行卡……反了”搭不上。"}, {"text": "插", "is_correct": true, "explanation": "正确：“插”指把卡放进插口，插反了机器就没反应，符合句意。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”一般用于果实、花叶，不能说“银行卡摘反了”。"}], "explanations": {"写": "语义：“写”用于写字，银行卡不能写反。", "唱": "语义：“唱”指发出歌声，与“银行卡……反了”搭不上。", "插": "正确：“插”指把卡放进插口，插反了机器就没反应，符合句意。", "摘": "搭配：“摘”一般用于果实、花叶，不能说“银行卡摘反了”。"}, "sentence_index": 6, "correct_answer": "插"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把药插在我的伤口上。", "explanation": "这里应该用〈涂〉。插指把细长或薄的东西放进空隙，药膏涂在伤口上要用“涂”。"}, {"text": "他把邮票插在信封的右上角。", "explanation": "这里应该用〈贴〉。插指把东西放进空隙，邮票粘在信封上要用“贴”。"}, {"text": "他把帽子插在头上。", "explanation": "这里应该用〈戴〉。插指把细长或薄的东西放进空隙，把帽子戴在头上要用“戴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她硬币插进了投币口。", "corrected_sentence": "她把硬币插进了投币口。", "error_description": "错误：“把”字句漏了“把”。“硬币”是被处置的宾语，要放在“把”后面，应说“她把硬币插进了投币口”，不能说“她硬币插进了投币口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把钥匙插了反，锁转不动。", "corrected_sentence": "这把钥匙插反了，锁转不动。", "error_description": "错误：“了”的位置不对。动词带结果补语时，“了”要放在补语后面，应说“插反了”，不能说“插了反”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
