INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90195, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "英尺是一种量长度的单位。", "primary_collocate": null, "pronunciation": "yīng chǐ", "ipa": "iŋ˥ ʈʂʰɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "这张桌子长六英尺。", "target_word": "英尺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的身高是五英尺十英寸。", "target_word": "英尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "美国人常用英尺量长度。", "target_word": "英尺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条河有两百英尺宽。", "target_word": "英尺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机飞到了三万英尺的高空。", "target_word": "英尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间宽十英尺，长十二英尺。", "target_word": "英尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "英尺是一种量长度的单位。", "target_word": "英尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跳了十五英尺远，真厉害。", "target_word": "英尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树大概有四十英尺高。", "target_word": "英尺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你告诉我，一英尺有多长？", "target_word": "英尺", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方英尺", "label": "复合"}, {"form": "立方英尺", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来量长度的英制单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a138068c-42b9-49dc-b301-f8a5ab1de2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90195, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "英尺", "is_correct": true, "explanation": "英尺是长度单位，可以量桌子的长度，符合“长六……”。"}, {"text": "公斤", "is_correct": false, "explanation": "搭配：“长”要用长度单位，“公斤”量重量，不能说“长六公斤”。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”量书册，不能用来量桌子的长度。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”量动物或成对的小物件，不能用来量长度。"}], "explanations": {"英尺": "英尺是长度单位，可以量桌子的长度，符合“长六……”。", "公斤": "搭配：“长”要用长度单位，“公斤”量重量，不能说“长六公斤”。", "本": "语义：“本”量书册，不能用来量桌子的长度。", "只": "语义：“只”量动物或成对的小物件，不能用来量长度。"}, "sentence_index": 0, "correct_answer": "英尺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块手机屏幕是六英尺的。", "explanation": "这里应该用〈英寸〉。手机、电视的屏幕尺寸用英寸，英尺太大，不这么说。"}, {"text": "从学校到机场有两英尺。", "explanation": "这里应该用〈英里〉。较远的距离用英里，英尺只适合很短的距离。"}, {"text": "这个房间的面积是二十英尺。", "explanation": "这里应该用〈平方英尺〉。面积是平方单位，英尺只量长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90195, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "英尺", "is_correct": true, "explanation": "英尺是英制长度单位，正是“量长度的单位”。"}, {"text": "克", "is_correct": false, "explanation": "语义：“克”是重量单位，与“量长度”矛盾。"}, {"text": "升", "is_correct": false, "explanation": "语义：“升”是容积单位，不用来量长度。"}, {"text": "小时", "is_correct": false, "explanation": "搭配：“小时”是时间单位，不能用来说明长度单位。"}], "explanations": {"英尺": "英尺是英制长度单位，正是“量长度的单位”。", "克": "语义：“克”是重量单位，与“量长度”矛盾。", "升": "语义：“升”是容积单位，不用来量长度。", "小时": "搭配：“小时”是时间单位，不能用来说明长度单位。"}, "sentence_index": 6, "correct_answer": "英尺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把尺子长三十英尺。", "explanation": "这里应该用〈厘米〉。尺子这类小物件的长度用厘米，英尺太长。"}, {"text": "这袋大米重五英尺。", "explanation": "这里应该用〈公斤〉。英尺只量长度，表示重量要用公斤。"}, {"text": "这个箱子的体积是三十英尺。", "explanation": "这里应该用〈立方英尺〉。体积是立方单位，英尺只量长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根木棍长六只英尺。", "corrected_sentence": "这根木棍长六英尺。", "error_description": "错误：“只”是量动物或成对小物件的量词，不能用来修饰“英尺”。量长度时应直接说“长六英尺”，应去掉“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥有五百英尺得长。", "corrected_sentence": "这座桥有五百英尺长。", "error_description": "助词错误：这里不用“得”，应说“这座桥有五百英尺长”，不说“这座桥有五百英尺得长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
