INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90196, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "英制长度单位，一英尺约等于零点三零四八米。", "primary_collocate": null, "pronunciation": "yīng chǐ", "ipa": "iŋ˥ ʈʂʰɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "一英尺约等于三十厘米。", "target_word": "英尺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "十英尺差不多是三米。", "target_word": "英尺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座楼高三百英尺，约九十一米。", "target_word": "英尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把二十米换成英尺。", "target_word": "英尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球架高十英尺，约三米。", "target_word": "英尺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一英尺比三十厘米长一点。", "target_word": "英尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块木板长八英尺，正好够用。", "target_word": "英尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百英尺差不多是三十米。", "target_word": "英尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条跑道长三千英尺，约九百多米。", "target_word": "英尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "英制里的英尺，在中国不太常用。", "target_word": "英尺", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方英尺", "label": "复合"}, {"form": "立方英尺", "label": "复合"}], "register": "中性", "sense_fingerprint": "英制长度单位，约等于零点三零四八米", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a138068c-42b9-49dc-b301-f8a5ab1de2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "英尺", "is_correct": true, "explanation": "一英尺约等于三十厘米，符合句意。"}, {"text": "克", "is_correct": false, "explanation": "语义：“克”量重量，不能与厘米这样的长度单位相等。"}, {"text": "升", "is_correct": false, "explanation": "语义：“升”量容积，不能换算成长度。"}, {"text": "小时", "is_correct": false, "explanation": "搭配：“小时”是时间单位，不能与厘米换算。"}], "explanations": {"英尺": "一英尺约等于三十厘米，符合句意。", "克": "语义：“克”量重量，不能与厘米这样的长度单位相等。", "升": "语义：“升”量容积，不能换算成长度。", "小时": "搭配：“小时”是时间单位，不能与厘米换算。"}, "sentence_index": 0, "correct_answer": "英尺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电视是二十英尺的。", "explanation": "这里应该用〈英寸〉。电视、屏幕的尺寸用英寸，英尺太大，不这么说。"}, {"text": "这个水箱的体积是三十英尺。", "explanation": "这里应该用〈立方英尺〉。体积是立方单位，英尺只量长度。"}, {"text": "从纽约到波士顿有三百英尺。", "explanation": "这里应该用〈英里〉。城市之间的远距离用英里，英尺只适合很短的距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "英尺", "is_correct": true, "explanation": "英尺是长度单位，木板长八英尺，符合句意。"}, {"text": "公斤", "is_correct": false, "explanation": "搭配：“长”要用长度单位，“公斤”量重量，不能说“长八公斤”。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”量动物或成对的小物件，不能用来量木板的长度。"}, {"text": "元", "is_correct": false, "explanation": "语义：“元”是货币单位，与“长”和“够用”都不合。"}], "explanations": {"英尺": "英尺是长度单位，木板长八英尺，符合句意。", "公斤": "搭配：“长”要用长度单位，“公斤”量重量，不能说“长八公斤”。", "只": "语义：“只”量动物或成对的小物件，不能用来量木板的长度。", "元": "语义：“元”是货币单位，与“长”和“够用”都不合。"}, "sentence_index": 6, "correct_answer": "英尺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支铅笔长二十英尺。", "explanation": "这里应该用〈厘米〉。铅笔这类小物件的长度用厘米，英尺太长。"}, {"text": "这块地的面积是五百英尺。", "explanation": "这里应该用〈平方英尺〉。面积是平方单位，英尺只量长度。"}, {"text": "这筐苹果重十英尺。", "explanation": "这里应该用〈公斤〉。英尺是长度单位，表示重量要用公斤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根绳子长五只英尺。", "corrected_sentence": "这根绳子长五英尺。", "error_description": "错误：“只”是量动物或成对小物件的量词，不能用来修饰“英尺”。量长度时应直接说“长五英尺”，应去掉“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路有三十个英尺宽。", "corrected_sentence": "这条路有三十英尺宽。", "error_description": "量词错误：“英尺”本身就是量词，数词直接加在前面，不能再加“个”。应去掉“个”，说“这条路有三十英尺宽”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90198, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分裂", "is_correct": true, "explanation": "“分裂”与“团结”意思相反，指分开、不再联合。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”是独立的思维活动，与“团结”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”是体育活动，与“团结”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”是文艺活动，与“团结”没有反义关系。"}], "correct_answer": "分裂", "explanations": {"分裂": "“分裂”与“团结”意思相反，指分开、不再联合。", "思考": "“思考”是独立的思维活动，与“团结”没有反义关系。", "游泳": "“游泳”是体育活动，与“团结”没有反义关系。", "唱歌": "“唱歌”是文艺活动，与“团结”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90198, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分裂", "is_correct": true, "explanation": "“分裂”与“团结”意思相反，指分开、不再联合。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”是书写动作，与“团结”没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "“洗澡”是日常生活活动，与“团结”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”是学习活动，与“团结”没有反义关系。"}], "correct_answer": "分裂", "explanations": {"分裂": "“分裂”与“团结”意思相反，指分开、不再联合。", "写字": "“写字”是书写动作，与“团结”没有反义关系。", "洗澡": "“洗澡”是日常生活活动，与“团结”没有反义关系。", "读书": "“读书”是学习活动，与“团结”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90198, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了共同目标而联合、结合。", "primary_collocate": null, "pronunciation": "tuán jié", "ipa": "tʰwan˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "我们要团结起来解决问题。", "target_word": "团结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家团结一心，才能成功。", "target_word": "团结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我们要团结同学。", "target_word": "团结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了比赛，全班团结在一起。", "target_word": "团结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有团结，我们才能赢。", "target_word": "团结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们团结起来，争取更好的待遇。", "target_word": "团结", "complexity_tier": "T3", "furigana": "gōng rén men tuán jié qǐ lái zhēng qǔ gèng hǎo de dài yù", "sentence_source": "generated"}, {"text": "各国团结起来，一起帮助穷人。", "target_word": "团结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们团结起来，一起完成了任务。", "target_word": "团结", "complexity_tier": "T3", "furigana": "tā men tuán jié qǐ lái yì qǐ wán chéng le rèn wu", "sentence_source": "generated"}, {"text": "我们团结起来，把房子盖好了。", "target_word": "团结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组团结得很好，完成了任务。", "target_word": "团结", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "团结了", "label": "体标"}, {"form": "團結", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为了共同目标而联合在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f5c63e9-0e4b-49d3-a0e2-d030fdf3d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90198, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "团结", "is_correct": true, "explanation": "“团结”表示为共同目标而联合，与“起来”和“解决问题”搭配，句意通顺。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”表示流泪，与“解决问题”的意思不合。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”表示休息，不能用来解决问题。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃起来”表示味道，不能说“吃起来解决问题”。"}], "explanations": {"团结": "“团结”表示为共同目标而联合，与“起来”和“解决问题”搭配，句意通顺。", "哭": "语义：“哭”表示流泪，与“解决问题”的意思不合。", "睡": "语义：“睡”表示休息，不能用来解决问题。", "吃": "搭配：“吃起来”表示味道，不能说“吃起来解决问题”。"}, "sentence_index": 0, "correct_answer": "团结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把三张桌子团结起来。", "explanation": "这里应该用〈拼〉。团结用于人或集体，桌子要说“拼”。"}, {"text": "这条桥团结两岸。", "explanation": "这里应该用〈连接〉。团结用于人，不用于桥梁把两岸连起来。"}, {"text": "这些零件团结在一起，组装成了一台机器。", "explanation": "这里应该用〈组合〉。团结指人或集体为共同目标而联合，零件之间是拼装关系，应说组合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "团结", "is_correct": true, "explanation": "“团结起来”表示人们为共同目标联合，与“各国”和“一起帮助穷人”意思一致。"}, {"text": "竞争", "is_correct": false, "explanation": "语义：“竞争”与“一起帮助穷人”的意思相反，句子说不通。"}, {"text": "逃", "is_correct": false, "explanation": "语义：“逃”表示逃避，不能与“一起帮助穷人”搭配。"}, {"text": "散", "is_correct": false, "explanation": "搭配：“散起来”不是常用搭配，而且与“一起帮助”的意思矛盾。"}], "explanations": {"团结": "“团结起来”表示人们为共同目标联合，与“各国”和“一起帮助穷人”意思一致。", "竞争": "语义：“竞争”与“一起帮助穷人”的意思相反，句子说不通。", "逃": "语义：“逃”表示逃避，不能与“一起帮助穷人”搭配。", "散": "搭配：“散起来”不是常用搭配，而且与“一起帮助”的意思矛盾。"}, "sentence_index": 6, "correct_answer": "团结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一个人团结起来，把难题解决了。", "explanation": "这里应该用〈振作〉。团结要求两方或多人为共同目标而联合，一个人不能说团结起来；自己振作要说“振作起来”。"}, {"text": "他们团结成了一对夫妻。", "explanation": "这里应该用〈结成〉。团结指为共同目标而联合，不用于婚姻关系；结成夫妻要说“结成”。"}, {"text": "他团结了一只流浪猫，把它带回了家。", "explanation": "这里应该用〈收养〉。团结的对象是人或集体，不能用于动物；领养回家要说“收养”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家团结下来，把箱子搬走了。", "corrected_sentence": "大家团结起来，把箱子搬走了。", "error_description": "错误形式：“团结下来”；正确形式：“团结起来”。表示联合的趋向补语应用“起来”，不用“下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家很团结起来，把操场打扫干净了。", "corrected_sentence": "大家团结起来，把操场打扫干净了。", "error_description": "错误形式：“很团结起来”；正确形式：“团结起来”。“团结起来”表示动作开始并联合，前面不能加程度副词“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
