INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90201, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "葡萄是一串一串的圆圆的小水果，酸酸甜甜的。", "primary_collocate": null, "pronunciation": "pú táo", "ipa": "pʰu˧˥ tʰɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "这串葡萄又大又甜。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天早上吃一些葡萄。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把葡萄洗干净了。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗葡萄有点酸。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子最爱吃紫色的葡萄。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一盘葡萄。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了两斤葡萄。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把葡萄一颗一颗放进嘴里。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葡萄皮可以吃吗？", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃葡萄的时候不用剥皮。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一串葡萄", "label": "量词"}, {"form": "一颗葡萄", "label": "量词"}, {"form": "葡萄干", "label": "复合"}, {"form": "葡萄酒", "label": "复合"}], "register": "中性", "sense_fingerprint": "成串的圆形小水果，可以直接吃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0e4be8-25eb-4115-9c6a-5a16b534add7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90201, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "葡萄", "is_correct": true, "explanation": "正确：「葡萄」成串，又大又甜，与句意相合。"}, {"text": "西瓜", "is_correct": false, "explanation": "搭配：「西瓜」不说「这串」，应说「这个」或「这块」。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不说「又甜」，与句中对味道的描述不合。"}, {"text": "橘子", "is_correct": false, "explanation": "搭配：「橘子」不用「串」计量，应说「这个」或「这瓣」。"}], "explanations": {"葡萄": "正确：「葡萄」成串，又大又甜，与句意相合。", "西瓜": "搭配：「西瓜」不说「这串」，应说「这个」或「这块」。", "鱼": "语义：鱼不说「又甜」，与句中对味道的描述不合。", "橘子": "搭配：「橘子」不用「串」计量，应说「这个」或「这瓣」。"}, "sentence_index": 0, "correct_answer": "葡萄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给病人输了一些葡萄，补充能量。", "explanation": "这里应该用〈葡萄糖〉。葡萄是水果，静脉输液补充能量用的是葡萄糖，不能说输葡萄。"}, {"text": "我在葡萄里干活，满头大汗。", "explanation": "这里应该用〈葡萄园〉。葡萄是果实，不能当场地；在地里干活要说葡萄园，不能用葡萄。"}, {"text": "我们一起喝了葡萄，有点醉了。", "explanation": "这里应该用〈葡萄酒〉。葡萄是水果，喝了会醉的是酒，要说葡萄酒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90201, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "葡萄", "is_correct": true, "explanation": "正确：「两斤葡萄」指按斤称的水果，与句意相合。"}, {"text": "香水", "is_correct": false, "explanation": "搭配：香水按瓶或毫升计，不按斤称。"}, {"text": "钻石", "is_correct": false, "explanation": "搭配：钻石按克拉计，不说「两斤」。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能购买，「买了两斤空气」意思不通。"}], "explanations": {"葡萄": "正确：「两斤葡萄」指按斤称的水果，与句意相合。", "香水": "搭配：香水按瓶或毫升计，不按斤称。", "钻石": "搭配：钻石按克拉计，不说「两斤」。", "空气": "语义：空气不能购买，「买了两斤空气」意思不通。"}, "sentence_index": 6, "correct_answer": "葡萄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "葡萄晒干以后，就成了葡萄，可以放很久。", "explanation": "这里应该用〈葡萄干〉。葡萄晒干后叫葡萄干，不能说成葡萄。"}, {"text": "我每天早上都喝一杯葡萄，很解渴。", "explanation": "这里应该用〈葡萄汁〉。葡萄是水果，要喝得说葡萄汁。"}, {"text": "吃葡萄时，我把葡萄吐了出来，因为太硬了。", "explanation": "这里应该用〈葡萄籽〉。吃葡萄时吐出来的硬东西是籽，要说葡萄籽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只葡萄，很甜。", "corrected_sentence": "我买了一串葡萄，很甜。", "error_description": "错误在量词：葡萄成串，量词应用「串」，「只」多用于动物，不能用来数葡萄。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买的这些葡萄们很新鲜。", "corrected_sentence": "我买的这些葡萄很新鲜。", "error_description": "错误在「们」：「葡萄」表示的是水果，不能加「们」表示复数，应说「这些葡萄」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
