INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90202, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "落叶藤本植物，果实成串，圆形或椭圆形，可食用或酿酒。", "primary_collocate": null, "pronunciation": "pú táo", "ipa": "pʰu˧˥ tʰɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "葡萄是一种藤本植物。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葡萄的叶子到秋天会掉。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在院子里种了葡萄。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种葡萄可以用来酿酒。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葡萄需要架子，才能向上长。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上种满了葡萄。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葡萄要在春天剪枝。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葡萄的果实成串，圆圆的。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葡萄喜欢阳光和干燥的天气。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葡萄在夏天开花，秋天成熟。", "target_word": "葡萄", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "葡萄酒", "label": "复合"}, {"form": "葡萄干", "label": "复合"}, {"form": "葡萄藤", "label": "复合"}], "register": "中性", "sense_fingerprint": "作为藤本植物的葡萄，涉及种植、生长、酿酒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0e4be8-25eb-4115-9c6a-5a16b534add7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90202, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "葡萄", "is_correct": true, "explanation": "正确：葡萄是落叶藤本植物，与句意相合。"}, {"text": "竹子", "is_correct": false, "explanation": "语义：竹子是禾本科植物，不是藤本植物。"}, {"text": "松树", "is_correct": false, "explanation": "语义：松树是乔木，不是藤本植物。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：「石头」不是生物，不能与「一种藤本植物」的类属搭配。"}], "explanations": {"葡萄": "正确：葡萄是落叶藤本植物，与句意相合。", "竹子": "语义：竹子是禾本科植物，不是藤本植物。", "松树": "语义：松树是乔木，不是藤本植物。", "石头": "搭配：「石头」不是生物，不能与「一种藤本植物」的类属搭配。"}, "sentence_index": 0, "correct_answer": "葡萄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶葡萄很醇厚，适合配牛排。", "explanation": "这里应该用〈葡萄酒〉。醇厚和「一瓶」都是说酒的，葡萄是植物。"}, {"text": "护士给病人输了葡萄，补充了不少能量。", "explanation": "这里应该用〈葡萄糖〉。葡萄是植物的果实，不能用来输液；补充能量用的是葡萄糖。"}, {"text": "这种葡萄晒干以后，就成了葡萄。", "explanation": "这里应该用〈葡萄干〉。晒干后的葡萄叫葡萄干，不能说成葡萄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90202, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "葡萄", "is_correct": true, "explanation": "正确：葡萄有枝条，要在春天修剪，与句意相合。"}, {"text": "小麦", "is_correct": false, "explanation": "语义：小麦是禾本科草本，没有需要春天修剪的枝条。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：「剪枝」的对象要是有枝条的植物，「桌子」不能剪枝。"}, {"text": "水稻", "is_correct": false, "explanation": "语义：水稻是禾本作物，春天要插秧，不是剪枝。"}], "explanations": {"葡萄": "正确：葡萄有枝条，要在春天修剪，与句意相合。", "小麦": "语义：小麦是禾本科草本，没有需要春天修剪的枝条。", "桌子": "搭配：「剪枝」的对象要是有枝条的植物，「桌子」不能剪枝。", "水稻": "语义：水稻是禾本作物，春天要插秧，不是剪枝。"}, "sentence_index": 6, "correct_answer": "葡萄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我早上喝了一杯葡萄，很甜。", "explanation": "这里应该用〈葡萄汁〉。葡萄是植物和它的果实，不能直接「喝一杯」，要说葡萄汁。"}, {"text": "我们用葡萄包饭，很香。", "explanation": "这里应该用〈葡萄叶〉。包饭用的是叶子，不能用葡萄本身。"}, {"text": "爷爷剪下一根葡萄，长两米多。", "explanation": "这里应该用〈葡萄藤〉。能论「根」、剪下来的长枝条是葡萄藤，不能只说葡萄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里种着一只葡萄。", "corrected_sentence": "院子里种着一株葡萄。", "error_description": "错误在量词：葡萄植株应用「株」，「只」用于动物，不能说「一只葡萄」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片山坡很适合种葡萄们。", "corrected_sentence": "这片山坡很适合种葡萄。", "error_description": "错误在「们」：「葡萄」作为植物名词不加「们」，应说「种葡萄」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
