INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90205, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "工人在盖房子、修路。", "primary_collocate": null, "pronunciation": "shī gōng", "ipa": "ʂʅ˥ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "工人们正在路上施工。", "target_word": "施工", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "前面的马路在施工，我们走另一条路吧。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这栋楼从去年开始施工。", "target_word": "施工", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "施工的时候，工人都要戴安全帽。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小区门口昨天开始施工，晚上很吵。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天不能施工，工人们只好休息。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在河边施工了三个月，才修好那座桥。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们顶着太阳在高楼上施工。", "target_word": "施工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路要施工一个星期，请大家绕行。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们已经施工三天了，路快修好了。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "施工队", "label": "复合词"}, {"form": "施工现场", "label": "复合词"}, {"form": "施工图", "label": "复合词"}], "register": "中性", "sense_fingerprint": "施工|工人盖房子、修路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '410036aa-66b9-4036-830e-495e3a8f36e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90205, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "施工", "is_correct": true, "explanation": "正确：施工指按设计修路、盖房等工程，与“工人们正在路上”搭配。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：生产的场所通常是工厂、车间，不能说在路上生产。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙指做面包、饼干等食品，与路上的工作无关。"}, {"text": "装订", "is_correct": false, "explanation": "语义：装订的对象是书本、文件，不能在路上进行。"}], "explanations": {"施工": "正确：施工指按设计修路、盖房等工程，与“工人们正在路上”搭配。", "生产": "搭配：生产的场所通常是工厂、车间，不能说在路上生产。", "烘焙": "语义：烘焙指做面包、饼干等食品，与路上的工作无关。", "装订": "语义：装订的对象是书本、文件，不能在路上进行。"}, "sentence_index": 0, "correct_answer": "施工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的自行车坏了，我去施工一下。", "explanation": "这里应该用〈修理〉。施工指按设计修路、盖房等工程，修自行车这类物件要用修理。"}, {"text": "他每天晚上都施工写作业。", "explanation": "这里应该用〈做〉。施工指按设计建造工程，做功课这类学习活动不能用施工。"}, {"text": "考古队在遗址上施工文物。", "explanation": "这里应该用〈挖掘〉。施工是按设计建造工程，考古发掘文物要用挖掘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90205, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "施工", "is_correct": true, "explanation": "正确：施工指进行修桥等工程建设，与“才修好那座桥”相合。"}, {"text": "垂钓", "is_correct": false, "explanation": "语义：垂钓是钓鱼，与修好桥这一结果毫无关系。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”的对象是布、网等，不能用来指修桥的工程。"}, {"text": "写作", "is_correct": false, "explanation": "语义：写作是写文章，与在河边修桥不相关。"}], "explanations": {"施工": "正确：施工指进行修桥等工程建设，与“才修好那座桥”相合。", "垂钓": "语义：垂钓是钓鱼，与修好桥这一结果毫无关系。", "织": "搭配：“织”的对象是布、网等，不能用来指修桥的工程。", "写作": "语义：写作是写文章，与在河边修桥不相关。"}, "sentence_index": 6, "correct_answer": "施工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在地里施工了玉米。", "explanation": "这里应该用〈栽种〉。施工指按设计进行建设，种植庄稼要用栽种。"}, {"text": "他把这首歌施工得很好听。", "explanation": "这里应该用〈编曲〉。施工指按设计建造工程，为歌曲配器、编排要用编曲，不能用施工。"}, {"text": "裁缝施工了一件西装。", "explanation": "这里应该用〈缝制〉。施工是建造工程，缝制衣服要用缝制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们正在路上施工过，所以交通很慢。", "corrected_sentence": "工人们正在路上施工，所以交通很慢。", "error_description": "错误：“正在……施工过”。“正在”表示动作正在进行，“过”表示曾经发生的经历，二者不能同用。正确：“正在路上施工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座桥施工的完了，车辆可以通行了。", "corrected_sentence": "那座桥施工完了，车辆可以通行了。", "error_description": "错误：“施工”后多加了“的”。“施工”是动词，后面应直接接结果补语“完”，加“的”会使结构变成名词性的，不通顺。正确：“施工完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
