INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90207, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "薪水是工作一个月后，公司给你的钱。", "primary_collocate": null, "pronunciation": "xīn shuǐ", "ipa": "ɕin˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我每个月十号拿薪水。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的薪水不高，但是工作很轻松。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的薪水我已经寄给妈妈了。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给我的薪水比以前多了。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用第一个月的薪水买了一块表。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一个月的薪水是多少？", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把薪水都存在银行里。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板还没发这个月的薪水。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一份薪水高一点的工作。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作了一个月，我拿到了第一份薪水。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}], "register": "通用", "sense_fingerprint": "工作一个月后公司给个人的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0e4be8-25eb-4115-9c6a-5a16b534add7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90207, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "薪水", "is_correct": true, "explanation": "正确：薪水，指工作后按期付给的报酬。"}, {"text": "新税", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是新的税收，不是工资。"}, {"text": "亲水", "is_correct": false, "explanation": "qīn 与 xīn 声母不同（q 与 x），意思是亲近水，如亲水平台，不是工资。"}, {"text": "香水", "is_correct": false, "explanation": "xiāng 与 xīn 韵母不同，意思是香水，不是工资。"}, {"text": "咸水", "is_correct": false, "explanation": "xián 与 xīn 韵母不同，意思是咸的水，不是工资。"}], "explanations": {"薪水": "正确：薪水，指工作后按期付给的报酬。", "新税": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是新的税收，不是工资。", "亲水": "qīn 与 xīn 声母不同（q 与 x），意思是亲近水，如亲水平台，不是工资。", "香水": "xiāng 与 xīn 韵母不同，意思是香水，不是工资。", "咸水": "xián 与 xīn 韵母不同，意思是咸的水，不是工资。"}, "sentence_index": null, "correct_answer": "薪水"}, "level_3": {"options": [{"text": "薪水", "is_correct": true, "explanation": "正确：“拿”后接的是按月发放的工资，符合“每个月十号”的语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“每个月十号拿冰箱”说不通，领到的不是冰箱。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天是季节，不是可以拿到的东西。"}, {"text": "病", "is_correct": false, "explanation": "搭配：“拿病”不成立，病不能像东西一样被拿。"}], "explanations": {"薪水": "正确：“拿”后接的是按月发放的工资，符合“每个月十号”的语境。", "冰箱": "搭配：“每个月十号拿冰箱”说不通，领到的不是冰箱。", "夏天": "语义：夏天是季节，不是可以拿到的东西。", "病": "搭配：“拿病”不成立，病不能像东西一样被拿。"}, "sentence_index": 0, "correct_answer": "薪水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我违章停车，被交警罚了一笔薪水。", "explanation": "这里应该用〈罚款〉。薪水是工作后按月付给员工的报酬，违章被罚的钱要说〈罚款〉。"}, {"text": "我不小心把邻居的玻璃砸碎了，要赔给他一笔薪水。", "explanation": "这里应该用〈赔偿〉。薪水是工作的报酬，赔给别人的损失费要说〈赔偿〉。"}, {"text": "我每年都要给保险公司交一笔薪水。", "explanation": "这里应该用〈保费〉。薪水是付给员工的报酬，买保险交的钱叫〈保费〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90207, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "薪水", "is_correct": true, "explanation": "正确：“存在银行里”的是钱，薪水是工资。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是钱，不能存进银行。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是财物，不能存进银行。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“存在银行里”搭配的是钱或财物，“空气”不能这样存。"}], "explanations": {"薪水": "正确：“存在银行里”的是钱，薪水是工资。", "雨": "语义：雨不是钱，不能存进银行。", "汽油": "语义：汽油是燃料，不是财物，不能存进银行。", "空气": "搭配：“存在银行里”搭配的是钱或财物，“空气”不能这样存。"}, "sentence_index": 6, "correct_answer": "薪水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每个月都给公司发薪水。", "explanation": "这里混淆了付薪与收薪：薪水是公司付给员工的报酬，员工不能给公司发薪水；员工交给公司的钱不叫薪水。"}, {"text": "在餐厅吃完饭，我给服务员留了一点薪水。", "explanation": "这里应该用〈小费〉。小费是客人额外给服务员的钱，薪水是公司按月发给员工的报酬。"}, {"text": "我向朋友借了一笔薪水，下个月还他。", "explanation": "这里应该用〈借款〉。薪水是工作的报酬，借来的钱不是薪水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90207, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚找到工作，拿到了一个薪水。", "corrected_sentence": "他刚找到工作，拿到了一份薪水。", "error_description": "错误：量词“个”用于薪水不对；正确：量词“份”。薪水是工资，常用的量词是“份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90207, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年公司给我了很高的薪水。", "corrected_sentence": "去年公司给了我很高的薪水。", "error_description": "错误：“了”放在“我”后面；正确：“了”应紧跟动词“给”，写作“给了我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
