INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "按期付给工作人员的报酬。", "primary_collocate": null, "pronunciation": "xīn shuǐ", "ipa": "ɕin˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "学校按时给老师发薪水。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们每周领一次薪水。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的服务员薪水按月发。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司两个月没给员工薪水。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的护士薪水跟工作时间有关。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份薪水包括基本工资和奖金。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个工作人员的薪水都不一样。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说下个月会提高大家的薪水。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的薪水每月五号准时发。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里的薪水是按小时算的。", "target_word": "薪水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}], "register": "通用", "sense_fingerprint": "按期付给工作人员的报酬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0e4be8-25eb-4115-9c6a-5a16b534add7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90208, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "薪水", "is_correct": true, "explanation": "正确：薪水，指按期付给工作人员的报酬。"}, {"text": "新税", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是新的税收，不是报酬。"}, {"text": "亲水", "is_correct": false, "explanation": "qīn 与 xīn 声母不同（q 与 x），意思是亲近水，不是报酬。"}, {"text": "香水", "is_correct": false, "explanation": "xiāng 与 xīn 韵母不同，意思是香水，不是报酬。"}, {"text": "咸水", "is_correct": false, "explanation": "xián 与 xīn 韵母不同，意思是咸的水，不是报酬。"}], "explanations": {"薪水": "正确：薪水，指按期付给工作人员的报酬。", "新税": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是新的税收，不是报酬。", "亲水": "qīn 与 xīn 声母不同（q 与 x），意思是亲近水，不是报酬。", "香水": "xiāng 与 xīn 韵母不同，意思是香水，不是报酬。", "咸水": "xián 与 xīn 韵母不同，意思是咸的水，不是报酬。"}, "sentence_index": null, "correct_answer": "薪水"}, "level_3": {"options": [{"text": "薪水", "is_correct": true, "explanation": "正确：“发”给老师的是按时支付的报酬。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以按时发给老师的东西，“发颜色”说不通。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天是季节，不能发给老师。"}, {"text": "病", "is_correct": false, "explanation": "搭配：“发病”指疾病发作，不能用在“给老师”的对象上。"}], "explanations": {"薪水": "正确：“发”给老师的是按时支付的报酬。", "颜色": "语义：颜色不是可以按时发给老师的东西，“发颜色”说不通。", "夏天": "语义：夏天是季节，不能发给老师。", "病": "搭配：“发病”指疾病发作，不能用在“给老师”的对象上。"}, "sentence_index": 0, "correct_answer": "薪水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的薪水是五千元。", "explanation": "这里应该用〈价格〉。薪水是付给工作人员的报酬，商品的售价要说〈价格〉。"}, {"text": "我把钱存在银行里，每个月都能拿到一笔薪水。", "explanation": "这里应该用〈利息〉。薪水是按期付给工作人员的报酬，存款每月给的收益叫〈利息〉。"}, {"text": "我每学期都要交一次薪水。", "explanation": "这里应该用〈学费〉。学费是学生交给学校的钱，薪水是公司付给员工的报酬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "薪水", "is_correct": true, "explanation": "正确：“每个工作人员的……都不一样”指的是报酬。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是工作人员的报酬。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不是报酬，不会因人而异地“都不一样”。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“每个……都不一样”搭配的是报酬或待遇，“空气”不能这样说。"}], "explanations": {"薪水": "正确：“每个工作人员的……都不一样”指的是报酬。", "雨": "语义：雨不是工作人员的报酬。", "汽油": "语义：汽油不是报酬，不会因人而异地“都不一样”。", "空气": "搭配：“每个……都不一样”搭配的是报酬或待遇，“空气”不能这样说。"}, "sentence_index": 6, "correct_answer": "薪水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生每个月都给学校发薪水。", "explanation": "这里混淆了付钱与收薪：薪水是单位付给员工的报酬，学生不是员工；学生交给学校的钱应说〈交费〉，不能叫薪水。"}, {"text": "过年的时候，我给奶奶包了很多薪水。", "explanation": "这里应该用〈红包〉。红包是给亲友的礼金，薪水是工作的报酬。"}, {"text": "他向银行借了一笔薪水，下个月再还。", "explanation": "这里应该用〈贷款〉。薪水是工作的报酬，不是从银行借来的钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司每个月给员工领薪水。", "corrected_sentence": "公司每个月给员工发薪水。", "error_description": "错误在动词：“领”是员工收取报酬的动作，与“给员工”的单位支付意思不合；正确为“发薪水”，表示单位按期付给员工报酬。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每个月都有一条稳定的薪水。", "corrected_sentence": "他每个月都有一份稳定的薪水。", "error_description": "错误：量词“条”用于薪水不对；正确：量词“份”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
