INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90210, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "购买商品或接受服务的个人或单位。", "primary_collocate": null, "pronunciation": "kè hù", "ipa": "kʰɤ˥˩ xu˥˩", "syllable_count": 2, "sentences": [{"text": "我们公司有很多外国客户。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理明天要去见一位重要的客户。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的客户包括银行和学校。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客户收到货以后，给我们打了电话。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了留住客户，公司降低了价格。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作是联系客户，介绍新产品。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客户对我们的服务很满意。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的最大客户是一家汽车公司。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客户提出了新的要求，我们要改计划。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她负责接待来公司参观的客户。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "大客户", "label": "复合"}, {"form": "客户服务", "label": "复合"}, {"form": "客戶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "购买商品或接受服务的个人或单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88131405-7030-4d15-aa9d-0a48d00bcf95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客户", "is_correct": true, "explanation": "正确。“外国客户”指来自外国、购买本公司商品或服务的个人或单位，与句意相符。"}, {"text": "同学", "is_correct": false, "explanation": "语义：公司里不会有“同学”这种关系，与“我们公司”不相符。"}, {"text": "同胞", "is_correct": false, "explanation": "搭配：“同胞”指同一国家的人，“外国同胞”自相矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是人或单位，不能说“我们公司有很多外国石头”。"}], "explanations": {"客户": "正确。“外国客户”指来自外国、购买本公司商品或服务的个人或单位，与句意相符。", "同学": "语义：公司里不会有“同学”这种关系，与“我们公司”不相符。", "同胞": "搭配：“同胞”指同一国家的人，“外国同胞”自相矛盾。", "石头": "语义：“石头”不是人或单位，不能说“我们公司有很多外国石头”。"}, "sentence_index": 0, "correct_answer": "客户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每天早上，那位客户负责打扫办公室，把桌子都擦干净了。", "explanation": "这里应该用〈清洁工〉。“客户”指购买或接受服务的一方，打扫办公室的是提供服务的人，应说清洁工。"}, {"text": "我们公司有很多只客户，都在等着买东西。", "explanation": "这里应该用〈位〉或〈家〉。“只”多用于动物，不能用来数“客户”。"}, {"text": "这家公司是我们的客户，负责向我们供应原材料。", "explanation": "这里应该用〈供应商〉。“客户”指购买或接受服务的一方，向我们供货的应说供应商。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客户", "is_correct": true, "explanation": "正确。“客户”指接受服务的个人或单位，与“对我们的服务很满意”相符。"}, {"text": "竞争对手", "is_correct": false, "explanation": "语义：竞争对手与我们是对立关系，不会对我们的服务感到满意。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：“书桌”是物件，不会对服务感到满意。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是物品，不会对服务感到满意。"}], "explanations": {"客户": "正确。“客户”指接受服务的个人或单位，与“对我们的服务很满意”相符。", "竞争对手": "语义：竞争对手与我们是对立关系，不会对我们的服务感到满意。", "书桌": "语义：“书桌”是物件，不会对服务感到满意。", "雨伞": "语义：“雨伞”是物品，不会对服务感到满意。"}, "sentence_index": 6, "correct_answer": "客户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她负责接待来公司参观的一辆客户。", "explanation": "这里应该用〈位〉。“辆”用于车辆，不能用来数“客户”。"}, {"text": "她负责接待来公司参观的一条客户。", "explanation": "这里应该用〈位〉。“条”用于细长的东西，数人要用“位”。"}, {"text": "她负责接待来公司参观的一张客户。", "explanation": "这里应该用〈位〉。“张”用于纸张、桌子等平面的东西，数人要用“位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂来了一只客户，想订购一批机器。", "corrected_sentence": "这家工厂来了一位客户，想订购一批机器。", "error_description": "“只”多用于动物，不能用来数“客户”。这里指的是来工厂的个人，应说“一位客户”，量词应为“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台客户对我们的服务很满意，还介绍了朋友来。", "corrected_sentence": "这位客户对我们的服务很满意，还介绍了朋友来。", "error_description": "“台”用于机器等物件，指人应说“这位客户”，量词应为“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
