INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90211, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "坐车坐船出远门的人。", "primary_collocate": null, "pronunciation": "lǚ kè", "ipa": "ly˨˩˦ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "船上有很多旅客。", "target_word": "旅客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "旅客们都在车站等车。", "target_word": "旅客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车开了，旅客们慢慢坐好。", "target_word": "旅客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位旅客的行李太重了。", "target_word": "旅客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅客要先买票再上船。", "target_word": "旅客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一位旅客在船上睡着了。", "target_word": "旅客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "长途汽车上的旅客都很累。", "target_word": "旅客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请旅客们带好自己的东西。", "target_word": "旅客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天黑了，旅客还在路上走着。", "target_word": "旅客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下船的旅客都去找旅馆了。", "target_word": "旅客", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "旅客们", "label": "复数"}], "register": "中性", "sense_fingerprint": "乘车、乘船出远门的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65a17352-6903-43e6-8fa1-188b5f5fe0c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90211, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旅客", "is_correct": true, "explanation": "“旅客”指出远门的人，“船上有很多旅客”语义通顺。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间单位，船上不会“有很多星期”，与语境不合。"}, {"text": "树", "is_correct": false, "explanation": "语义：船上一般不会有很多树。"}, {"text": "句子", "is_correct": false, "explanation": "语义：句子是语言单位，不是船上摆着的东西，与语境不合。"}], "explanations": {"旅客": "“旅客”指出远门的人，“船上有很多旅客”语义通顺。", "星期": "语义：星期是时间单位，船上不会“有很多星期”，与语境不合。", "树": "语义：船上一般不会有很多树。", "句子": "语义：句子是语言单位，不是船上摆着的东西，与语境不合。"}, "sentence_index": 0, "correct_answer": "旅客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "剧院里坐满了旅客。", "explanation": "这里应该用〈观众〉。旅客指出远门、乘坐车船飞机的人，看演出的人要说观众。"}, {"text": "教室里坐着很多旅客。", "explanation": "这里应该用〈学生〉。旅客指出远门、乘坐车船飞机的人，上课的人要说学生。"}, {"text": "医院里有很多旅客。", "explanation": "这里应该用〈病人〉。旅客指出远门的人，在医院看病的人要说病人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旅客", "is_correct": true, "explanation": "“旅客”指乘车的人，“长途汽车上的旅客都很累”语义通顺。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位是物品，没有身体感觉，不能说“座位都很累”。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李没有感觉，不会累。"}, {"text": "广告", "is_correct": false, "explanation": "语义：广告没有身体感受，不会累。"}], "explanations": {"旅客": "“旅客”指乘车的人，“长途汽车上的旅客都很累”语义通顺。", "座位": "语义：座位是物品，没有身体感觉，不能说“座位都很累”。", "行李": "语义：行李没有感觉，不会累。", "广告": "语义：广告没有身体感受，不会累。"}, "sentence_index": 6, "correct_answer": "旅客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司里有很多旅客。", "explanation": "这里应该用〈员工〉。旅客指出远门、乘坐车船飞机的人，在公司工作的人要说员工。"}, {"text": "军营里站着很多旅客。", "explanation": "这里应该用〈战士〉。旅客指出远门、乘坐车船飞机的人，军营里的人要说战士。"}, {"text": "赛场上有很多旅客。", "explanation": "这里应该用〈运动员〉。旅客指出远门、乘坐车船飞机的人，比赛场上的人要说运动员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只旅客买了一张去上海的票。", "corrected_sentence": "那位旅客买了一张去上海的票。", "error_description": "“旅客”是指人的名词，量词应用“位”。“只”多用于动物或小件物品，用在人身上是错误的，应说“那位旅客”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位旅客们刚下车。", "corrected_sentence": "这位旅客刚下车。", "error_description": "“这位”与“旅客”搭配，“位”表示单个的人，不能再加复数词尾“们”。应说“这位旅客刚下车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
