INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外出旅行的人；乘坐车船飞机的人。", "primary_collocate": null, "pronunciation": "lǚ kè", "ipa": "ly˨˩˦ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "飞机上的旅客请系好安全带。", "target_word": "旅客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "机场里有很多外国旅客。", "target_word": "旅客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家酒店今天来了不少旅客。", "target_word": "旅客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅客们在景点拍了很多照片。", "target_word": "旅客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天来这里玩的旅客特别多。", "target_word": "旅客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那位旅客在问去机场怎么走。", "target_word": "旅客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车站里的旅客都急着上车。", "target_word": "旅客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机晚点了，旅客们很生气。", "target_word": "旅客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位旅客买了两张去北京的票。", "target_word": "旅客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅客可以在机场的商店买东西。", "target_word": "旅客", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "旅客们", "label": "复数"}], "register": "中性", "sense_fingerprint": "外出旅行、乘坐车船飞机的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65a17352-6903-43e6-8fa1-188b5f5fe0c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旅客", "is_correct": true, "explanation": "“旅客”指乘坐飞机出行的人，“飞机上的旅客请系好安全带”语义通顺。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不乘飞机，也不需要系安全带。"}, {"text": "河水", "is_correct": false, "explanation": "语义：河水不乘飞机，与“系安全带”无关。"}, {"text": "墙壁", "is_correct": false, "explanation": "搭配：“请系好安全带”的对象要能乘坐，墙壁不能说系安全带。"}], "explanations": {"旅客": "“旅客”指乘坐飞机出行的人，“飞机上的旅客请系好安全带”语义通顺。", "花朵": "语义：花朵不乘飞机，也不需要系安全带。", "河水": "语义：河水不乘飞机，与“系安全带”无关。", "墙壁": "搭配：“请系好安全带”的对象要能乘坐，墙壁不能说系安全带。"}, "sentence_index": 0, "correct_answer": "旅客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电影院里坐满了旅客。", "explanation": "这里应该用〈观众〉。旅客指出远门、乘坐车船飞机的人，看电影的人要说观众。"}, {"text": "公司里有很多旅客。", "explanation": "这里应该用〈员工〉。旅客指出远门、乘坐车船飞机的人，在公司工作的人要说员工。"}, {"text": "赛场上有很多旅客。", "explanation": "这里应该用〈运动员〉。旅客指出远门、乘坐车船飞机的人，比赛场上的人要说运动员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旅客", "is_correct": true, "explanation": "“旅客”指乘坐火车出行的人，“火车站里的旅客都急着上车”语义通顺。"}, {"text": "广告", "is_correct": false, "explanation": "语义：广告不会动，也不会急着上车。"}, {"text": "站台", "is_correct": false, "explanation": "语义：站台是建筑，不会急着上车。"}, {"text": "铁轨", "is_correct": false, "explanation": "语义：“急着上车”的主语必须是人，铁轨不能上车。"}], "explanations": {"旅客": "“旅客”指乘坐火车出行的人，“火车站里的旅客都急着上车”语义通顺。", "广告": "语义：广告不会动，也不会急着上车。", "站台": "语义：站台是建筑，不会急着上车。", "铁轨": "语义：“急着上车”的主语必须是人，铁轨不能上车。"}, "sentence_index": 6, "correct_answer": "旅客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室里坐着很多旅客。", "explanation": "这里应该用〈学生〉。旅客指出远门、乘坐车船飞机的人，上课的人要说学生。"}, {"text": "医院里有很多旅客。", "explanation": "这里应该用〈病人〉。旅客指出远门、乘坐车船飞机的人，在医院看病的人要说病人。"}, {"text": "军营里站着很多旅客。", "explanation": "这里应该用〈战士〉。旅客指出远门、乘坐车船飞机的人，军营里的人要说战士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只旅客在机场换了一张票。", "corrected_sentence": "这位旅客在机场换了一张票。", "error_description": "“旅客”是指人的名词，量词应用“位”。“只”用于动物或小件物品，用在人身上是错误的，应说“这位旅客”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位旅客们在等出租车。", "corrected_sentence": "这位旅客在等出租车。", "error_description": "“这位”与“旅客”搭配，“位”表示单个的人，不能再加复数词尾“们”。应说“这位旅客在等出租车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
