INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90213, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90213, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "见识是你通过看过、经历过的事而获得的知识和眼界，让你懂得很多。", "primary_collocate": null, "pronunciation": "jiàn shi", "ipa": "tɕjɛn ʂɨ", "syllable_count": 2, "sentences": [{"text": "旅行能让人增长见识。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他见识很广，什么都知道。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多出去看看，可以长见识。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时去过很多地方，很有见识。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次出国让我开阔了见识。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是个有见识的人，大家都听她的。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书和旅行都能增加见识。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去大城市工作，多长长见识。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在博物馆里长了不少见识。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有见识，才会相信这种骗人的话。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "見識", "label": "繁体"}], "register": "中性", "sense_fingerprint": "见识：看过、经历过的事所带来的知识和眼界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20f9c372-ecc3-4b34-9028-39b875025280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90213, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "见识", "is_correct": true, "explanation": "正确。见识：看过、经历过的事所带来的知识和眼界，读作 jiàn shi（第二音节轻声）。"}, {"text": "剑士", "is_correct": false, "explanation": "“剑士”（jiàn shì）第二音节为第四声，与“见识”的轻声不同，意思是剑客。"}, {"text": "监视", "is_correct": false, "explanation": "“监视”（jiān shì）两个音节的声调都与“见识”不同，意思是盯住某人或某处、防止其行动。"}, {"text": "简史", "is_correct": false, "explanation": "“简史”（jiǎn shǐ）两个音节的声调都与“见识”不同，意思是简要的历史。"}, {"text": "检视", "is_correct": false, "explanation": "“检视”（jiǎn shì）第一音节为第三声，与“见识”的第四声不同，意思是仔细检查。"}], "explanations": {"见识": "正确。见识：看过、经历过的事所带来的知识和眼界，读作 jiàn shi（第二音节轻声）。", "剑士": "“剑士”（jiàn shì）第二音节为第四声，与“见识”的轻声不同，意思是剑客。", "监视": "“监视”（jiān shì）两个音节的声调都与“见识”不同，意思是盯住某人或某处、防止其行动。", "简史": "“简史”（jiǎn shǐ）两个音节的声调都与“见识”不同，意思是简要的历史。", "检视": "“检视”（jiǎn shì）第一音节为第三声，与“见识”的第四声不同，意思是仔细检查。"}, "sentence_index": null, "correct_answer": "见识"}, "level_3": {"options": [{"text": "见识", "is_correct": true, "explanation": "正确。“增长见识”指增加见闻和知识，符合句意。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“增长”用于知识、见识等抽象事物，不能说“增长行李”。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是入场凭证，与旅行带来的见闻和眼界无关。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是地理图纸，不是经历带来的认识，“增长地图”说不通。"}], "explanations": {"见识": "正确。“增长见识”指增加见闻和知识，符合句意。", "行李": "搭配：“增长”用于知识、见识等抽象事物，不能说“增长行李”。", "门票": "语义：门票是入场凭证，与旅行带来的见闻和眼界无关。", "地图": "语义：地图是地理图纸，不是经历带来的认识，“增长地图”说不通。"}, "sentence_index": 0, "correct_answer": "见识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的工作见识在柜子里放了三年，已经发霉了。", "explanation": "这里应该用〈资料〉。见识指见闻和眼界，不能像纸张一样存放发霉。"}, {"text": "这孩子一年里见识长了十公分。", "explanation": "这里应该用〈身高〉。见识指见闻和眼界，孩子长高的是身高，不能用“见识”。"}, {"text": "他每天上班的见识有十公里，很辛苦。", "explanation": "这里应该用〈路程〉。见识指见闻和眼界，不能用来表示距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90213, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "见识", "is_correct": true, "explanation": "正确。见识：看过、经历过的事所带来的知识和眼界，读作 jiàn shi（第二音节轻声）。"}, {"text": "剑士", "is_correct": false, "explanation": "“剑士”（jiàn shì）第二音节为第四声，与“见识”的轻声不同，意思是剑客。"}, {"text": "监事", "is_correct": false, "explanation": "“监事”（jiān shì）两个音节的声调都与“见识”不同，意思是监督公司或组织事务的人。"}, {"text": "捡拾", "is_correct": false, "explanation": "“捡拾”（jiǎn shí）两个音节的声调都与“见识”不同，意思是拾起。"}, {"text": "检视", "is_correct": false, "explanation": "“检视”（jiǎn shì）第一音节为第三声，与“见识”的第四声不同，意思是仔细检查。"}], "explanations": {"见识": "正确。见识：看过、经历过的事所带来的知识和眼界，读作 jiàn shi（第二音节轻声）。", "剑士": "“剑士”（jiàn shì）第二音节为第四声，与“见识”的轻声不同，意思是剑客。", "监事": "“监事”（jiān shì）两个音节的声调都与“见识”不同，意思是监督公司或组织事务的人。", "捡拾": "“捡拾”（jiǎn shí）两个音节的声调都与“见识”不同，意思是拾起。", "检视": "“检视”（jiǎn shì）第一音节为第三声，与“见识”的第四声不同，意思是仔细检查。"}, "sentence_index": null, "correct_answer": "见识"}, "level_3": {"options": [{"text": "见识", "is_correct": true, "explanation": "正确。“增加见识”指读书和旅行带来更多见闻，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，读书和旅行不会增加它，句子说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，读书和旅行不能“增加身材”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，与读书和旅行带来的认识无关。"}], "explanations": {"见识": "正确。“增加见识”指读书和旅行带来更多见闻，符合句意。", "厨房": "语义：厨房是做饭的地方，读书和旅行不会增加它，句子说不通。", "身材": "体貌：“身材”指人的体形，读书和旅行不能“增加身材”。", "钥匙": "语义：钥匙是开锁的工具，与读书和旅行带来的认识无关。"}, "sentence_index": 6, "correct_answer": "见识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做的菜很有见识，吃起来特别香。", "explanation": "这里应该用〈味道〉。见识指见闻和眼界，不能用来形容菜肴的口感。"}, {"text": "他没上过大学，却考到了很高的见识。", "explanation": "这里应该用〈分数〉。见识指见闻和眼界，考试成绩要用“分数”。"}, {"text": "这块木头的见识很厚，锯起来很费劲。", "explanation": "这里应该用〈厚度〉。见识指见闻和眼界，不能用来形容木材的厚薄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90213, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他第一次出国，长着不少见识。", "corrected_sentence": "他第一次出国，长了不少见识。", "error_description": "“长见识”表示已经发生的变化，应用“了”（长了不少见识）；“着”表示持续状态，不能这样用，应改为“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90213, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行让我长过不少见识。", "corrected_sentence": "这次旅行让我长了不少见识。", "error_description": "“长了见识”表示变化已经发生，应用“了”。用“过”不通，应改为“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90214, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90214, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90214, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "见闻和知识；也指通过经历增长的认识。", "primary_collocate": null, "pronunciation": "jiàn shi", "ipa": "tɕjɛn ʂɨ", "syllable_count": 2, "sentences": [{"text": "出国留学让她的见识大不一样了。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人见识过人，大家都很佩服。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没读过多少书，但见识不少。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见识短的人容易被骗。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多交朋友，也能开阔见识。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈见识广，总能给我好建议。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次次出差，让他的见识越来越广。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人要多走走，增长见识。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她虽然年轻，但很有见识。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他见识浅，看不出这里面的问题。", "target_word": "见识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "見識", "label": "繁体"}], "register": "中性", "sense_fingerprint": "见识：见闻和知识，经历增长的认识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20f9c372-ecc3-4b34-9028-39b875025280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90214, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "见识", "is_correct": true, "explanation": "正确。见识：见闻和知识，经历增长的认识，读作 jiàn shi（第二音节轻声）。"}, {"text": "剑士", "is_correct": false, "explanation": "“剑士”（jiàn shì）第二音节为第四声，与“见识”的轻声不同，意思是剑客。"}, {"text": "监视", "is_correct": false, "explanation": "“监视”（jiān shì）两个音节的声调都与“见识”不同，意思是盯住某人或某处。"}, {"text": "捡拾", "is_correct": false, "explanation": "“捡拾”（jiǎn shí）两个音节的声调都与“见识”不同，意思是拾起。"}, {"text": "简史", "is_correct": false, "explanation": "“简史”（jiǎn shǐ）两个音节的声调都与“见识”不同，意思是简要的历史。"}], "explanations": {"见识": "正确。见识：见闻和知识，经历增长的认识，读作 jiàn shi（第二音节轻声）。", "剑士": "“剑士”（jiàn shì）第二音节为第四声，与“见识”的轻声不同，意思是剑客。", "监视": "“监视”（jiān shì）两个音节的声调都与“见识”不同，意思是盯住某人或某处。", "捡拾": "“捡拾”（jiǎn shí）两个音节的声调都与“见识”不同，意思是拾起。", "简史": "“简史”（jiǎn shǐ）两个音节的声调都与“见识”不同，意思是简要的历史。"}, "sentence_index": null, "correct_answer": "见识"}, "level_3": {"options": [{"text": "见识", "is_correct": true, "explanation": "正确。“她的见识大不一样了”指出国留学后眼界和认识有明显变化，符合句意。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温反映天气冷暖，不会因为出国留学而改变，句意说不通。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：脚印是走过留下的痕迹，不是人的认识或眼界。"}, {"text": "骨架", "is_correct": false, "explanation": "体貌：“骨架”指身体的骨骼框架，出国留学不会让它大不一样。"}], "explanations": {"见识": "正确。“她的见识大不一样了”指出国留学后眼界和认识有明显变化，符合句意。", "气温": "语义：气温反映天气冷暖，不会因为出国留学而改变，句意说不通。", "脚印": "语义：脚印是走过留下的痕迹，不是人的认识或眼界。", "骨架": "体貌：“骨架”指身体的骨骼框架，出国留学不会让它大不一样。"}, "sentence_index": 0, "correct_answer": "见识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的见识很熟练，做事又快又好。", "explanation": "这里应该用〈技能〉。见识指见闻和眼界，不能用“熟练”来形容。"}, {"text": "他的见识是红色的，很好看。", "explanation": "这里应该用〈颜色〉。见识指见闻和眼界，不指颜色。"}, {"text": "他的见识很重，我一个人抬不动。", "explanation": "这里应该用〈体重〉。见识指见闻和眼界，没有轻重，说人身体的重量要用“体重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90214, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "见识", "is_correct": true, "explanation": "正确。见识：见闻和知识，经历增长的认识，读作 jiàn shi（第二音节轻声）。"}, {"text": "剑士", "is_correct": false, "explanation": "“剑士”（jiàn shì）第二音节为第四声，与“见识”的轻声不同，意思是剑客。"}, {"text": "监事", "is_correct": false, "explanation": "“监事”（jiān shì）两个音节的声调都与“见识”不同，意思是监督公司或组织事务的人。"}, {"text": "检视", "is_correct": false, "explanation": "“检视”（jiǎn shì）第一音节为第三声，与“见识”的第四声不同，意思是仔细检查。"}, {"text": "捡拾", "is_correct": false, "explanation": "“捡拾”（jiǎn shí）两个音节的声调都与“见识”不同，意思是拾起。"}], "explanations": {"见识": "正确。见识：见闻和知识，经历增长的认识，读作 jiàn shi（第二音节轻声）。", "剑士": "“剑士”（jiàn shì）第二音节为第四声，与“见识”的轻声不同，意思是剑客。", "监事": "“监事”（jiān shì）两个音节的声调都与“见识”不同，意思是监督公司或组织事务的人。", "检视": "“检视”（jiǎn shì）第一音节为第三声，与“见识”的第四声不同，意思是仔细检查。", "捡拾": "“捡拾”（jiǎn shí）两个音节的声调都与“见识”不同，意思是拾起。"}, "sentence_index": null, "correct_answer": "见识"}, "level_3": {"options": [{"text": "见识", "is_correct": true, "explanation": "正确。“见识越来越广”说明经历增多后眼界越来越开阔，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“广”不能用来形容声音，“声音越来越广”说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步是走路的动作，与出差带来的眼界无关。"}, {"text": "肤色", "is_correct": false, "explanation": "体貌：“肤色”指皮肤的颜色，不会因为出差而越来越广。"}], "explanations": {"见识": "正确。“见识越来越广”说明经历增多后眼界越来越开阔，符合句意。", "声音": "搭配：“广”不能用来形容声音，“声音越来越广”说不通。", "脚步": "语义：脚步是走路的动作，与出差带来的眼界无关。", "肤色": "体貌：“肤色”指皮肤的颜色，不会因为出差而越来越广。"}, "sentence_index": 6, "correct_answer": "见识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿到了硕士见识，很多公司都抢着要。", "explanation": "这里应该用〈文凭〉。见识指见闻和眼界，不指学历证书。"}, {"text": "他的见识已经五十岁了，还在工作。", "explanation": "这里应该用〈年龄〉。见识指见闻和眼界，说人的岁数要用“年龄”。"}, {"text": "这位工人的见识有一米九，在人群里很显眼。", "explanation": "这里应该用〈身高〉。见识指见闻和眼界，不能用来说人的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跟着父母走遍了南北，长着不少见识。", "corrected_sentence": "他跟着父母走遍了南北，长了不少见识。", "error_description": "“长见识”表示已经发生的变化，应用“了”（长了不少见识）；“着”表示持续状态，不能这样用，应改为“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年跟着团队出差，他长过不少见识。", "corrected_sentence": "这几年跟着团队出差，他长了不少见识。", "error_description": "“长了见识”表示变化已经发生，应用“了”。用“过”不通，应改为“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba2a05c2-e6c9-4469-9b18-b78882106ba0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
