INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90215, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "过去有一天。", "primary_collocate": null, "pronunciation": "yǒu yī cì", "ipa": "jou˨˩ i˥ tsʰɹ̩˥˩", "syllable_count": 3, "sentences": [{"text": "有一次，我在公园遇到了小学同学。", "target_word": "有一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一次，妈妈做的饭太咸了，我们都没吃完。", "target_word": "有一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一次下大雨，我忘了带伞。", "target_word": "有一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一次，爸爸带我去海边玩。", "target_word": "有一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候，有一次一个人去了奶奶家。", "target_word": "有一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一次，老师在课上讲了一个笑话。", "target_word": "有一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年冬天，有一次我在路上滑倒了。", "target_word": "有一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一次，我坐错了公共汽车。", "target_word": "有一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一次，弟弟把我的手机弄坏了。", "target_word": "有一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，有一次他在山里看到了一只熊。", "target_word": "有一次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "有一次：指过去的某一天，用来引出一件往事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20866e08-b43e-403c-ad2b-6b6e0b8a5d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90215, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有一次", "is_correct": true, "explanation": "正确。「有一次」引出过去的一件往事，与「遇到了」相符。"}, {"text": "马上", "is_correct": false, "explanation": "体貌：「马上」表示即将发生，与已完成的「遇到了」冲突。"}, {"text": "一直", "is_correct": false, "explanation": "语义：「一直」表示持续不断，与一次性的相遇不相合。"}, {"text": "永远", "is_correct": false, "explanation": "语义：「永远」指长久不变，不能修饰一次已完成的相遇。"}], "explanations": {"有一次": "正确。「有一次」引出过去的一件往事，与「遇到了」相符。", "马上": "体貌：「马上」表示即将发生，与已完成的「遇到了」冲突。", "一直": "语义：「一直」表示持续不断，与一次性的相遇不相合。", "永远": "语义：「永远」指长久不变，不能修饰一次已完成的相遇。"}, "sentence_index": 0, "correct_answer": "有一次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们有一次每周都去河边散步。", "explanation": "这里表示每周都去的习惯，应该用〈时常〉之类表示习惯的词。「有一次」只指过去的某一次，不能与「每周都」放在同一句里表示习惯。"}, {"text": "有一次下雨，我每次都忘带伞。", "explanation": "「有一次」只指过去的某一回，与「每次都」表示每一回都如此相矛盾。应去掉「有一次」，改说〈每次下雨，我都忘带伞〉。"}, {"text": "我明年有一次要去北京。", "explanation": "这里「有一次」用于将来，但它只指过去的某一次，不能用于将来计划，与「要去」的将来含义矛盾。表示将来的一次可说〈有一天〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90215, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有一次", "is_correct": true, "explanation": "正确。「有一次」指去年冬天的某一次滑倒，与句子相符。"}, {"text": "立刻", "is_correct": false, "explanation": "体貌：「立刻」表示马上发生，与「去年冬天」指过去的时间冲突。"}, {"text": "经常", "is_correct": false, "explanation": "语义：「经常」表示反复发生，与只滑倒一次的事实不符。"}, {"text": "总是", "is_correct": false, "explanation": "语义：「总是」表示一贯如此，与「滑倒了」这一次性的事冲突。"}], "explanations": {"有一次": "正确。「有一次」指去年冬天的某一次滑倒，与句子相符。", "立刻": "体貌：「立刻」表示马上发生，与「去年冬天」指过去的时间冲突。", "经常": "语义：「经常」表示反复发生，与只滑倒一次的事实不符。", "总是": "语义：「总是」表示一贯如此，与「滑倒了」这一次性的事冲突。"}, "sentence_index": 6, "correct_answer": "有一次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我这三年有一次一直住在北京。", "explanation": "这里说的是持续三年的状态，「有一次」只指过去的某一次，不能和「一直」一起表示持续，应去掉「有一次」。"}, {"text": "我这个月有一次每天早上都跑步。", "explanation": "这里表示每天早上都跑步的习惯，应该用〈经常〉之类表示习惯的词。「有一次」只指过去的某一次，不能与「每天早上都」放在同一句里。"}, {"text": "他明年有一次会当医生。", "explanation": "这里说的是将来，「有一次」只指过去的某一次，不能用于将来，应说〈明年他会当医生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上个月有一次的去了北京。", "corrected_sentence": "我上个月有一次去了北京。", "error_description": "错误：「有一次」后多加了「的」。正确：「我上个月有一次去了北京。」「有一次」后直接接动词，不加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上个月，有一次了我在公园遇到了老师。", "corrected_sentence": "上个月，有一次我在公园遇到了老师。", "error_description": "错误：「有一次」后多加了「了」。正确：「上个月，有一次我在公园遇到了老师。」「了」只用于动词「遇到」后，「有一次」后不加。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
