INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90217, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "亲吻是用嘴轻轻碰一下喜欢的人。", "primary_collocate": null, "pronunciation": "qīn wěn", "ipa": "tɕʰin˥ wən˨˩˦", "syllable_count": 2, "sentences": [{"text": "他轻轻亲吻了喜欢的女孩。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她亲吻了男朋友的脸。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在电影里，两个人亲吻了。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临走前，他亲吻了妻子。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在雨中亲吻着。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你亲吻过自己喜欢的人吗？", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她踮起脚，亲吻他一下。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不好意思在人前亲吻她。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭着眼睛亲吻爱人。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老公出门前总会亲吻我。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲吻了", "label": "完成体"}, {"form": "亲吻着", "label": "持续体"}, {"form": "亲吻过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "恋人或爱人之间用嘴轻碰对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0e4be8-25eb-4115-9c6a-5a16b534add7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90217, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "踹", "is_correct": false, "explanation": "语义：“踹”是用脚猛踢，与“轻轻”和喜欢的人的温柔语境相矛盾。"}, {"text": "亲吻", "is_correct": true, "explanation": "亲吻：恋人之间用嘴轻碰对方，与“轻轻”和“喜欢的女孩”相符。"}, {"text": "训", "is_correct": false, "explanation": "语义：“训”表示斥责，与对喜欢的人的温柔态度不符。"}, {"text": "揍", "is_correct": false, "explanation": "语义：“揍”是用拳头打人，带有暴力意味，与“轻轻”和喜欢的人的温柔语境矛盾。"}], "explanations": {"踹": "语义：“踹”是用脚猛踢，与“轻轻”和喜欢的人的温柔语境相矛盾。", "亲吻": "亲吻：恋人之间用嘴轻碰对方，与“轻轻”和“喜欢的女孩”相符。", "训": "语义：“训”表示斥责，与对喜欢的人的温柔态度不符。", "揍": "语义：“揍”是用拳头打人，带有暴力意味，与“轻轻”和喜欢的人的温柔语境矛盾。"}, "sentence_index": 0, "correct_answer": "亲吻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下班后亲吻了一下电脑，然后和同事道别。", "explanation": "这里应该用〈关〉。亲吻只用于喜欢的人，不能用于电脑；下班前关电脑才是正常动作。"}, {"text": "他在街上亲吻了路边的电线杆，表示问候。", "explanation": "这里应该用〈挥手〉。亲吻只用于喜欢的人，不能用于电线杆；打招呼可以挥手。"}, {"text": "听众纷纷亲吻讲台，表示赞美。", "explanation": "这里应该用〈鼓掌〉。亲吻表达爱意，不能用于对讲台的赞赏，公开表示赞赏要用鼓掌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能用于他。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示抛掷，与“踮起脚”亲近对方的动作不符。"}, {"text": "亲吻", "is_correct": true, "explanation": "亲吻：用嘴唇轻碰对方，与“踮起脚”的亲近动作相符。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”表示跌落或用力甩下，与“踮起脚”的温柔动作矛盾。"}], "explanations": {"吃": "搭配：“吃”的宾语是食物，不能用于他。", "扔": "语义：“扔”表示抛掷，与“踮起脚”亲近对方的动作不符。", "亲吻": "亲吻：用嘴唇轻碰对方，与“踮起脚”的亲近动作相符。", "摔": "语义：“摔”表示跌落或用力甩下，与“踮起脚”的温柔动作矛盾。"}, "sentence_index": 6, "correct_answer": "亲吻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他亲吻了朋友的鞋，以示见面礼节。", "explanation": "这里应该用〈拱手〉。亲吻只用于喜欢的人，不能用于鞋子；见面礼节要用拱手。"}, {"text": "他每天早上都亲吻一下牙刷，然后开始刷牙。", "explanation": "这里应该用〈拿起〉。亲吻只用于喜欢的人，不能用于牙刷；刷牙前拿起牙刷才是正常动作。"}, {"text": "老板每天进办公室都亲吻一下文件，然后坐下。", "explanation": "这里应该用〈翻〉。亲吻只用于喜欢的人，不能用于文件；翻开文件是普通动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他临走前给了妻子一条亲吻。", "corrected_sentence": "他临走前给了妻子一个亲吻。", "error_description": "错误在量词。“亲吻”作名词表示一次亲吻时用量词“个”，“条”多用于细长的东西，不能用于“亲吻”。应说“一个亲吻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他亲吻很轻，怕吵醒孩子。", "corrected_sentence": "他亲吻得很轻，怕吵醒孩子。", "error_description": "错误在“亲吻”后面缺少“得”。“亲吻”后接表示程度的“很轻”时，要用“得”连接，应说“亲吻得很轻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
