INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90218, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用嘴唇轻触对方以表示喜爱。", "primary_collocate": null, "pronunciation": "qīn wěn", "ipa": "tɕʰin˥ wən˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈轻轻亲吻了孩子的脸。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他低下头，亲吻她的手。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新郎亲吻了新娘。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天晚上亲吻女儿说晚安。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子亲吻了妈妈一下。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭上眼睛，等着他亲吻。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他亲吻着照片里的妈妈。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶亲吻了小孙子的额头。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次亲吻她是在海边。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他弯下腰，亲吻了一下孩子。", "target_word": "亲吻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲吻了", "label": "完成体"}, {"form": "亲吻着", "label": "持续体"}, {"form": "亲吻过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用嘴唇轻触人的脸、手、额头等表示喜爱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0e4be8-25eb-4115-9c6a-5a16b534add7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的动作要用脚，不能用来指对脸的接触。"}, {"text": "亲吻", "is_correct": true, "explanation": "亲吻：用嘴唇轻触孩子的脸，与“轻轻”和表示喜爱的语境相符。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”需要用力，与“轻轻”的描写相矛盾。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”的对象是纸张等可撕的东西，不能用于脸。"}], "explanations": {"踢": "搭配：“踢”的动作要用脚，不能用来指对脸的接触。", "亲吻": "亲吻：用嘴唇轻触孩子的脸，与“轻轻”和表示喜爱的语境相符。", "砸": "语义：“砸”需要用力，与“轻轻”的描写相矛盾。", "撕": "搭配：“撕”的对象是纸张等可撕的东西，不能用于脸。"}, "sentence_index": 0, "correct_answer": "亲吻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在会议上和客人亲吻。", "explanation": "这里应该用〈握手〉。亲吻表示亲密喜爱，只用于家人或恋人，与客人见面的礼节要用握手。"}, {"text": "学生见到老师，就走上前去亲吻老师。", "explanation": "这里应该用〈鞠躬〉。亲吻表示亲密喜爱，不用于见面时对老师的尊敬，表示尊敬要用鞠躬。"}, {"text": "他在街对面亲吻了路灯，向远去的朋友告别。", "explanation": "这里应该用〈挥手〉。亲吻只用于喜欢的人，不能用于路灯；远距离告别要用挥手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能用于照片里的人。"}, {"text": "亲吻", "is_correct": true, "explanation": "亲吻：用嘴唇轻触照片里的人，表示思念与喜爱，与句子的语境相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示抛掷，与表达思念和喜爱的语境不符。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”表示跌落或用力甩下，与表达思念的语境矛盾。"}], "explanations": {"吃": "搭配：“吃”的宾语是食物，不能用于照片里的人。", "亲吻": "亲吻：用嘴唇轻触照片里的人，表示思念与喜爱，与句子的语境相符。", "扔": "语义：“扔”表示抛掷，与表达思念和喜爱的语境不符。", "摔": "语义：“摔”表示跌落或用力甩下，与表达思念的语境矛盾。"}, "sentence_index": 6, "correct_answer": "亲吻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他亲吻了每一把椅子，表示致意。", "explanation": "这里应该用〈点头〉。亲吻只用于喜欢的人，不能用于椅子；致意要用点头。"}, {"text": "大家举杯亲吻。", "explanation": "这里应该用〈干杯〉。亲吻表示亲密喜爱，不用于集体举杯庆祝，庆祝时应该说干杯。"}, {"text": "士兵在战场上亲吻了长官。", "explanation": "这里应该用〈敬礼〉。亲吻表示亲密喜爱，不用于军人对长官的礼节，礼节要用敬礼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在门口给了我一只亲吻。", "corrected_sentence": "她在门口给了我一个亲吻。", "error_description": "错误在量词。“亲吻”作名词表示一次亲吻时用量词“个”，“只”一般用于动物或成对的东西，不能用于“亲吻”。应说“一个亲吻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她弯下腰，亲吻很轻，怕吵醒孩子。", "corrected_sentence": "她弯下腰，亲吻得很轻，怕吵醒孩子。", "error_description": "错误在“亲吻”后面缺少“得”。“亲吻”后接表示程度的“很轻”时，要用“得”连接，应说“亲吻得很轻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
