INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90220, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "已发生的、可供参考或分析的实例。", "primary_collocate": null, "pronunciation": "àn lì", "ipa": "an⁵¹ li⁵¹", "syllable_count": 2, "sentences": [{"text": "老师给我们讲了一个成功的案例。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多公司管理的案例。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要分析这个案例，找出问题。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案例对我们很有参考价值。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在报告里用了三个案例。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再找一个类似的案例。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些案例可以帮助我们做决定。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想看看别的公司的案例。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课上我们讨论了几个典型案例。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案例说明，提前准备很重要。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个案例", "label": "量词"}, {"form": "案例分析", "label": "复合"}], "register": "中性", "sense_fingerprint": "已发生、可供参考或分析的实例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '410036aa-66b9-4036-830e-495e3a8f36e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "案例", "is_correct": true, "explanation": "正确：案例指可供学习参考的真实事例，与“老师给我们讲了”“成功的”搭配。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食品，不是可以讲述的事例。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑物，不能用来讲述。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“讲”的对象是故事、道理，不能讲手套。"}], "explanations": {"案例": "正确：案例指可供学习参考的真实事例，与“老师给我们讲了”“成功的”搭配。", "蛋糕": "语义：蛋糕是食品，不是可以讲述的事例。", "房子": "语义：房子是建筑物，不能用来讲述。", "手套": "搭配：“讲”的对象是故事、道理，不能讲手套。"}, "sentence_index": 0, "correct_answer": "案例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察正在调查这起案例。", "explanation": "这里应该用〈案件〉。调查、侦破的是案件，案例是用来学习参考的真实事例。"}, {"text": "他把这个案例放进了冰箱里。", "explanation": "这里应该用〈食物〉。案例指可供参考的真实事例，不能放进冰箱保存。"}, {"text": "孩子们喜欢听这个童话案例。", "explanation": "这里应该用〈故事〉。童话是虚构的故事，案例指真实发生的事例，不能说童话案例。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "案例", "is_correct": true, "explanation": "正确：案例指可供学习参考的真实事例，与“可以帮助我们做决定”相合。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵是植物的部分，无法帮助人做决定。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是矿物，不能提供帮助人决策的依据。"}, {"text": "调料", "is_correct": false, "explanation": "搭配：“做决定”需要依据信息、经验，调料不能用来帮助决定。"}], "explanations": {"案例": "正确：案例指可供学习参考的真实事例，与“可以帮助我们做决定”相合。", "花朵": "语义：花朵是植物的部分，无法帮助人做决定。", "石头": "语义：石头是矿物，不能提供帮助人决策的依据。", "调料": "搭配：“做决定”需要依据信息、经验，调料不能用来帮助决定。"}, "sentence_index": 6, "correct_answer": "案例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次案例造成了很大的损失。", "explanation": "这里应该用〈事件〉。事件指已经发生的事情，案例是可供学习参考的实例，不能造成损失。"}, {"text": "他每天用这个案例做饭。", "explanation": "这里应该用〈食材〉。案例指可供学习的真实事情，不能当作食材用来做饭。"}, {"text": "这位老人把案例当成宠物养。", "explanation": "这里应该用〈小狗〉。案例是可供学习的真实事情，不是生物，不能当作小狗来饲养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们研究了很多案例们。", "corrected_sentence": "我们研究了很多案例。", "error_description": "错误：“案例们”。正确：“案例”。“们”只用于指人的名词表示复数，“案例”不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师讲了三案例。", "corrected_sentence": "老师讲了三个案例。", "error_description": "错误：“三案例”。正确：“三个案例”。数词与名词之间要加量词，“案例”前应加“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
