INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90223, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "谈谈是和别人说说话，说说想法。", "primary_collocate": null, "pronunciation": "tán tan", "ipa": "tʰan˧˥ tʰan", "syllable_count": 2, "sentences": [{"text": "晚上我想和你谈谈。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想跟小明谈谈学习的事。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐下来好好谈谈吧。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈要和我谈谈我的想法。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有空吗？我想找你谈谈。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去咖啡馆谈谈吧。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想跟朋友谈谈心里的烦恼。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把我叫到房间里谈谈。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题就来找我谈谈。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们坐在一起谈谈自己的想法。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "谈一谈", "label": "重叠"}, {"form": "谈了谈", "label": "体标"}], "register": "口语", "sense_fingerprint": "和别人交流，说说自己的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a138068c-42b9-49dc-b301-f8a5ab1de2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90223, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谈谈", "is_correct": true, "explanation": "“谈谈”指和对方说说话，符合“晚上我想和你……”的语境。"}, {"text": "摔碎", "is_correct": false, "explanation": "语义：摔碎指把东西摔成碎片，不能和别人一起去做。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：冻结指使物体变硬或停止，与和你一起做的动作不符。"}, {"text": "扔掉", "is_correct": false, "explanation": "配价：扔掉要带受事宾语，此处“和你”之后没有可扔的东西。"}], "explanations": {"谈谈": "“谈谈”指和对方说说话，符合“晚上我想和你……”的语境。", "摔碎": "语义：摔碎指把东西摔成碎片，不能和别人一起去做。", "冻结": "语义：冻结指使物体变硬或停止，与和你一起做的动作不符。", "扔掉": "配价：扔掉要带受事宾语，此处“和你”之后没有可扔的东西。"}, "sentence_index": 0, "correct_answer": "谈谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师狠狠地谈谈他。", "explanation": "这里应该用〈批评〉。谈谈表示平等地交换想法，不带责备的意思；责备他人要用批评。"}, {"text": "他坚决谈谈这个计划。", "explanation": "这里应该用〈反对〉。谈谈只是交换意见，没有表示对立的意思；坚决表示不同意要用反对。"}, {"text": "他用刷子谈谈墙面，想把它刷白。", "explanation": "这里应该用〈刷〉。谈谈表示交谈、说说想法，不能用来描述用刷子刷墙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90223, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谈谈", "is_correct": true, "explanation": "“谈谈”指和朋友说说心里的事，符合“他想跟朋友……心里的烦恼”的语境。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：搬运指把货物从一处移到另一处，烦恼不能被搬运。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：缝补多用于衣物，不说缝补烦恼。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：修剪多用于树枝、头发等，不说修剪烦恼。"}], "explanations": {"谈谈": "“谈谈”指和朋友说说心里的事，符合“他想跟朋友……心里的烦恼”的语境。", "搬运": "语义：搬运指把货物从一处移到另一处，烦恼不能被搬运。", "缝补": "搭配：缝补多用于衣物，不说缝补烦恼。", "修剪": "搭配：修剪多用于树枝、头发等，不说修剪烦恼。"}, "sentence_index": 6, "correct_answer": "谈谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店谈谈水果。", "explanation": "这里应该用〈卖〉。谈谈表示交谈、说说想法，不表示买卖。"}, {"text": "她在厨房里谈谈水，想把它烧开。", "explanation": "这里应该用〈烧〉。谈谈表示交谈、说说想法，不表示把水烧开。"}, {"text": "他在纸上谈谈一条线，想把它画直。", "explanation": "这里应该用〈画〉。谈谈表示交谈、说说想法，不表示在纸上画线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90223, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们谈谈了很久，终于达成了一致。", "corrected_sentence": "我们谈了很久，终于达成了一致。", "error_description": "错误：“谈谈了”；正确：“谈了”。谈谈是重叠形式，不能再带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90223, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下课后我想和你谈谈一谈。", "corrected_sentence": "下课后我想和你谈一谈。", "error_description": "错误：“谈谈一谈”；正确：“谈一谈”或“谈谈”。动词重叠只能用一种形式，不能叠在一起用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
