INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90224, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "交谈，说一说。", "primary_collocate": null, "pronunciation": "tán tan", "ipa": "tʰan˧˥ tʰan", "syllable_count": 2, "sentences": [{"text": "请你谈谈对这本书的看法。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家来谈谈今年的计划吧。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请他在班会上谈谈自己的感受。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们谈谈暑假的生活。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能不能谈谈你在中国的经历？", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我想谈谈怎么学汉字。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝茶的时候，客人们想谈谈各国的文化。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者请他谈谈比赛后的心情。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你也来谈谈这件事吧。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先谈谈价钱，再决定买不买。", "target_word": "谈谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "谈一谈", "label": "重叠"}, {"form": "谈了谈", "label": "体标"}], "register": "口语", "sense_fingerprint": "围绕某个话题说一说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a138068c-42b9-49dc-b301-f8a5ab1de2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谈谈", "is_correct": true, "explanation": "“谈谈”指围绕某个话题说一说，符合“请你……对这本书的看法”的语境。"}, {"text": "测量", "is_correct": false, "explanation": "语义：测量指用工具量出长度、重量等，看法不能被测量。"}, {"text": "熨烫", "is_correct": false, "explanation": "搭配：熨烫多用于衣物，不说熨烫看法。"}, {"text": "切开", "is_correct": false, "explanation": "语义：切开指用刀把东西分成几部分，与表达看法无关。"}], "explanations": {"谈谈": "“谈谈”指围绕某个话题说一说，符合“请你……对这本书的看法”的语境。", "测量": "语义：测量指用工具量出长度、重量等，看法不能被测量。", "熨烫": "搭配：熨烫多用于衣物，不说熨烫看法。", "切开": "语义：切开指用刀把东西分成几部分，与表达看法无关。"}, "sentence_index": 0, "correct_answer": "谈谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用力谈谈瓶盖，想把它拧开。", "explanation": "这里应该用〈拧〉。谈谈表示交谈、说一说，不能表示用力拧开瓶盖。"}, {"text": "他很仔细地谈谈窗户。", "explanation": "这里应该用〈擦〉。谈谈表示交谈、说一说，不表示擦拭窗户。"}, {"text": "他用剪刀谈谈这张纸，想把它剪成两半。", "explanation": "这里应该用〈剪〉。谈谈表示交谈、说一说，不表示用剪刀剪纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谈谈", "is_correct": true, "explanation": "“谈谈”指围绕话题说一说，符合“客人们想……各国的文化”的语境。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：拆除多用于建筑、设施，不说拆除文化。"}, {"text": "切割", "is_correct": false, "explanation": "语义：切割指用刀具把物体分开，文化不能被切割。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮指用水加热食物，文化不能被煮。"}], "explanations": {"谈谈": "“谈谈”指围绕话题说一说，符合“客人们想……各国的文化”的语境。", "拆除": "搭配：拆除多用于建筑、设施，不说拆除文化。", "切割": "语义：切割指用刀具把物体分开，文化不能被切割。", "煮": "语义：煮指用水加热食物，文化不能被煮。"}, "sentence_index": 6, "correct_answer": "谈谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力谈谈门，门还是没开。", "explanation": "这里应该用〈推〉。谈谈表示交谈、说一说，不能表示用力推门。"}, {"text": "她用手谈谈面团。", "explanation": "这里应该用〈揉〉。谈谈表示说话交流，不能表示揉面团。"}, {"text": "工人用锤子谈谈铁块，想把它敲平。", "explanation": "这里应该用〈敲〉。谈谈表示交谈、说一说，不能表示用锤子敲铁块。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们谈谈得很开心，忘了时间。", "corrected_sentence": "我们谈得很开心，忘了时间。", "error_description": "错误：“谈谈得”；正确：“谈得”。重叠形式不能直接带程度补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你们可以先谈谈了合作的条件。", "corrected_sentence": "你们可以先谈谈合作的条件。", "error_description": "错误：“谈谈了”；正确：“谈谈”。“了”不能直接加在重叠形式“谈谈”后面；这里表示建议，不需要体标。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
