INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90227, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "警报是发出的响声或信号，告诉大家有危险。", "primary_collocate": null, "pronunciation": "jǐng bào", "ipa": "tɕiŋ˨˩ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "警报突然响了，大家马上跑出教室。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到警报，工人们都离开了工厂。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车站的警报响了很久。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜里，警报把全家人吵醒了。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每年都会拉响一次警报，让学生练习。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里有烟，警报马上响了起来。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心按了按钮，警报一下子响了。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听见警报，我们要先关掉煤气。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警报响过以后，街上很快就安静了。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个警报很吵，邻居都来看是怎么回事。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "警报器", "label": "复合"}, {"form": "一次警报", "label": "量词"}], "register": "中性", "sense_fingerprint": "告诉大家有危险的响声或信号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9b14e92-3a0f-44e7-b1c6-121a5b382a86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90227, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警报", "is_correct": true, "explanation": "警报：发出的响声或信号，告诉大家有危险，与“突然响了”相符。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不会发出响声，不可能“突然响了”。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“响”不能搭配“香味”这类气味名词。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是吃的东西，不会突然响起来。"}], "explanations": {"警报": "警报：发出的响声或信号，告诉大家有危险，与“突然响了”相符。", "花朵": "语义：花朵不会发出响声，不可能“突然响了”。", "香味": "搭配：“响”不能搭配“香味”这类气味名词。", "早餐": "语义：早餐是吃的东西，不会突然响起来。"}, "sentence_index": 0, "correct_answer": "警报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警报把小偷抓住了，全村人都松了一口气。", "explanation": "这里应该用〈警察〉。警报是危险信号的响声，不能抓人，抓人的是警察。"}, {"text": "学校发了一份警报，让大家下午放假。", "explanation": "这里应该用〈通知〉。警报只用于告知危险，放假的消息应用〈通知〉。"}, {"text": "警报里播放着音乐，大家很开心。", "explanation": "这里应该用〈广播〉。警报是报警的响声，不会播放音乐，播放音乐的是广播。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警报", "is_correct": true, "explanation": "警报：发出的响声或信号，与“按了按钮，一下子响了”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“响”不能搭配“颜色”这类视觉名词。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色属于外貌和表情，不会发出响声。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵不会发出响声，与“按了按钮”的情况无关。"}], "explanations": {"警报": "警报：发出的响声或信号，与“按了按钮，一下子响了”相符。", "颜色": "搭配：“响”不能搭配“颜色”这类视觉名词。", "脸色": "体貌：脸色属于外貌和表情，不会发出响声。", "云朵": "语义：云朵不会发出响声，与“按了按钮”的情况无关。"}, "sentence_index": 6, "correct_answer": "警报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家那只警报很吵，邻居都来看。", "explanation": "量词错误：“只”多用于动物，不用来数警报，应说“个”或“次”。"}, {"text": "那位警报一响，大家都跑出来了。", "explanation": "量词错误：“位”用于人，警报不是人，应说“个”或“次”。"}, {"text": "这张警报坏了，半夜一直在响。", "explanation": "量词错误：“张”用于平面的东西，不用来数警报，应说“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把警报吓了我一跳。", "corrected_sentence": "这次警报吓了我一跳。", "error_description": "错误形式是“这把警报”，“把”用于有柄的器具，不能用来数警报；正确形式是“这次警报”，用“次”计数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候听过警报过，很害怕。", "corrected_sentence": "我小时候听过警报，很害怕。", "error_description": "错误形式是“听过警报过”，句中多出一个“过”；“过”只紧跟动词“听”表示经历，末尾多余的“过”要去掉。正确形式是“听过警报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
