INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90228, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对危险情况发出的通知信号。", "primary_collocate": null, "pronunciation": "jǐng bào", "ipa": "tɕiŋ˨˩ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "气象台发出了台风警报，海边的人都回家了。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上的风越来越大，警报已经发出了。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台发出了地震警报，大家要做好准备。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家发布了高温警报，请大家少出门。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区下了大雨，政府马上发出洪水警报。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机收到了暴雨警报，我就没出门。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "解除警报以后，船又可以出海了。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家向大家发出警报，河水可能会涨。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，这是最后一次警报，请马上离开。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听了广播里的警报，赶快回家了。", "target_word": "警报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "警报器", "label": "复合"}, {"form": "一次警报", "label": "量词"}], "register": "中性", "sense_fingerprint": "对危险情况发出的通知", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9b14e92-3a0f-44e7-b1c6-121a5b382a86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90228, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警报", "is_correct": true, "explanation": "警报：对危险情况发出的通知信号，与“台风”和“海边的人都回家了”相符。"}, {"text": "香水", "is_correct": false, "explanation": "语义：香水不是通知信号，与台风无关。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是音乐作品，不能作为台风的通知。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“发出”不能搭配“饼干”这类食品名词。"}], "explanations": {"警报": "警报：对危险情况发出的通知信号，与“台风”和“海边的人都回家了”相符。", "香水": "语义：香水不是通知信号，与台风无关。", "歌曲": "语义：歌曲是音乐作品，不能作为台风的通知。", "饼干": "搭配：“发出”不能搭配“饼干”这类食品名词。"}, "sentence_index": 0, "correct_answer": "警报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板给他一次警报，让他以后别迟到。", "explanation": "这里应该用〈警告〉。警报只用于危险情况，对员工的批评应说“警告”。"}, {"text": "公司发了一份警报，明天放假。", "explanation": "这里应该用〈通知〉。警报是危险信号，放假的消息应用“通知”。"}, {"text": "电视上播了一条警报，推荐一款新手机。", "explanation": "这里应该用〈广告〉。警报是危险的通知，推荐商品的是广告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警报", "is_correct": true, "explanation": "警报：对危险情况发出的通知，解除后船才能出海，与句意相符。"}, {"text": "婚约", "is_correct": false, "explanation": "语义：婚约是两人之间的约定，与船能否出海无关。"}, {"text": "病痛", "is_correct": false, "explanation": "语义：病痛是身体的不适，与船出海的情况无关。"}, {"text": "人群", "is_correct": false, "explanation": "搭配：“解除”不能搭配“人群”这类集合名词。"}], "explanations": {"警报": "警报：对危险情况发出的通知，解除后船才能出海，与句意相符。", "婚约": "语义：婚约是两人之间的约定，与船能否出海无关。", "病痛": "语义：病痛是身体的不适，与船出海的情况无关。", "人群": "搭配：“解除”不能搭配“人群”这类集合名词。"}, "sentence_index": 6, "correct_answer": "警报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听了广播里的一只警报，赶快回家了。", "explanation": "量词错误：“只”多用于动物，不能用来数警报，应说“条”或“则”。"}, {"text": "他收到了一位暴雨警报，赶快回家了。", "explanation": "量词错误：“位”用于人，不能用来数通知信号，应说“条”或“次”。"}, {"text": "他收到一把警报，赶快回家了。", "explanation": "量词错误：“把”用于有柄的东西，不能用来数警报，应说“条”或“次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把台风警报发布得很及时。", "corrected_sentence": "这次台风警报发布得很及时。", "error_description": "错误形式是“这把台风警报”，“把”用于有柄的器具，不能用来数警报；正确形式是“这次台风警报”，用“次”计数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去年听过台风警报过。", "corrected_sentence": "我去年听过台风警报。", "error_description": "错误形式是“听过台风警报过”，句末多出一个“过”；“过”只紧跟动词“听”表示经历，末尾多余的“过”要去掉。正确形式是“听过台风警报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73be577-e0a7-4f1b-ae45-fcde7e3914eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
