INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90229, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一定要做成一件事的想法。", "primary_collocate": null, "pronunciation": "jué xīn", "ipa": "tɕɥɛ˧˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "他下了决心，明年一定要考上大学。", "target_word": "决心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我有决心学好汉语。", "target_word": "决心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的决心很大，一定能做好。", "target_word": "决心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你真的下了决心要学游泳吗？", "target_word": "决心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他早就有了戒烟的决心。", "target_word": "决心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的决心是每天跑步。", "target_word": "决心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看到他的决心，大家都愿意帮他。", "target_word": "决心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了买房子，她下定决心少花钱。", "target_word": "决心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不知道自己有没有决心去外国住。", "target_word": "决心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小王把自己的决心写在了本子上。", "target_word": "决心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一定要做成某件事的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65a17352-6903-43e6-8fa1-188b5f5fe0c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90229, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "决心", "is_correct": true, "explanation": "“下了决心”是常用搭配，表示下定决心要做某事，与“明年一定要考上大学”相合。"}, {"text": "信心", "is_correct": false, "explanation": "搭配：“下”不与“信心”搭配，不说“下了信心”，应说“有了信心”。"}, {"text": "愿望", "is_correct": false, "explanation": "语义：愿望只表示希望，不表示下定的决定，与“一定要”的语气不合。"}, {"text": "目标", "is_correct": false, "explanation": "搭配：“下”不与“目标”搭配，应说“定下目标”。"}], "explanations": {"决心": "“下了决心”是常用搭配，表示下定决心要做某事，与“明年一定要考上大学”相合。", "信心": "搭配：“下”不与“信心”搭配，不说“下了信心”，应说“有了信心”。", "愿望": "语义：愿望只表示希望，不表示下定的决定，与“一定要”的语气不合。", "目标": "搭配：“下”不与“目标”搭配，应说“定下目标”。"}, "sentence_index": 0, "correct_answer": "决心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师向学生提出了决心，希望大家认真复习。", "explanation": "这里应该用〈要求〉。“要求”是向别人提出的，可以说“向学生提出要求”；“决心”是自己的意志，不能“向学生提出”。"}, {"text": "这个决心一共写了十页，每一步都很清楚。", "explanation": "这里应该用〈计划〉。“计划”是可以写成很多页、分步骤的方案；“决心”是意志，不能有页数和步骤。"}, {"text": "这本书的决心很精彩，值得一读。", "explanation": "这里应该用〈内容〉。“内容”可以用“精彩”来形容，“决心”是意志，不能说“决心很精彩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90229, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "决心", "is_correct": true, "explanation": "“决心”指他的意志，看到它大家才愿意帮他，句意通顺。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指身体的高矮，不能作为大家愿意帮他的理由。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体特征，不能成为大家愿意帮他的原因。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不能让人愿意帮忙，“看到时间”后接“大家都愿意帮他”，句意说不通。"}], "explanations": {"决心": "“决心”指他的意志，看到它大家才愿意帮他，句意通顺。", "身高": "语义：“身高”指身体的高矮，不能作为大家愿意帮他的理由。", "体重": "语义：“体重”是身体特征，不能成为大家愿意帮他的原因。", "时间": "语义：“时间”不能让人愿意帮忙，“看到时间”后接“大家都愿意帮他”，句意说不通。"}, "sentence_index": 6, "correct_answer": "决心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们终于取得了决心。", "explanation": "这里应该用〈胜利〉。“取得”后面接的是胜利、成绩等结果，“决心”不是能取得的东西。"}, {"text": "这幅画的决心很鲜艳。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容的是颜色，“决心”不能用“鲜艳”来形容。"}, {"text": "这座山的决心是两千米。", "explanation": "这里应该用〈高度〉。“两千米”说的是高度，“决心”不能用米来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我做了决心，每天早起。", "corrected_sentence": "我下了决心，每天早起。", "error_description": "错误：“做了决心”。正确：“下了决心”。“决心”前面的动词要用“下”，不能用“做”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于下了一张决心。", "corrected_sentence": "他终于下了一个决心。", "error_description": "错误：“一张决心”。正确：“一个决心”。“张”用于纸、桌子等平面的东西，“决心”的量词要用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
