INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90230, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "坚定不移地要做某事的意志。", "primary_collocate": null, "pronunciation": "jué xīn", "ipa": "tɕɥɛ˧˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "没有人能改变她的决心。", "target_word": "决心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用行动表示了自己的决心。", "target_word": "决心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的决心很坚定，一点儿也不怕难。", "target_word": "决心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "虽然很难，但他的决心一直没变。", "target_word": "决心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家看到了她戒酒的决心。", "target_word": "决心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的话让他有了更大的决心。", "target_word": "决心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的决心不会因为困难而变。", "target_word": "决心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "面对困难，我们要有坚定的决心。", "target_word": "决心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的决心让全家人都很感动。", "target_word": "决心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她带着学好跳舞的决心来到了这里。", "target_word": "决心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "坚定不变、不怕困难的意志", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65a17352-6903-43e6-8fa1-188b5f5fe0c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "决心", "is_correct": true, "explanation": "“决心”指她的意志，能被“改变”，句意通顺。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“她的河流”说不通，河流不是人的所有物，句意荒谬。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“她的石头”说不通，石头不是人的所有物，句意荒谬。"}, {"text": "电线", "is_correct": false, "explanation": "语义：“她的电线”说不通，句意荒谬。"}], "explanations": {"决心": "“决心”指她的意志，能被“改变”，句意通顺。", "河流": "语义：“她的河流”说不通，河流不是人的所有物，句意荒谬。", "石头": "语义：“她的石头”说不通，石头不是人的所有物，句意荒谬。", "电线": "语义：“她的电线”说不通，句意荒谬。"}, "sentence_index": 0, "correct_answer": "决心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次迟到的决心是路上堵车。", "explanation": "这里应该用〈理由〉。“决心”指坚定的意志，不能用来解释迟到的原因。"}, {"text": "事故的决心是司机喝了酒。", "explanation": "这里应该用〈原因〉。“决心”不指事情的起因，不能说“事故的决心是……”。"}, {"text": "这个决心很详细，大家都很满意。", "explanation": "这里应该用〈计划〉。“详细”可以形容计划，“决心”是意志，不能说“决心很详细”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "决心", "is_correct": true, "explanation": "“决心”是他的意志，不会因困难改变，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人所拥有的东西，“他的天气”说不通，句意荒谬。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不会因困难而变，句子在语义上说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是人所拥有的东西，“他的空气”说不通，句意荒谬。"}], "explanations": {"决心": "“决心”是他的意志，不会因困难改变，句意通顺。", "天气": "语义：天气不是人所拥有的东西，“他的天气”说不通，句意荒谬。", "时间": "语义：“时间”不会因困难而变，句子在语义上说不通。", "空气": "语义：空气不是人所拥有的东西，“他的空气”说不通，句意荒谬。"}, "sentence_index": 6, "correct_answer": "决心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这个月的决心减轻了三公斤。", "explanation": "这里应该用〈体重〉。“减轻”和公斤用于体重，“决心”不能这样计量或减轻。"}, {"text": "这条河的决心很清。", "explanation": "这里应该用〈水〉。“清”形容水，“决心”不能用“清”来形容。"}, {"text": "我们选的决心很可行。", "explanation": "这里应该用〈方案〉。“方案”可以说“可行”，“决心”是意志，不能用“可行”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这件事地决心很坚定。", "corrected_sentence": "他对这件事的决心很坚定。", "error_description": "错误在目标词前的结构助词：“事地决心”中的“地”应为“的”。“地”用于修饰动词、形容词，名词“决心”前要用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不有决心去戒烟。", "corrected_sentence": "他没有决心去戒烟。", "error_description": "错误：“不有决心”。正确：“没有决心”。表示“有”的否定要用“没有”，不能用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
