INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90231, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "议案是提出来让大家讨论并决定的一份建议。", "primary_collocate": null, "pronunciation": "yì àn", "ipa": "i˥˩ an˥˩", "syllable_count": 2, "sentences": [{"text": "他在会上提出了一份议案。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家正在讨论这份议案。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个议案很简单，大家都看得懂。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把议案发给了每个同学。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班会上，同学们投票通过了这项议案。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份议案写着我们的活动计划。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的议案没有通过，他有点儿难过。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看过这份议案吗？", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为什么反对这个议案？", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会以前，请先读一读议案。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份议案", "label": "量词"}, {"form": "一项议案", "label": "量词"}], "register": "正式", "sense_fingerprint": "提出来供大家讨论、表决的建议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a138068c-42b9-49dc-b301-f8a5ab1de2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90231, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "议案", "is_correct": true, "explanation": "“提出了一份……”与“在会上”搭配，议案是提交会议讨论的建议。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能在会上“提出”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是建议或文件，不能在会上“提出”。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“提出”一般不与小说搭配，小说不是提交讨论的建议。"}], "explanations": {"议案": "“提出了一份……”与“在会上”搭配，议案是提交会议讨论的建议。", "面包": "语义：面包是食物，不能在会上“提出”。", "蛋糕": "语义：蛋糕不是建议或文件，不能在会上“提出”。", "小说": "搭配：“提出”一般不与小说搭配，小说不是提交讨论的建议。"}, "sentence_index": 0, "correct_answer": "议案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天用一份议案记录开支。", "explanation": "这里应该用〈账本〉。议案是提交会议表决的提案，记录开支要用账本，不说“议案”。"}, {"text": "他为生日派对设计了一份议案。", "explanation": "这里应该用〈方案〉。议案要经会议讨论表决，生日派对的安排用“方案”。"}, {"text": "他每天晚上都在议案上写日记。", "explanation": "这里应该用〈日记本〉。议案是提交会议讨论表决的提案，写日记用的是日记本，不说“议案”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "议案", "is_correct": true, "explanation": "“没有通过”说的是提案不被表决通过，议案正好适用。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种病，不能“通过”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是提案，不能“通过”。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“通过”不与生日搭配。"}], "explanations": {"议案": "“没有通过”说的是提案不被表决通过，议案正好适用。", "感冒": "语义：感冒是一种病，不能“通过”。", "天气": "语义：天气不是提案，不能“通过”。", "生日": "搭配：“通过”不与生日搭配。"}, "sentence_index": 6, "correct_answer": "议案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份议案的主角是一只会说话的猫。", "explanation": "这里应该用〈小说〉。议案是提交会议讨论的提案，有主角、情节的故事要用小说，不说“议案”。"}, {"text": "他写了一份议案，总结了这个学期的工作。", "explanation": "这里应该用〈报告〉。总结工作要用报告，议案是提交会议表决的提案。"}, {"text": "他们和客户签了一份议案。", "explanation": "这里应该用〈合同〉。签订的是双方协议，议案要提交会议讨论，不能“签”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他提出了三只议案。", "corrected_sentence": "他提出了三份议案。", "error_description": "错误：“议案”的量词应为“份”或“项”，不能用量动物的“只”。正确说法是“三份议案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家把这只议案研究了一遍。", "corrected_sentence": "大家把这份议案研究了一遍。", "error_description": "错误：“议案”的量词应为“份”或“项”，不能用量动物的“只”。正确说法是“把这份议案研究了一遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
