INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90232, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "提交会议审议讨论的提案。", "primary_collocate": null, "pronunciation": "yì àn", "ipa": "i˥˩ an˥˩", "syllable_count": 2, "sentences": [{"text": "代表们在大会上审议了这份议案。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "委员会提交了一项新的议案。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项议案明天交给大会讨论。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会否决了这个议案。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表们对议案提出了很多意见。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过投票，议案终于通过了。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这项议案的提出者。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议上有三项议案需要讨论。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民希望议会通过这份议案。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个议案的内容跟教育有关。", "target_word": "议案", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份议案", "label": "量词"}, {"form": "一项议案", "label": "量词"}], "register": "正式", "sense_fingerprint": "提交给会议或议会审议的正式提案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a138068c-42b9-49dc-b301-f8a5ab1de2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "议案", "is_correct": true, "explanation": "“审议”的对象是提交给大会的正式提案，议案正好适用。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是可以审议的文件，不能“审议”。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“审议”不与疾病搭配。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，不能“审议”。"}], "explanations": {"议案": "“审议”的对象是提交给大会的正式提案，议案正好适用。", "蛋糕": "语义：蛋糕不是可以审议的文件，不能“审议”。", "感冒": "搭配：“审议”不与疾病搭配。", "咖啡": "语义：咖啡是饮料，不能“审议”。"}, "sentence_index": 0, "correct_answer": "议案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为新房子的装修设计了一份议案。", "explanation": "这里应该用〈方案〉。议案要提交会议审议，私人的装修安排用“方案”。"}, {"text": "我们和房东签了一份议案。", "explanation": "这里应该用〈合同〉。与房东签的是双方之间的协议；议案是提交会议审议的提案，不是两方之间的约定。"}, {"text": "老师写了一份议案，总结了学生的表现。", "explanation": "这里应该用〈报告〉。总结表现要用报告，议案是提交会议审议的正式提案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "议案", "is_correct": true, "explanation": "“提出者”指提交议案的人，“这项议案”正好适用。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以被提出的项目。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“提出”不与生日搭配。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋不是可以提出的项目，不能说“提出者”。"}], "explanations": {"议案": "“提出者”指提交议案的人，“这项议案”正好适用。", "天气": "语义：天气不是可以被提出的项目。", "生日": "搭配：“提出”不与生日搭配。", "鸡蛋": "语义：鸡蛋不是可以提出的项目，不能说“提出者”。"}, "sentence_index": 6, "correct_answer": "议案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把这份议案夹在了书里，当作标记页码的东西。", "explanation": "这里应该用〈书签〉。议案是提交会议审议的提案，夹在书页之间标记位置的是书签，不说“议案”。"}, {"text": "这首议案唱起来很好听。", "explanation": "这里应该用〈歌曲〉。议案是提交会议审议的提案，唱起来好听的是歌曲，不说“议案”。"}, {"text": "妈妈列了一份议案。", "explanation": "这里应该用〈清单〉。列出要买的东西用清单，议案是提交会议审议的正式提案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大会主席把这只议案交给了代表们。", "corrected_sentence": "大会主席把这份议案交给了代表们。", "error_description": "错误：“议案”的量词应为“份”或“项”，不能用量动物的“只”。正确说法是“这份议案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "议会终于把这只议案通过了。", "corrected_sentence": "议会终于把这份议案通过了。", "error_description": "错误：“议案”的量词应为“份”或“项”，不能用量动物的“只”。正确说法是“把这份议案通过了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
