INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90233, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比赛里最后的一场，赢的得第一。", "primary_collocate": null, "pronunciation": "jué sài", "ipa": "tɕɥɛ˧˥ saɪ˥˩", "syllable_count": 2, "sentences": [{"text": "今晚的决赛谁会赢？", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "决赛是最后一场比赛。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在决赛里赢了对手。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班打进了篮球决赛。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "决赛赢了就是第一名。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸一直在电视前看决赛。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "决赛那天，下了很大的雨。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她为了决赛练了很久。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场决赛的票卖完了。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在决赛里踢得很好。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "半决赛", "label": "复合"}, {"form": "总决赛", "label": "复合"}], "register": "中性", "sense_fingerprint": "比赛里最后一场，赢者得第一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65a17352-6903-43e6-8fa1-188b5f5fe0c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90233, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚饭", "is_correct": false, "explanation": "语义：晚饭不是比赛，“今晚的晚饭谁会赢”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能分出胜负，“今晚的天气谁会赢”说不通。"}, {"text": "决赛", "is_correct": true, "explanation": "决赛：比赛里最后的一场，赢的得第一，与“谁会赢”相合。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：一般不说考试“谁会赢”，“赢”不与“考试”搭配。"}], "explanations": {"晚饭": "语义：晚饭不是比赛，“今晚的晚饭谁会赢”说不通。", "天气": "语义：天气不能分出胜负，“今晚的天气谁会赢”说不通。", "决赛": "决赛：比赛里最后的一场，赢的得第一，与“谁会赢”相合。", "考试": "搭配：一般不说考试“谁会赢”，“赢”不与“考试”搭配。"}, "sentence_index": 0, "correct_answer": "决赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "决赛后，只有前八名进入下一轮。", "explanation": "这里应该用〈初赛〉。决赛是最后一场，之后不能再进入下一轮；前面的轮次要用初赛。"}, {"text": "决赛是第一场比赛。", "explanation": "这里应该用〈预赛〉。决赛是最后一场比赛，不能是第一场；第一场比赛要用预赛。"}, {"text": "我们的决赛是正确的。", "explanation": "这里应该用〈决定〉。决赛指比赛，不能用来说判断“正确”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90233, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晴天", "is_correct": false, "explanation": "语义：晴天不会下大雨，与“下了很大的雨”相矛盾。"}, {"text": "旱季", "is_correct": false, "explanation": "语义：旱季少雨，与“下了很大的雨”的语境不符。"}, {"text": "决赛", "is_correct": true, "explanation": "决赛：比赛里最后的一场，作为“那天”的事件，与语境相合。"}, {"text": "大旱", "is_correct": false, "explanation": "搭配：“大旱”与“下了很大的雨”不搭配，二者矛盾。"}], "explanations": {"晴天": "语义：晴天不会下大雨，与“下了很大的雨”相矛盾。", "旱季": "语义：旱季少雨，与“下了很大的雨”的语境不符。", "决赛": "决赛：比赛里最后的一场，作为“那天”的事件，与语境相合。", "大旱": "搭配：“大旱”与“下了很大的雨”不搭配，二者矛盾。"}, "sentence_index": 6, "correct_answer": "决赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我住在决赛里。", "explanation": "这里应该用〈场地〉。决赛是比赛，不是地方，不能“住在”里面。"}, {"text": "这场决赛讨论了明年的预算。", "explanation": "这里应该用〈会议〉。决赛是竞赛，不能讨论预算；讨论预算的是会议。"}, {"text": "我们把决赛撕掉了。", "explanation": "这里应该用〈取消〉。“撕掉”只用于纸张等物品，决赛是比赛，应说“取消”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她为了一条决赛练习了很久。", "corrected_sentence": "她为了一场决赛练习了很久。", "error_description": "错误在量词：“条”用于细长的东西，比赛类活动要用量词“场”，应说“一场决赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条决赛的票都卖完了。", "corrected_sentence": "这场决赛的票都卖完了。", "error_description": "错误在量词：“条”用于细长的东西，比赛类活动要用量词“场”，应说“这场决赛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
