INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90234, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "竞赛中最后决定名次的比赛。", "primary_collocate": null, "pronunciation": "jué sài", "ipa": "tɕɥɛ˧˥ saɪ˥˩", "syllable_count": 2, "sentences": [{"text": "明天下午有足球决赛。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他进入了游泳决赛。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "决赛的成绩下午会公布。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次决赛有八个选手参加。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在决赛中得了第二名。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛分为预赛和决赛。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "观众们都来看决赛。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "决赛结束后，大家一起合影。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有进决赛，很难过。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "决赛前，教练和队员开了会。", "target_word": "决赛", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "半决赛", "label": "复合"}, {"form": "总决赛", "label": "复合"}], "register": "中性", "sense_fingerprint": "竞赛中最后决定名次的比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65a17352-6903-43e6-8fa1-188b5f5fe0c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "午餐", "is_correct": false, "explanation": "语义：午餐与足球不是同一类活动，“明天下午有足球午餐”说不通。"}, {"text": "期末", "is_correct": false, "explanation": "搭配：“期末”是时间段，不能说“有足球期末”。"}, {"text": "决赛", "is_correct": true, "explanation": "决赛：竞赛中最后决定名次的比赛，与“足球”和“明天下午”相合。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“足球空气”说不通，空气不是比赛，句意荒谬。"}], "explanations": {"午餐": "语义：午餐与足球不是同一类活动，“明天下午有足球午餐”说不通。", "期末": "搭配：“期末”是时间段，不能说“有足球期末”。", "决赛": "决赛：竞赛中最后决定名次的比赛，与“足球”和“明天下午”相合。", "空气": "语义：“足球空气”说不通，空气不是比赛，句意荒谬。"}, "sentence_index": 0, "correct_answer": "决赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "决赛只是第一轮，选手很多。", "explanation": "这里应该用〈预赛〉。决赛是最后一场，不能是第一轮；第一轮要用预赛。"}, {"text": "这次决赛的汤很咸。", "explanation": "这里应该用〈汤〉。“咸”形容食物的味道，决赛是竞赛，不能作为汤的修饰语。"}, {"text": "这次决赛是他做出的一个重要抉择。", "explanation": "这里应该用〈决定〉。决赛指竞赛，不能用来指“决定”这种判断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早餐", "is_correct": false, "explanation": "语义：观众来看的是比赛，不是早餐，“观众们都来看早餐”说不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“看”不能以“空气”作观看的对象。"}, {"text": "决赛", "is_correct": true, "explanation": "决赛：观众来看的正是竞赛的最后一场比赛，与语境相合。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：观众不会来看饼干，与“观众们都来看”的语境不符。"}], "explanations": {"早餐": "语义：观众来看的是比赛，不是早餐，“观众们都来看早餐”说不通。", "空气": "搭配：“看”不能以“空气”作观看的对象。", "决赛": "决赛：观众来看的正是竞赛的最后一场比赛，与语境相合。", "饼干": "语义：观众不会来看饼干，与“观众们都来看”的语境不符。"}, "sentence_index": 6, "correct_answer": "决赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把决赛装进了书包。", "explanation": "这里应该用〈作业〉。决赛是比赛，不是可以装进书包的东西。"}, {"text": "妈妈在决赛里炒了两个菜。", "explanation": "这里应该用〈厨房〉。炒菜在厨房里，决赛是比赛，不是地方。"}, {"text": "他把决赛吃掉了。", "explanation": "这里应该用〈蛋糕〉。“吃掉”的对象是食物，决赛是比赛，不能被吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天下午有一条篮球决赛。", "corrected_sentence": "明天下午有一场篮球决赛。", "error_description": "错误在量词：“条”用于细长的东西，比赛类活动要用量词“场”，应说“一场篮球决赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她顺利进入在决赛。", "corrected_sentence": "她顺利进入决赛。", "error_description": "错误在介词：“进入”后直接接宾语“决赛”，中间不加“在”，应说“进入决赛”。加“在”后句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90235, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出事", "is_correct": true, "explanation": "反义：“没事”指平安、没受伤，“出事”指发生意外，二者相对。"}, {"text": "吃饭", "is_correct": false, "explanation": "与“没事”无反义关系，也不是其任何义项的反义词。"}, {"text": "旅行", "is_correct": false, "explanation": "与“没事”无反义关系，也不是其任何义项的反义词。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“没事”无反义关系，也不是其任何义项的反义词。"}], "correct_answer": "出事", "explanations": {"出事": "反义：“没事”指平安、没受伤，“出事”指发生意外，二者相对。", "吃饭": "与“没事”无反义关系，也不是其任何义项的反义词。", "旅行": "与“没事”无反义关系，也不是其任何义项的反义词。", "睡觉": "与“没事”无反义关系，也不是其任何义项的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
