INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90235, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "没有问题，也没有坏事。", "primary_collocate": null, "pronunciation": "méi shì", "ipa": "mei˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "医生说他的检查结果没事。", "target_word": "没事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子从车上摔下来，幸好没事。", "target_word": "没事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，家里人都没事。", "target_word": "没事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的手没事吧？", "target_word": "没事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到她没事，我才放心。", "target_word": "没事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天雨很大，但是孩子们都没事。", "target_word": "没事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝了很多酒，不过现在没事了。", "target_word": "没事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车撞坏了，人没事就好。", "target_word": "没事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只猫从楼上掉下来，竟然没事。", "target_word": "没事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查完了，医生说奶奶的身体没事。", "target_word": "没事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没事了", "label": "体标"}], "register": "口语", "sense_fingerprint": "人或事物平安，没有出问题，没有受伤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad8dbc6-820a-4e36-a32d-a214082bc3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90235, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "没事", "is_correct": true, "explanation": "没事：没有问题，也没有受伤或出事。"}, {"text": "美式", "is_correct": false, "explanation": "美式（měi shì）第一音节声调不同：没（méi）与美（měi）不同，意思是美国式的。"}, {"text": "美食", "is_correct": false, "explanation": "美食（měi shí）两个音节的声调都不同，意思是美味的食物。"}, {"text": "美事", "is_correct": false, "explanation": "美事（měi shì）第一音节声调不同，意思是美好的事情。"}], "explanations": {"没事": "没事：没有问题，也没有受伤或出事。", "美式": "美式（měi shì）第一音节声调不同：没（méi）与美（měi）不同，意思是美国式的。", "美食": "美食（měi shí）两个音节的声调都不同，意思是美味的食物。", "美事": "美事（měi shì）第一音节声调不同，意思是美好的事情。"}, "sentence_index": null, "correct_answer": "没事"}, "level_3": {"options": [{"text": "没事", "is_correct": true, "explanation": "正确：表示检查结果正常、没有问题，与“医生说”的语境相符。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指人或物下落不明，检查结果不能失踪，句意不通。"}, {"text": "出国", "is_correct": false, "explanation": "语义：“出国”是人的行动，检查结果不能出国，句意不通。"}, {"text": "下班", "is_correct": false, "explanation": "搭配：“下班”的主体须是人，不能用于“检查结果”。"}], "explanations": {"没事": "正确：表示检查结果正常、没有问题，与“医生说”的语境相符。", "失踪": "语义：“失踪”指人或物下落不明，检查结果不能失踪，句意不通。", "出国": "语义：“出国”是人的行动，检查结果不能出国，句意不通。", "下班": "搭配：“下班”的主体须是人，不能用于“检查结果”。"}, "sentence_index": 0, "correct_answer": "没事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个会议没事参加，只好取消。", "explanation": "这里应该用〈没人〉。没事表示没有问题，不能指“没有人参加”，此处应说“没人”。"}, {"text": "他没事去超市买了很多水果。", "explanation": "这里应该用〈没课〉或〈有空〉。没事在这里表示平安、没出问题，不能表示有时间、有空，此处说“有空”更清楚。"}, {"text": "这家店没事，老板只好关门。", "explanation": "这里应该用〈没生意〉。没事表示没有问题，不能指“没有生意”，此处应说“没生意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90235, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没事", "is_correct": true, "explanation": "正确：表示喝酒后已经平安、没有不适，与“不过”的转折相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语法：“桌子”是名词，不能作“现在……了”的谓语，句子不成立。"}, {"text": "苹果", "is_correct": false, "explanation": "语法：“苹果”是名词，不能说“他现在苹果了”。"}, {"text": "窗户", "is_correct": false, "explanation": "语法：“窗户”是名词，不能描述人喝酒后的状态。"}], "explanations": {"没事": "正确：表示喝酒后已经平安、没有不适，与“不过”的转折相符。", "桌子": "语法：“桌子”是名词，不能作“现在……了”的谓语，句子不成立。", "苹果": "语法：“苹果”是名词，不能说“他现在苹果了”。", "窗户": "语法：“窗户”是名词，不能描述人喝酒后的状态。"}, "sentence_index": 6, "correct_answer": "没事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题太难，我没事做出来了。", "explanation": "这里应该用〈没办法〉。没事不能表示“做不出来”，此处要说“没办法做出来”。"}, {"text": "他没事考上大学，很难过。", "explanation": "这里应该用〈没考上〉。没事不能表示“没有考上”，此处应说“没考上”。"}, {"text": "这台机器没事无损，可以用。", "explanation": "这里应该用〈完好〉。“完好无损”是固定说法，“没事无损”不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90235, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那天他从楼梯上摔下来，但是不没事。", "corrected_sentence": "那天他从楼梯上摔下来，但是没事。", "error_description": "“没”已表示否定，“没事”前不能再加“不”，应说“没事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90235, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生说他的身体有没事，可以出院了。", "corrected_sentence": "医生说他的身体没事，可以出院了。", "error_description": "“没事”前不能加“有”，“有没事”不成立，应为“身体没事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
