INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90237, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90237, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变天是天气变了，比如要下雨或变冷。", "primary_collocate": null, "pronunciation": "biàn tiān", "ipa": "pjɛn˥˩ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "看，要变天了，快回家吧。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天早上还很热，下午突然变天了。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说她的腿疼，一定是要变天了。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一变天，我就想多穿一件衣服。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说明天会变天，我们别去爬山了。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚变天了，今早特别冷。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每次变天以前，天空都会很暗。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变天了，别忘了收衣服。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报说周末要变天，会下大雨。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一看云就知道快变天了。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变天了", "label": "体标"}], "register": "口语", "sense_fingerprint": "天气变了，如要下雨或变冷", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95593539-6a07-48d3-929c-5995fd291c1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90237, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变天", "is_correct": true, "explanation": "正确：“要变天了”说天气将要转变，与“看”和“快回家吧”的语境相合。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”是学生完成学业，不能用来说天气，“要毕业了”与“看”和“快回家吧”不合。"}, {"text": "开花", "is_correct": false, "explanation": "搭配：“开花”只用于植物，不能用于天气。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”说种子或植物长出芽，不能用于天气。"}], "explanations": {"变天": "正确：“要变天了”说天气将要转变，与“看”和“快回家吧”的语境相合。", "毕业": "语义：“毕业”是学生完成学业，不能用来说天气，“要毕业了”与“看”和“快回家吧”不合。", "开花": "搭配：“开花”只用于植物，不能用于天气。", "发芽": "搭配：“发芽”说种子或植物长出芽，不能用于天气。"}, "sentence_index": 0, "correct_answer": "变天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个计划一下子变天了。", "explanation": "这里应该用〈变卦〉。〈变卦〉指计划或主意改变，“变天”只指天气变化或政权更替，不能用于计划。"}, {"text": "这碗汤放一会儿就变天了。", "explanation": "这里应该用〈凉〉。〈凉〉可以说食物温度下降，“变天”只说天气变化，不能用于食物。"}, {"text": "妈妈一变天，我就不敢说话。", "explanation": "这里应该用〈发火〉。〈发火〉用于人的情绪，“变天”只说天气变化，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90237, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变天", "is_correct": true, "explanation": "正确：“每次变天以前”指天气转变之前，天空变暗，符合语境。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与天空变暗没有关系，句子不通。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“发烧”的主体是人，不能说“天空发烧”。"}, {"text": "开学", "is_correct": false, "explanation": "语义：“开学”是学校的事，与“天空都会很暗”无关。"}], "explanations": {"变天": "正确：“每次变天以前”指天气转变之前，天空变暗，符合语境。", "结婚": "语义：“结婚”与天空变暗没有关系，句子不通。", "发烧": "搭配：“发烧”的主体是人，不能说“天空发烧”。", "开学": "语义：“开学”是学校的事，与“天空都会很暗”无关。"}, "sentence_index": 6, "correct_answer": "变天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子一变天，大人就手忙脚乱。", "explanation": "这里应该用〈哭〉。〈哭〉的主语可以是孩子，“变天”只说天气变化，不能用于孩子。"}, {"text": "这壶水一烧，就变天了。", "explanation": "这里应该用〈烫〉。〈烫〉说水的温度高，“变天”只说天气变化，不能用于水。"}, {"text": "灯一亮，屋里就变天了。", "explanation": "这里应该用〈敞亮〉。〈敞亮〉说屋子明亮，“变天”只说天气变化，不能用于房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90237, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "刚下班，外面就被变天了。", "corrected_sentence": "刚下班，外面就变天了。", "error_description": "“变天”是不及物动词，表示天气自己变化，不能用“被”构成被动句。应改为“外面就变天了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90237, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天夜里很变天了，早上特别冷。", "corrected_sentence": "昨天夜里变天了，早上特别冷。", "error_description": "“变天”是动词，表示天气发生变化，前面不能加程度副词“很”。应改为“昨天夜里变天了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
