INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90238, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90238, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "天气发生变化。", "primary_collocate": null, "pronunciation": "biàn tiān", "ipa": "pjɛn˥˩ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "北方的秋天常常变天，早晚很凉。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚才还是晴天，现在变天了。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变天以后，街上的人少了很多。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天可能变天，出门带上伞吧。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天老变天，我有点感冒。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的老毛病一变天就犯。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里容易变天，你要小心。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天夜里变天了，早上下起了小雨。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到天上的黑云，大家知道要变天了。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变天了，我们把衣服收进来吧。", "target_word": "变天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变天了", "label": "体标"}], "register": "口语", "sense_fingerprint": "天气发生变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95593539-6a07-48d3-929c-5995fd291c1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变天", "is_correct": true, "explanation": "正确：“常常变天”说秋天天气多变，与“早晚很凉”相合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是学业活动，不能说“秋天常常考试”来描述天气凉。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”说种子或植物长出芽，不能用于天气。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”指人的体温升高，与“北方的秋天”无关。"}], "explanations": {"变天": "正确：“常常变天”说秋天天气多变，与“早晚很凉”相合。", "考试": "语义：“考试”是学业活动，不能说“秋天常常考试”来描述天气凉。", "发芽": "搭配：“发芽”说种子或植物长出芽，不能用于天气。", "发烧": "语义：“发烧”指人的体温升高，与“北方的秋天”无关。"}, "sentence_index": 0, "correct_answer": "变天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事他一下子变天了。", "explanation": "这里应该用〈变卦〉。〈变卦〉指主意或计划改变，“变天”只指天气变化或政权更替，不能用于事情。"}, {"text": "这间屋子一到晚上就变天。", "explanation": "这里应该用〈冷〉。〈冷〉可以说房间温度低，“变天”只说天气变化，不能用于房间。"}, {"text": "他一变天，家里就没人敢说话。", "explanation": "这里应该用〈生气〉。〈生气〉用于人的情绪，“变天”只说天气变化，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变天", "is_correct": true, "explanation": "正确：“容易变天”说天气易变，与“你要小心”的提醒相合。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与天气无关，句子不通。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是学业活动，不能说“山里容易考试”来提醒人小心。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”指人没按时到，不能用于天气。"}], "explanations": {"变天": "正确：“容易变天”说天气易变，与“你要小心”的提醒相合。", "结婚": "语义：“结婚”与天气无关，句子不通。", "考试": "语义：“考试”是学业活动，不能说“山里容易考试”来提醒人小心。", "迟到": "语义：“迟到”指人没按时到，不能用于天气。"}, "sentence_index": 6, "correct_answer": "变天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铃声一变天，我们就起床了。", "explanation": "这里应该用〈响〉。〈响〉说声音发出，“变天”只说天气变化，不能用于声音。"}, {"text": "门一变天，冷风就灌进来了。", "explanation": "这里应该用〈开〉。〈开〉说门被打开，“变天”只说天气变化，不能用于门。"}, {"text": "灯一变天，屋里就暗了。", "explanation": "这里应该用〈熄〉。〈熄〉说灯被关掉，“变天”只说天气变化，不能用于灯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前几天天气晴朗，昨天却被变天了。", "corrected_sentence": "前几天天气晴朗，昨天却变天了。", "error_description": "“变天”是不及物动词，不能用“被”构成被动句。天气自己变化，应说“昨天却变天了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋天的早晨凉快，中午却突然被变天了。", "corrected_sentence": "秋天的早晨凉快，中午却突然变天了。", "error_description": "“变天”是不及物动词，不能用“被”构成被动句。天气自己变化，应说“中午却突然变天了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7925578-ac2d-4938-a71d-abe881f72603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
