INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90239, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能飞到天上去的、很长很大的机器。", "primary_collocate": null, "pronunciation": "huǒ jiàn", "ipa": "xuɔ˨˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我在电视上看到了火箭。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火箭飞到天上去了。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火箭可以飞到很远的地方。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个火箭又长又大。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火箭会飞到很高的天上。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想坐火箭去月亮上看看。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们看了一张火箭的照片。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他画了一个红色的火箭。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火箭里面坐着两个宇航员。", "target_word": "火箭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们抬头看着天上的火箭。", "target_word": "火箭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "量词"}, {"form": "运载火箭", "label": "复合"}], "register": "中性", "sense_fingerprint": "能飞上天的又长又大的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65a17352-6903-43e6-8fa1-188b5f5fe0c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90239, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "火箭", "is_correct": true, "explanation": "正确答案。火箭指能飞到天上去的、很长很大的机器。"}, {"text": "货件", "is_correct": false, "explanation": "huò（第四声）与 huǒ（第三声）声调不同，货件指一件货物。"}, {"text": "火线", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同，火线指带电的导线。"}, {"text": "火碱", "is_correct": false, "explanation": "jiǎn 与 jiàn 只差声调，火碱指氢氧化钠，是化工原料。"}], "explanations": {"火箭": "正确答案。火箭指能飞到天上去的、很长很大的机器。", "货件": "huò（第四声）与 huǒ（第三声）声调不同，货件指一件货物。", "火线": "xiàn 与 jiàn 声母不同，火线指带电的导线。", "火碱": "jiǎn 与 jiàn 只差声调，火碱指氢氧化钠，是化工原料。"}, "sentence_index": null, "correct_answer": "火箭"}, "level_3": {"options": [{"text": "火箭", "is_correct": true, "explanation": "“我在电视上看到了火箭”，电视上能看到火箭，句意通顺。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”不用于“声音”，看不到声音，应说“听到声音”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看”不用于“味道”，应说“闻到味道”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是看不见的，“在电视上看到空气”说不通。"}], "explanations": {"火箭": "“我在电视上看到了火箭”，电视上能看到火箭，句意通顺。", "声音": "搭配：“看”不用于“声音”，看不到声音，应说“听到声音”。", "味道": "搭配：“看”不用于“味道”，应说“闻到味道”。", "空气": "语义：空气是看不见的，“在电视上看到空气”说不通。"}, "sentence_index": 0, "correct_answer": "火箭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火箭在水里游，很快就到了对岸。", "explanation": "这里应该用〈潜水艇〉。潜水艇在水里航行，火箭靠喷射燃气在空中飞行，不能在水里游。"}, {"text": "他们坐火箭去对岸。", "explanation": "这里应该用〈船〉。去对岸要坐船，火箭能飞到天上去，不能用来渡河。"}, {"text": "火箭在天上轻轻地飘。", "explanation": "这里应该用〈风筝〉。火箭靠喷射燃气快速飞行，不会像风筝那样轻轻飘浮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90239, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火箭", "is_correct": true, "explanation": "“一张火箭的照片”指一张火箭的相片，句意通顺。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：“梦想”是抽象的愿望，不能被拍成照片，句子说不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“照片”要拍可见的事物，“时间”不能拍成照片。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是性情，不能拍成一张照片给人看，句意不通。"}], "explanations": {"火箭": "“一张火箭的照片”指一张火箭的相片，句意通顺。", "梦想": "语义：“梦想”是抽象的愿望，不能被拍成照片，句子说不通。", "时间": "搭配：“照片”要拍可见的事物，“时间”不能拍成照片。", "脾气": "语义：“脾气”是性情，不能拍成一张照片给人看，句意不通。"}, "sentence_index": 6, "correct_answer": "火箭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火箭在树上唱歌。", "explanation": "这里应该用〈小鸟〉。唱歌是小鸟的行为，火箭是机器，不能在树上唱歌。"}, {"text": "火箭在花丛中飞来飞去。", "explanation": "这里应该用〈蜜蜂〉。蜜蜂会在花丛中飞来飞去，火箭是能飞到天上去的机器，不会这样活动。"}, {"text": "火箭在草地上奔跑。", "explanation": "这里应该用〈马〉。“奔跑”是马等动物的行为，火箭不能在草地上奔跑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90239, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看见了一个很大火箭。", "corrected_sentence": "我看见了一个很大的火箭。", "error_description": "错误：“很大火箭”。正确：“很大的火箭”。形容词修饰名词时，中间要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90239, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他抬头看见一个大很的火箭。", "corrected_sentence": "他抬头看见一个很大的火箭。", "error_description": "错误：“大很的火箭”。正确：“很大的火箭”。程度副词“很”要放在形容词“大”的前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
