INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "靠喷射燃气飞行的飞行器，可用来发射卫星。", "primary_collocate": null, "pronunciation": "huǒ jiàn", "ipa": "xuɔ˨˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "火箭把卫星送上了太空。", "target_word": "火箭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这枚火箭明天早上发射。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师们正在检查火箭的发动机。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火箭靠喷出的燃气向上飞。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次火箭发射很成功。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火箭飞得很高，很快就看不见了。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视里正在直播火箭发射。", "target_word": "火箭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家用火箭把新卫星送进了太空。", "target_word": "火箭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭的第一级用完燃料后会掉下来。", "target_word": "火箭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者站在远处，看火箭慢慢升空。", "target_word": "火箭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "量词"}, {"form": "运载火箭", "label": "复合"}], "register": "中性", "sense_fingerprint": "靠喷射燃气飞行、可发射卫星的飞行器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65a17352-6903-43e6-8fa1-188b5f5fe0c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90240, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "火箭", "is_correct": true, "explanation": "正确答案。火箭指靠喷射燃气飞行、可发射卫星的飞行器。"}, {"text": "货件", "is_correct": false, "explanation": "huò（第四声）与 huǒ（第三声）声调不同，货件指一件货物。"}, {"text": "火线", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同，火线指带电的导线。"}, {"text": "火碱", "is_correct": false, "explanation": "jiǎn 与 jiàn 只差声调，火碱指氢氧化钠，是化工原料。"}], "explanations": {"火箭": "正确答案。火箭指靠喷射燃气飞行、可发射卫星的飞行器。", "货件": "huò（第四声）与 huǒ（第三声）声调不同，货件指一件货物。", "火线": "xiàn 与 jiàn 声母不同，火线指带电的导线。", "火碱": "jiǎn 与 jiàn 只差声调，火碱指氢氧化钠，是化工原料。"}, "sentence_index": null, "correct_answer": "火箭"}, "level_3": {"options": [{"text": "火箭", "is_correct": true, "explanation": "“火箭把卫星送上了太空”中，能运载卫星升空的正是火箭，句意通顺。"}, {"text": "火车", "is_correct": false, "explanation": "语义：火车不能把卫星送上太空，与“太空”不合。"}, {"text": "轮船", "is_correct": false, "explanation": "语义：轮船只能在水上航行，不能把卫星送上太空。"}, {"text": "卫星", "is_correct": false, "explanation": "配价：“送”的主语要能主动运送，卫星不能把自己送上太空。"}], "explanations": {"火箭": "“火箭把卫星送上了太空”中，能运载卫星升空的正是火箭，句意通顺。", "火车": "语义：火车不能把卫星送上太空，与“太空”不合。", "轮船": "语义：轮船只能在水上航行，不能把卫星送上太空。", "卫星": "配价：“送”的主语要能主动运送，卫星不能把自己送上太空。"}, "sentence_index": 0, "correct_answer": "火箭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火箭靠螺旋桨向前飞。", "explanation": "这里应该用〈飞机〉。火箭靠喷射燃气飞行，没有螺旋桨，靠螺旋桨飞的是飞机。"}, {"text": "渔民在河上划火箭捕鱼。", "explanation": "这里应该用〈船〉。“划”的对象是船，火箭靠喷射燃气飞行，不能用来划水捕鱼。"}, {"text": "火箭在马路上跑。", "explanation": "这里应该用〈汽车〉。汽车在路上行驶，火箭靠喷射燃气飞行，不能在马路上跑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火箭", "is_correct": true, "explanation": "“直播火箭发射”指电视播放火箭升空，句意通顺。"}, {"text": "足球", "is_correct": false, "explanation": "搭配：“发射”用于火箭、导弹、卫星等，不说“发射足球”。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：汽车不能被“发射”，与“发射”搭配不当。"}, {"text": "面条", "is_correct": false, "explanation": "语义：面条不能被发射，“直播面条发射”句意荒谬。"}], "explanations": {"火箭": "“直播火箭发射”指电视播放火箭升空，句意通顺。", "足球": "搭配：“发射”用于火箭、导弹、卫星等，不说“发射足球”。", "汽车": "搭配：汽车不能被“发射”，与“发射”搭配不当。", "面条": "语义：面条不能被发射，“直播面条发射”句意荒谬。"}, "sentence_index": 6, "correct_answer": "火箭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火箭在草地上吃草。", "explanation": "这里应该用〈牛〉。吃草是牛羊等动物的行为，火箭是机器，不会吃草。"}, {"text": "火箭扇着翅膀飞上了树枝。", "explanation": "这里应该用〈小鸟〉。扇翅膀、落在树枝上是鸟的行为，火箭靠喷射燃气飞行，没有翅膀可扇。"}, {"text": "火箭在海底航行。", "explanation": "这里应该用〈潜艇〉。潜艇在海底航行，火箭靠喷射燃气在空中飞行，不能在海底航行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张火箭很快就升上了天空。", "corrected_sentence": "这枚火箭很快就升上了天空。", "error_description": "错误：“张”。正确：“枚”。“张”用于纸、桌子等平面的东西，火箭的量词用“枚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条火箭今天下午要发射。", "corrected_sentence": "这枚火箭今天下午要发射。", "error_description": "错误：“条”。正确：“枚”。火箭的量词应用“枚”，“条”用于细长的东西，不用于火箭。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39c2d9a-1351-4099-a8c5-b2f7374bf97b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
