INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90241, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变换是把一个样子换成另一个样子。", "primary_collocate": null, "pronunciation": "biàn huàn", "ipa": "pjɛn˥˩ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "灯光不停地变换着颜色。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他变换了一下坐的姿势。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云在天上变换着各种形状。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞蹈演员快速变换队形。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变色龙会变换身体的颜色。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不停地变换造型玩游戏。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她变换了发型，看起来更年轻。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镜子前，他变换着各种表情。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以变换一下角度拍照。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种生物能在两种形态之间变换。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变换了", "label": "体标"}, {"form": "变换着", "label": "体标"}, {"form": "变换过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把外表、姿势、颜色等样子换成另一种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a138068c-42b9-49dc-b301-f8a5ab1de2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90241, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变换", "is_correct": true, "explanation": "“变换”指把颜色不断换来换去，符合“不停地……着”的语境。"}, {"text": "吞食", "is_correct": false, "explanation": "语义：吞食指把东西咽下去，灯光不会吞食颜色。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：修剪多用于树枝、头发等，不说修剪颜色。"}, {"text": "切割", "is_correct": false, "explanation": "语义：切割指用刀具把物体分开，与灯光变色无关。"}], "explanations": {"变换": "“变换”指把颜色不断换来换去，符合“不停地……着”的语境。", "吞食": "语义：吞食指把东西咽下去，灯光不会吞食颜色。", "修剪": "搭配：修剪多用于树枝、头发等，不说修剪颜色。", "切割": "语义：切割指用刀具把物体分开，与灯光变色无关。"}, "sentence_index": 0, "correct_answer": "变换"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座小城这几年的人口变换很大。", "explanation": "这里应该用〈变化〉。人口数量的增减不是把一个样子换成另一个样子，应说“变化很大”。"}, {"text": "医生已经变换了病人的输液管。", "explanation": "这里应该用〈更换〉。变换强调样子或形式的转换，把旧输液管换成新的要用更换。"}, {"text": "工人用新零件变换了旧零件。", "explanation": "这里应该用〈替换〉。变换指样子或形式的改变，用新零件取代旧零件要用替换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90241, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变换", "is_correct": true, "explanation": "“变换”指把发型换成另一种样子，符合“她……了发型”的语境。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住东西，发型不能被咬。"}, {"text": "擦去", "is_correct": false, "explanation": "搭配：擦去多用于灰尘、污渍，不说擦去发型。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉是丢弃，与“看起来更年轻”的改变意思不符。"}], "explanations": {"变换": "“变换”指把发型换成另一种样子，符合“她……了发型”的语境。", "咬": "语义：咬是用牙齿夹住东西，发型不能被咬。", "擦去": "搭配：擦去多用于灰尘、污渍，不说擦去发型。", "扔掉": "语义：扔掉是丢弃，与“看起来更年轻”的改变意思不符。"}, "sentence_index": 6, "correct_answer": "变换"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听完他的劝告，她的想法发生了变换。", "explanation": "这里应该用〈转变〉。变换指样子或形式的替换；想法、态度的根本改变要用转变。"}, {"text": "两个朋友变换了礼物，都很开心。", "explanation": "这里应该用〈交换〉。变换表示改变样子，不指双方互相交付物品；互换礼物要用交换。"}, {"text": "他把客厅的沙发变换到了窗边。", "explanation": "这里应该用〈搬〉。变换指把一个样子换成另一个样子；只是把沙发挪到窗边，要用“搬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们正在变换了造型，玩得很开心。", "corrected_sentence": "孩子们正在变换造型，玩得很开心。", "error_description": "错误：“正在变换了造型”；正确：“正在变换造型”。“正在”表示动作正在进行，句中不能再用“了”表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把拍摄角度变换，终于拍到满意的照片。", "corrected_sentence": "他把拍摄角度变换了，终于拍到满意的照片。", "error_description": "错误：“把拍摄角度变换”；正确：“把拍摄角度变换了”。用“把”字句时，动词后要有“了”或其他补足成分，单独的动词不能结束句子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
