INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90242, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一种形式或内容换成另一种。", "primary_collocate": null, "pronunciation": "biàn huàn", "ipa": "pjɛn˥˩ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "老师变换了教学的方法。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话时常常变换话题。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台每周变换节目内容。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他变换了几种说法，想让大家明白。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家喜欢变换写作的手法。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司变换了做生意的方式。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐一响，舞步也跟着变换。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他变换着语气，给孩子读故事。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的商品总是变换花样。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以变换一下学习方式。", "target_word": "变换", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变换了", "label": "体标"}, {"form": "变换着", "label": "体标"}, {"form": "变换过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把方法、话题、内容等形式换成另一种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a138068c-42b9-49dc-b301-f8a5ab1de2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变换", "is_correct": true, "explanation": "“变换”指把教学方法换成另一种，符合“老师……了教学的方法”的语境。"}, {"text": "擦去", "is_correct": false, "explanation": "搭配：擦去多用于灰尘、污渍，不说擦去方法。"}, {"text": "拆卸", "is_correct": false, "explanation": "搭配：拆卸多用于机器、设备，不说拆卸教学方法。"}, {"text": "切割", "is_correct": false, "explanation": "语义：切割指用刀具把物体分开，与改变教学方法无关。"}], "explanations": {"变换": "“变换”指把教学方法换成另一种，符合“老师……了教学的方法”的语境。", "擦去": "搭配：擦去多用于灰尘、污渍，不说擦去方法。", "拆卸": "搭配：拆卸多用于机器、设备，不说拆卸教学方法。", "切割": "语义：切割指用刀具把物体分开，与改变教学方法无关。"}, "sentence_index": 0, "correct_answer": "变换"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次公司变换了新的办公地址。", "explanation": "这里应该用〈更换〉。变换指方法、内容等形式的改换；把旧地址换成新地址要用“更换”。"}, {"text": "两国代表变换了意见。", "explanation": "这里应该用〈交换〉。变换指形式或方式的改换，双方互相交流看法要用交换。"}, {"text": "这两年他的身高变换了不少。", "explanation": "这里应该用〈变化〉。变换指从一种形式或内容换成另一种，身高自然增长要用变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变换", "is_correct": true, "explanation": "“变换”指舞步随音乐改换样子，符合“跟着”的语境。"}, {"text": "复印", "is_correct": false, "explanation": "语义：复印指把文件复制一份，舞步不能被复印。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：清洗多用于衣物、器具等，不说清洗舞步。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉是丢弃，与“跟着音乐”的动作意思不符。"}], "explanations": {"变换": "“变换”指舞步随音乐改换样子，符合“跟着”的语境。", "复印": "语义：复印指把文件复制一份，舞步不能被复印。", "清洗": "搭配：清洗多用于衣物、器具等，不说清洗舞步。", "扔掉": "语义：扔掉是丢弃，与“跟着音乐”的动作意思不符。"}, "sentence_index": 6, "correct_answer": "变换"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的态度发生了变换，不再那么固执。", "explanation": "这里应该用〈转变〉。变换指样子或形式的替换；态度的根本改变要用转变。"}, {"text": "他把书架变换到了门口。", "explanation": "这里应该用〈搬〉。变换指形式或内容的改换；把书架挪到门口只是移动位置，要用“搬”。"}, {"text": "他把公司变换给了朋友。", "explanation": "这里应该用〈转让〉。变换指样子或形式的改换，不指把所有权交给别人；交出公司要用转让。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师经常变换了教学的方法。", "corrected_sentence": "这位老师经常变换教学的方法。", "error_description": "错误：“变换了”；正确：“变换”。“经常”表示习惯性的动作，后面不用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们常常变换得游戏的规则。", "corrected_sentence": "孩子们常常变换游戏的规则。", "error_description": "错误：“变换得”；正确：“变换”。“得”用来引出补语，“变换”后面没有补语，不能直接加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e27c2ae-ef0f-474d-8b23-04b1a8e717bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90245, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "批评", "is_correct": true, "explanation": "批评与赞美相对，指指出别人的缺点或不足，是这一义项的反义词。"}, {"text": "观察", "is_correct": false, "explanation": "观察是仔细看、留意，与夸奖没有反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "购买是花钱买东西，与称赞别人没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考是用脑子分析问题，与夸奖不构成反义。"}], "correct_answer": "批评", "explanations": {"批评": "批评与赞美相对，指指出别人的缺点或不足，是这一义项的反义词。", "观察": "观察是仔细看、留意，与夸奖没有反义关系。", "购买": "购买是花钱买东西，与称赞别人没有反义关系。", "思考": "思考是用脑子分析问题，与夸奖不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90245, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "批评", "is_correct": true, "explanation": "批评与赞美相对，指指出别人的缺点或不足，是这一义项的反义词。"}, {"text": "散步", "is_correct": false, "explanation": "散步是随意走动，与夸奖别人没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运是把东西从一处移到另一处，与称赞没有反义关系。"}, {"text": "检查", "is_correct": false, "explanation": "检查是查看是否合格，与夸奖别人不构成反义。"}], "correct_answer": "批评", "explanations": {"批评": "批评与赞美相对，指指出别人的缺点或不足，是这一义项的反义词。", "散步": "散步是随意走动，与夸奖别人没有反义关系。", "搬运": "搬运是把东西从一处移到另一处，与称赞没有反义关系。", "检查": "检查是查看是否合格，与夸奖别人不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90245, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赞美是说别人的好话，夸奖别人。", "primary_collocate": null, "pronunciation": "zàn měi", "ipa": "tsan⁵¹ meɪ²¹⁴", "syllable_count": 2, "sentences": [{"text": "老师当众赞美了他的作文。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都赞美她的歌声。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不赞美别人，总是批评。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子做完作业，妈妈赞美了他。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们赞美着这里的美景。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很少听到他赞美同事。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着赞美我的新裙子。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么不赞美一下他的努力呢？", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画受到很多人赞美。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板赞美小李工作认真。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赞美了", "label": "了体"}, {"form": "赞美着", "label": "着体"}, {"form": "赞美过", "label": "过体"}], "register": "中性", "sense_fingerprint": "对人说好话，夸奖别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b588376-c1a7-4853-aa69-24c24846ed71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90245, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赞美", "is_correct": true, "explanation": "正确：“赞美”表示夸奖，与“当众”和“他的作文”搭配，符合语境。"}, {"text": "赞成", "is_correct": false, "explanation": "搭配：“赞成”用于意见、方案，不说“赞成作文”。"}, {"text": "安慰", "is_correct": false, "explanation": "配价：“安慰”的宾语须是人，不能说安慰作文。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是对他人的帮助或恩惠表示谢意，作文不是可以感谢的对象。"}], "explanations": {"赞美": "正确：“赞美”表示夸奖，与“当众”和“他的作文”搭配，符合语境。", "赞成": "搭配：“赞成”用于意见、方案，不说“赞成作文”。", "安慰": "配价：“安慰”的宾语须是人，不能说安慰作文。", "感谢": "语义：“感谢”是对他人的帮助或恩惠表示谢意，作文不是可以感谢的对象。"}, "sentence_index": 0, "correct_answer": "赞美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司出资赞美了这场比赛。", "explanation": "这里应该用〈赞助〉。赞美是称赞，不表示出资支持；公司出资支持比赛要用赞助。"}, {"text": "董事会投票赞美了这项提案。", "explanation": "这里应该用〈赞成〉。赞美是称赞，不用于投票表决；投票表示同意要用赞成。"}, {"text": "老师赞美地点了点头。", "explanation": "这里应该用〈赞许〉。赞美是言语上的称赞，不能描述点头这类表示认可的神态；点头表示认可要用赞许。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90245, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赞美", "is_correct": true, "explanation": "正确：“赞美”表示称赞，与“笑着”和“我的新裙子”的语境相符。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的宾语是车、船等交通工具，不说“驾驶裙子”。"}, {"text": "请教", "is_correct": false, "explanation": "语义：“请教”是向有知识的人求教，裙子不能成为求教的对象。"}, {"text": "喂", "is_correct": false, "explanation": "配价：“喂”要求有生命的宾语，不能说喂衣服。"}], "explanations": {"赞美": "正确：“赞美”表示称赞，与“笑着”和“我的新裙子”的语境相符。", "驾驶": "搭配：“驾驶”的宾语是车、船等交通工具，不说“驾驶裙子”。", "请教": "语义：“请教”是向有知识的人求教，裙子不能成为求教的对象。", "喂": "配价：“喂”要求有生命的宾语，不能说喂衣服。"}, "sentence_index": 6, "correct_answer": "赞美"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师赞美他作业没交。", "explanation": "这里应该用〈指责〉。赞美是称赞，不能用于对过失的表态；指出别人的过失要用指责。"}, {"text": "法官赞美了那个抢劫犯。", "explanation": "这里应该用〈惩罚〉。赞美是称赞别人的优点，不能用于对犯罪者的处罚；处罚犯人要用惩罚。"}, {"text": "保安赞美了闹事的人。", "explanation": "这里应该用〈驱赶〉。赞美是称赞，不能用于把闹事的人赶走；赶走闹事的人要用驱赶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我常常赞美了着她的歌声。", "corrected_sentence": "我常常赞美她的歌声。", "error_description": "错误：动词“赞美”后不能同时带动态助词“了”和“着”，应全部去掉，说“我常常赞美她的歌声”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90245, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把我的画赞美。", "corrected_sentence": "他把我的画赞美了一番。", "error_description": "错误：“把”字句中的动词“赞美”缺少补语。“把”字句需要“了一番”之类的补语，应说“他把我的画赞美了一番”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
