INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90246, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "称赞，夸奖。", "primary_collocate": null, "pronunciation": "zàn měi", "ipa": "tsan⁵¹ meɪ²¹⁴", "syllable_count": 2, "sentences": [{"text": "人们都赞美这位医生的善良。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的厨艺很棒，我由衷赞美她。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人赞美这家饭店的服务很好。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常常赞美奶奶做的饺子。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗人赞美春天的美丽。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家赞美他帮助别人的行为。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师赞美过这个班的学生。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们赞美着自己的老师。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不好意思听别人赞美他。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌赞美了母亲的爱。", "target_word": "赞美", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赞美了", "label": "了体"}, {"form": "赞美着", "label": "着体"}, {"form": "赞美过", "label": "过体"}], "register": "中性", "sense_fingerprint": "称赞、夸奖人或事物的优点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b588376-c1a7-4853-aa69-24c24846ed71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors 