INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赞美", "is_correct": true, "explanation": "正确：“赞美”表示称赞，与“善良”这种值得称赞的品质相符。"}, {"text": "打击", "is_correct": false, "explanation": "语义：“打击”的对象是人或信心，不是善良这样的品质。"}, {"text": "借", "is_correct": false, "explanation": "搭配：“借”的宾语是物品或钱财，不说“借善良”。"}, {"text": "拍", "is_correct": false, "explanation": "配价：“拍”要求有形的动作对象，不能拍品质。"}], "explanations": {"赞美": "正确：“赞美”表示称赞，与“善良”这种值得称赞的品质相符。", "打击": "语义：“打击”的对象是人或信心，不是善良这样的品质。", "借": "搭配：“借”的宾语是物品或钱财，不说“借善良”。", "拍": "配价：“拍”要求有形的动作对象，不能拍品质。"}, "sentence_index": 0, "correct_answer": "赞美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家银行出资赞美了这届运动会。", "explanation": "这里应该用〈赞助〉。赞美是称赞，不表示出资；银行出资支持运动会要用赞助。"}, {"text": "我投票赞美你的提议。", "explanation": "这里应该用〈赞成〉。赞美是称赞，不用于投票表决；投票同意提议要用赞成。"}, {"text": "爸爸赞美地对我笑了笑。", "explanation": "这里应该用〈赞许〉。赞美是言语上的称赞，不能描述笑这类表示认可的神态；表示认可的神态要用赞许。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赞美", "is_correct": true, "explanation": "正确：“赞美”表示称赞，与“老师”和“这个班的学生”的语境相符。"}, {"text": "颁布", "is_correct": false, "explanation": "搭配：“颁布”的宾语是法令、制度，不说“颁布学生”。"}, {"text": "嫁", "is_correct": false, "explanation": "语义：“嫁”指女子出嫁，与老师和学生之间的关系不合。"}, {"text": "推销", "is_correct": false, "explanation": "配价：“推销”的宾语是商品，不能推销人。"}], "explanations": {"赞美": "正确：“赞美”表示称赞，与“老师”和“这个班的学生”的语境相符。", "颁布": "搭配：“颁布”的宾语是法令、制度，不说“颁布学生”。", "嫁": "语义：“嫁”指女子出嫁，与老师和学生之间的关系不合。", "推销": "配价：“推销”的宾语是商品，不能推销人。"}, "sentence_index": 6, "correct_answer": "赞美"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈赞美我没洗碗。", "explanation": "这里应该用〈责备〉。赞美是称赞，不能用于指出别人的过失；责备没洗碗要用责备。"}, {"text": "警察赞美了那个小偷。", "explanation": "这里应该用〈逮捕〉。赞美是称赞，不表示抓捕；警察抓捕小偷要用逮捕。"}, {"text": "大家赞美他摔倒了。", "explanation": "这里应该用〈嘲笑〉。赞美是称赞，不能用于取笑别人的失误；取笑别人要用嘲笑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈很少赞美了我。", "corrected_sentence": "妈妈很少赞美我。", "error_description": "错误：表示经常性、习惯性的否定动作时，动词后不加“了”。“很少”后面的“赞美”不能带“了”，应说“妈妈很少赞美我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把那个孩子赞美。", "corrected_sentence": "老师把那个孩子赞美了一番。", "error_description": "错误：“把”字句中的动词“赞美”缺少补语。“把”字句需要“了一番”之类的补语，应说“老师把那个孩子赞美了一番”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
