INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90248, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供演员表演节目的平台，通常设在剧场或礼堂内，高于观众席。", "primary_collocate": null, "pronunciation": "wǔ tái", "ipa": "u˨˩˦ tʰai̯˧˥", "syllable_count": 2, "sentences": [{"text": "剧场的舞台比观众席高一米。", "target_word": "舞台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "礼堂里的舞台上放着一架钢琴。", "target_word": "舞台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出前，工作人员在舞台上放好了椅子。", "target_word": "舞台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台中间站着一位年轻的歌手。", "target_word": "舞台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员从舞台后面慢慢走出来。", "target_word": "舞台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台上挂着红色的幕布。", "target_word": "舞台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个礼堂的舞台很宽。", "target_word": "舞台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爬上舞台，向大家问好。", "target_word": "舞台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台下面坐满了观众。", "target_word": "舞台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手唱完歌，走下了舞台。", "target_word": "舞台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "舞臺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "剧场或礼堂内高于观众席、供演员表演的平台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad8dbc6-820a-4e36-a32d-a214082bc3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "舞台", "is_correct": true, "explanation": "正确：指剧场中高于观众席、供演员表演的平台，与“比观众席高一米”相符。"}, {"text": "零食", "is_correct": false, "explanation": "语义：“零食”不是平台，不能与观众席比较高度，句意不通。"}, {"text": "票", "is_correct": false, "explanation": "搭配：“高一米”的主语须是有高度的物体，“票”没有高矮可比。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐没有高度，不能与观众席比较高矮，句意不通。"}], "explanations": {"舞台": "正确：指剧场中高于观众席、供演员表演的平台，与“比观众席高一米”相符。", "零食": "语义：“零食”不是平台，不能与观众席比较高度，句意不通。", "票": "搭配：“高一米”的主语须是有高度的物体，“票”没有高矮可比。", "音乐": "语义：音乐没有高度，不能与观众席比较高矮，句意不通。"}, "sentence_index": 0, "correct_answer": "舞台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "观众坐在舞台上看比赛。", "explanation": "这里应该用〈看台〉。观众坐的地方是看台或观众席，舞台是供演员表演的平台。"}, {"text": "妈妈站在舞台前炒菜。", "explanation": "这里应该用〈灶台〉。炒菜要在灶台上进行，舞台不能用来炒菜。"}, {"text": "剧场里有一块舞台。", "explanation": "这里应该用〈个〉。“块”用于成块的东西，不用于修饰舞台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舞台", "is_correct": true, "explanation": "正确：指礼堂里供演员表演的高台，与“很宽”的描述相符。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“很宽”不能形容时间，句中主语是礼堂的部分，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“宽”形容空间，“心情”不能与“礼堂的”搭配作为被描述的对象。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能作为礼堂的部件来形容宽窄，句意不通。"}], "explanations": {"舞台": "正确：指礼堂里供演员表演的高台，与“很宽”的描述相符。", "时间": "语义：“很宽”不能形容时间，句中主语是礼堂的部分，句意不通。", "心情": "搭配：“宽”形容空间，“心情”不能与“礼堂的”搭配作为被描述的对象。", "空气": "语义：空气不能作为礼堂的部件来形容宽窄，句意不通。"}, "sentence_index": 6, "correct_answer": "舞台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在舞台里睡觉，很舒服。", "explanation": "这里应该用〈卧室〉。舞台是供表演的高台，不能用来睡觉，睡觉应在卧室里。"}, {"text": "他骑着舞台回家了。", "explanation": "这里应该用〈自行车〉。舞台是供表演的平台，不能骑，应说“骑着自行车回家”。"}, {"text": "礼堂里有一扇舞台。", "explanation": "这里应该用〈个〉。“扇”用于门窗等，不能用来修饰舞台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个剧场有一只很大的舞台。", "corrected_sentence": "这个剧场有一个很大的舞台。", "error_description": "“只”多用于动物、船只、箱子等，不用于“舞台”；舞台应用“个”，故应为“一个很大的舞台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "礼堂前面有一条很宽的舞台。", "corrected_sentence": "礼堂前面有一个很宽的舞台。", "error_description": "“条”用于细长的东西，如河、路，不用于“舞台”；舞台应用“个”，应为“一个很宽的舞台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff69dc8a-b428-4448-b274-55afe2b84a0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
