INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90249, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "透明、硬硬的，一摔就会破的东西。", "primary_collocate": null, "pronunciation": "bō li", "ipa": "pwo⁵⁵ li", "syllable_count": 2, "sentences": [{"text": "玻璃掉在地上就碎了。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，玻璃很容易破。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块玻璃又干净又透明。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不小心打破了一块玻璃。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有玻璃，别过去。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用布擦了擦玻璃。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃很硬，可是一摔就会破。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我透过玻璃看见了外面的雪。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要用手摸这块玻璃。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的玻璃碎了，要小心。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块玻璃", "label": "量词"}, {"form": "玻璃杯", "label": "复合"}, {"form": "玻璃窗", "label": "复合"}], "register": "中性", "sense_fingerprint": "透明、硬而易碎的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '410036aa-66b9-4036-830e-495e3a8f36e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90249, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玻璃", "is_correct": true, "explanation": "玻璃：透明而易碎，掉在地上会碎，符合句意。"}, {"text": "羽毛", "is_correct": false, "explanation": "语义：羽毛掉在地上不会碎，与“碎了”矛盾。"}, {"text": "水", "is_correct": false, "explanation": "语义：水洒在地上不会“碎”，句子不通。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“碎”用于有固体形状的东西，不能说“雨掉在地上就碎了”。"}], "explanations": {"玻璃": "玻璃：透明而易碎，掉在地上会碎，符合句意。", "羽毛": "语义：羽毛掉在地上不会碎，与“碎了”矛盾。", "水": "语义：水洒在地上不会“碎”，句子不通。", "雨": "搭配：“碎”用于有固体形状的东西，不能说“雨掉在地上就碎了”。"}, "sentence_index": 0, "correct_answer": "玻璃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只玻璃。", "explanation": "这里应该用〈块〉。玻璃是片状材料，量词用“块”或“片”，不用“只”。"}, {"text": "妈妈买了一根玻璃。", "explanation": "这里应该用〈块〉。“根”用于细长的东西，玻璃是片状的，不能用“根”。"}, {"text": "妈妈把玻璃放到火上，煮了一顿饭。", "explanation": "这里应该用〈锅〉。玻璃是透明的硬物，不能放在火上烧煮食物，煮饭要用锅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90249, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玻璃", "is_correct": true, "explanation": "玻璃：硬而易碎，符合“很硬，一摔就会破”的描述。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁一摔不会破，与“一摔就会破”矛盾。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花是软的，与“很硬”矛盾。"}, {"text": "橡胶", "is_correct": false, "explanation": "语义：橡胶有弹性，一摔不会破，与“一摔就会破”矛盾。"}], "explanations": {"玻璃": "玻璃：硬而易碎，符合“很硬，一摔就会破”的描述。", "钢铁": "语义：钢铁一摔不会破，与“一摔就会破”矛盾。", "棉花": "语义：棉花是软的，与“很硬”矛盾。", "橡胶": "语义：橡胶有弹性，一摔不会破，与“一摔就会破”矛盾。"}, "sentence_index": 6, "correct_answer": "玻璃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一条玻璃。", "explanation": "这里应该用〈块〉。“条”用于长条形的东西，玻璃是片状的，不能用“条”。"}, {"text": "妈妈在柜子上放了一个玻璃。", "explanation": "这里应该用〈块〉或〈片〉。“个”不适合用于玻璃这种片状材料。"}, {"text": "冬天早上，窗户上结了一块玻璃。", "explanation": "这里应该用〈冰〉。玻璃是人造的透明材料，不会在窗上自然结成；寒冷时窗上结的是冰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗户上的那只玻璃很干净。", "corrected_sentence": "窗户上的那块玻璃很干净。", "error_description": "错误：玻璃是片状材料，应用量词“块”，不用“只”。应说“那块玻璃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不小心把一只玻璃打碎了。", "corrected_sentence": "他不小心把一块玻璃打碎了。", "error_description": "错误：玻璃是片状材料，量词应用“块”，不用“只”。应说“一块玻璃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab2075-cb43-480e-bee1-5797992a9f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
