INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90251, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "走廊是房子里长长的、可以走路的地方。", "primary_collocate": null, "pronunciation": "zǒu láng", "ipa": "tsoʊ˨˩˦ laŋ˧˥", "syllable_count": 2, "sentences": [{"text": "教室外面的走廊很长。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在走廊里等老师。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在走廊上跑来跑去。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的走廊很窄，放不下桌子。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的走廊里很安静。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走廊的灯坏了，晚上很黑。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走过走廊，打开了最后一扇门。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在走廊里排好队。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在走廊里大声说话。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的走廊上铺着红色的地毯。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "通用", "sense_fingerprint": "房子里长长的可以走路的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0e4be8-25eb-4115-9c6a-5a16b534add7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90251, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走廊", "is_correct": true, "explanation": "正确：走廊，是房子里长长的可以走路的地方，符合“教室外面”和“很长”。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“很长”不能修饰空气，空气没有“长”的说法。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是小型电子设备，不是教室外面的长通道。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是教室外面的长通道。"}], "explanations": {"走廊": "正确：走廊，是房子里长长的可以走路的地方，符合“教室外面”和“很长”。", "空气": "搭配：“很长”不能修饰空气，空气没有“长”的说法。", "手机": "语义：手机是小型电子设备，不是教室外面的长通道。", "冰箱": "语义：冰箱是家用电器，不是教室外面的长通道。"}, "sentence_index": 0, "correct_answer": "走廊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们沿着走廊上了三楼。", "explanation": "这里应该用〈楼梯〉。走廊是横向的通道，不能用来上楼。"}, {"text": "我们在走廊里种了一大片菜。", "explanation": "这里应该用〈院子〉。走廊是房子里狭长的通道，不能用来种成片的菜；种菜要在〈院子〉或〈菜地〉里。"}, {"text": "路口的走廊上停着很多车。", "explanation": "这里应该用〈马路〉。走廊在建筑内，不能用来停车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走廊", "is_correct": true, "explanation": "正确：走廊，可以“走过”的长通道，符合“打开了最后一扇门”的语境。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是可以走过的地方。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是饮料，不是可以走过的地方。"}, {"text": "铅笔", "is_correct": false, "explanation": "配价：“走过”需要路线或场所作宾语，“铅笔”不符合。"}], "explanations": {"走廊": "正确：走廊，可以“走过”的长通道，符合“打开了最后一扇门”的语境。", "汽油": "语义：汽油是燃料，不是可以走过的地方。", "牛奶": "语义：牛奶是饮料，不是可以走过的地方。", "铅笔": "配价：“走过”需要路线或场所作宾语，“铅笔”不符合。"}, "sentence_index": 6, "correct_answer": "走廊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把书都装进了走廊。", "explanation": "这里应该用〈箱子〉。走廊是供人通行的通道，不能用来装东西，装书要用〈箱子〉。"}, {"text": "我往走廊里倒满了水，准备洗澡。", "explanation": "这里应该用〈浴缸〉。走廊是供人走路的通道，不能装水洗澡，洗澡要在〈浴缸〉里。"}, {"text": "这条走廊很长，车可以从里面穿过。", "explanation": "这里应该用〈隧道〉。走廊不能用来让车辆穿过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在一扇长长的走廊里排队。", "corrected_sentence": "我们在一条长长的走廊里排队。", "error_description": "错误：量词“扇”用于走廊不对；正确：量词“条”。“扇”用于门窗，走廊要用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90251, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她走过一只走廊，打开了门。", "corrected_sentence": "她走过一条走廊，打开了门。", "error_description": "错误：量词“只”用于走廊不对；正确：量词“条”。“只”用于动物等，走廊要用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
