INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90252, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "建筑物内外有顶的长形通道。", "primary_collocate": null, "pronunciation": "zǒu láng", "ipa": "tsoʊ˨˩˦ laŋ˧˥", "syllable_count": 2, "sentences": [{"text": "公园里有一条很长的走廊。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们在走廊里躲雨。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子外面有一条木头走廊。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走廊两边种着很多花。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，老人们坐在走廊里喝茶。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥有一条带顶的走廊，可以避雨。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼外的走廊连着两栋楼。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古老的院子里有一条红色的走廊。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着走廊走到了花园。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走廊外面是一个大湖。", "target_word": "走廊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "通用", "sense_fingerprint": "建筑物内外有顶的长形通道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0e4be8-25eb-4115-9c6a-5a16b534add7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走廊", "is_correct": true, "explanation": "正确：走廊，是建筑物内外有顶的长形通道，符合“公园里有一条很长的”。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“一条很长的”不用来修饰雨。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是有顶的长形通道，不能在公园里“有一条”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是公园里的长形通道。"}], "explanations": {"走廊": "正确：走廊，是建筑物内外有顶的长形通道，符合“公园里有一条很长的”。", "雨": "搭配：“一条很长的”不用来修饰雨。", "空气": "语义：空气不是有顶的长形通道，不能在公园里“有一条”。", "冰箱": "语义：冰箱是家用电器，不是公园里的长形通道。"}, "sentence_index": 0, "correct_answer": "走廊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在走廊里摆了一张大床，晚上就睡在那里。", "explanation": "这里应该用〈卧室〉。走廊是供人通行的有顶通道，不能当作卧室睡觉，睡觉要在〈卧室〉里。"}, {"text": "我开车沿着走廊回家。", "explanation": "这里应该用〈马路〉。走廊不能用来行车。"}, {"text": "走廊上漂着很多船。", "explanation": "这里应该用〈湖面〉。走廊是建筑内外的通道，不是水面，不能漂船。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走廊", "is_correct": true, "explanation": "正确：走廊，是长形通道，能够“连着两栋楼”。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不能连接两栋楼。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天是季节，不能作“连着两栋楼”的主语。"}, {"text": "铅笔", "is_correct": false, "explanation": "配价：“连着”需要建筑或通道作主语，“铅笔”不符合。"}], "explanations": {"走廊": "正确：走廊，是长形通道，能够“连着两栋楼”。", "汽油": "语义：汽油是燃料，不能连接两栋楼。", "夏天": "语义：夏天是季节，不能作“连着两栋楼”的主语。", "铅笔": "配价：“连着”需要建筑或通道作主语，“铅笔”不符合。"}, "sentence_index": 6, "correct_answer": "走廊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在走廊里收割了一大片稻子。", "explanation": "这里应该用〈稻田〉。走廊是通道，不能用来收割庄稼，成片的稻子要长在〈稻田〉里。"}, {"text": "这条走廊很宽，车很多。", "explanation": "这里应该用〈公路〉。走廊是供人行走的有顶通道，不能用来通车。"}, {"text": "我们在走廊里游了一下午的泳。", "explanation": "这里应该用〈泳池〉。走廊是通道，不能在里面游泳，游泳要去〈泳池〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那座老房子里有一张走廊。", "corrected_sentence": "那座老房子里有一条走廊。", "error_description": "错误：量词“张”用于走廊不对；正确：量词“条”。“张”多用于平面物件，走廊是细长的通道，用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家后院有一只木头走廊。", "corrected_sentence": "我家后院有一条木头走廊。", "error_description": "错误：量词“只”用于走廊不对；正确：量词“条”。“只”用于动物，走廊要用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
