INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90256, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对不如意的事想得开，不再计较。", "primary_collocate": null, "pronunciation": "kàn kāi", "ipa": "kʰan˥˩ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "钱少一点没关系，他早就看开了。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输赢她已经看开了，不再计较。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人对名和利都看开了。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃点亏没什么，要看开，别计较。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对升职的事看开了，不再争了。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事占了便宜，他看开了，没再生气。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪大了，对得失就看开了。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友借钱不还，我看开了，不想再要。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把成败看开了，不再和别人比。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对小事要看开，别总是和人计较。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看开了", "label": "体标"}, {"form": "看开过", "label": "体标"}, {"form": "看得开", "label": "可能补语"}, {"form": "看不开", "label": "可能补语"}, {"form": "看開", "label": "繁体"}], "register": "口语", "sense_fingerprint": "对得失、吃亏、名利等不再计较，想得开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed144756-53d4-4300-bd5f-f63fe54a21d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "计较", "is_correct": false, "explanation": "语义：“计较”表示在意得失，与“钱少一点没关系”的态度相反。"}, {"text": "看开", "is_correct": true, "explanation": "正确：看开表示对得失想得开、不再计较，符合“钱少一点没关系”的语境。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”表示因钱的事不满，与“没关系”的句意矛盾。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“跑步”是运动，与“钱少一点没关系”的态度无关，句意不通。"}], "explanations": {"计较": "语义：“计较”表示在意得失，与“钱少一点没关系”的态度相反。", "看开": "正确：看开表示对得失想得开、不再计较，符合“钱少一点没关系”的语境。", "生气": "语义：“生气”表示因钱的事不满，与“没关系”的句意矛盾。", "跑步": "语义：“跑步”是运动，与“钱少一点没关系”的态度无关，句意不通。"}, "sentence_index": 0, "correct_answer": "看开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在远处看开了他的背影。", "explanation": "这里应该用〈看见〉。看开表示想得开、不计较，不能表示视觉上看到人或物。"}, {"text": "这篇文章很难，我终于看开了它的意思。", "explanation": "这里应该用〈看懂〉。看开表示想得开，不能表示读懂文字的意思。"}, {"text": "他负责看开那些犯人。", "explanation": "这里应该用〈看守〉。看开指想得开，不能表示看管人员或囚犯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上学", "is_correct": false, "explanation": "语义：“上学”与“年纪大了，对得失”的语境不合，句意荒谬。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“对得失”无关，不能表示对得失的态度。"}, {"text": "看开", "is_correct": true, "explanation": "正确：看开表示对得失想得开、不再计较，符合“年纪大了”的语境。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物或身体，不能与“得失”搭配。"}], "explanations": {"上学": "语义：“上学”与“年纪大了，对得失”的语境不合，句意荒谬。", "吃饭": "语义：“吃饭”与“对得失”无关，不能表示对得失的态度。", "看开": "正确：看开表示对得失想得开、不再计较，符合“年纪大了”的语境。", "洗": "搭配：“洗”的对象是衣物或身体，不能与“得失”搭配。"}, "sentence_index": 6, "correct_answer": "看开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很看开这份友谊，一直很珍惜。", "explanation": "这里应该用〈看重〉。看开表示想得开，不表示重视某段关系。"}, {"text": "周末我去医院看开奶奶。", "explanation": "这里应该用〈看望〉。看开表示想得开，不能表示去探视某人。"}, {"text": "她一眼就看开了那件衣服，马上买下。", "explanation": "这里应该用〈看中〉。看开不能表示挑中某样东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终于看开过，不再为一点钱生气。", "corrected_sentence": "她终于看开了，不再为一点钱生气。", "error_description": "错误：“看开过”。正确：“看开了”。“过”表示曾经有过的经历，与“终于……不再为一点钱生气”所描述的已完成的转变不相符；表示变化已经完成应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "输了比赛他很快就把看开了，没再生气。", "corrected_sentence": "输了比赛他很快就看开了，没再生气。", "error_description": "错误：“把看开了”。正确：“看开了”。“把”字句必须有宾语（如“把成败看开了”），这里“把”后缺少宾语，所以不成立；没有宾语时直接说“看开了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db9e259-24f8-4873-845d-be6bf865173b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90257, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "错过", "is_correct": true, "explanation": "正确：“错过”与“赶上”（及时到达）相反，表示没有及时赶到。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”表示交流意见，与“赶上”的任何义项都不相反。"}, {"text": "写作", "is_correct": false, "explanation": "无反义关系：“写作”表示写文章，与“赶上”没有对应关系。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：“游泳”表示在水中活动，与“赶上”的任何义项都不构成反义。"}], "correct_answer": "错过", "explanations": {"错过": "正确：“错过”与“赶上”（及时到达）相反，表示没有及时赶到。", "讨论": "无反义关系：“讨论”表示交流意见，与“赶上”的任何义项都不相反。", "写作": "无反义关系：“写作”表示写文章，与“赶上”没有对应关系。", "游泳": "无反义关系：“游泳”表示在水中活动，与“赶上”的任何义项都不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90257, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "错过", "is_correct": true, "explanation": "正确：“错过”与“赶上”（及时到达）相反，表示没有赶到所需的时间。"}, {"text": "出发", "is_correct": false, "explanation": "无反义关系：“出发”表示动身，与“赶上”的任何义项都不相反。"}, {"text": "思考", "is_correct": false, "explanation": "无反义关系：“思考”表示用脑想问题，与“赶上”没有对应关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无反义关系：“睡觉”表示入睡，与“赶上”的任何义项都不构成反义。"}], "correct_answer": "错过", "explanations": {"错过": "正确：“错过”与“赶上”（及时到达）相反，表示没有赶到所需的时间。", "出发": "无反义关系：“出发”表示动身，与“赶上”的任何义项都不相反。", "思考": "无反义关系：“思考”表示用脑想问题，与“赶上”没有对应关系。", "睡觉": "无反义关系：“睡觉”表示入睡，与“赶上”的任何义项都不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90257, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赶上是跑得快，到了别人旁边或没有错过。", "primary_collocate": null, "pronunciation": "gǎn shàng", "ipa": "kan˨˩˦ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他跑得很快，一会儿就赶上了前面的同学。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跑了一路，终于赶上了最后一班公共汽车。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先走，我马上就赶上你。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她迟到了五分钟，没赶上火车。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗拼命跑，想赶上前面的主人。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点儿，我们还能赶上七点的电影。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑车追了很久，才赶上那辆公共汽车。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步比赛中，他最后赶上了第一名。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们走得太快，我很难赶上。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打车去机场，正好赶上飞机。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赶上了", "label": "体标"}, {"form": "赶上过", "label": "体标"}, {"form": "趕上", "label": "繁体"}], "register": "中性", "sense_fingerprint": "快跑追到别人身边，或及时到达没有错过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c4d128-43e8-4390-b92a-c10afdd8f3f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90257, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赶上", "is_correct": true, "explanation": "正确：“赶上”表示快跑追到，句中是他跑得快，追到了前面的同学。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”的对象是衣服或鞋子，不能穿同学。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是场所或物品，不能打扫人。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”后接活动或比赛，不能直接以“同学”作宾语。"}], "explanations": {"赶上": "正确：“赶上”表示快跑追到，句中是他跑得快，追到了前面的同学。", "穿": "语义：“穿”的对象是衣服或鞋子，不能穿同学。", "打扫": "语义：“打扫”的对象是场所或物品，不能打扫人。", "参加": "配价：“参加”后接活动或比赛，不能直接以“同学”作宾语。"}, "sentence_index": 0, "correct_answer": "赶上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在图书馆门口赶上了整整一个下午。", "explanation": "这里应该用〈等〉。赶上表示追到或及时赶到，不表示等待；等待一个下午要用“等”。"}, {"text": "我们八点赶上了学校。", "explanation": "这里应该用〈赶到〉。赶到表示到达某地，后面接地点；赶上表示追到或及时遇到，不能接“学校”这样的地点。"}, {"text": "他赶上了十分钟。", "explanation": "这里应该用〈迟到〉。赶上接的是人或事，不能接表示时段的“十分钟”；说“迟到了十分钟”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赶上", "is_correct": true, "explanation": "正确：“赶上”表示追到，句中是他骑车追了很久，终于追上了公共汽车。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”的动作无法用来作用于车，句子不成立。"}, {"text": "恳求", "is_correct": false, "explanation": "语义：“恳求”的对象必须是能听懂请求的人，不能恳求公共汽车。"}, {"text": "拨打", "is_correct": false, "explanation": "配价：“拨打”的宾语是电话号码，不能以“公共汽车”作宾语。"}], "explanations": {"赶上": "正确：“赶上”表示追到，句中是他骑车追了很久，终于追上了公共汽车。", "咬": "语义：“咬”的动作无法用来作用于车，句子不成立。", "恳求": "语义：“恳求”的对象必须是能听懂请求的人，不能恳求公共汽车。", "拨打": "配价：“拨打”的宾语是电话号码，不能以“公共汽车”作宾语。"}, "sentence_index": 6, "correct_answer": "赶上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "石头赶上了窗户。", "explanation": "这里应该用〈打中〉。赶上表示追到、追平或来得及，不表示击中物体；这句说的是石头击中窗户，要用“打中”。"}, {"text": "他赶上了公司的名誉。", "explanation": "这里应该用〈挽回〉。赶上接的是能追上的人或事，不能用于挽回已经失去的名誉。"}, {"text": "他的话赶上了朋友的心。", "explanation": "这里应该用〈伤害〉。赶上只表示追到或来得及，不表示伤害别人的感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在路口等了很久，终于赶上着末班车。", "corrected_sentence": "我们在路口等了很久，终于赶上了末班车。", "error_description": "体标用错：“赶上着”；正确：“赶上了”。“着”表示动作的持续状态，“赶上”是一次性完成的动作，完成义应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我虽然起步晚，还是被赶上了前面的队伍。", "corrected_sentence": "我虽然起步晚，还是赶上了前面的队伍。", "error_description": "句式用错：加上“被”变成被动，句子说成我被别人追上，与原意相反；这里“我”是追赶的一方，应直接用“赶上了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90258, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "错过", "is_correct": true, "explanation": "正确：“错过”与“赶上”（恰好碰上）相反，表示没有遇到所说的时机。"}, {"text": "出发", "is_correct": false, "explanation": "无反义关系：“出发”表示动身，与“赶上”的任何义项都不相反。"}, {"text": "思考", "is_correct": false, "explanation": "无反义关系：“思考”表示用脑想问题，与“赶上”没有对应关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无反义关系：“睡觉”表示入睡，与“赶上”的任何义项都不构成反义。"}], "correct_answer": "错过", "explanations": {"错过": "正确：“错过”与“赶上”（恰好碰上）相反，表示没有遇到所说的时机。", "出发": "无反义关系：“出发”表示动身，与“赶上”的任何义项都不相反。", "思考": "无反义关系：“思考”表示用脑想问题，与“赶上”没有对应关系。", "睡觉": "无反义关系：“睡觉”表示入睡，与“赶上”的任何义项都不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90258, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "落后", "is_correct": true, "explanation": "正确：“落后”与“赶上”（水平追平）相反，表示水平低于别人。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”表示交流意见，与“赶上”的任何义项都不相反。"}, {"text": "写作", "is_correct": false, "explanation": "无反义关系：“写作”表示写文章，与“赶上”没有对应关系。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：“游泳”表示在水中活动，与“赶上”的任何义项都不构成反义。"}], "correct_answer": "落后", "explanations": {"落后": "正确：“落后”与“赶上”（水平追平）相反，表示水平低于别人。", "讨论": "无反义关系：“讨论”表示交流意见，与“赶上”的任何义项都不相反。", "写作": "无反义关系：“写作”表示写文章，与“赶上”没有对应关系。", "游泳": "无反义关系：“游泳”表示在水中活动，与“赶上”的任何义项都不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90258, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "追上；也指恰好碰上。", "primary_collocate": null, "pronunciation": "gǎn shàng", "ipa": "kan˨˩˦ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他学习很努力，成绩很快赶上了别的同学。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，我们的经济发展得很快，赶上了不少国家。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去北京，正好赶上了下雪。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他来旅游，赶上了春节，街上很热闹。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天出门，不巧赶上大雨，衣服都湿了。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟个子长得快，已经赶上哥哥了。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的产品慢慢赶上了同行的水平。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真巧，我回家的时候刚好赶上妈妈做饭。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去买东西，赶上商店打折，买了很多。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要每天练习，你的水平一定能赶上他。", "target_word": "赶上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赶上了", "label": "体标"}, {"form": "赶上过", "label": "体标"}, {"form": "趕上", "label": "繁体"}], "register": "中性", "sense_fingerprint": "水平追平别人，或恰好碰上某个情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c4d128-43e8-4390-b92a-c10afdd8f3f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赶上", "is_correct": true, "explanation": "正确：“赶上”表示追平，句中是成绩追上了别的同学。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶某人，成绩不能讨厌同学。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”后接活动或比赛，不能直接以“同学”作宾语。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：“帮助”的主语必须是能施助的人，成绩不能帮助别人。"}], "explanations": {"赶上": "正确：“赶上”表示追平，句中是成绩追上了别的同学。", "讨厌": "语义：“讨厌”表示厌恶某人，成绩不能讨厌同学。", "参加": "配价：“参加”后接活动或比赛，不能直接以“同学”作宾语。", "帮助": "语义：“帮助”的主语必须是能施助的人，成绩不能帮助别人。"}, "sentence_index": 0, "correct_answer": "赶上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们十点赶上了机场。", "explanation": "这里应该用〈赶到〉。赶到表示到达某地，后面接地点；赶上后面接的是要追的人或要赶的事，不能接“机场”这样的地点。"}, {"text": "他赶上了五分钟。", "explanation": "这里应该用〈迟到〉。赶上接的是人或事，不能接表示时段的“五分钟”；说“迟到了五分钟”才对。"}, {"text": "我们在车站赶上了一小时的车。", "explanation": "这里应该用〈等〉。赶上表示追到或及时赶到，不表示等待一段时间；等车一小时要用“等”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赶上", "is_correct": true, "explanation": "正确：“赶上”表示追平，句中是产品的水平追平了同行。"}, {"text": "减少", "is_correct": false, "explanation": "搭配：“减少”用于数量，不能说减少“水平”。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语是场所或展览，不能是“水平”。"}, {"text": "请教", "is_correct": false, "explanation": "语义：“请教”是向人讨教，产品不能向同行请教水平。"}], "explanations": {"赶上": "正确：“赶上”表示追平，句中是产品的水平追平了同行。", "减少": "搭配：“减少”用于数量，不能说减少“水平”。", "参观": "配价：“参观”的宾语是场所或展览，不能是“水平”。", "请教": "语义：“请教”是向人讨教，产品不能向同行请教水平。"}, "sentence_index": 6, "correct_answer": "赶上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "球赶上了他的头。", "explanation": "这里应该用〈打中〉。赶上只表示追到、追平或来得及，不表示击中；这句说的是球击中了人，要用“打中”。"}, {"text": "他赶上了公司的名誉。", "explanation": "这里应该用〈挽回〉。赶上接的是能追上的人或事，不能用于挽回已经失去的名誉。"}, {"text": "他的话赶上了朋友的感情。", "explanation": "这里应该用〈伤害〉。赶上只表示追到或追平，不表示伤害感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
